window.QDATA=[{"id":"exam-1","part":"exam","n":1,"en":"Why is the discount factor (γ) important in reinforcement learning algorithms like Episodic Sarsa?","vi":"Tại sao hệ số chiết khấu (γ) lại quan trọng trong các thuật toán học tăng cường như Sarsa theo từng episode?","opts":[{"l":"A","en":"It controls the agent's learning rate","vi":"Nó điều khiển tốc độ học của agent.","note":""},{"l":"B","en":"It balances immediate and future rewards","vi":"Nó cân bằng giữa phần thưởng tức thời và phần thưởng tương lai.","note":""},{"l":"C","en":"It dictates the exploration strategy","vi":"Nó quyết định chiến lược khám phá.","note":""},{"l":"D","en":"It scales the state transition probabilities","vi":"Nó co giãn các xác suất chuyển trạng thái.","note":""}],"ans":"B","ansnote":"","exp":[["p","γ quyết định mỗi phần thưởng ở tương lai được tính nặng hay nhẹ so với phần thưởng hiện tại. A sai vì tốc độ học là α (step size). C sai vì khám phá do ε (ε-greedy) hoặc chính sách quyết định. D sai vì xác suất chuyển p(s'|s,a) là tính chất của môi trường, γ không tác động vào nó."]],"rl":[["p","Return có chiết khấu và luật cập nhật Sarsa:"],["code","G_t = R_{t+1} + \\gamma R_{t+2} + \\gamma^2 R_{t+3} + \\dots = \\sum_{k=0}^{\\infty} \\gamma^k R_{t+k+1}"],["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha \\big[ R + \\gamma Q(S',A') - Q(S,A) \\big]"],["p","γ ∈ [0,1]. γ = 0 là \"cận thị\" (chỉ quan tâm reward tức thì). γ gần 1 là \"nhìn xa\". Với bài toán episodic, có thể dùng γ = 1 vì tổng hữu hạn."]],"ex":[["p","Reward 10 đến ở bước thứ 3 (R_{t+3} = 10). Với γ = 0.9 giá trị quy về hiện tại là 0.9² × 10 = 8.1. Với γ = 0.5 chỉ còn 0.5² × 10 = 2.5, nên agent sẽ ưu tiên reward gần hơn."]],"tip":[["p","α = \"tốc độ học\", ε = \"khám phá\", γ = \"tầm nhìn xa\". Thấy chữ discount thì nghĩ ngay \"cân bằng ngắn hạn và dài hạn\"."]],"fig":false},{"id":"exam-2","part":"exam","n":2,"en":"In Importance Sampling, why can estimates become highly variable when the behavior policy b differs significantly from the target policy π?","vi":"Trong Importance Sampling (lấy mẫu theo tầm quan trọng), vì sao các ước lượng có thể dao động rất mạnh khi chính sách hành vi b khác nhiều so với chính sách đích π?","opts":[{"l":"A","en":"Because rewards are always stochastic","vi":"Vì phần thưởng luôn mang tính ngẫu nhiên.","note":""},{"l":"B","en":"Because large weights appear when b(x) is small","vi":"Vì xuất hiện các trọng số rất lớn khi b(x) nhỏ.","note":""},{"l":"C","en":"Because policies become deterministic over time","vi":"Vì các chính sách trở nên xác định theo thời gian.","note":""},{"l":"D","en":"Because value functions cannot be normalized properly","vi":"Vì hàm giá trị không thể chuẩn hóa đúng cách.","note":""}],"ans":"B","ansnote":"","exp":[["p","Trọng số importance sampling là π(x)/b(x). Khi b(x) rất nhỏ mà π(x) lớn, tỉ số này phình to, vài mẫu hiếm chi phối cả ước lượng nên phương sai rất cao. A sai vì reward ngẫu nhiên có ở mọi phương pháp, không phải nguyên nhân riêng của IS. C sai vì không có chuyện chính sách tự trở nên xác định. D sai vì việc chuẩn hóa không phải vấn đề gốc (weighted IS có chuẩn hóa nhưng nó là cách giảm phương sai)."]],"rl":[["p","Tỉ số importance sampling của cả quỹ đạo và hai ước lượng:"],["code","\\rho_{t:T-1} = \\prod_{k=t}^{T-1} \\frac{\\pi(A_k|S_k)}{b(A_k|S_k)}"],["code","V_{\\text{ordinary}}(s) = \\frac{\\sum_{t \\in \\mathcal{T}(s)} \\rho_{t:T-1} G_t}{|\\mathcal{T}(s)|}, \\qquad V_{\\text{weighted}}(s) = \\frac{\\sum_{t \\in \\mathcal{T}(s)} \\rho_{t:T-1} G_t}{\\sum_{t \\in \\mathcal{T}(s)} \\rho_{t:T-1}}"],["p","Điều kiện coverage: π(a|s) > 0 thì b(a|s) > 0. Ordinary IS không chệch nhưng phương sai có thể vô hạn. Weighted IS bị chệch nhẹ nhưng phương sai thấp hơn nhiều."]],"ex":[["p","π chọn hành động a với xác suất 0.9, còn b chỉ chọn a với xác suất 0.01, thì ρ = 0.9/0.01 = 90. Một mẫu có trọng số 90 sẽ \"át\" hàng chục mẫu khác có trọng số xấp xỉ 1, nên ước lượng nhảy lung tung."]],"tip":[["p","Chia cho số nhỏ thì ra số rất lớn: b nhỏ ⇒ weight lớn ⇒ variance lớn. Muốn ổn định thì dùng weighted IS."]],"fig":false},{"id":"exam-3","part":"exam","n":3,"en":"In Q-learning, which term is used to update the Q-value for state s and action a?","vi":"Trong Q-learning, đại lượng nào được dùng để cập nhật giá trị Q cho trạng thái s và hành động a?","opts":[{"l":"A","en":"α (learning rate)","vi":"α (tốc độ học).","note":""},{"l":"B","en":"β (exploration rate)","vi":"β (tỉ lệ khám phá).","note":""},{"l":"C","en":"δ (error term)","vi":"δ (số hạng sai số).","note":""},{"l":"D","en":"λ (decay rate)","vi":"λ (tỉ lệ suy giảm).","note":""}],"ans":"A","ansnote":"","exp":[["p","Đáp án của đề là α: đây là tham số (step size) quyết định mức độ điều chỉnh Q(s,a) theo sai số TD trong mỗi lần cập nhật. B sai vì không có ký hiệu β chuẩn cho exploration (ε mới là ε-greedy). C là cái bẫy: δ chính là sai số TD nằm trong ngoặc, nhưng nó là đại lượng được tính ra chứ không phải \"tham số dùng để cập nhật\"; cập nhật thực chất là α·δ. D sai vì λ là hệ số suy giảm của eligibility trace trong TD(λ), không có trong Q-learning một bước."]],"rl":[["p","Luật cập nhật Q-learning (off-policy, dùng max):"],["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha \\Big[ R + \\gamma \\max_{a'} Q(S',a') - Q(S,A) \\Big]"],["p","Sai số TD: δ = R + γ max Q(S',a') − Q(S,A). Vậy Q ← Q + α·δ."]],"ex":[["p","Q(s,a) = 2, R = 1, γ = 0.9, max Q(S',·) = 5, α = 0.1. Khi đó δ = 1 + 0.9×5 − 2 = 3.5, Q mới = 2 + 0.1×3.5 = 2.35. Nếu α = 1 thì Q nhảy thẳng lên 5.5."]],"tip":[["p","α = \"bước chân\" (alpha = step), δ = \"độ lệch\" (delta = difference), λ = \"vết\" của trace. Câu hỏi nói \"term used to update\" thì chọn tham số bước α."]],"fig":false},{"id":"exam-4","part":"exam","n":4,"en":"When using function approximation with optimistic initial values, which type of function approximation method can be used?","vi":"Khi dùng xấp xỉ hàm kết hợp với giá trị khởi tạo lạc quan, có thể dùng loại phương pháp xấp xỉ hàm nào?","opts":[{"l":"A","en":"Linear function approximation","vi":"Xấp xỉ hàm tuyến tính.","note":""},{"l":"B","en":"Neural networks","vi":"Mạng nơ-ron.","note":""},{"l":"C","en":"Decision trees","vi":"Cây quyết định.","note":""},{"l":"D","en":"All of the above","vi":"Tất cả các đáp án trên.","note":""}],"ans":"A","ansnote":"","exp":[["p","Với xấp xỉ tuyến tính v̂(s,w) = wᵀx(s) và đặc trưng không âm (như tile coding), chỉ cần khởi tạo trọng số w lớn là mọi giá trị ban đầu đều lạc quan, dễ kiểm soát. Với mạng nơ-ron hay cây quyết định, đầu ra ban đầu không dễ đặt đồng đều ở mức cao, và việc học ở một vùng lan sang vùng khác làm mất tính lạc quan, nên không dùng trực tiếp được. Vì vậy B, C sai, D sai theo."]],"rl":[["p","Optimistic initial values: khởi tạo Q cao hơn giá trị thật để agent tự khám phá (hành động chưa thử vẫn \"hấp dẫn\" cho đến khi bị thử và kéo xuống). Dạng tuyến tính:"],["code","\\hat{v}(s, \\mathbf{w}) = \\mathbf{w}^\\top \\mathbf{x}(s)"],["p","Nếu x(s) ≥ 0 và w khởi tạo bằng giá trị lớn thì v̂ lớn với mọi s."]],"ex":[["p","Tile coding có 8 tile bật cho mỗi trạng thái, mỗi trọng số khởi tạo 2.0 thì v̂ ban đầu = 16 (lạc quan nếu return tối đa là 10). Với mạng nơ-ron, đầu ra khởi tạo thường gần 0 và đổi theo toàn bộ trọng số nên khó ép \"cao đều\"."]],"tip":[["p","Lạc quan chỉ làm dễ khi \"chỉnh được từng núm\": tabular và tuyến tính thì chỉnh được, mạng sâu và cây thì không."]],"fig":false},{"id":"exam-5","part":"exam","n":5,"en":"What does the curse of dimensionality refer to in reinforcement learning?","vi":"\"Lời nguyền số chiều\" trong học tăng cường nói đến điều gì?","opts":[{"l":"A","en":"The increase in the number of actions available","vi":"Số hành động khả dụng tăng lên.","note":""},{"l":"B","en":"The exponential growth of the state space as the number of state variables increases","vi":"Không gian trạng thái tăng theo hàm mũ khi số biến trạng thái tăng.","note":""},{"l":"C","en":"The difficulty of finding an optimal policy","vi":"Độ khó của việc tìm chính sách tối ưu.","note":""},{"l":"D","en":"The limitation of using Monte Carlo methods","vi":"Hạn chế khi dùng các phương pháp Monte Carlo.","note":""}],"ans":"B","ansnote":"","exp":[["p","Nếu mỗi biến trạng thái có m giá trị và có d biến thì số trạng thái là m^d, tăng theo hàm mũ. A chỉ nói về số hành động, không phải số chiều trạng thái. C quá chung chung, không phải định nghĩa. D sai vì đây không phải hạn chế riêng của Monte Carlo."]],"rl":[["p","Hệ quả: bảng giá trị (tabular) không còn khả thi, cần xấp xỉ hàm (tuyến tính, tile coding, mạng nơ-ron) để khái quát hóa giữa các trạng thái."]],"ex":[["p","Mỗi biến có 10 giá trị. d = 2 cho 100 trạng thái, d = 6 cho 1.000.000, d = 10 cho 10 tỉ trạng thái. Chỉ thêm 8 biến mà bảng đã quá lớn để lưu và để thăm hết."]],"tip":[["p","Dimensionality = \"số chiều\", curse = \"nổ mũ\". Thấy \"exponential growth of state space\" là chọn."]],"fig":false},{"id":"exam-6","part":"exam","n":6,"en":"Which of the following statements is true regarding the optimal value function (v star)?","vi":"Phát biểu nào sau đây đúng về hàm giá trị tối ưu (v*)?","opts":[{"l":"A","en":"It is always negative","vi":"Nó luôn âm.","note":""},{"l":"B","en":"It can be used to derive the optimal policy","vi":"Nó có thể dùng để suy ra chính sách tối ưu.","note":""},{"l":"C","en":"It is independent of the dynamics function p","vi":"Nó độc lập với hàm động lực p.","note":""},{"l":"D","en":"It only applies to deterministic environments","vi":"Nó chỉ áp dụng cho môi trường xác định.","note":""}],"ans":"B","ansnote":"","exp":[["p","Có v* thì chọn hành động tốt nhất theo nhìn trước một bước là ra chính sách tối ưu. A sai vì dấu của v* phụ thuộc reward (có thể dương). C sai vì v* được định nghĩa qua phương trình Bellman tối ưu, trong đó có p. D sai vì MDP ngẫu nhiên vẫn có v*."]],"rl":[["code","v_*(s) = \\max_a \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_*(s')\\,], \\qquad \\pi_*(s) = \\arg\\max_a \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_*(s')\\,]"],["p","Nếu có q* thì đơn giản hơn: π*(s) = argmax_a q*(s,a), không cần mô hình p."]],"ex":[["p","Từ ô s có hai hành động, một đến ô có v* = 3, một đến ô có v* = 8 (reward bằng nhau). Chọn hành động thứ hai."]],"tip":[["p","v* → \"chỉ đường\" cho π*. Đừng nhầm v* độc lập với môi trường, thực ra nó phụ thuộc hoàn toàn vào môi trường."]],"fig":false},{"id":"exam-7","part":"exam","n":7,"en":"Why is it problematic to predict the outcomes of star exploration missions?","vi":"Vì sao việc dự đoán kết quả các nhiệm vụ thám hiểm vì sao là gặp vấn đề?","opts":[{"l":"A","en":"There is too much public interest","vi":"Có quá nhiều sự quan tâm của công chúng.","note":""},{"l":"B","en":"The lack of advanced computer models","vi":"Thiếu các mô hình máy tính tiên tiến.","note":""},{"l":"C","en":"Uncertainties and unknown variables in space","vi":"Sự bất định và các biến số chưa biết trong không gian.","note":""},{"l":"D","en":"Predicting outcomes is unnecessary","vi":"Việc dự đoán kết quả là không cần thiết.","note":""}],"ans":"C","ansnote":"","exp":[["p","Môi trường vũ trụ có nhiều yếu tố ngẫu nhiên và chưa biết nên không dự đoán chính xác được. A và D không liên quan đến độ khó dự đoán. B không phải nguyên nhân gốc vì mô hình tốt đến đâu cũng không xóa được bất định."]],"rl":[["p","Đây là lý do RL cần học từ tương tác: khi môi trường ngẫu nhiên và động lực p(s',r|s,a) không biết trước, ta dùng phương pháp dựa trên mẫu (Monte Carlo, TD) thay vì tính toán chính xác bằng DP."]],"ex":[["p","Bức xạ vũ trụ bất ngờ làm cảm biến lỗi. Kết quả cùng một hành động khác nhau giữa các lần bay."]],"tip":[["p","Đề \"kể chuyện\" thì đáp án thường nhắc tới uncertainty (bất định), đây là bản chất của bài toán RL."]],"fig":false},{"id":"exam-8","part":"exam","n":8,"en":"What is a significant drawback of distribution models in reinforcement learning?","vi":"Nhược điểm đáng kể của các mô hình phân phối (distribution model) trong học tăng cường là gì?","opts":[{"l":"A","en":"They cannot handle large state spaces","vi":"Chúng không xử lý được không gian trạng thái lớn.","note":""},{"l":"B","en":"They require extensive prior knowledge of the environment","vi":"Chúng đòi hỏi nhiều kiến thức trước về môi trường.","note":""},{"l":"C","en":"They are not scalable to real-world applications","vi":"Chúng không mở rộng được cho ứng dụng thực tế.","note":""},{"l":"D","en":"They converge slower than sample-based models","vi":"Chúng hội tụ chậm hơn mô hình dựa trên mẫu.","note":""}],"ans":"A","ansnote":"","exp":[["p","Distribution model phải liệt kê toàn bộ xác suất p(s',r|s,a), số lượng tăng rất nhanh theo không gian trạng thái nên khó lưu và tính. B, C nói chung chung và chỉ là hệ quả của A. D không đúng vì đây không phải vấn đề tốc độ hội tụ."]],"rl":[["p","Hai loại mô hình môi trường: distribution model (cho toàn bộ phân phối, cần cho DP) và sample model (chỉ sinh ra một mẫu (s',r) theo phân phối, dùng cho Dyna, planning bằng mẫu)."]],"ex":[["p","Tổng 100 viên xúc xắt: distribution model phải liệt kê mọi tổng (nặng, nhiều giá trị), còn sample model chỉ cần gieo 100 lần."]],"tip":[["p","Distribution = \"phải bày hết\", Sample = \"chỉ bốc một mẫu\". Bày hết thì không gian lớn là bùng nổ."]],"fig":false},{"id":"exam-9","part":"exam","n":9,"en":"What role does the target policy play in off-policy learning?","vi":"Chính sách đích (target policy) đóng vai trò gì trong học off-policy?","opts":[{"l":"A","en":"It defines the behavior policy","vi":"Nó xác định chính sách hành vi.","note":""},{"l":"B","en":"It defines the policy being learned and improved","vi":"Nó là chính sách đang được học và cải thiện.","note":""},{"l":"C","en":"It defines the reward function","vi":"Nó xác định hàm phần thưởng.","note":""},{"l":"D","en":"It defines the exploration strategy","vi":"Nó xác định chiến lược khám phá.","note":""}],"ans":"B","ansnote":"","exp":[["p","Off-policy tách hai chính sách: π (target) là cái ta muốn đánh giá và cải thiện, b (behavior) là cái sinh dữ liệu. A và D đều nói về b. C sai vì reward là do môi trường."]],"rl":[["p","On-policy: π = b (Sarsa). Off-policy: π ≠ b (Q-learning, trong đó π là greedy còn b là ε-greedy). Cần coverage: π(a|s) > 0 thì b(a|s) > 0."]],"ex":[["p","Robot học đường bằng cách đi lung tung (b) nhưng đang học đường ngắn nhất (π greedy)."]],"tip":[["p","Target = \"mục tiêu học\", Behavior = \"cách hành xử\". Q-learning là off-policy: b ε-greedy, π greedy."]],"fig":false},{"id":"exam-10","part":"exam","n":10,"en":"In Monte Carlo prediction, what is typically used to estimate the value of a state?","vi":"Trong dự đoán Monte Carlo, thường dùng gì để ước lượng giá trị của một trạng thái?","opts":[{"l":"A","en":"The maximum reward observed during operation","vi":"Phần thưởng lớn nhất quan sát được.","note":""},{"l":"B","en":"The average return observed from that state","vi":"Return trung bình quan sát được từ trạng thái đó.","note":""},{"l":"C","en":"The sum of immediate rewards","vi":"Tổng các phần thưởng tức thời.","note":""},{"l":"D","en":"The minimum reward observed","vi":"Phần thưởng nhỏ nhất quan sát được.","note":""}],"ans":"B","ansnote":"","exp":[["p","v_π(s) = E[G_t | S_t = s], MC xấp xỉ kỳ vọng bằng trung bình các return thực tế. A, D là cực trị, không phải kỳ vọng. C chỉ gồm reward tức thời nên bỏ qua phần tương lai."]],"rl":[["code","v_\\pi(s) = \\mathbb{E}_\\pi[G_t | S_t = s] \\approx \\frac{1}{N(s)} \\sum_{i=1}^{N(s)} G^{(i)}(s)"],["p","First-visit MC: chỉ tính lần ghé đầu của s trong mỗi episode. Every-visit MC: tính mọi lần ghé. MC chỉ dùng cho episodic và không cần mô hình."]],"ex":[["p","Trạng thái s xuất hiện trong 3 episode với return 4, 6, 8, ước lượng v(s) = (4+6+8)/3 = 6."]],"tip":[["p","Monte Carlo = \"trung bình các lần thử\" (như đổ xúc xắt nhiều lần rồi lấy trung bình)."]],"fig":false},{"id":"exam-11","part":"exam","n":11,"en":"What is the primary focus of sample-based models in reinforcement learning?","vi":"Trọng tâm chính của các mô hình dựa trên mẫu (sample-based) trong học tăng cường là gì?","opts":[{"l":"A","en":"Modeling the environment's entire distribution","vi":"Mô hình hóa toàn bộ phân phối của môi trường.","note":""},{"l":"B","en":"Learning from direct interactions with the environment","vi":"Học từ tương tác trực tiếp với môi trường.","note":""},{"l":"C","en":"Using theoretical distributions for decision-making","vi":"Dùng các phân phối lý thuyết để ra quyết định.","note":""},{"l":"D","en":"Predicting future states without actual sampling","vi":"Dự đoán trạng thái tương lai mà không cần lấy mẫu thực tế.","note":""}],"ans":"B","ansnote":"","exp":[["p","Phương pháp dựa trên mẫu học từ các mẫu kinh nghiệm (s, a, r, s') thay vì cần biết trọn phân phối. A và C mô tả distribution model. D trái ngược tên gọi vì \"sample-based\" là phải lấy mẫu."]],"rl":[["p","Sample model chỉ trả về một cặp (s', r) ngẫu nhiên theo p(s',r|s,a). Distribution model trả về toàn bộ xác suất. MC, TD, Q-learning, Dyna đều dùng mẫu."]],"ex":[["p","Thay vì tính xác suất mọi kết quả của một ván cờ, ta chơi thử nhiều ván rồi học từ kết quả."]],"tip":[["p","Sample = \"mẫu\" = \"trải nghiệm thực\", Distribution = \"bảng xác suất đầy đủ\"."]],"fig":false},{"id":"exam-12","part":"exam","n":12,"en":"Which factor influences the stability of policy gradient algorithms during training?","vi":"Yếu tố nào ảnh hưởng đến độ ổn định của các thuật toán policy gradient khi huấn luyện?","opts":[{"l":"A","en":"Learning rate","vi":"Tốc độ học.","note":""},{"l":"B","en":"Discount factor","vi":"Hệ số chiết khấu.","note":""},{"l":"C","en":"Exploration rate","vi":"Tỉ lệ khám phá.","note":""},{"l":"D","en":"Entropy regularization","vi":"Điều chuẩn entropy.","note":""}],"ans":"A","ansnote":"","exp":[["p","Policy gradient cập nhật θ ← θ + α∇J(θ). α quá lớn thì bước nhảy vượt qua vùng tốt và mất ổn định (chính sách có thể sụp đổ), quá nhỏ thì học rất chậm. B ảnh hưởng mục tiêu tối ưu chứ không phải yếu tố ổn định trực tiếp. C và D chủ yếu điều chỉnh mức khám phá (entropy cũng có tác dụng ổn định nhẹ, nhưng đáp án của đề là A)."]],"rl":[["code","\\theta \\leftarrow \\theta + \\alpha \\, \\nabla_\\theta J(\\theta), \\qquad \\nabla_\\theta J(\\theta) = \\mathbb{E}_\\pi\\big[ G_t \\nabla_\\theta \\ln \\pi(A_t|S_t,\\theta) \\big]"],["p","Policy gradient có phương sai cao nên thường thêm baseline hay critic (Actor-Critic) để giảm. TRPO/PPO giới hạn độ lớn bước cập nhật để ổn định."]],"ex":[["p","α = 0.001 học ổn định nhưng chậm. α = 1 có thể đẩy xác suất một hành động lên gần 1 quá sớm và kẹt ở chính sách kém."]],"tip":[["p","\"Ổn định khi huấn luyện\" → nghĩ ngay đến learning rate (bước cập nhật)."]],"fig":false},{"id":"exam-13","part":"exam","n":13,"en":"Which of the following statements is true about Q-learning?","vi":"Phát biểu nào sau đây đúng về Q-learning?","opts":[{"l":"A","en":"It is a sample-based version of policy iteration","vi":"Đây là phiên bản dựa trên mẫu của policy iteration.","note":""},{"l":"B","en":"It uses the Bellman equation for action values","vi":"Nó dùng phương trình Bellman cho giá trị hành động.","note":""},{"l":"C","en":"It can converge to the optimal value function with sufficient exploration","vi":"Nó có thể hội tụ về hàm giá trị tối ưu nếu khám phá đủ.","note":""},{"l":"D","en":"It requires prior knowledge of the environment's dynamics","vi":"Nó cần biết trước động lực của môi trường.","note":""}],"ans":"C","ansnote":"","exp":[["p","Định lý Watkins: nếu mọi cặp (s,a) được thăm vô hạn lần và α giảm đúng điều kiện, Q hội tụ về q*. A sai vì Q-learning là phiên bản mẫu của value iteration (dùng max), không phải policy iteration. D sai vì nó model-free. B gần đúng nhưng phải là Bellman optimality equation (có max); đề chọn C vì đây là tính chất đặc trưng nhất."]],"rl":[["code","q_*(s,a) = \\sum_{s',r} p(s',r|s,a)\\Big[ r + \\gamma \\max_{a'} q_*(s',a') \\Big]"],["p","Q-learning = off-policy TD control, mục tiêu cập nhật R + γ max Q(S',a')."]],"ex":[["p","Robot dùng ε-greedy (ε = 0.1) cho đủ khám phá, sau nhiều lần thử Q hội tụ về q* dù hành vi vẫn có ngẫu nhiên."]],"tip":[["p","Q-learning ↔ Value iteration (max), Sarsa ↔ Policy iteration (theo chính sách). Nhớ cặp này để tránh bẫy A."]],"fig":false},{"id":"exam-14","part":"exam","n":14,"en":"Which dynamic programming method iteratively improves both the policy and the value function?","vi":"Phương pháp quy hoạch động nào lặp đi lặp lại để cải thiện đồng thời cả chính sách và hàm giá trị?","opts":[{"l":"A","en":"Policy iteration","vi":"Lặp chính sách.","note":""},{"l":"B","en":"Value iteration","vi":"Lặp giá trị.","note":""},{"l":"C","en":"Monte Carlo methods","vi":"Các phương pháp Monte Carlo.","note":""},{"l":"D","en":"Q-learning","vi":"Q-learning.","note":""}],"ans":"A","ansnote":"","exp":[["p","Policy iteration xen kẽ hai bước: đánh giá chính sách (tính v_π) rồi cải thiện chính sách (greedy theo v_π). B chỉ cập nhật trực tiếp hàm giá trị bằng phép max, chính sách chỉ trích ra ở cuối. C và D không phải DP vì không dùng mô hình."]],"rl":[["p","Policy iteration: π₀ → v_π₀ → π₁ → v_π₁ → ... → π*. Value iteration:"],["code","v_{k+1}(s) = \\max_a \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_k(s')\\,]"],["p","Cả hai đều cần mô hình p, và hội tụ về π*, v*. Chung ý tưởng là GPI (Generalized Policy Iteration)."]],"ex":[["p","Gridworld: đánh giá chính sách ngẫu nhiên → cập nhật greedy → đánh giá lại. Thường chỉ sau vài vòng đã ổn định."]],"tip":[["p","Policy iteration = có hai chân (evaluation + improvement). Value iteration = một chân gộp."]],"fig":false},{"id":"exam-15","part":"exam","n":15,"en":"What does the Q-learning update with function approximation replace in expected Sarsa?","vi":"Cập nhật Q-learning với xấp xỉ hàm thay thế cái gì trong Expected Sarsa?","opts":[{"l":"A","en":"The action value with a random value","vi":"Giá trị hành động bằng một giá trị ngẫu nhiên.","note":""},{"l":"B","en":"The expectation with the maximum action value","vi":"Kỳ vọng bằng giá trị hành động lớn nhất.","note":""},{"l":"C","en":"The weight vector with a fixed value","vi":"Vector trọng số bằng giá trị cố định.","note":""},{"l":"D","en":"The target policy with a uniform policy","vi":"Chính sách đích bằng chính sách đều.","note":""}],"ans":"B","ansnote":"","exp":[["p","Expected Sarsa dùng kỳ vọng Σπ(a'|S')q̂(S',a'). Q-learning thay kỳ vọng đó bằng max_a' q̂(S',a'), tức là π greedy. A, C, D không đúng với cấu trúc cập nhật."]],"rl":[["code","\\text{Expected Sarsa: } \\mathbf{w} \\leftarrow \\mathbf{w} + \\alpha \\Big[ R + \\gamma \\sum_{a'} \\pi(a'|S')\\,\\hat q(S',a',\\mathbf{w}) - \\hat q(S,A,\\mathbf{w}) \\Big] \\nabla \\hat q(S,A,\\mathbf{w})"],["code","\\text{Q-learning: } \\mathbf{w} \\leftarrow \\mathbf{w} + \\alpha \\Big[ R + \\gamma \\max_{a'} \\hat q(S',a',\\mathbf{w}) - \\hat q(S,A,\\mathbf{w}) \\Big] \\nabla \\hat q(S,A,\\mathbf{w})"]],"ex":[["p","Ở S' có q̂ = (2, 6), π đều (0.5, 0.5). Expected Sarsa dùng 0.5×2 + 0.5×6 = 4, Q-learning dùng max = 6."]],"tip":[["p","Expected = \"trung bình theo π\", Q-learning = \"lấy max\"; đặt π greedy vào Expected Sarsa thì ra Q-learning."]],"fig":false},{"id":"exam-16","part":"exam","n":16,"en":"Which property ensures that all states can be reached from any other state in an MDP?","vi":"Tính chất nào đảm bảo mọi trạng thái đều có thể đến được từ bất kỳ trạng thái nào khác trong một MDP?","opts":[{"l":"A","en":"Completeness","vi":"Tính đầy đủ.","note":""},{"l":"B","en":"Determinism","vi":"Tính xác định.","note":""},{"l":"C","en":"Ergodicity","vi":"Tính ergodic (đảng đều, liên thông).","note":""},{"l":"D","en":"Consistency","vi":"Tính nhất quán.","note":""}],"ans":"C","ansnote":"","exp":[["p","MDP ergodic là MDP mà từ mọi trạng thái có thể đến mọi trạng thái khác (dưới mọi chính sách), nên có phân phối dừng duy nhất. A và D không phải thuật ngữ chuẩn của MDP trong ngữ cảnh này. B (xác định) nói chuyện chuyển trạng thái không ngẫu nhiên, không liên quan đến khả năng đến được."]],"rl":[["p","Ergodicity quan trọng cho continuing task và average reward r(π) = Σμ_π(s)Σπ(a|s)Σp(s',r|s,a)r, vì μ_π (phân phối dừng) phải tồn tại và không phụ thuộc trạng thái ban đầu."]],"ex":[["p","Bản đồ 3 phòng mà phòng nào cũng có đường đi sang phòng khác là ergodic. Nếu có phòng \"bẫy\" vào được mà không ra được thì không ergodic."]],"tip":[["p","Ergodic = \"đi đến đâu cũng được, đi lại tự do\"."]],"fig":false},{"id":"exam-17","part":"exam","n":17,"en":"Which of the following is a potential drawback of off-policy learning?","vi":"Điều nào sau đây là nhược điểm tiềm ẩn của học off-policy?","opts":[{"l":"A","en":"It requires extensive domain knowledge","vi":"Nó đòi hỏi nhiều kiến thức chuyên môn về lĩnh vực.","note":""},{"l":"B","en":"It can lead to instability in learning","vi":"Nó có thể gây bất ổn trong quá trình học.","note":""},{"l":"C","en":"It is computationally inefficient","vi":"Nó tốn tài nguyên tính toán.","note":""},{"l":"D","en":"It is only suitable for discrete action spaces","vi":"Nó chỉ phù hợp với không gian hành động rời rạc.","note":""}],"ans":"B","ansnote":"","exp":[["p","Khi π ≠ b, ước lượng có phương sai cao (IS) và kết hợp xấp xỉ hàm + bootstrapping có thể phân kỳ. A và C không phải đặc điểm riêng. D sai vì off-policy dùng được cho hành động liên tục (ví dụ DDPG)."]],"rl":[["p","\"Deadly triad\" gồm: xấp xỉ hàm, bootstrapping, off-policy. Có đủ cả ba thì thuật toán có thể không hội tụ. Đổi lại off-policy cho phép học chính sách tối ưu từ dữ liệu của chính sách khác (experience replay, học từ demo)."]],"ex":[["p","Q-learning + mạng nơ-ron có thể dao động/phân kỳ nên DQN phải thêm target network và replay buffer."]],"tip":[["p","Off-policy = \"linh hoạt nhưng dễ lệch\": nhớ từ khóa instability / high variance."]],"fig":false},{"id":"exam-18","part":"exam","n":18,"en":"When a child learns to use a specific greeting for different individuals (e.g., 'Hi' for peers, 'Good morning' for teachers), this is an example of:","vi":"Khi một đứa trẻ học dùng lời chào riêng cho từng đối tượng (ví dụ \"Hi\" với bạn bè, \"Good morning\" với giáo viên), đây là ví dụ của:","opts":[{"l":"A","en":"Generalization","vi":"Khái quát hóa.","note":""},{"l":"B","en":"Discrimination","vi":"Phân biệt.","note":""},{"l":"C","en":"Extinction","vi":"Dập tắt (mất phản xạ).","note":""},{"l":"D","en":"Classical conditioning","vi":"Điều kiện hóa cổ điển.","note":""}],"ans":"B","ansnote":"","exp":[["p","Phản ứng khác nhau cho các kích thích tương tự nhưng khác biệt là discrimination. A là phản ứng giống nhau cho kích thích tương tự. C là phản ứng dần biến mất khi không còn được củng cố. D là gắn kích thích trung tính với kích thích vô điều kiện."]],"rl":[["p","Trong RL với xấp xỉ hàm, generalization là việc học ở một trạng thái lan sang trạng thái gần; discrimination là khả năng tách riêng giá trị của hai trạng thái gần nhau (tile nhỏ = discrimination cao, tile lớn = generalization cao)."]],"ex":[["p","Trẻ chào \"Hi\" với bạn, \"Good morning\" với cô giáo: nhận ra sự khác biệt giữa hai kích thích."]],"tip":[["p","Generalization = \"gộp chung\", Discrimination = \"tách riêng\". Hai câu 18, 37, 43 cùng chủ đề này."]],"fig":false},{"id":"exam-19","part":"exam","n":19,"en":"In which type of environments is state aggregation particularly useful?","vi":"Gom nhóm trạng thái (state aggregation) đặc biệt hữu ích trong loại môi trường nào?","opts":[{"l":"A","en":"Environments with a very small state space","vi":"Môi trường có không gian trạng thái rất nhỏ.","note":""},{"l":"B","en":"Environments with deterministic transitions","vi":"Môi trường có chuyển trạng thái xác định.","note":""},{"l":"C","en":"Environments with a very large or continuous state space","vi":"Môi trường có không gian trạng thái rất lớn hoặc liên tục.","note":""},{"l":"D","en":"Environments with no reward structure","vi":"Môi trường không có cấu trúc phần thưởng.","note":""}],"ans":"C","ansnote":"","exp":[["p","Gom nhiều trạng thái thành nhóm, mỗi nhóm dùng chung một giá trị, giúp giảm số tham số khi trạng thái quá nhiều hay liên tục. A không cần vì bảng đã đủ nhỏ. B và D không liên quan đến lợi ích của gom nhóm."]],"rl":[["p","State aggregation là trường hợp đặc biệt của xấp xỉ tuyến tính với đặc trưng one-hot: v̂(s,w) = w_{g(s)}, g(s) là nhóm chứa s. Cập nhật gradient chỉ đổi trọng số của nhóm đó."]],"ex":[["p","1000 trạng thái chia thành 10 nhóm (mỗi nhóm 100) còn 10 tham số. Nhược điểm: các trạng thái trong nhóm bị coi như giống nhau nên mất độ chi tiết."]],"tip":[["p","Aggregation = \"gom rổ\": rổ ít hơn trạng thái, dùng khi trạng thái nhiều quá hoặc liên tục."]],"fig":false},{"id":"exam-20","part":"exam","n":20,"en":"In Iterative Policy Evaluation, what does the value function represent?","vi":"Trong Iterative Policy Evaluation (đánh giá chính sách lặp), hàm giá trị biểu diễn điều gì?","opts":[{"l":"A","en":"The probability of selecting an action in a given state","vi":"Xác suất chọn một hành động tại một trạng thái.","note":""},{"l":"B","en":"The expected cumulative reward starting from a given state and following a specific policy","vi":"Phần thưởng tích lũy kỳ vọng bắt đầu từ một trạng thái và theo một chính sách cụ thể.","note":""},{"l":"C","en":"The policy's exploration rate","vi":"Tỉ lệ khám phá của chính sách.","note":""},{"l":"D","en":"The action-value function","vi":"Hàm giá trị hành động.","note":""}],"ans":"B","ansnote":"","exp":[["p","Đây là định nghĩa của v_π(s). A là bản thân chính sách π(a|s). C không phải hàm giá trị. D là q_π(s,a), có thêm hành động, khác v_π(s)."]],"rl":[["code","v_{k+1}(s) = \\sum_a \\pi(a|s) \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_k(s')\\,]"],["p","Lặp cho đến khi max_s |v_{k+1}(s) − v_k(s)| < θ nhỏ. Thuật toán dùng hai mảng V và V' (xem câu 29)."]],"ex":[["p","Gridworld 4×4, π ngẫu nhiên, reward −1 mỗi bước. Vòng lặp đầu v_1 = −1 ở mọi ô không phải đích, sau nhiều vòng hội tụ về v_π."]],"tip":[["p","v_π(s) = \"đứng ở s, làm theo π, kỳ vọng còn bao nhiêu\"; q_π(s,a) = có thêm chữ \"làm a trước\"."]],"fig":false},{"id":"exam-21","part":"exam","n":21,"en":"Which of the following is a potential disadvantage of Random Tabular Q-planning?","vi":"Điều nào sau đây là nhược điểm tiềm ẩn của Random Tabular Q-planning (lập kế hoạch Q dạng bảng ngẫu nhiên)?","opts":[{"l":"A","en":"It requires a model of the environment","vi":"Nó cần mô hình của môi trường.","note":""},{"l":"B","en":"It may converge slower due to random updates","vi":"Nó có thể hội tụ chậm hơn vì các cập nhật ngẫu nhiên.","note":""},{"l":"C","en":"It is not applicable to large state spaces","vi":"Nó không áp dụng được cho không gian trạng thái lớn.","note":""},{"l":"D","en":"It cannot handle stochastic environments","vi":"Nó không xử lý được môi trường ngẫu nhiên.","note":""}],"ans":"B","ansnote":"","exp":[["p","Thuật toán chọn (s,a) ngẫu nhiên nên nhiều cập nhật rơi vào cặp không quan trọng, gây lãng phí và hội tụ chậm. A là điều kiện của mọi phương pháp planning, không phải nhược điểm riêng. C chỉ phản ánh dạng bảng (tabular) nói chung. D sai vì dùng sample model vẫn xử lý được ngẫu nhiên."]],"rl":[["p","Mỗi bước: chọn (S,A) ngẫu nhiên, hỏi sample model lấy (R,S'), rồi cập nhật Q(S,A) ← Q(S,A) + α[R + γ max Q(S',a') − Q(S,A)]. Cải tiến: prioritized sweeping (ưu tiên cặp có sai số lớn)."]],"ex":[["p","Mê cung lớn: phần lớn cặp (s,a) chọn ngẫu nhiên là ô chưa biết giá trị (Q = 0) nên cập nhật không đổi gì."]],"tip":[["p","\"Random\" = \"may rủ\" = lãng phí; nhớ từ khóa random → slower."]],"fig":false},{"id":"exam-22","part":"exam","n":22,"en":"During the first episode, how does the robot update its action values?","vi":"Trong episode đầu tiên, robot cập nhật giá trị hành động bằng cách nào?","opts":[{"l":"A","en":"Using simulated experience","vi":"Dùng kinh nghiệm mô phỏng.","note":""},{"l":"B","en":"By exploring all possible actions","vi":"Bằng cách thử tất cả hành động có thể.","note":""},{"l":"C","en":"Through direct RL updates from real experience","vi":"Qua cập nhật RL trực tiếp từ kinh nghiệm thực.","note":""},{"l":"D","en":"By following a fixed policy","vi":"Bằng cách theo một chính sách cố định.","note":""}],"ans":"C","ansnote":"","exp":[["p","Ở episode đầu mô hình (model) còn trống nên chưa có gì để mô phỏng. Agent chỉ cập nhật trực tiếp từ những gì thực sự xảy ra. A cần model đã học. B không thực tế và không đảm bảo trong một episode. D không nói về cách cập nhật."]],"rl":[["p","Dyna-Q mỗi bước thực: (a) direct RL: Q-learning từ (S,A,R,S') thật; (b) học model: Model(S,A) ← (R,S'); (c) planning: lặp n lần cập nhật Q từ (s,a) đã thấy qua model. Planning chỉ có tác dụng khi model đã có dữ liệu."]],"ex":[["p","Dyna maze: episode 1 agent phải đi ~ hàng chục bước để tìm đích. Chiều ngược lại, từ episode 2 planning đã lan truyền giá trị nhanh."]],"tip":[["p","Chưa có model → chưa planning → chỉ direct RL."]],"fig":false},{"id":"exam-23","part":"exam","n":23,"en":"What is the primary goal when maintaining a website with millions of hits a day in the context of the k-armed bandit problem?","vi":"Khi duy trì một website có hàng triệu lượt truy cập mỗi ngày, trong bối cảnh bài toán k-armed bandit thì mục tiêu chính là gì?","opts":[{"l":"A","en":"To increase the number of ads displayed","vi":"Tăng số quảng cáo hiển thị.","note":""},{"l":"B","en":"To display the ad that generates the most money","vi":"Hiển thị quảng cáo mang lại nhiều tiền nhất.","note":""},{"l":"C","en":"To reduce the loading time of the website","vi":"Giảm thời gian tải trang.","note":""},{"l":"D","en":"To track user behavior","vi":"Theo dõi hành vi người dùng.","note":""}],"ans":"B","ansnote":"","exp":[["p","Mỗi quảng cáo là một cánh tay (arm), reward là click/doanh thu, mục tiêu là tối đa hóa reward, tức chọn quảng cáo sinh nhiều tiền nhất. A, C, D không phải mục tiêu tối ưu hóa reward của bandit."]],"rl":[["p","K-armed bandit: mỗi bước chọn một arm, nhận reward ngẫu nhiên theo phân phối của arm. Giá trị hành động: q*(a) = E[R_t | A_t = a], cần cân bằng exploration và exploitation."]],"ex":[["p","3 quảng cáo có CTR 1%, 2%, 3%. Hiển thị quảng cáo 3% nhiều nhất để tối đa doanh thu, nhưng vẫn cần thử ít quảng cáo khác."]],"tip":[["p","Bandit = \"máy đánh bạc nhiều tay\": mục tiêu là thắng nhiều tiền nhất."]],"fig":false},{"id":"exam-24","part":"exam","n":24,"en":"Which of the following statements is true about dynamic programming in reinforcement learning?","vi":"Phát biểu nào sau đây đúng về quy hoạch động trong học tăng cường?","opts":[{"l":"A","en":"It is only applicable to problems with discrete action spaces","vi":"Chỉ áp dụng cho bài toán có không gian hành động rời rạc.","note":""},{"l":"B","en":"It always guarantees convergence to the globally optimal policy","vi":"Luôn đảm bảo hội tụ về chính sách tối ưu toàn cục.","note":""},{"l":"C","en":"It is computationally efficient for problems with continuous state spaces","vi":"Hiệu quả về tính toán với không gian trạng thái liên tục.","note":""},{"l":"D","en":"It is primarily used for deep reinforcement learning tasks","vi":"Chủ yếu dùng cho các bài toán học tăng cường sâu.","note":""}],"ans":"B","ansnote":"","exp":[["p","Với MDP hữu hạn và mô hình đầy đủ, policy iteration và value iteration hội tụ về π* và v*. C sai vì DP bị curse of dimensionality, không hiệu quả với trạng thái lớn hay liên tục. D sai vì DP là phương pháp cổ điển, không phải deep RL. A sai vì chỉ là giới hạn thực dụng, không phải một phát biểu đúng về bản chất."]],"rl":[["p","DP yêu cầu mô hình đầy đủ p(s',r|s,a) và dùng bootstrapping (cập nhật dựa trên ước lượng khác). Hai thuật toán: policy iteration và value iteration (GPI)."]],"ex":[["p","Gridworld 4×4 với luật chuyển biết trước, DP tìm được π* chính xác chỉ sau vài lần lặp."]],"tip":[["p","DP = \"cần biết luật chơi, đảm bảo tối ưu, nhưng chỉ dùng được cho không gian nhỏ\"."]],"fig":false},{"id":"exam-25","part":"exam","n":25,"en":"How does coarse coding help in handling large state spaces in reinforcement learning?","vi":"Coarse coding (mã hóa thô) giúp xử lý các không gian trạng thái lớn trong học tăng cường như thế nào?","opts":[{"l":"A","en":"By dividing the state space into non-overlapping regions","vi":"Bằng cách chia không gian trạng thái thành các vùng không chồng lấn.","note":""},{"l":"B","en":"By using a high-dimensional binary feature vector for each state","vi":"Bằng cách dùng vector đặc trưng nhị phân nhiều chiều cho mỗi trạng thái.","note":""},{"l":"C","en":"By approximating value functions over a coarsely divided state space","vi":"Bằng cách xấp xỉ hàm giá trị trên một không gian trạng thái được chia thô.","note":""},{"l":"D","en":"By applying a hierarchical approach to action selection","vi":"Bằng cách áp dụng cách tiếp cận phân cấp cho việc chọn hành động.","note":""}],"ans":"C","ansnote":"theo khóa của trang","exp":[["p","Coarse coding biểu diễn trạng thái bằng các vùng (receptive field) hình tròn chồng lấn, và xấp xỉ hàm giá trị trên cách chia thô đó nên không phải lưu mỗi trạng thái riêng lẻ. A sai vì các vùng phải chồng lấn (không chồng lấn là state aggregation). D là khái niệm khác (hierarchical RL). Lưu ý: B cũng mô tả đúng một phần (đặc trưng là vector nhị phân), nhưng khóa là C, cần chọn C khi thi."]],"rl":[["p","Coarse coding: mỗi receptive field là một đặc trưng nhị phân (1 nếu trạng thái nằm trong vùng). Kích thước vùng quyết định mức generalization, số vùng quyết định độ phân giải. Tile coding là dạng coarse coding có cấu trúc lưới."]],"ex":[["p","Trạng thái 2D nằm trong 3 vòng tròn chồng nhau thì 3 đặc trưng bật (1), các đặc trưng khác tắt (0). Học ở điểm này lan sang các điểm cùng nằm trong các vòng đó."]],"tip":[["p","Coarse = \"thô\" + \"chồng lấn\". State aggregation = không chồng lấn; coarse/tile coding = chồng lấn."]],"fig":false},{"id":"exam-26","part":"exam","n":26,"en":"What is the target policy in off policy learning?","vi":"Chính sách đích (target policy) trong học off-policy là gì?","opts":[{"l":"A","en":"The policy used to select actions","vi":"Chính sách dùng để chọn hành động.","note":""},{"l":"B","en":"The policy that the agent is learning about","vi":"Chính sách mà agent đang học về nó.","note":""},{"l":"C","en":"The policy that generates data","vi":"Chính sách sinh ra dữ liệu.","note":""},{"l":"D","en":"The policy that evaluates the value function","vi":"Chính sách đánh giá hàm giá trị.","note":""}],"ans":"B","ansnote":"","exp":[["p","Target policy π là chính sách mà ta muốn ước lượng giá trị và cải thiện. A và C mô tả behavior policy b (chọn hành động và sinh dữ liệu). D không phải thuật ngữ chuẩn, hàm giá trị là thứ được đánh giá cho π chứ không phải chính sách."]],"rl":[["p","Off-policy: học v_π hoặc q_π từ dữ liệu do b sinh ra (π ≠ b). Yêu cầu coverage: π(a|s) > 0 ⇒ b(a|s) > 0. Câu này lặp lại câu 9 và 49."]],"ex":[["p","Q-learning: π là greedy (target), b là ε-greedy (behavior)."]],"tip":[["p","Target = \"cái đang học\", Behavior = \"cái đang làm\"."]],"fig":false},{"id":"exam-27","part":"exam","n":27,"en":"In the context of Deep Q-Learning, what purpose does the target network serve?","vi":"Trong Deep Q-Learning, mạng mục tiêu (target network) có mục đích gì?","opts":[{"l":"A","en":"It helps in selecting actions based on the policy","vi":"Giúp chọn hành động dựa trên chính sách.","note":""},{"l":"B","en":"It stabilizes training by providing consistent target values","vi":"Ổn định huấn luyện bằng cách cung cấp giá trị mục tiêu ổn định.","note":""},{"l":"C","en":"It generates synthetic experiences for training","vi":"Sinh kinh nghiệm tổng hợp để huấn luyện.","note":""},{"l":"D","en":"It models the transition probabilities between states","vi":"Mô hình hóa xác suất chuyển trạng thái.","note":""}],"ans":"B","ansnote":"","exp":[["p","Target network là bản sao của mạng Q, cố định trong một khoảng để \"mục tiêu\" không đổi liên tục theo mạng đang học, tránh dao động. A là vai trò của mạng online. C nói về replay/Dyna. D nói về mô hình môi trường, DQN là model-free."]],"rl":[["code","y = R + \\gamma \\max_{a'} \\hat q(S',a',\\mathbf{w}^-), \\qquad L(\\mathbf{w}) = \\mathbb{E}\\big[ (y - \\hat q(S,A,\\mathbf{w}))^2 \\big]"],["p","w⁻ là trọng số target network, sao chép từ w sau mỗi C bước. DQN còn dùng experience replay để phá tính tương quan giữa các mẫu."]],"ex":[["p","Nếu dùng cùng mạng tạo mục tiêu, mỗi lần cập nhật thì mục tiêu cũng đổi (\"đuổi theo cái bóng của mình\"). Target network giữ y ở 1.000 bước rồi mới đồng bộ."]],"tip":[["p","Target network = \"mục tiêu đứng yên\"; replay buffer = \"xáo trộn dữ liệu\"."]],"fig":false},{"id":"exam-28","part":"exam","n":28,"en":"In reinforcement learning, what is a common downside of pure exploitation without exploration?","vi":"Trong học tăng cường, nhược điểm thường gặp của việc chỉ khai thác thuần túy mà không khám phá là gì?","opts":[{"l":"A","en":"Increased computational complexity","vi":"Độ phức tạp tính toán tăng.","note":""},{"l":"B","en":"Missing out on potentially better actions that haven't been tried enough","vi":"Bỏ lỡ những hành động có thể tốt hơn mà chưa được thử đủ.","note":""},{"l":"C","en":"High variance in reward estimation","vi":"Phương sai cao khi ước lượng phần thưởng.","note":""},{"l":"D","en":"Difficulty in policy convergence to get maximum the total rewards","vi":"Khó hội tụ chính sách để đạt tổng phần thưởng tối đa.","note":""}],"ans":"B","ansnote":"","exp":[["p","Greedy thuần túy luôn chọn hành động có ước lượng cao nhất hiện tại nên có thể kẹt ở hành động \"tạm ổn\" và không bao giờ biết hành động tốt hơn. A, C không phải hệ quả trực tiếp. D là hệ quả gián tiếp (không đạt tối ưu), nhưng không phải lý do trực tiếp như B."]],"rl":[["p","Exploration vs exploitation. ε-greedy: với xác suất ε chọn ngẫu nhiên, còn lại chọn argmax Q. Optimistic initial values, UCB và softmax cũng giúp khám phá."]],"ex":[["p","Chọn mãi quán phở gần nhà vì lần đầu ngon, không bao giờ thử quán khác nên bỏ lỡ quán ngon hơn."]],"tip":[["p","Chỉ khai thác = \"ếch ngồi đáy giếng\" (bỏ lỡ điều tốt hơn)."]],"fig":false},{"id":"exam-29","part":"exam","n":29,"en":"Which of the following best describes the role of the two arrays (V and V prime) in the iterative policy evaluation algorithm?","vi":"Điều nào sau đây mô tả đúng nhất vai trò của hai mảng (V và V phẩy) trong thuật toán đánh giá chính sách lặp?","opts":[{"l":"A","en":"They store the rewards for each state","vi":"Lưu phần thưởng của mỗi trạng thái.","note":""},{"l":"B","en":"They hold the current and updated values to avoid overwriting during updates","vi":"Giữ giá trị hiện tại và giá trị cập nhật để tránh ghi đè trong khi cập nhật.","note":""},{"l":"C","en":"They represent the actions taken in each state","vi":"Biểu diễn hành động ở mỗi trạng thái.","note":""},{"l":"D","en":"They are used to track the exploration strategy","vi":"Dùng để theo dõi chiến lược khám phá.","note":""}],"ans":"B","ansnote":"","exp":[["p","V là giá trị v_k, V' là v_{k+1}. Mỗi lượt tính toàn bộ V' từ V rồi mới đổi chỗ, nên cập nhật của trạng thái này không làm hỏng giá trị cũ cần cho trạng thái khác trong cùng lượt. A, C, D không liên quan đến hai mảng này."]],"rl":[["p","Hai mảng (synchronous): V'(s) ← ΣπΣp[r + γV(s')] cho mọi s, rồi V ← V'. Có biến thể in-place (một mảng, dùng ngay giá trị mới) thường hội tụ nhanh hơn."]],"ex":[["p","Các ô A, B. Tính V'(A) dùng V(B). Nếu ghi đè V(A) ngay, thì khi tính V'(B) sẽ lỡ dùng V(A) đã đổi."]],"tip":[["p","Hai mảng = \"vở nháp và vở sạch\": viết vào vở sạch, tham khảo vở nháp."]],"fig":false},{"id":"exam-30","part":"exam","n":30,"en":"Which type of task is more likely to involve checkpoints or milestones?","vi":"Loại nhiệm vụ nào có nhiều khả năng liên quan đến các điểm kiểm tra (checkpoint) hoặc cột mốc?","opts":[{"l":"A","en":"Episodic tasks","vi":"Nhiệm vụ theo từng episode.","note":""},{"l":"B","en":"Continuing tasks","vi":"Nhiệm vụ liên tục.","note":""},{"l":"C","en":"Both episodic and continuing tasks","vi":"Cả hai loại.","note":""},{"l":"D","en":"Neither episodic nor continuing tasks","vi":"Không loại nào.","note":""}],"ans":"A","ansnote":"","exp":[["p","Episodic task có điểm bắt đầu, điểm kết thúc và trạng thái cuối rõ ràng, nên dễ chia thành các mốc (episode, mục tiêu trung gian). Continuing task không kết thúc nên không có mốc tự nhiên. C không đúng vì continuing không có điểm dừng. Lưu ý: đây là câu hỏi khá định tính, không phải thuật ngữ chuẩn."]],"rl":[["p","Episodic: G_t = R_{t+1} + … + R_T, hữu hạn, γ = 1 được. Continuing: T = ∞, cần γ < 1 (hoặc average reward) để return hữu hạn."]],"ex":[["p","Ván cờ vua (episodic, có thắng/thua) so với điều khiển nhiệt độ toà nhà chạy mãi (continuing)."]],"tip":[["p","Episodic = \"có hồi, có chap\" (chia chương, có mốc); Continuing = \"dòng sông chảy mãi\"."]],"fig":false},{"id":"exam-31","part":"exam","n":31,"en":"What does the Dyna architecture primarily combine?","vi":"Kiến trúc Dyna chủ yếu kết hợp những gì?","opts":[{"l":"A","en":"Direct RL updates and planning updates","vi":"Cập nhật RL trực tiếp và cập nhật lập kế hoạch (planning).","note":""},{"l":"B","en":"Supervised learning and unsupervised learning","vi":"Học có giám sát và không giám sát.","note":""},{"l":"C","en":"Neural networks and decision trees","vi":"Mạng nơ-ron và cây quyết định.","note":""},{"l":"D","en":"Clustering and regression","vi":"Phân cụm và hồi quy.","note":""}],"ans":"A","ansnote":"","exp":[["p","Dyna dùng cả kinh nghiệm thật (direct RL, cũng để học model) và kinh nghiệm mô phỏng từ model (planning). B, C, D là các kỹ thuật ML không liên quan đến Dyna."]],"rl":[["p","Dyna-Q mỗi bước thực: cập nhật Q từ mẫu thật, cập nhật model, rồi lặp n bước planning cập nhật Q từ mẫu mô phỏng. N càng lớn thì học càng nhanh theo số bước thực (nhưng tốn tính toán)."]],"ex":[["p","Sau khi đi 1 lần tới đích, với n = 50 agent \"ôn lại\" 50 lần trong đầu, giá trị lan ngược rất xa chỉ trong một bước thực."]],"tip":[["p","Dyna = \"học thật + tưởng tượng\" (real + imagined)."]],"fig":false},{"id":"exam-32","part":"exam","n":32,"en":"What is the primary objective in the k-armed bandit problem?","vi":"Mục tiêu chính trong bài toán k-armed bandit là gì?","opts":[{"l":"A","en":"To minimize the number of arms used","vi":"Giảm thiểu số cánh tay được sử dụng.","note":""},{"l":"B","en":"To maximize the cumulative reward over time","vi":"Tối đa hóa tổng phần thưởng tích lũy theo thời gian.","note":""},{"l":"C","en":"To balance the use of all arms equally","vi":"Dùng cân bằng tất cả các cánh tay như nhau.","note":""},{"l":"D","en":"To minimize the variance of rewards","vi":"Giảm thiểu phương sai của phần thưởng.","note":""}],"ans":"B","ansnote":"","exp":[["p","Mục tiêu là tối đa hóa tổng reward kỳ vọng sau nhiều lần kéo. A và C làm reward kém (dùng đều cả tay tối lẫn xấu). D không phải mục tiêu (chỉ quan tâm kỳ vọng)."]],"rl":[["p","Giá trị hành động q*(a) = E[R_t | A_t = a]. Ước lượng trung bình mẫu và cập nhật tăng dần:"],["code","Q_{n+1} = Q_n + \\frac{1}{n}\\,[\\,R_n - Q_n\\,]"],["p","Phải cân bằng khám phá (ε-greedy, UCB, optimistic initial values) và khai thác."]],"ex":[["p","5 máy slot, mỗi máy có lãi trung bình khác nhau; để tối đa tiền sau 1000 lượt, thử vài lần rồi tập trung vào máy tốt nhất."]],"tip":[["p","Bandit = \"tối đa tổng thưởng\", đừng nhầm với \"dùng đều các tay\"."]],"fig":false},{"id":"exam-33","part":"exam","n":33,"en":"What is the role of the exploration constant C in the Upper Confidence Bound formula used in MCTS?","vi":"Hằng số khám phá C trong công thức Upper Confidence Bound (UCB) dùng trong MCTS có vai trò gì?","opts":[{"l":"A","en":"It determines the rate at which new nodes are expanded","vi":"Quyết định tốc độ mở rộng các nút mới.","note":""},{"l":"B","en":"It scales the reward values","vi":"Điều chỉnh tỉ lệ giá trị phần thưởng.","note":""},{"l":"C","en":"It balances the trade-off between exploration and exploitation","vi":"Cân bằng giữa khám phá và khai thác.","note":""},{"l":"D","en":"It controls the depth of the search tree","vi":"Kiểm soát độ sâu của cây tìm kiếm.","note":""}],"ans":"C","ansnote":"","exp":[["p","C là hệ số nhân với số hạng \"thưởng khám phá\", C lớn thì ưu tiên nút ít được thăm, C nhỏ thì ưu tiên nút có giá trị cao. A, B, D đều không phải vai trò của C."]],"rl":[["p","UCB/UCT chọn nút con theo:"],["code","\\text{UCB}(i) = \\bar{X}_i + C \\sqrt{\\frac{\\ln N}{n_i}}"],["p","X̄_i là reward trung bình của nút i (khai thác), N là số lần thăm nút cha, n_i là số lần thăm nút i. MCTS gồm 4 bước: selection, expansion, simulation (rollout), backpropagation."]],"ex":[["p","N = 100. Nút 1: X̄ = 0.6, n = 80. Nút 2: X̄ = 0.4, n = 5. Với C = 1.4, UCB nhút 1 ≈ 0.6 + 1.4×0.24 = 0.94, nhút 2 ≈ 0.4 + 1.4×0.96 = 1.74, chọn nút 2 để khám phá."]],"tip":[["p","C = \"núm điều chỉnh độ tò mò\": càng lớn càng thích khám phá."]],"fig":false},{"id":"exam-34","part":"exam","n":34,"en":"Which parameter determines the degree of exploration in Actor-Critic with Softmax Policies?","vi":"Tham số nào quyết định mức độ khám phá trong Actor-Critic với chính sách softmax?","opts":[{"l":"A","en":"Learning rate","vi":"Tốc độ học.","note":""},{"l":"B","en":"Temperature parameter","vi":"Tham số nhiệt độ.","note":""},{"l":"C","en":"Discount factor","vi":"Hệ số chiết khấu.","note":""},{"l":"D","en":"Advantage function","vi":"Hàm lợi thế.","note":""}],"ans":"B","ansnote":"","exp":[["p","Nhiệt độ τ trong softmax quyết định chính sách \"phẳng\" (khám phá nhiều) hay \"nhọn\" (khai thác nhiều). A điều khiển tốc độ cập nhật. C điều khiển tầm nhìn xa. D là ước lượng lợi thế của hành động, không phải tham số khám phá."]],"rl":[["code","\\pi(a|s,\\theta) = \\frac{\\exp\\big(h(s,a,\\theta)/\\tau\\big)}{\\sum_{b} \\exp\\big(h(s,b,\\theta)/\\tau\\big)}"],["p","h là action preference. τ lớn → gần chính sách đều (khám phá nhiều). τ nhỏ → gần greedy. Actor cập nhật chính sách, critic ước lượng giá trị."]],"ex":[["p","h = (2, 1, 0). τ = 1 cho π ≈ (0.67, 0.24, 0.09). τ = 10 cho π ≈ (0.37, 0.33, 0.30), gần đều hơn."]],"tip":[["p","Softmax + \"nhiệt độ\" → nóng = loạn/khám phá, lạnh = chắc chắn/khai thác."]],"fig":false},{"id":"exam-35","part":"exam","n":35,"en":"Why does this TD update allow faster propagation of value information across states?","vi":"Vì sao cập nhật TD này cho phép lan truyền thông tin giá trị giữa các trạng thái nhanh hơn?","opts":[{"l":"A","en":"Because it waits until the full return is observed","vi":"Vì nó chờ đến khi quan sát được toàn bộ return.","note":""},{"l":"B","en":"Because it uses estimated future values during each update","vi":"Vì nó dùng giá trị tương lai ước lượng ở mỗi lần cập nhật.","note":""},{"l":"C","en":"Because it eliminates the need for rewards in the update rule","vi":"Vì nó không cần phần thưởng trong luật cập nhật.","note":""},{"l":"D","en":"Because it requires complete knowledge of all transitions in the environment","vi":"Vì nó đòi hỏi biết đầy đủ mọi chuyển trạng thái của môi trường.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD bootstrapping: cập nhật V(S) ngay sau một bước bằng R + γV(S'), nên thông tin từ trạng thái kế được đưa ngay về trạng thái trước. A là đặc điểm của Monte Carlo (chờ hết episode). C sai vì luật TD có R. D là đặc điểm của DP (cần mô hình), còn TD model-free."]],"rl":[["code","V(S_t) \\leftarrow V(S_t) + \\alpha\\,\\big[\\,R_{t+1} + \\gamma V(S_{t+1}) - V(S_t)\\,\\big]"],["p","TD(0) được cập nhật mỗi bước (online), MC phải chờ cuối episode. Bootstrapping có chệch nhưng phương sai thấp hơn MC."]],"ex":[["p","Chuỗi A→B→C→đích. Khi C được biết có giá trị cao, TD cập nhật B ngay ở lần sau, rồi A. MC chỉ cập nhật cả ba sau khi episode kết thúc."]],"tip":[["p","TD = \"đoán dựa trên đoán\" (bootstrapping): nhanh vì không phải chờ. Lưu ý câu hỏi gốc có đề \"this TD update\" nhưng các lựa chọn đủ để suy ra đáp án."]],"fig":false},{"id":"exam-36","part":"exam","n":36,"en":"What is the primary difference between Dyna-Q and Q-learning?","vi":"Khác biệt chính giữa Dyna-Q và Q-learning là gì?","opts":[{"l":"A","en":"Dyna-Q uses a model of the environment","vi":"Dyna-Q dùng một mô hình của môi trường.","note":""},{"l":"B","en":"Q-learning updates Q-values online","vi":"Q-learning cập nhật giá trị Q theo thời gian thực (online).","note":""},{"l":"C","en":"Q-learning is model-free, while Dyna-Q is model-based","vi":"Q-learning không cần mô hình, còn Dyna-Q dựa trên mô hình.","note":""},{"l":"D","en":"Dyna-Q is less prone to overestimation bias","vi":"Dyna-Q ít bị thiên lệch ước lượng quá cao hơn.","note":""}],"ans":"C","ansnote":"","exp":[["p","C phát biểu đầy đủ sự khác biệt cốt lõi: có mô hình để lập kế hoạch hay không. A đúng một nửa (chỉ nói Dyna-Q), B cũng đúng nhưng Dyna-Q cũng cập nhật online nên không phải điểm khác. D sai vì cả hai đều dùng max nên đều có thể ước lượng quá cao."]],"rl":[["p","Dyna-Q = Q-learning + học mô hình + planning n bước mỗi lượt thực. Q-learning thuần chỉ cập nhật từ mẫu thật (model-free)."]],"ex":[["p","Mê cung: Q-learning phải đi lại nhiều lần mới lan giá trị, Dyna-Q có thể \"nhớ\" các bước đã đi và phát lại."]],"tip":[["p","Dyna = Q-learning + mô hình. Chọn đáp án nêu rõ cặp model-free / model-based."]],"fig":false},{"id":"exam-37","part":"exam","n":37,"en":"Which principle explains why a person might fear all dogs after being bitten by one?","vi":"Nguyên tắc nào giải thích vì sao một người có thể sợ tất cả chó sau khi bị một con cắn?","opts":[{"l":"A","en":"Extinction","vi":"Dập tắt (phản xạ mất dần).","note":""},{"l":"B","en":"Generalization","vi":"Khái quát hóa.","note":""},{"l":"C","en":"Discrimination","vi":"Phân biệt.","note":""},{"l":"D","en":"Spontaneous recovery","vi":"Phục hồi tự phát.","note":""}],"ans":"B","ansnote":"","exp":[["p","Phản ứng sợ lan sang mọi kích thích tương tự (mọi con chó) là khái quát hóa. A: phản xạ yếu dần khi không còn củng cố. C: chỉ sợ con chó đã cắn, không sợ chó khác. D: phản xạ đã tắt tự xuất hiện lại."]],"rl":[["p","Trong xấp xỉ hàm, khái quát hóa cho phép học ở trạng thái này giúp trạng thái gần nó (tile lớn, coarse coding rộng). Mặt trái là mất độ chi tiết (xem câu 18 và 43)."]],"ex":[["p","Robot ngã ở một vị trí trơn và giảm giá trị cả vùng lân cận dù những chỗ đó không trơn."]],"tip":[["p","Generalization = \"gộp chung\", Discrimination = \"tách riêng\"."]],"fig":false},{"id":"exam-38","part":"exam","n":38,"en":"Why is it difficult to ensure accurate navigation for star exploration missions?","vi":"Vì sao khó đảm bảo định hướng chính xác cho các nhiệm vụ thám hiểm các vì sao?","opts":[{"l":"A","en":"Stars are invisible from Earth","vi":"Các ngôi sao không nhìn thấy từ Trái Đất.","note":""},{"l":"B","en":"There is no way to measure distances accurately in space","vi":"Không có cách đo khoảng cách chính xác trong không gian.","note":""},{"l":"C","en":"The vast distances cause significant deviations from intended paths","vi":"Khoảng cách quá lớn gây ra độ lệch đáng kể so với quỹ đạo dự định.","note":""},{"l":"D","en":"Spacecraft cannot carry enough fuel","vi":"Tàu vũ trụ không chở đủ nhiên liệu.","note":""}],"ans":"C","ansnote":"","exp":[["p","Sai số nhỏ tích lũy qua quãng đường rất dài thành độ lệch lớn. A sai vì có thể quan sát sao. B sai vì vẫn đo được khoảng cách (có sai số). D không phải lý do về độ chính xác định hướng."]],"rl":[["p","Đây là bối cảnh minh họa (cùng loạt câu 7) cho môi trường ngẫu nhiên và sai số tích lũy: lỗi nhỏ mỗi bước dẫn tới lệch lớn, nên cần học thích nghi liên tục từ phản hồi."]],"ex":[["p","Lệch 0,01 độ khi xuất phát, sau hàng trăm triệu km lệch hàng chục nghìn km."]],"tip":[["p","Câu \"kể chuyện\" thì chọn đáp án nói về bất định/sai số tích lũy."]],"fig":false},{"id":"exam-39","part":"exam","n":39,"en":"The concept of Dyna Architecture is closely associated with which field?","vi":"Khái niệm kiến trúc Dyna gắn chặt với lĩnh vực nào?","opts":[{"l":"A","en":"Artificial Intelligence","vi":"Trí tuệ nhân tạo.","note":""},{"l":"B","en":"Cybersecurity","vi":"An ninh mạng.","note":""},{"l":"C","en":"Software Engineering","vi":"Kỹ thuật phần mềm.","note":""},{"l":"D","en":"Network Management","vi":"Quản trị mạng.","note":""}],"ans":"A","ansnote":"","exp":[["p","Dyna do Richard Sutton đề xuất (1990) trong học tăng cường, một nhánh của AI. B, C, D không liên quan."]],"rl":[["p","Dyna thống nhất học và lập kế hoạch: kinh nghiệm thật vừa cập nhật giá trị vừa cập nhật mô hình, mô hình lại sinh kinh nghiệm giả để cập nhật thêm (xem câu 22, 31)."]],"ex":[["p","Dyna-Q, Dyna-Q+ (thưởng khám phá để thích nghi khi môi trường đổi)."]],"tip":[["p","Dyna ↔ Sutton ↔ RL ↔ AI. Câu \"dễ ăn điểm\"."]],"fig":false},{"id":"exam-40","part":"exam","n":40,"en":"How does the Epsilon-greedy strategy decide whether to explore or exploit?","vi":"Chiến lược ε-greedy quyết định khám phá hay khai thác như thế nào?","opts":[{"l":"A","en":"It uses a random number generator to choose between exploring or exploiting","vi":"Dùng bộ sinh số ngẫu nhiên để chọn giữa khám phá và khai thác.","note":""},{"l":"B","en":"It always explores for the first half of the time and exploits for the second half","vi":"Luôn khám phá nửa đầu thời gian và khai thác nửa sau.","note":""},{"l":"C","en":"It explores if a randomly generated number is less than epsilon","vi":"Khám phá nếu một số ngẫu nhiên sinh ra nhỏ hơn epsilon.","note":""},{"l":"D","en":"It exploits if a randomly generated number is less than epsilon","vi":"Khai thác nếu số ngẫu nhiên nhỏ hơn epsilon.","note":""}],"ans":"C","ansnote":"","exp":[["p","Sinh u ~ U(0,1): nếu u < ε thì chọn hành động ngẫu nhiên (khám phá), ngược lại chọn argmax Q. A đúng chung chung nhưng thiếu quy tắc cụ thể nên C chính xác hơn. B mô tả lịch cố định, không phải ε-greedy. D đảo ngược điều kiện."]],"rl":[["code","A = \\begin{cases} \\text{random action} & \\text{với xác suất } \\varepsilon \\\\ \\arg\\max_a Q(s,a) & \\text{với xác suất } 1-\\varepsilon \\end{cases}"],["p","Xác suất chọn hành động tốt nhất là 1 − ε + ε/|A|, mỗi hành động khác là ε/|A|."]],"ex":[["p","ε = 0,1, có 4 hành động: u = 0,05 < 0,1 chọn ngẫu nhiên; u = 0,7 chọn hành động tốt nhất. Hành động tốt nhất được chọn với xác suất 0,9 + 0,025 = 0,925."]],"tip":[["p","\"u nhỏ hơn ε thì khám phá\" (ε nhỏ nên khám phá ít khi xảy ra)."]],"fig":false},{"id":"exam-41","part":"exam","n":41,"en":"What is the primary objective of policy control in reinforcement learning?","vi":"Mục tiêu chính của bài toán điều khiển chính sách (policy control) trong học tăng cường là gì?","opts":[{"l":"A","en":"Maximizing immediate rewards","vi":"Tối đa hóa phần thưởng tức thời.","note":""},{"l":"B","en":"Minimizing state-action space","vi":"Thu nhỏ không gian trạng thái-hành động.","note":""},{"l":"C","en":"Balancing exploration and exploitation","vi":"Cân bằng giữa khám phá và khai thác.","note":""},{"l":"D","en":"Optimizing computational resources","vi":"Tối ưu tài nguyên tính toán.","note":""}],"ans":"C","ansnote":"theo khóa của trang","exp":[["p","Để tìm chính sách tốt, agent phải vừa thử hành động mới (khám phá) vừa dùng hành động đang tốt nhất (khai thác); đây là đặc trưng của thuật toán control như Sarsa, Q-learning với ε-greedy. A sai vì RL tối đa hóa return dài hạn chứ không phải reward tức thời. B và D không phải mục tiêu của control. Lưu ý: định nghĩa chặt chẽ nhất của control là \"tìm chính sách tối ưu\", nhưng trong các lựa chọn này C là phù hợp nhất."]],"rl":[["p","Prediction: ước lượng v_π. Control: tìm π*. GPI luân phiên đánh giá và cải thiện. Q-learning, Sarsa, Expected Sarsa là các thuật toán control."]],"ex":[["p","Sarsa với ε = 0,1 cải thiện chính sách dần nhưng vẫn thử 10% hành động ngẫu nhiên để không bỏ sót đường đi tốt hơn."]],"tip":[["p","Prediction = \"đánh giá\", Control = \"tìm cách chơi tốt nhất\" (cần cân bằng khám phá/khai thác)."]],"fig":false},{"id":"exam-42","part":"exam","n":42,"en":"How is the variance parameter typically represented in a Gaussian policy?","vi":"Tham số phương sai thường được biểu diễn như thế nào trong chính sách Gaussian?","opts":[{"l":"A","en":"Scalar value","vi":"Một giá trị vô hướng.","note":""},{"l":"B","en":"Vector","vi":"Một vector.","note":""},{"l":"C","en":"Matrix","vi":"Một ma trận.","note":""},{"l":"D","en":"Tensor","vi":"Một tensor.","note":""}],"ans":"C","ansnote":"theo khóa của trang","exp":[["p","Với hành động nhiều chiều, phương sai tổng quát là ma trận hiệp phương sai Σ (đường chéo là phương sai từng chiều, ngoài đường chéo là tương quan). A chỉ đúng khi hành động 1 chiều (σ² là số vô hướng). B đúng khi dùng Σ đường chéo (chỉ lưu đường chéo). D không dùng. Lưu ý: nếu đề nói 1 chiều thì đáp án sẽ là A, nhưng khóa của trang chọn C nên dùng C khi thi."]],"rl":[["code","\\pi(a|s,\\theta) = \\frac{1}{\\sqrt{(2\\pi)^k |\\Sigma|}} \\exp\\Big( -\\tfrac{1}{2}(a-\\mu)^\\top \\Sigma^{-1} (a-\\mu) \\Big)"],["p","μ(s,θ) là trung bình, Σ(s,θ) là hiệp phương sai. Gaussian policy dùng cho hành động liên tục; trường hợp 1 chiều: π(a|s) = N(μ, σ²)."]],"ex":[["p","Cánh tay robot 3 khớp: hành động là vector 3 chiều, μ là vector 3 phần tử, Σ là ma trận 3×3."]],"tip":[["p","Trung bình = vector, phương sai nhiều chiều = ma trận (hiệp phương sai)."]],"fig":false},{"id":"exam-43","part":"exam","n":43,"en":"What is discrimination in the context of learning and behavior?","vi":"Phân biệt (discrimination) trong ngữ cảnh học tập và hành vi là gì?","opts":[{"l":"A","en":"The process by which a response spreads from one specific stimulus to other stimuli that resemble the original","vi":"Quá trình một phản ứng lan từ một kích thích cụ thể sang các kích thích giống nó.","note":""},{"l":"B","en":"The ability to respond differently to similar but distinct stimuli","vi":"Khả năng phản ứng khác nhau với các kích thích giống nhau nhưng khác biệt.","note":""},{"l":"C","en":"The reinforcement of a behavior in order to increase its frequency","vi":"Việc củng cố một hành vi để tăng tần suất.","note":""},{"l":"D","en":"The gradual weakening and disappearance of a conditioned response","vi":"Sự yếu đi và biến mất dần của phản ứng có điều kiện.","note":""}],"ans":"B","ansnote":"","exp":[["p","Discrimination là phản ứng khác nhau với các kích thích tương tự. A là generalization. C là reinforcement. D là extinction."]],"rl":[["p","Bộ ba khái niệm: generalization (lan sang kích thích giống), discrimination (tách biệt kích thích giống), extinction (phản xạ mất khi không còn củng cố). Trong xấp xỉ hàm: tile nhỏ hoặc nhiều tile chồng nhau cho phép phân biệt tốt hơn."]],"ex":[["p","Chim bồ câu học mổ đèn xanh để có thức ăn nhưng không mổ đèn đỏ: nó phân biệt hai màu."]],"tip":[["p","Discrimination = \"discriminate\" = phân biệt. Cả câu 18, 37, 43 dùng cùng bộ khái niệm; học một lần dùng cho cả ba."]],"fig":false},{"id":"exam-44","part":"exam","n":44,"en":"Why is it important to specify an objective in policy evaluation under function approximation?","vi":"Vì sao cần xác định một hàm mục tiêu khi đánh giá chính sách với xấp xỉ hàm?","opts":[{"l":"A","en":"To ensure the algorithm runs faster","vi":"Để thuật toán chạy nhanh hơn.","note":""},{"l":"B","en":"To adapt weights for minimizing value error","vi":"Để điều chỉnh trọng số nhằm giảm sai số giá trị.","note":""},{"l":"C","en":"To increase the complexity of the model","vi":"Để tăng độ phức tạp của mô hình.","note":""},{"l":"D","en":"To avoid overfitting","vi":"Để tránh quá khớp.","note":""}],"ans":"B","ansnote":"","exp":[["p","Với xấp xỉ hàm, không thể làm đúng mọi trạng thái cùng lúc, nên cần mục tiêu (ví dụ Mean Squared Value Error) để biết nên ưu tiên trạng thái nào và cập nhật w để giảm sai số. A, C không phải lý do. D là mối lo của học có giám sát, không phải mục đích chính của việc đặt mục tiêu."]],"rl":[["code","\\overline{VE}(\\mathbf{w}) = \\sum_s \\mu(s)\\,\\big[\\,v_\\pi(s) - \\hat v(s,\\mathbf{w})\\,\\big]^2"],["p","μ(s) là phân phối trạng thái (mức quan tâm). Cập nhật gradient: w ← w + α [U_t − v̂(S_t,w)] ∇v̂(S_t,w), trong đó U_t là target (G_t của MC, hoặc R + γv̂(S') của TD)."]],"ex":[["p","Với 1000 trạng thái nhưng chỉ 10 trọng số, giảm lỗi ở trạng thái hay gặp (μ lớn) có thể phải đánh đổi lỗi ở trạng thái hiếm."]],"tip":[["p","Có xấp xỉ thì phải có mục tiêu: \"VE = sai số giá trị có trọng số μ\"."]],"fig":false},{"id":"exam-45","part":"exam","n":45,"en":"What is the main shape used in tile coding to partition the state space?","vi":"Hình dạng chính được dùng trong tile coding để chia không gian trạng thái là gì?","opts":[{"l":"A","en":"Circles","vi":"Hình tròn.","note":""},{"l":"B","en":"Triangles","vi":"Hình tam giác.","note":""},{"l":"C","en":"Squares","vi":"Hình vuông.","note":""},{"l":"D","en":"Hexagons","vi":"Hình lục giác.","note":""}],"ans":"C","ansnote":"","exp":[["p","Tile coding chia không gian thành lưới ô vuông (hoặc chữ nhật) và dùng nhiều lưới lệch nhau. Hình tròn là của coarse coding (câu 25). Tam giác, lục giác có thể dùng được nhưng không phải dạng chuẩn."]],"rl":[["p","Mỗi tiling là một lưới ô; mỗi trạng thái rơi vào đúng một tile của mỗi tiling, đặc trưng là vector nhị phân với số phần tử bằng 1 cố định bằng số tiling. Thường chia bước học: α = α₀ / (số tiling)."]],"ex":[["p","8 tiling mỗi cái 10×10 lệch nhau: mỗi trạng thái bật 8 đặc trưng trong tổng 800."]],"tip":[["p","Tile = \"viên gạch\" lát nền = hình vuông. Coarse coding = \"vòng tròn\"."]],"fig":false},{"id":"exam-46","part":"exam","n":46,"en":"What is the task of policy evaluation?","vi":"Nhiệm vụ của đánh giá chính sách (policy evaluation) là gì?","opts":[{"l":"A","en":"To find a new policy that maximizes rewards","vi":"Tìm một chính sách mới tối đa hóa phần thưởng.","note":""},{"l":"B","en":"To determine the state value function for a specific policy","vi":"Xác định hàm giá trị trạng thái cho một chính sách cụ thể.","note":""},{"l":"C","en":"To compute the dynamics of the environment","vi":"Tính động lực học của môi trường.","note":""},{"l":"D","en":"To reduce the problem of finding v pi to a system of linear equations","vi":"Đưa bài toán tìm v_π về hệ phương trình tuyến tính.","note":""}],"ans":"B","ansnote":"","exp":[["p","Policy evaluation = prediction: cho π, tính v_π. A là nhiệm vụ của control/improvement. C là việc học model. D là một cách giải (trực tiếp), không phải bản thân nhiệm vụ."]],"rl":[["p","Bellman expectation:"],["code","v_\\pi(s) = \\sum_a \\pi(a|s) \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_\\pi(s')\\,]"],["p","Với |S| trạng thái là hệ |S| phương trình tuyến tính (giải trực tiếp O(|S|³)) hoặc lặp (iterative policy evaluation)."]],"ex":[["p","Đánh giá chính sách \"rẽ trái 50%, phải 50%\" trên bản đồ để biết ô nào \"tốt\" dưới chính sách đó."]],"tip":[["p","Evaluation = \"chấm điểm\" cho một π; Improvement = \"sửa π để điểm cao hơn\"."]],"fig":false},{"id":"exam-47","part":"exam","n":47,"en":"What is the common parameterized function used in reinforcement learning to approximate value functions?","vi":"Hàm có tham số phổ biến nào được dùng trong học tăng cường để xấp xỉ hàm giá trị?","opts":[{"l":"A","en":"Linear regression","vi":"Hồi quy tuyến tính.","note":""},{"l":"B","en":"Polynomial regression","vi":"Hồi quy đa thức.","note":""},{"l":"C","en":"Neural networks","vi":"Mạng nơ-ron.","note":""},{"l":"D","en":"Decision trees","vi":"Cây quyết định.","note":""}],"ans":"C","ansnote":"","exp":[["p","Mạng nơ-ron là hàm tham số phi tuyến mạnh, huấn luyện bằng gradient, thường dùng nhất trong RL hiện đại (DQN). A, B (cũng là tuyến tính theo tham số) vẫn dùng được nhưng biểu diễn yếu hơn. D không khả vi theo tham số nên khó dùng cập nhật gradient."]],"rl":[["p","xấp xỉ v̂(s,w) ≈ v_π(s), w được cập nhật bằng (semi-)gradient descent. Tuyến tính: v̂ = wᵀx(s). Phi tuyến: mạng nơ-ron nhiều lớp (backprop)."]],"ex":[["p","DQN dùng CNN nhận ảnh game Atari, đầu ra là Q cho mỗi hành động."]],"tip":[["p","\"Parameterized function\" hiện đại = neural network."]],"fig":false},{"id":"exam-48","part":"exam","n":48,"en":"What is the typical initial value for the Q-table in Q-learning?","vi":"Giá trị khởi tạo thường gặp của bảng Q trong Q-learning là gì?","opts":[{"l":"A","en":"Random values","vi":"Các giá trị ngẫu nhiên.","note":""},{"l":"B","en":"Infinity","vi":"Vô cùng.","note":""},{"l":"C","en":"Zero","vi":"Bằng 0.","note":""},{"l":"D","en":"One","vi":"Bằng 1.","note":""}],"ans":"C","ansnote":"","exp":[["p","Thông thường khởi tạo Q(s,a) = 0 (và Q của trạng thái kết thúc = 0). A dùng được nhưng không phổ biến. B gây lỗi số học (vô cùng không cập nhật được). D là giá trị lạc quan nhỏ tuỳ bài, không phải mặc định."]],"rl":[["p","Khởi tạo là lựa chọn, ví dụ Q = 0 (trung tính), Q lớn (optimistic, khuyến khích khám phá — xem câu 4). Q(terminal, ·) = 0 theo quy ước."]],"ex":[["p","Bảng Q 5 trạng thái × 4 hành động: np.zeros((5, 4))."]],"tip":[["p","Không biết gì thì bắt đầu từ 0."]],"fig":false},{"id":"exam-49","part":"exam","n":49,"en":"In Off-policy Learning, why must the behavior policy b cover the target policy π?","vi":"Trong học Off-policy, vì sao chính sách hành vi b phải \"phủ\" (cover) chính sách đích π?","opts":[{"l":"A","en":"To ensure equal probability for all actions in each state","vi":"Để đảm bảo xác suất bằng nhau cho mọi hành động ở mỗi trạng thái.","note":""},{"l":"B","en":"To guarantee that actions used by π can also be sampled by b","vi":"Để đảm bảo các hành động mà π dùng cũng có thể được b lấy mẫu.","note":""},{"l":"C","en":"To force the behavior policy to match the target policy exactly","vi":"Để ép b trùng khớp hoàn toàn với π.","note":""},{"l":"D","en":"To ensure that each state is visited only once during training","vi":"Để mỗi trạng thái chỉ được ghé thăm một lần.","note":""}],"ans":"B","ansnote":"","exp":[["p","Nếu π(a|s) > 0 mà b(a|s) = 0 thì không bao giờ có dữ liệu về hành động đó, và tỉ số π/b không xác định. A, C không đúng vì b không cần đều hay giống π (nếu giống thì là on-policy). D không liên quan."]],"rl":[["p","Điều kiện coverage (assumption of coverage): π(a|s) > 0 ⇒ b(a|s) > 0. Xem câu 2, 9, 26 về ρ = π/b."]],"ex":[["p","π chọn trái/phải/lên. Nếu b không bao giờ chọn \"lên\" thì không thể đánh giá π vì thiếu mẫu \"lên\"."]],"tip":[["p","Cover = \"b phải từng làm mọi việc mà π có thể làm\"."]],"fig":false},{"id":"exam-50","part":"exam","n":50,"en":"Which algorithm is commonly used to estimate action values in model-free reinforcement learning?","vi":"Thuật toán nào thường được dùng để ước lượng giá trị hành động trong học tăng cường không mô hình (model-free)?","opts":[{"l":"A","en":"Monte Carlo Methods","vi":"Các phương pháp Monte Carlo.","note":""},{"l":"B","en":"Value Iteration","vi":"Lặp giá trị.","note":""},{"l":"C","en":"Q-Learning","vi":"Q-learning.","note":""},{"l":"D","en":"Policy Gradient Methods","vi":"Các phương pháp gradient chính sách.","note":""}],"ans":"C","ansnote":"","exp":[["p","Q-learning ước lượng trực tiếp Q(s,a), không cần model. B là DP, cần model. D tham số hóa chính sách chứ không ước lượng Q trực tiếp. A (MC) cũng ước lượng được Q và cũng model-free, nhưng trang chọn C vì Q-learning là thuật toán điển hình nhất."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\,\\big[\\,R + \\gamma \\max_{a'} Q(S',a') - Q(S,A)\\,\\big]"],["p","Model-free: Q-learning, Sarsa, Expected Sarsa, MC. Model-based: DP, Dyna, MCTS."]],"ex":[["p","Agent học chơi game chỉ qua (s,a,r,s') quan sát được, không biết luật chơi."]],"tip":[["p","\"Estimate action values model-free\" là từ khóa của Q-learning (Q = action value)."]],"fig":false},{"id":"exam-51","part":"exam","n":51,"en":"Which algorithm is commonly used for off-policy learning in reinforcement learning?","vi":"Thuật toán nào thường được dùng cho học off-policy trong học tăng cường?","opts":[{"l":"A","en":"Q-learning","vi":"Q-learning.","note":""},{"l":"B","en":"SARSA","vi":"SARSA.","note":""},{"l":"C","en":"Deep Q-Network (DQN)","vi":"Mạng Q sâu (DQN).","note":""},{"l":"D","en":"Policy Gradient","vi":"Gradient chính sách.","note":""}],"ans":"A","ansnote":"","exp":[["p","Q-learning là thuật toán off-policy kinh điển: cập nhật bằng max Q(S',a') (chính sách đích greedy) trong khi hành vi theo ε-greedy. B (SARSA) là on-policy vì dùng đúng hành động A' mà chính sách đang chọn. C (DQN) thực ra cũng off-policy nhưng nó là mở rộng của Q-learning, nên đáp án gốc là A. D thường là on-policy (REINFORCE, A2C)."]],"rl":[["code","\\text{Q-learning: } Q(S,A) \\leftarrow Q(S,A) + \\alpha[R + \\gamma \\max_{a'} Q(S',a') - Q(S,A)]"],["code","\\text{Sarsa: } Q(S,A) \\leftarrow Q(S,A) + \\alpha[R + \\gamma Q(S',A') - Q(S,A)]"]],"ex":[["p","Robot đi theo ε-greedy (b) nhưng bảng Q hội tụ về q*, tức học chính sách greedy tối ưu (π)."]],"tip":[["p","Q-learning = \"Q có max\" = off-policy. Sarsa có đủ 5 phần tử S,A,R,S',A' = on-policy."]],"fig":false},{"id":"exam-52","part":"exam","n":52,"en":"What is one advantage of Temporal Difference (TD) methods over Dynamic Programming (DP) and Monte Carlo methods?","vi":"Một ưu điểm của các phương pháp Temporal Difference (TD) so với Quy hoạch động (DP) và Monte Carlo là gì?","opts":[{"l":"A","en":"TD methods are guaranteed to converge to the optimal solution","vi":"TD đảm bảo hội tụ về nghiệm tối ưu.","note":""},{"l":"B","en":"TD methods do not require knowledge of the complete environment dynamics","vi":"TD không cần biết đầy đủ động lực của môi trường.","note":""},{"l":"C","en":"TD methods are computationally less expensive","vi":"TD tốn ít tính toán hơn.","note":""},{"l":"D","en":"TD methods can handle only episodic tasks efficiently","vi":"TD chỉ xử lý hiệu quả nhiệm vụ theo episode.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD là model-free (khác DP cần p(s',r|s,a)) và còn cập nhật ngay mỗi bước, không phải chờ hết episode như MC. A sai vì TD(0) cho prediction hội tụ về v_π chứ không tự đảm bảo \"tối ưu\". C chưa chắc đúng. D sai vì TD dùng được cả continuing task."]],"rl":[["p","Bảng so sánh ngắn: DP cần model + bootstrapping; MC không cần model, không bootstrapping, chờ hết episode; TD không cần model, có bootstrapping, cập nhật mỗi bước."],["code","V(S_t) \\leftarrow V(S_t) + \\alpha[R_{t+1} + \\gamma V(S_{t+1}) - V(S_t)]"]],"ex":[["p","Dự đoán thời gian đi làm: TD điều chỉnh dự đoán ngay khi gặp kẹt xe ở giữa đường, MC phải chờ đến công ty mới cập nhật."]],"tip":[["p","TD = \"MC + DP\": lấy ưu điểm model-free của MC và bootstrapping của DP."]],"fig":false},{"id":"exam-53","part":"exam","n":53,"en":"What type of learning method is Monte Carlo prediction classified as?","vi":"Dự đoán Monte Carlo được xếp vào loại phương pháp học nào?","opts":[{"l":"A","en":"Supervised learning","vi":"Học có giám sát.","note":""},{"l":"B","en":"Unsupervised learning","vi":"Học không giám sát.","note":""},{"l":"C","en":"Semi-supervised learning","vi":"Học bán giám sát.","note":""},{"l":"D","en":"Reinforcement learning","vi":"Học tăng cường.","note":""}],"ans":"D","ansnote":"","exp":[["p","MC prediction học từ tương tác với môi trường, nhận reward và ước lượng giá trị từ return, đây là RL. A cần nhãn đúng có sẵn, B tìm cấu trúc dữ liệu không nhãn, C kết hợp ít nhãn với nhiều dữ liệu không nhãn; không cái nào đúng với MC."]],"rl":[["p","RL khác ML khác ở chỗ: tín hiệu học là reward (không có nhãn đúng), hành động ảnh hưởng dữ liệu tương lai, và có đánh đổi khám phá/khai thác."]],"ex":[["p","Chơi cờ: không ai cho biết nước đi đúng, chỉ có kết quả thắng/thua cuối ván (return)."]],"tip":[["p","Bất cứ phương pháp nào có reward và return (MC, TD, DP, Q-learning) đều thuộc RL."]],"fig":false},{"id":"exam-54","part":"exam","n":54,"en":"Which of the following is a characteristic of temporal-difference learning algorithms?","vi":"Đặc điểm nào sau đây là của các thuật toán học temporal-difference?","opts":[{"l":"A","en":"They require labeled data for training","vi":"Cần dữ liệu có nhãn để huấn luyện.","note":""},{"l":"B","en":"They learn from delayed rewards","vi":"Học từ các phần thưởng trì hoãn.","note":""},{"l":"C","en":"They are only applicable in stationary environments","vi":"Chỉ áp dụng được cho môi trường tĩnh.","note":""},{"l":"D","en":"They rely solely on a pre-defined set of rules","vi":"Chỉ dựa vào một bộ luật định sẵn.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD truyền thông tin từ reward về các trạng thái trước nó bằng bootstrapping, nên học được từ reward đến muộn (credit assignment). A sai vì RL không cần nhãn. C sai vì dùng step-size cố định, TD thích nghi được môi trường thay đổi. D sai vì nó học chứ không theo luật cố định."]],"rl":[["p","Delayed reward + credit assignment là thách thức cốt lõi của RL; TD dùng sai số TD δ = R + γV(S') − V(S) để đổ credit ngược dần."]],"ex":[["p","Trong mê cung chỉ có reward ở đích; sau vài episode, các ô gần đích có V cao, rồi giá trị lan dần về ô xuất phát."]],"tip":[["p","TD = \"học từ chênh lệch dự đoán\" + \"reward đến chậm vẫn học được\"."]],"fig":false},{"id":"exam-55","part":"exam","n":55,"en":"Which of the following statements about Monte Carlo methods is true?","vi":"Phát biểu nào sau đây về các phương pháp Monte Carlo là đúng?","opts":[{"l":"A","en":"Monte Carlo methods require knowledge of the environment's model","vi":"MC cần biết mô hình của môi trường.","note":""},{"l":"B","en":"Monte Carlo methods update action values incrementally during an episode","vi":"MC cập nhật giá trị hành động dần dần trong lúc episode đang diễn ra.","note":""},{"l":"C","en":"Monte Carlo methods update action values only at the end of an episode","vi":"MC chỉ cập nhật giá trị hành động khi episode kết thúc.","note":""},{"l":"D","en":"Monte Carlo methods can only be applied to deterministic environments","vi":"MC chỉ áp dụng được cho môi trường xác định.","note":""}],"ans":"C","ansnote":"","exp":[["p","MC cần return G_t đầy đủ nên phải chờ đến hết episode. A sai (model-free). B là đặc điểm của TD. D sai vì MC dùng tốt cho môi trường ngẫu nhiên (lấy trung bình mẫu)."]],"rl":[["p","MC chỉ cho episodic task, không bootstrapping, ước lượng không chệch nhưng phương sai cao. Có thể cập nhật tăng dần theo công thức:"],["code","V(S_t) \\leftarrow V(S_t) + \\alpha\\,[\\,G_t - V(S_t)\\,]"]],"ex":[["p","Chơi một ván cờ xong mới biết thắng/thua, rồi mới cập nhật toàn bộ các thế cờ đã đi qua."]],"tip":[["p","MC = \"Mãi đến cuối\" (chờ hết episode); TD = \"Từng Điểm\" (từng bước)."]],"fig":false},{"id":"exam-56","part":"exam","n":56,"en":"Why is maintaining exploration important in Monte-Carlo methods?","vi":"Vì sao việc duy trì khám phá lại quan trọng trong các phương pháp Monte Carlo?","opts":[{"l":"A","en":"To ensure rapid convergence","vi":"Để đảm bảo hội tụ nhanh.","note":""},{"l":"B","en":"To prevent the algorithm from getting stuck in local optima","vi":"Để tránh thuật toán kẹt ở tối ưu cục bộ.","note":""},{"l":"C","en":"To reduce memory usage","vi":"Để giảm bộ nhớ sử dụng.","note":""},{"l":"D","en":"To increase the speed of computation","vi":"Để tăng tốc độ tính toán.","note":""}],"ans":"B","ansnote":"","exp":[["p","MC control chỉ ước lượng được giá trị của hành động mà nó đã thử. Nếu không khám phá, agent bám vào hành động hiện tốt nhất và bỏ lỡ hành động tốt hơn, tức kẹt ở chính sách kém. A, C, D đều sai vì khám phá làm chậm hơn chứ không nhanh hơn, và không liên quan đến bộ nhớ hay tốc độ."]],"rl":[["p","Cách duy trì khám phá trong MC: exploring starts (bắt đầu từ mọi cặp (s,a)), ε-soft policy (mọi hành động có xác suất ≥ ε/|A|), hoặc off-policy với b khám phá."]],"ex":[["p","Chỉ đi món ăn quen thuộc thì không bao giờ biết có quán ngon hơn."]],"tip":[["p","Không khám phá = đóng cửa với thông tin mới, nên bị kẹt."]],"fig":false},{"id":"exam-57","part":"exam","n":57,"en":"Which of the following statements is true regarding the update rule of Expected Sarsa?","vi":"Phát biểu nào sau đây đúng về luật cập nhật của Expected Sarsa?","opts":[{"l":"A","en":"It only updates based on the greedy action","vi":"Chỉ cập nhật dựa trên hành động greedy.","note":""},{"l":"B","en":"It updates based on a weighted sum of Q-values for all possible actions","vi":"Cập nhật dựa trên tổng có trọng số các giá trị Q của mọi hành động có thể.","note":""},{"l":"C","en":"It requires the entire model of the environment","vi":"Cần toàn bộ mô hình môi trường.","note":""},{"l":"D","en":"It updates based on the worst possible action","vi":"Cập nhật dựa trên hành động tệ nhất.","note":""}],"ans":"B","ansnote":"","exp":[["p","Expected Sarsa dùng kỳ vọng Σ π(a'|S') Q(S',a'), tức tổng có trọng số theo xác suất chọn của chính sách. A là Q-learning. C sai vì nó model-free. D không phải thuật toán nào."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\Big[R + \\gamma \\sum_{a'} \\pi(a'|S')\\,Q(S',a') - Q(S,A)\\Big]"],["p","Nếu π là greedy thì Expected Sarsa trở thành Q-learning."]],"ex":[["p","ε-greedy ε = 0,1, 2 hành động, Q(S',·) = (4, 2): E = 0,95×4 + 0,05×2 = 3,9 (Q-learning dùng 4)."]],"tip":[["p","Expected = \"kỳ vọng\" = \"trung bình có trọng số theo π\"."]],"fig":false},{"id":"exam-58","part":"exam","n":58,"en":"What is the primary objective of Random Tabular Q-planning in reinforcement learning?","vi":"Mục tiêu chính của Random Tabular Q-planning trong học tăng cường là gì?","opts":[{"l":"A","en":"To find the shortest path in a graph","vi":"Tìm đường đi ngắn nhất trên đồ thị.","note":""},{"l":"B","en":"To estimate the value function for a policy","vi":"Ước lượng hàm giá trị cho một chính sách.","note":""},{"l":"C","en":"To optimize the policy for better future rewards","vi":"Tối ưu chính sách để đạt phần thưởng tương lai tốt hơn.","note":""},{"l":"D","en":"To model the environment dynamics","vi":"Mô hình hóa động lực môi trường.","note":""}],"ans":"C","ansnote":"","exp":[["p","Planning dùng mô hình để cập nhật Q (điều khiển) nhằm cải thiện chính sách. A không phải bài toán đồ thị. B là prediction, trong khi Q-planning hướng tới control (cập nhật Q bằng max). D là đầu vào của planning chứ không phải mục tiêu."]],"rl":[["p","Random-sample one-step tabular Q-planning: lặp lại chọn (S,A) ngẫu nhiên, hỏi sample model lấy (R,S'), cập nhật Q(S,A) ← Q(S,A) + α[R + γ max Q(S',a') − Q(S,A)]. Xem câu 21."]],"ex":[["p","Sau khi học model của mê cung, agent \"nghiền ngẫm\" hàng nghìn lần cập nhật Q mà không cần đi thật."]],"tip":[["p","Q-planning = Q-learning chạy trên dữ liệu từ model."]],"fig":false},{"id":"exam-59","part":"exam","n":59,"en":"What distinguishes Temporal Difference (TD) methods from Monte Carlo methods regarding the handling of incomplete episodes?","vi":"Điểm nào phân biệt TD với Monte Carlo trong việc xử lý các episode chưa hoàn tất?","opts":[{"l":"A","en":"TD methods require complete episodes for updating values","vi":"TD cần episode hoàn chỉnh để cập nhật.","note":""},{"l":"B","en":"TD methods update values based on incomplete episodes","vi":"TD cập nhật giá trị dựa trên các episode chưa hoàn tất.","note":""},{"l":"C","en":"TD methods cannot handle incomplete episodes efficiently","vi":"TD không xử lý hiệu quả episode chưa hoàn tất.","note":""},{"l":"D","en":"TD methods do not rely on experiences for learning","vi":"TD không dựa vào kinh nghiệm để học.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD cần một bước (S,A,R,S') là cập nhật được, nên dùng được cho episode dài hoặc cả continuing task. A, C là đặc điểm của MC. D sai vì TD học từ kinh nghiệm."]],"rl":[["p","TD(0) đủ dùng để online. MC cần G_t cuối episode. Giữa hai cực là n-step TD và TD(λ)."]],"ex":[["p","Robot đi mãi không dừng (continuing): TD vẫn học từng bước, MC không biết khi nào để cập nhật."]],"tip":[["p","TD = \"học dần từng bước\", MC = \"chờ trọn chương mới học\"."]],"fig":false},{"id":"exam-60","part":"exam","n":60,"en":"How does Expected Sarsa reduce the variance in Q-value updates compared to Q-learning?","vi":"Expected Sarsa giảm phương sai trong cập nhật giá trị Q so với Q-learning bằng cách nào?","opts":[{"l":"A","en":"By using a fixed learning rate","vi":"Dùng tốc độ học cố định.","note":""},{"l":"B","en":"By averaging over all possible actions","vi":"Lấy trung bình trên mọi hành động có thể.","note":""},{"l":"C","en":"By always selecting the action with the highest Q-value","vi":"Luôn chọn hành động có Q cao nhất.","note":""},{"l":"D","en":"By ignoring the reward signal","vi":"Bỏ qua tín hiệu phần thưởng.","note":""}],"ans":"B","ansnote":"","exp":[["p","Thay vì dùng một hành động A' lấy mẫu (ngẫu nhiên), Expected Sarsa tính trung bình đúng theo π, loại bỏ phương sai do chọn A'. A không liên quan đến phương sai của target. C là Q-learning (greedy). D vô lý vì reward là phần cốt lõi."]],"rl":[["p","Phương sai của target Sarsa ≥ Expected Sarsa vì Expected Sarsa khử ngẫu nhiên chọn A'. Đổi lại tốn thêm tính toán một tổng trên |A| hành động mỗi bước."]],"ex":[["p","Sarsa có lúc chọn A' tồi (do ε) làm target nhảy mạnh, Expected Sarsa luôn dùng cùng một giá trị trung bình."]],"tip":[["p","Expected Sarsa = \"lấy trung bình\" → ít giật cục, ổn định hơn."]],"fig":false},{"id":"exam-61","part":"exam","n":61,"en":"How can overfitting be addressed in machine learning models?","vi":"Có thể xử lý hiện tượng quá khớp (overfitting) trong các mô hình học máy như thế nào?","opts":[{"l":"A","en":"By reducing the complexity of the model","vi":"Bằng cách giảm độ phức tạp của mô hình.","note":""},{"l":"B","en":"By increasing the complexity of the model","vi":"Bằng cách tăng độ phức tạp của mô hình.","note":""},{"l":"C","en":"By ignoring the validation data","vi":"Bằng cách bỏ qua dữ liệu kiểm định.","note":""},{"l":"D","en":"By introducing more noise into the training data","vi":"Bằng cách thêm nhiều nhiễu vào dữ liệu huấn luyện.","note":""}],"ans":"A","ansnote":"","exp":[["p","Overfitting xảy ra khi mô hình quá phức tạp nên học thuộc cả nhiễu của dữ liệu huấn luyện. Giảm độ phức tạp (ít tham số, regularization, early stopping) giúp khái quát hóa tốt hơn. B làm tệ hơn. C sai vì dữ liệu validation chính là thứ phát hiện overfitting. D không phải cách chữa (chỉ thêm nhiễu có kiểm soát như data augmentation mới hỗ trợ)."]],"rl":[["p","Trong RL với xấp xỉ hàm, overfitting có thể xảy ra khi mạng quá lớn so với lượng kinh nghiệm. Các biện pháp: mạng nhỏ hơn, L2/weight decay, dropout, thêm dữ liệu (experience replay lớn)."]],"ex":[["p","Đa thức bậc 15 khớp 20 điểm rất sát nhưng dự đoán tệ ở điểm mới. Giảm xuống bậc 3 thì tổng quát tốt hơn."]],"tip":[["p","Overfit = \"học vẹt\". Cách chữa: đơn giản hóa mô hình, thêm dữ liệu, regularize."]],"fig":false},{"id":"exam-62","part":"exam","n":62,"en":"In the SARSA algorithm, what role does the learning rate (alpha) play?","vi":"Trong thuật toán SARSA, tốc độ học (alpha) đóng vai trò gì?","opts":[{"l":"A","en":"It determines how much new information overrides the old information","vi":"Nó quyết định thông tin mới ghi đè thông tin cũ nhiều hay ít.","note":""},{"l":"B","en":"It sets the probability of taking a random action","vi":"Nó đặt xác suất chọn hành động ngẫu nhiên.","note":""},{"l":"C","en":"It defines the discount factor for future rewards","vi":"Nó xác định hệ số chiết khấu cho phần thưởng tương lai.","note":""},{"l":"D","en":"It specifies the exploration-exploitation trade-off","vi":"Nó xác định sự đánh đổi khám phá-khai thác.","note":""}],"ans":"A","ansnote":"","exp":[["p","α là bước học: Q mới = (1 − α)·Q cũ + α·target. B là ε, C là γ, D là ε (hoặc τ, c) chứ không phải α."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\,[\\,R + \\gamma Q(S',A') - Q(S,A)\\,] = (1-\\alpha)Q(S,A) + \\alpha\\,[\\,R + \\gamma Q(S',A')\\,]"],["p","α = 0: không học gì. α = 1: bỏ hẳn giá trị cũ. Môi trường ngẫu nhiên nên dùng α nhỏ."]],"ex":[["p","Q cũ = 2, target = 6, α = 0,25 cho Q mới = 2 + 0,25×4 = 3."]],"tip":[["p","α = \"bước\" (alpha, step). ε = khám phá. γ = tầm nhìn xa (xem câu 1, 3)."]],"fig":false},{"id":"exam-63","part":"exam","n":63,"en":"What is the primary purpose of Dyna Architecture?","vi":"Mục đích chính của kiến trúc Dyna là gì?","opts":[{"l":"A","en":"To develop operating systems","vi":"Để phát triển hệ điều hành.","note":""},{"l":"B","en":"To design scalable web servers","vi":"Để thiết kế máy chủ web có khả năng mở rộng.","note":""},{"l":"C","en":"To model complex dynamic systems","vi":"Để mô hình hóa các hệ thống động phức tạp.","note":""},{"l":"D","en":"To manage database transactions","vi":"Để quản lý giao dịch cơ sở dữ liệu.","note":""}],"ans":"C","ansnote":"theo khóa của trang","exp":[["p","A, B, D thuộc lĩnh vực phần mềm khác nên loại ngay. C là lựa chọn liên quan nhất đến việc học mô hình động lực của môi trường. Mục đích thật sự của Dyna: tích hợp học từ kinh nghiệm, học mô hình và lập kế hoạch trong một vòng lặp."]],"rl":[["p","Dyna (Sutton 1990): direct RL + model learning + planning. Xem câu 22, 31, 36, 39."]],"ex":[["p","Dyna-Q trên mê cung: mỗi bước thực, thêm 50 bước planning từ model."]],"tip":[["p","Dyna = \"Dyna\" mic → model of dynamics. Phản xạ: câu nào nói OS/web/DB đều là bẫy."]],"fig":false},{"id":"exam-64","part":"exam","n":64,"en":"What does Temporal Difference (TD) learning combine?","vi":"Học Temporal Difference (TD) kết hợp những gì?","opts":[{"l":"A","en":"Monte Carlo methods and dynamic programming","vi":"Các phương pháp Monte Carlo và quy hoạch động.","note":""},{"l":"B","en":"Supervised learning and unsupervised learning","vi":"Học có giám sát và không giám sát.","note":""},{"l":"C","en":"Gradient descent and stochastic gradient descent","vi":"Gradient descent và SGD.","note":""},{"l":"D","en":"Neural networks and decision trees","vi":"Mạng nơ-ron và cây quyết định.","note":""}],"ans":"A","ansnote":"","exp":[["p","TD lấy từ MC việc học trực tiếp từ kinh nghiệm không cần model, và lấy từ DP việc bootstrapping (cập nhật dựa trên ước lượng khác). B, C, D không liên quan."]],"rl":[["code","\\underbrace{R_{t+1} + \\gamma V(S_{t+1})}_{\\text{TD target (bootstrapping, như DP)}} \\quad \\text{vs.} \\quad \\underbrace{G_t}_{\\text{MC target (mẫu thật)}}"]],"ex":[["p","Trên lộ trình đi làm, TD điều chỉnh dự đoán thời gian ngay khi thấy kẹt xe (mẫu thật + ước lượng tiếp theo)."]],"tip":[["p","TD = MC + DP (xem câu 52)."]],"fig":false},{"id":"exam-65","part":"exam","n":65,"en":"In Q-learning, what role does the learning rate (alpha) play in the update rule?","vi":"Trong Q-learning, tốc độ học (alpha) đóng vai trò gì trong luật cập nhật?","opts":[{"l":"A","en":"It determines how much the current Q-value is updated","vi":"Nó quyết định mức độ cập nhật giá trị Q hiện tại.","note":""},{"l":"B","en":"It determines how often the policy is changed","vi":"Nó quyết định tần suất thay đổi chính sách.","note":""},{"l":"C","en":"It sets the exploration rate","vi":"Nó đặt tỉ lệ khám phá.","note":""},{"l":"D","en":"It sets the discount factor for future rewards","vi":"Nó đặt hệ số chiết khấu.","note":""}],"ans":"A","ansnote":"","exp":[["p","Đây là bản Q-learning của câu 62: α điều tiết bước cập nhật Q về phía target. B, C, D lần lượt là vai trò của các yếu tố khác (cải thiện chính sách là do greedy, khám phá là ε, chiết khấu là γ)."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\,\\big[\\,R + \\gamma \\max_{a'} Q(S',a') - Q(S,A)\\,\\big]"],["p","Trong môi trường tĩnh, tốc độ học thường giảm dần (α_n = 1/n) để hội tụ; α cố định giúp theo dõi môi trường thay đổi."]],"ex":[["p","α = 0,1: mỗi lần chỉ nhích Q 10% về phía target nên học ổn định. α = 1: Q nhảy thẳng đến target."]],"tip":[["p","α ở Q-learning, Sarsa, TD đều là \"bước học\". Gặp câu nào hỏi \"learning rate\" là chọn \"mức độ cập nhật\"."]],"fig":false},{"id":"exam-66","part":"exam","n":66,"en":"What is one of the main challenges when using distribution models in reinforcement learning?","vi":"Một trong những thách thức chính khi dùng mô hình phân phối (distribution model) trong học tăng cường là gì?","opts":[{"l":"A","en":"High variance in action selection","vi":"Phương sai cao trong việc chọn hành động.","note":""},{"l":"B","en":"The need for large amounts of interaction data","vi":"Cần lượng lớn dữ liệu tương tác.","note":""},{"l":"C","en":"Difficulty in accurately modeling the environment's dynamics","vi":"Khó mô hình hóa chính xác động lực của môi trường.","note":""},{"l":"D","en":"Slow convergence to the optimal policy","vi":"Hội tụ chậm về chính sách tối ưu.","note":""}],"ans":"C","ansnote":"","exp":[["p","Distribution model phải cho đầy đủ p(s',r|s,a), nghe tuy đẹp nhưng trong thực tế rất khó ước lượng chính xác, nhất là môi trường lớn và ngẫu nhiên. A không phải vấn đề của model. B là vấn đề của model-free. D không phải thách thức đặc trưng của distribution model. (Đối chiếu câu 8: đáp án nêu vấn đề không gian trạng thái lớn, phần này nêu vấn đề độ chính xác.)"]],"rl":[["p","Sai số model (model error) dịch sang planning: nếu model sai, các cập nhật từ model làm hỏng giá trị. Sample model dễ lấy hơn distribution model."]],"ex":[["p","Mô hình hóa xác suất mọi tình huống của xe tự lái trên đường phố: gần như không thể liệt kê đủ và đúng."]],"tip":[["p","Distribution model = \"bản đồ hoàn hảo\" nhưng đảm bảo chính xác thì rất khó."]],"fig":false},{"id":"exam-67","part":"exam","n":67,"en":"Which of the following is an advantage of off-policy learning?","vi":"Điều nào sau đây là ưu điểm của học off-policy?","opts":[{"l":"A","en":"It requires less computational resources","vi":"Nó cần ít tài nguyên tính toán hơn.","note":""},{"l":"B","en":"It guarantees convergence to the optimal policy","vi":"Nó đảm bảo hội tụ về chính sách tối ưu.","note":""},{"l":"C","en":"It allows learning from non-optimal behavior","vi":"Nó cho phép học từ hành vi không tối ưu.","note":""},{"l":"D","en":"It eliminates the need for exploration entirely","vi":"Nó loại bỏ hoàn toàn nhu cầu khám phá.","note":""}],"ans":"C","ansnote":"","exp":[["p","Off-policy tách chính sách hành vi khỏi chính sách đích, nên học được chính sách tốt từ dữ liệu của hành vi kém, ngẫu nhiên, hay do người sinh ra. A sai (thường tốn hơn, phương sai cao). B sai vì không đảm bảo. D sai vì vẫn cần coverage, tức vẫn cần khám phá."]],"rl":[["p","Lợi ích: học từ dữ liệu cũ, demo của người, nhiều chính sách cùng lúc; vừa khám phá vừa học chính sách greedy. Nhược: phương sai cao, khó ổn định (xem câu 17)."]],"ex":[["p","Học từ nhật ký lái xe của nhiều tài xế (b), rồi tạo chính sách lái an toàn hơn (π)."]],"tip":[["p","Off-policy = \"học từ người khác\", nên dữ liệu tồi vẫn dùng được."]],"fig":false},{"id":"exam-68","part":"exam","n":68,"en":"What is the main objective of the Q-learning algorithm?","vi":"Mục tiêu chính của thuật toán Q-learning là gì?","opts":[{"l":"A","en":"To minimize the state-action pair values","vi":"Giảm thiểu giá trị các cặp trạng thái-hành động.","note":""},{"l":"B","en":"To maximize the total reward over time","vi":"Tối đa hóa tổng phần thưởng theo thời gian.","note":""},{"l":"C","en":"To minimize the exploration rate","vi":"Giảm thiểu tỉ lệ khám phá.","note":""},{"l":"D","en":"To maximize the number of actions taken","vi":"Tối đa hóa số hành động đã thực hiện.","note":""}],"ans":"B","ansnote":"","exp":[["p","Q-learning học q* để suy ra chính sách tối đa hóa return kỳ vọng. A, C, D đều không phải mục tiêu (giảm ε chỉ là kỹ thuật phụ)."]],"rl":[["p","Mục tiêu của RL: max E[G_t]. Q-learning tìm q*, rồi π*(s) = argmax_a q*(s,a)."]],"ex":[["p","Robot hút bụi học chọn hướng để tổng lượng rác thu được lâu dài là cao nhất."]],"tip":[["p","Mọi thuật toán RL đều có chung mục tiêu: tối đa hóa tổng reward tích lũy."]],"fig":false},{"id":"exam-69","part":"exam","n":69,"en":"What does the \"difference\" in temporal-difference learning refer to?","vi":"Từ \"difference\" (sự khác biệt) trong temporal-difference learning nói đến điều gì?","opts":[{"l":"A","en":"The difference between rewards and penalties","vi":"Khác biệt giữa thưởng và phạt.","note":""},{"l":"B","en":"The difference between observed and predicted values","vi":"Khác biệt giữa giá trị quan sát được và giá trị dự đoán.","note":""},{"l":"C","en":"The difference between input and output data","vi":"Khác biệt giữa dữ liệu đầu vào và đầu ra.","note":""},{"l":"D","en":"The difference between model parameters","vi":"Khác biệt giữa các tham số mô hình.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD error δ_t = R_{t+1} + γV(S_{t+1}) − V(S_t) là chênh lệch giữa ước lượng ở hai thời điểm liên tiếp (một phần đã quan sát: R, phần còn lại là dự đoán mới so với dự đoán cũ). A, C, D không đúng."]],"rl":[["code","\\delta_t = R_{t+1} + \\gamma V(S_{t+1}) - V(S_t)"],["p","δ > 0: kết quả tốt hơn dự đoán, tăng V. δ < 0: xấu hơn dự đoán, giảm V. δ = 0: dự đoán đúng."]],"ex":[["p","Dự đoán mất 30 phút đi làm, đi 5 phút rồi chỉ còn 20 phút nữa. Tính mỗi phút là reward âm: δ = −5 + (−20) − (−30) = +5 > 0, tức tốt hơn dự đoán nên nâng V(S) lên (mất ít hơn 30 phút)."]],"tip":[["p","TD = \"Temporal\" (hai thời điểm liền nhau) + \"Difference\" (độ lệch giữa hai dự đoán)."]],"fig":false},{"id":"exam-70","part":"exam","n":70,"en":"Which technique in reinforcement learning allows learning from historical data while following a different policy?","vi":"Kỹ thuật nào trong học tăng cường cho phép học từ dữ liệu lịch sử trong khi theo một chính sách khác?","opts":[{"l":"A","en":"On-policy learning","vi":"Học on-policy.","note":""},{"l":"B","en":"Off-policy learning","vi":"Học off-policy.","note":""},{"l":"C","en":"Model-based learning","vi":"Học dựa trên mô hình.","note":""},{"l":"D","en":"Temporal Difference learning","vi":"Học Temporal Difference.","note":""}],"ans":"B","ansnote":"","exp":[["p","Off-policy cho phép dùng dữ liệu sinh từ chính sách khác b (dữ liệu lịch sử) để học chính sách đích π. A yêu cầu dữ liệu từ chính π. C, D không nói gì về việc tách hai chính sách (TD có cả on-policy lẫn off-policy)."]],"rl":[["p","Nguồn dữ liệu: b. Mục tiêu: v_π, q_π hoặc q*. Công cụ: importance sampling (ρ = π/b), Q-learning, experience replay."]],"ex":[["p","Trạm bán lẻ có nhật ký bán hàng của nhiều năm (b), học chính sách giá mới (π) mà không phải thử trên khách thật."]],"tip":[["p","\"Historical data + different policy\" = off-policy (nhớ cặp từ: off = khác chính sách)."]],"fig":false},{"id":"exam-71","part":"exam","n":71,"en":"What does state aggregation involve in reinforcement learning?","vi":"Gom nhóm trạng thái (state aggregation) trong học tăng cường bao gồm điều gì?","opts":[{"l":"A","en":"Combining similar states into groups to reduce the dimensionality of the state space","vi":"Gộp các trạng thái tương tự thành nhóm để giảm số chiều/kích thước không gian trạng thái.","note":""},{"l":"B","en":"Separating dissimilar states to increase the granularity of the state space","vi":"Tách các trạng thái khác nhau để tăng độ mịn của không gian trạng thái.","note":""},{"l":"C","en":"Ignoring certain states in the environment to simplify the learning process","vi":"Bỏ qua một số trạng thái để đơn giản hóa việc học.","note":""},{"l":"D","en":"Converting continuous state spaces into discrete state spaces","vi":"Chuyển không gian trạng thái liên tục thành rời rạc.","note":""}],"ans":"A","ansnote":"","exp":[["p","State aggregation gom nhiều trạng thái giống nhau thành một nhóm và chia sẻ một giá trị. B là ngược lại. C là bỏ sót trạng thái, không phải gom. D gần đúng với rời rạc hóa nhưng là một ứng dụng riêng, định nghĩa chính xác là A."]],"rl":[["p","State aggregation là xấp xỉ tuyến tính với đặc trưng one-hot theo nhóm: v̂(s,w) = w_{g(s)}. Xem câu 19."]],"ex":[["p","1000 trạng thái chia thành 10 nhóm 100 trạng thái. Mất chi tiết bên trong nhóm nhưng giảm 100 lần số tham số."]],"tip":[["p","Aggregation = \"gom\" (aggregate = tổng hợp). Granularity = độ mịn, ngược lại với aggregation."]],"fig":false},{"id":"exam-72","part":"exam","n":72,"en":"Which of the following is a characteristic of states represented by coarse coding?","vi":"Đặc điểm nào sau đây là của các trạng thái được biểu diễn bằng coarse coding?","opts":[{"l":"A","en":"Each state is represented by a unique, non-overlapping feature","vi":"Mỗi trạng thái được biểu diễn bằng một đặc trưng duy nhất, không chồng lấn.","note":""},{"l":"B","en":"States are represented by overlapping features, allowing for generalization","vi":"Trạng thái được biểu diễn bằng các đặc trưng chồng lấn, cho phép khái quát hóa.","note":""},{"l":"C","en":"States are ignored and only actions are considered","vi":"Bỏ qua trạng thái và chỉ xét hành động.","note":""},{"l":"D","en":"Each state is treated as a separate entity with no generalization","vi":"Mỗi trạng thái là một thực thể riêng, không khái quát hóa.","note":""}],"ans":"B","ansnote":"","exp":[["p","Coarse coding dùng các vùng (receptive field) chồng lấn; một trạng thái nằm trong nhiều vùng cùng lúc nên bật nhiều đặc trưng và khái quát hóa sang trạng thái lân cận. A và D là biểu diễn dạng bảng (tabular). C vô lý."]],"rl":[["p","Kích thước vùng quyết định độ rộng của khái quát hóa; số vùng quyết định độ phân giải. Xem câu 25."]],"ex":[["p","Một điểm nằm trong 3 vòng tròn chồng nhau bật 3 đặc trưng. Học ở điểm này cập nhật cả 3 trọng số nên ảnh hưởng tới các điểm gần."]],"tip":[["p","Coarse = chồng lấn → generalization. Tabular = không chồng lấn → không generalization."]],"fig":false},{"id":"exam-73","part":"exam","n":73,"en":"What is a primary challenge when setting up Tile Coding?","vi":"Thách thức chính khi thiết lập Tile Coding là gì?","opts":[{"l":"A","en":"Ensuring non-overlapping tiles","vi":"Đảm bảo các tile không chồng lấn.","note":""},{"l":"B","en":"Selecting the number and size of tiles","vi":"Chọn số lượng và kích thước các tile.","note":""},{"l":"C","en":"Finding the right discount factor","vi":"Tìm hệ số chiết khấu phù hợp.","note":""},{"l":"D","en":"Balancing exploration and exploitation","vi":"Cân bằng khám phá và khai thác.","note":""}],"ans":"B","ansnote":"","exp":[["p","Tile quá to thì khái quát hóa mạnh nhưng mất chi tiết, quá nhỏ thì học chậm và tốn bộ nhớ. Số tiling nhiều giúp mịn hơn nhưng tốn tính toán. A sai vì tile coding cố ý dùng các tiling lệch nhau để chồng lấn. C, D không phải vấn đề của việc thiết lập tile."]],"rl":[["p","Tham số thiết kế: số tiling, kích thước ô, độ lệch giữa các tiling. Thường α = α₀ / (số tiling) để đổi trọng số đều."]],"ex":[["p","Không gian [0,1]², 8 tiling 10×10 cho 800 đặc trưng (mỗi trạng thái bật 8). Tile 2×2 thì 32 đặc trưng, quá thô."]],"tip":[["p","Tile coding \"bài toán chọn cỡ gạch\": to thì thô, nhỏ thì tốn."]],"fig":false},{"id":"exam-74","part":"exam","n":74,"en":"Which of the following methods is NOT typically used to learn the parameters of a Gaussian policy?","vi":"Phương pháp nào sau đây KHÔNG thường được dùng để học tham số của chính sách Gaussian?","opts":[{"l":"A","en":"Maximum likelihood estimation","vi":"Ước lượng hợp lý cực đại.","note":""},{"l":"B","en":"Policy gradient methods","vi":"Các phương pháp gradient chính sách.","note":""},{"l":"C","en":"Q-Learning","vi":"Q-learning.","note":""},{"l":"D","en":"Actor-Critic methods","vi":"Các phương pháp Actor-Critic.","note":""}],"ans":"C","ansnote":"","exp":[["p","Q-learning là value-based, học Q(s,a) rồi lấy argmax; nó không có chính sách tham số hóa nên không học μ, σ của Gaussian, và argmax trên hành động liên tục rất khó. A dùng khi có dữ liệu hành động mẫu (imitation). B, D cập nhật trực tiếp tham số θ của chính sách."]],"rl":[["p","Gaussian policy: π(a|s) = N(μ(s,θ), σ²(s,θ)). Gradient log: ∇lnπ = (a − μ)/σ² · ∇μ, dùng trong REINFORCE và Actor-Critic."]],"ex":[["p","Xe tự lái chỉnh góc lái liên tục: chính sách Gaussian được huấn luyện bằng Actor-Critic, không dùng Q-learning thuần túy."]],"tip":[["p","Gaussian policy + liên tục → policy gradient / actor-critic. Q-learning → hành động rời rạc."]],"fig":false},{"id":"exam-75","part":"exam","n":75,"en":"When using Epsilon-greedy with function approximation, what role does the function approximator play?","vi":"Khi dùng ε-greedy cùng xấp xỉ hàm, bộ xấp xỉ hàm đóng vai trò gì?","opts":[{"l":"A","en":"It generates the random exploration rate","vi":"Nó sinh ra tỉ lệ khám phá ngẫu nhiên.","note":""},{"l":"B","en":"It approximates the Q-values for given states and actions","vi":"Nó xấp xỉ giá trị Q cho các trạng thái và hành động đã cho.","note":""},{"l":"C","en":"It determines when to switch between exploration and exploitation","vi":"Nó quyết định khi nào chuyển giữa khám phá và khai thác.","note":""},{"l":"D","en":"It sets the value of epsilon","vi":"Nó đặt giá trị epsilon.","note":""}],"ans":"B","ansnote":"","exp":[["p","Bộ xấp xỉ (tuyến tính, mạng nơ-ron) trả về q̂(s,a,w) để ε-greedy so sánh và chọn argmax. A, C, D là việc của bộ sinh số ngẫu nhiên và siêu tham số ε."]],"rl":[["code","A_t = \\begin{cases} \\arg\\max_a \\hat q(S_t,a,\\mathbf{w}) & \\text{với xác suất } 1-\\varepsilon \\\\ \\text{ngẫu nhiên} & \\text{với xác suất } \\varepsilon \\end{cases}"],["p","Cập nhật: w ← w + α[R + γ q̂(S',A',w) − q̂(S,A,w)] ∇q̂(S,A,w) (Sarsa xấp xỉ)."]],"ex":[["p","Trong DQN, mạng nhận ảnh game và đưa ra Q cho từng nút bấm; ε-greedy chọn nút có Q cao nhất (90%) hoặc ngẫu nhiên (10%)."]],"tip":[["p","Approximator = \"bảng Q thuộc lòng\" (trả Q), ε-greedy = \"quy tắc chọn\"."]],"fig":false},{"id":"exam-76","part":"exam","n":76,"en":"What is a parameterized function in the context of reinforcement learning?","vi":"Hàm có tham số (parameterized function) trong ngữ cảnh học tăng cường là gì?","opts":[{"l":"A","en":"A function that takes no inputs and outputs a constant value","vi":"Hàm không có đầu vào và trả về hằng số.","note":""},{"l":"B","en":"A function that uses parameters (weights) to approximate another function","vi":"Hàm dùng các tham số (trọng số) để xấp xỉ một hàm khác.","note":""},{"l":"C","en":"A function that always returns the same value regardless of inputs","vi":"Hàm luôn trả về cùng một giá trị bất kể đầu vào.","note":""},{"l":"D","en":"A function that randomly changes its parameters during training","vi":"Hàm tự đổi tham số ngẫu nhiên trong lúc huấn luyện.","note":""}],"ans":"B","ansnote":"","exp":[["p","Ví dụ v̂(s,w) = wᵀx(s): hàm có vector trọng số w, được chỉnh để xấp xỉ v_π(s). A, C là hàm hằng, không xấp xỉ được gì. D sai vì tham số được cập nhật theo gradient chứ không ngẫu nhiên."]],"rl":[["code","\\hat v(s,\\mathbf{w}) \\approx v_\\pi(s), \\qquad \\mathbf{w} \\leftarrow \\mathbf{w} + \\alpha\\,[\\,U_t - \\hat v(S_t,\\mathbf{w})\\,]\\,\\nabla \\hat v(S_t,\\mathbf{w})"],["p","Số tham số d ≪ |S| → khái quát hóa, đổi lại không đúng hoàn toàn."]],"ex":[["p","v̂(s) = 3·x₁(s) + 2·x₂(s): w = (3, 2) là hai tham số thay vì lưu một giá trị cho mỗi trạng thái."]],"tip":[["p","Parameterized = \"có núm vặn\" (w) để chỉnh cho đúng."]],"fig":false},{"id":"exam-77","part":"exam","n":77,"en":"What role does the discount factor play in Semi-Gradient TD learning?","vi":"Hệ số chiết khấu đóng vai trò gì trong học Semi-Gradient TD?","opts":[{"l":"A","en":"It determines the rate of eligibility trace decay","vi":"Nó quyết định tốc độ suy giảm của eligibility trace.","note":""},{"l":"B","en":"It controls the influence of future rewards on the updates","vi":"Nó kiểm soát ảnh hưởng của phần thưởng tương lai lên các cập nhật.","note":""},{"l":"C","en":"It sets the exploration-exploitation trade-off","vi":"Nó đặt sự đánh đổi khám phá-khai thác.","note":""},{"l":"D","en":"It adjusts the learning rate dynamically during training","vi":"Nó điều chỉnh tốc độ học động trong lúc huấn luyện.","note":""}],"ans":"B","ansnote":"","exp":[["p","γ đứng trước v̂(S',w) trong target R + γv̂(S',w), nên quyết định giá trị tương lai được tính bao nhiêu. A là λ (đúng là γλ, nhưng λ là tham số riêng). C là ε. D là việc của bộ tối ưu/α."]],"rl":[["code","\\mathbf{w} \\leftarrow \\mathbf{w} + \\alpha\\,\\big[\\,R + \\gamma \\hat v(S',\\mathbf{w}) - \\hat v(S,\\mathbf{w})\\,\\big]\\,\\nabla \\hat v(S,\\mathbf{w})"],["p","\"Semi-gradient\" vì chỉ lấy gradient của ước lượng hiện tại v̂(S,w), coi target (có v̂(S',w)) là hằng."]],"ex":[["p","γ = 0,9: phần thưởng ở bước kế tiếp được tính 90% khi cập nhật trạng thái hiện tại."]],"tip":[["p","γ = \"nhìn xa\", dù ở TD bảng hay TD xấp xỉ đều giống nhau."]],"fig":false},{"id":"exam-78","part":"exam","n":78,"en":"What is the significance of the average reward in reinforcement learning?","vi":"Ý nghĩa của phần thưởng trung bình (average reward) trong học tăng cường là gì?","opts":[{"l":"A","en":"It indicates the maximum achievable reward in an environment","vi":"Nó cho biết phần thưởng tối đa đạt được trong môi trường.","note":""},{"l":"B","en":"It helps in evaluating the performance of a learning agent over time","vi":"Nó giúp đánh giá hiệu suất của agent theo thời gian.","note":""},{"l":"C","en":"It represents the instantaneous reward received at each time step","vi":"Nó là phần thưởng tức thời ở mỗi bước.","note":""},{"l":"D","en":"It measures the variance in reward distribution","vi":"Nó đo phương sai của phân phối phần thưởng.","note":""}],"ans":"B","ansnote":"","exp":[["p","Average reward r(π) là reward trung bình trên mỗi bước lâu dài, dùng so sánh các chính sách (nhất là bài toán continuing). A, C, D đều không đúng định nghĩa."]],"rl":[["code","r(\\pi) = \\lim_{h \\to \\infty} \\frac{1}{h} \\sum_{t=1}^{h} \\mathbb{E}[R_t \\mid S_0, A_{0:t-1} \\sim \\pi] = \\sum_s \\mu_\\pi(s) \\sum_a \\pi(a|s) \\sum_{s',r} p(s',r|s,a)\\, r"],["p","Dùng trong continuing task thay cho chiết khấu. Cần MDP ergodic (xem câu 16). Differential value: ṽ(s) = E[Σ(R_{t+1} − r(π))]."]],"ex":[["p","Máy chiếu mỗi giờ nhận trung bình 12 đơn: r = 12 đơn/giờ, so sánh được hai cách sắp xếp."]],"tip":[["p","Continuing task → average reward; episodic → return có chiết khấu."]],"fig":false},{"id":"exam-79","part":"exam","n":79,"en":"In coarse coding, what is the effect of having overlapping regions?","vi":"Trong coarse coding, việc các vùng chồng lấn nhau có tác dụng gì?","opts":[{"l":"A","en":"It increases the complexity of the representation","vi":"Làm tăng độ phức tạp của biểu diễn.","note":""},{"l":"B","en":"It reduces the chance of generalization across similar states","vi":"Làm giảm khả năng khái quát hóa giữa các trạng thái tương tự.","note":""},{"l":"C","en":"It allows for better generalization and smoother function approximation","vi":"Cho phép khái quát hóa tốt hơn và xấp xỉ hàm mượt hơn.","note":""},{"l":"D","en":"It eliminates the need for exploration in reinforcement learning","vi":"Loại bỏ nhu cầu khám phá.","note":""}],"ans":"C","ansnote":"","exp":[["p","Chồng lấn khiến hai điểm gần nhau chia sẻ nhiều đặc trưng, nên giá trị thay đổi mượt theo khoảng cách. B trái ngược, D không liên quan đến khám phá. A có thể đúng một phần nhưng không phải điểm chính."]],"rl":[["p","Càng chồng lấn (nhiều vùng cùng phủ một điểm) thì hàm xấp xỉ càng mượt và độ phân giải mịn hơn. Tile coding dùng nhiều tiling lệch nhau để đạt được điều này."]],"ex":[["p","Hai điểm cách nhau 1 đơn vị cùng nằm trong 2 trong 3 vòng → giá trị giống nhau nhiều, không nhảy bậc."]],"tip":[["p","Chồng lấn = \"vùng chung\" = chia sẻ thông tin = khái quát hóa (xem câu 72)."]],"fig":false},{"id":"exam-80","part":"exam","n":80,"en":"Which of the following methods combines linear function approximation with policy improvement?","vi":"Phương pháp nào sau đây kết hợp xấp xỉ hàm tuyến tính với cải thiện chính sách?","opts":[{"l":"A","en":"Policy Gradient Methods","vi":"Các phương pháp gradient chính sách.","note":""},{"l":"B","en":"Value Iteration","vi":"Lặp giá trị.","note":""},{"l":"C","en":"Actor-Critic Methods","vi":"Các phương pháp Actor-Critic.","note":""},{"l":"D","en":"Tabular Q-Learning","vi":"Q-learning dạng bảng.","note":""}],"ans":"C","ansnote":"","exp":[["p","Actor-Critic có critic ước lượng giá trị bằng hàm xấp xỉ (có thể tuyến tính) và actor cải thiện chính sách. B và D dạng bảng, không có xấp xỉ hàm. A chỉ tối ưu chính sách, không nhấn mạnh critic xấp xỉ giá trị (thuần REINFORCE không dùng critic)."]],"rl":[["p","Actor-Critic: critic cập nhật w bằng TD; actor cập nhật θ theo δ:"],["code","\\delta = R + \\gamma \\hat v(S',\\mathbf{w}) - \\hat v(S,\\mathbf{w}); \\quad \\mathbf{w} \\leftarrow \\mathbf{w} + \\alpha_w \\delta \\nabla_{\\mathbf{w}} \\hat v; \\quad \\theta \\leftarrow \\theta + \\alpha_\\theta \\delta \\nabla_\\theta \\ln \\pi(A|S,\\theta)"]],"ex":[["p","Critic tuyến tính trên tile coding ước lượng giá trị, actor softmax chọn hướng đi cho xe trên đồi (Mountain Car)."]],"tip":[["p","Actor = \"diễn viên\" (chính sách), Critic = \"giám khảo\" (giá trị). Cả hai cùng cập nhật."]],"fig":false},{"id":"exam-81","part":"exam","n":81,"en":"In which type of environments is state aggregation particularly useful?","vi":"Gom nhóm trạng thái (state aggregation) đặc biệt hữu ích trong loại môi trường nào?","opts":[{"l":"A","en":"Environments with a very small state space","vi":"Môi trường có không gian trạng thái rất nhỏ.","note":""},{"l":"B","en":"Environments with deterministic transitions","vi":"Môi trường có chuyển trạng thái xác định.","note":""},{"l":"C","en":"Environments with a very large or continuous state space","vi":"Môi trường có không gian trạng thái rất lớn hoặc liên tục.","note":""},{"l":"D","en":"Environments with no reward structure","vi":"Môi trường không có cấu trúc phần thưởng.","note":""}],"ans":"C","ansnote":"","exp":[["p","Đây là câu trùng với câu 19 trong đề SU26. Khi trạng thái quá nhiều hoặc liên tục, bảng giá trị không khả thi, gom nhóm giúp giảm số tham số. A không cần gom. B, D không liên quan."]],"rl":[["p","v̂(s,w) = w_{g(s)}: mỗi nhóm một trọng số, cập nhật chỉ làm thay đổi trọng số của nhóm đó. Gradient: ∇v̂ = 1 ở nhóm chứa s và 0 ở các nhóm khác."]],"ex":[["p","Vị trí xe trên đường [0, 1000] m chia thành 10 đoạn 100 m, mỗi đoạn một giá trị."]],"tip":[["p","Gom nhóm = cứu tinh khi trạng thái nhiều/liên tục (xem câu 19, 71)."]],"fig":false},{"id":"exam-82","part":"exam","n":82,"en":"How are the actor and critic networks updated in Actor-Critic with Softmax Policies?","vi":"Các mạng actor và critic được cập nhật như thế nào trong Actor-Critic với chính sách softmax?","opts":[{"l":"A","en":"Only the actor network is updated","vi":"Chỉ mạng actor được cập nhật.","note":""},{"l":"B","en":"Only the critic network is updated","vi":"Chỉ mạng critic được cập nhật.","note":""},{"l":"C","en":"Both the actor and critic networks are updated simultaneously","vi":"Cả hai mạng actor và critic được cập nhật đồng thời.","note":""},{"l":"D","en":"The networks are updated independently","vi":"Hai mạng được cập nhật độc lập.","note":""}],"ans":"C","ansnote":"","exp":[["p","Mỗi bước, critic cập nhật giá trị bằng TD, actor cập nhật chính sách dùng cùng sai số δ. A hoặc B thiếu một bên. D sai vì actor phụ thuộc δ do critic tính, không độc lập."]],"rl":[["p","Critic: w ← w + α_w δ ∇v̂. Actor: θ ← θ + α_θ δ ∇lnπ(A|S,θ). δ = R + γv̂(S') − v̂(S) dùng chung cho cả hai (xem câu 80)."]],"ex":[["p","δ > 0 (kết quả tốt hơn dự đoán): critic nâng v̂(S), actor tăng xác suất hành động A vừa chọn."]],"tip":[["p","Hai bên cùng học \"cùng một δ\", như diễn viên và giám khảo cùng tiến bộ sau mỗi màn trình diễn."]],"fig":false},{"id":"exam-83","part":"exam","n":83,"en":"What role does the critic play in Actor-Critic with Softmax Policies?","vi":"Critic đóng vai trò gì trong Actor-Critic với chính sách softmax?","opts":[{"l":"A","en":"It learns the policy function","vi":"Nó học hàm chính sách.","note":""},{"l":"B","en":"It calculates the probability distribution over actions","vi":"Nó tính phân phối xác suất trên các hành động.","note":""},{"l":"C","en":"It evaluates the quality of the policy chosen by the actor","vi":"Nó đánh giá chất lượng chính sách mà actor chọn.","note":""},{"l":"D","en":"It determines the exploration rate","vi":"Nó quyết định tỉ lệ khám phá.","note":""}],"ans":"C","ansnote":"","exp":[["p","Critic ước lượng v̂ (hoặc q̂) cho chính sách hiện tại và trả về sai số TD δ cho actor. A và B là việc của actor (softmax ở actor). D là nhiệt độ τ trong softmax (xem câu 34)."]],"rl":[["p","Actor = chính sách π(a|s,θ) (softmax). Critic = hàm giá trị v̂(s,w). δ là \"điểm phê\" của critic dành cho hành động vừa chọn. Critic còn giảm phương sai so với REINFORCE."]],"ex":[["p","Actor chọn hành động \"sang trái\", critic thấy trạng thái mới tốt hơn dự đoán (δ > 0) nên khen, actor tăng xác suất sang trái."]],"tip":[["p","Critic = \"nhà phê bình\", chỉ chấm điểm, không chọn hành động."]],"fig":false},{"id":"exam-84","part":"exam","n":84,"en":"Which of the following is NOT a method for solving MDPs?","vi":"Phương pháp nào sau đây KHÔNG phải là phương pháp giải MDP?","opts":[{"l":"A","en":"Dynamic Programming","vi":"Quy hoạch động.","note":""},{"l":"B","en":"Monte Carlo Methods","vi":"Các phương pháp Monte Carlo.","note":""},{"l":"C","en":"Temporal Difference Learning","vi":"Học Temporal Difference.","note":""},{"l":"D","en":"Stochastic Gradient Descent","vi":"Gradient descent ngẫu nhiên.","note":""}],"ans":"D","ansnote":"","exp":[["p","SGD là thuật toán tối ưu hóa tham số, không phải phương pháp giải MDP; nó chỉ là công cụ dùng bên trong (ví dụ cập nhật trọng số của xấp xỉ hàm). A, B, C là ba họ phương pháp giải MDP cơ bản."]],"rl":[["p","Ba họ giải MDP: DP (cần model), MC (mẫu đầy episode), TD (mẫu + bootstrapping). \"Semi-gradient\" của TD dùng gradient nhưng đó là bước cập nhật, không phải bản thân phương pháp."]],"ex":[["p","Giải MDP gridworld: dùng value iteration (DP), hay Q-learning (TD). SGD chỉ xuất hiện khi huấn luyện mạng nơ-ron của DQN."]],"tip":[["p","Câu \"NOT\": tìm đáp án là kỹ thuật tối ưu hóa chung (SGD), không phải họ RL."]],"fig":false},{"id":"exam-85","part":"exam","n":85,"en":"How does the flexibility of the Policy Iteration Framework contribute to robustness?","vi":"Tính linh hoạt của khung Policy Iteration đóng góp vào độ bền vững (robustness) như thế nào?","opts":[{"l":"A","en":"By limiting the diversity of policies explored","vi":"Bằng cách giới hạn sự đa dạng của các chính sách được khám phá.","note":""},{"l":"B","en":"By allowing for rapid convergence to a single optimal policy","vi":"Bằng cách cho phép hội tụ nhanh tới một chính sách tối ưu duy nhất.","note":""},{"l":"C","en":"By enabling adaptation to varying conditions or goals","vi":"Bằng cách cho phép thích nghi với các điều kiện hoặc mục tiêu thay đổi.","note":""},{"l":"D","en":"None of the above","vi":"Không cái nào ở trên.","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy iteration (GPI) cho phép đánh giá và cải thiện đan xen linh hoạt (có thể đánh giá chỉ một phần, cải thiện ở một số trạng thái), nên dễ thích nghi khi môi trường hoặc mục tiêu thay đổi. A ngược lại. B nói về tốc độ chứ không phải bền vững. D sai vì C đúng."]],"rl":[["p","GPI: mọi thuật toán RL đều có hai tiến trình tương tác (giá trị → nhất quán với chính sách, chính sách → greedy với giá trị) cho đến khi ổn định ở π*, v*. Muốn đánh giá bao nhiêu bước cũng được, hội tụ vẫn đảm bảo."]],"ex":[["p","Đổi phần thưởng của bản đồ (mục tiêu mới): tiếp tục vòng đánh giá/cải thiện từ chính sách cũ, không phải học lại từ đầu."]],"tip":[["p","\"Flexibility\" → \"adaptation\" (thích nghi). Câu có từ \"single optimal policy\" thường là bẫy."]],"fig":false},{"id":"exam-86","part":"exam","n":86,"en":"In the context of the multi-armed bandit problem, what does the term \"exploitation\" refer to?","vi":"Trong bài toán multi-armed bandit, thuật ngữ \"khai thác\" (exploitation) đề cập đến điều gì?","opts":[{"l":"A","en":"Trying out different arms to gather information","vi":"Thử các cánh tay khác nhau để thu thập thông tin.","note":""},{"l":"B","en":"Using the known information to select the best arm","vi":"Dùng thông tin đã biết để chọn cánh tay tốt nhất.","note":""},{"l":"C","en":"Ignoring the past rewards and trying new strategies","vi":"Bỏ qua phần thưởng quá khứ và thử chiến lược mới.","note":""},{"l":"D","en":"Allocating equal time to all arms","vi":"Chia thời gian đều cho mọi cánh tay.","note":""}],"ans":"B","ansnote":"","exp":[["p","Exploitation = chọn hành động có ước lượng tốt nhất hiện tại (greedy). A và C mô tả exploration. D là chia đều, không phải cả hai."]],"rl":[["p","Greedy: A_t = argmax_a Q_t(a). Exploration: thử hành động khác để cải thiện ước lượng. Cân bằng: ε-greedy, UCB, softmax, optimistic initial values."]],"ex":[["p","Biết quán A trung bình 8 điểm, quán B 6 điểm: chọn A là khai thác, thử quán C mới là khám phá."]],"tip":[["p","Exploit = \"xài hàng có sẵn\", Explore = \"thử đồ mới\"."]],"fig":false},{"id":"exam-87","part":"exam","n":87,"en":"What happens if the value function of a policy converges during Iterative Policy Evaluation?","vi":"Điều gì xảy ra nếu hàm giá trị của một chính sách hội tụ trong quá trình Iterative Policy Evaluation?","opts":[{"l":"A","en":"The optimal policy is achieved","vi":"Đạt được chính sách tối ưu.","note":""},{"l":"B","en":"The value function becomes infinite","vi":"Hàm giá trị trở nên vô hạn.","note":""},{"l":"C","en":"The policy becomes deterministic","vi":"Chính sách trở nên xác định.","note":""},{"l":"D","en":"The policy evaluation process stops","vi":"Quá trình đánh giá chính sách dừng lại.","note":""}],"ans":"D","ansnote":"","exp":[["p","Khi max_s |v_{k+1}(s) − v_k(s)| < θ, thuật toán dừng và trả về v ≈ v_π. A sai vì đánh giá chỉ tính giá trị của π đã cho, chưa cải thiện π. B sai vì hội tụ nghĩa là hữu hạn ổn định. C không liên quan."]],"rl":[["p","Điều kiện dừng:"],["code","\\Delta = \\max_s |v_{k+1}(s) - v_k(s)| < \\theta"],["p","Sau đó mới đến bước policy improvement (greedy theo v_π) trong policy iteration. Với γ < 1 (hoặc episodic) thuật toán hội tụ theo co dãn."]],"ex":[["p","Δ = 0,0001 < θ = 0,001 thì dừng, đưa v_π đến bước cải thiện."]],"tip":[["p","Hội tụ = hết thay đổi = dừng. Đừng nhầm \"hội tụ\" với \"đã tối ưu\"."]],"fig":false},{"id":"exam-88","part":"exam","n":88,"en":"Which function is typically used to represent the action value in reinforcement learning?","vi":"Hàm nào thường được dùng để biểu diễn giá trị hành động trong học tăng cường?","opts":[{"l":"A","en":"Reward function (R)","vi":"Hàm phần thưởng (R).","note":""},{"l":"B","en":"Value function (V)","vi":"Hàm giá trị (V).","note":""},{"l":"C","en":"Policy function (π)","vi":"Hàm chính sách (π).","note":""},{"l":"D","en":"Q-function (Q)","vi":"Hàm Q.","note":""}],"ans":"D","ansnote":"","exp":[["p","Q(s,a) là giá trị của việc làm hành động a ở trạng thái s. R là phần thưởng tức thời. V(s) là giá trị của trạng thái (không có a). π là chính sách."]],"rl":[["code","q_\\pi(s,a) = \\mathbb{E}_\\pi[G_t \\mid S_t = s, A_t = a], \\qquad v_\\pi(s) = \\sum_a \\pi(a|s)\\, q_\\pi(s,a)"]],"ex":[["p","Tại ô s: q(s, trái) = 5, q(s, phải) = 8. Chọn \"phải\" là tốt hơn."]],"tip":[["p","Q = \"Quality of action\": chất lượng của (state, action). V = Value của state."]],"fig":false},{"id":"exam-89","part":"exam","n":89,"en":"How does hyperbolic discounting differ from exponential discounting?","vi":"Chiết khấu hyperbol khác chiết khấu mũ ở điểm nào?","opts":[{"l":"A","en":"Hyperbolic discounting values future rewards more than exponential discounting","vi":"Chiết khấu hyperbol đánh giá phần thưởng tương lai cao hơn chiết khấu mũ.","note":""},{"l":"B","en":"Exponential discounting values future rewards more than hyperbolic discounting","vi":"Chiết khấu mũ đánh giá phần thưởng tương lai cao hơn chiết khấu hyperbol.","note":""},{"l":"C","en":"Both discount future rewards equally","vi":"Cả hai chiết khấu như nhau.","note":""},{"l":"D","en":"Hyperbolic discounting is not related to time preference","vi":"Chiết khấu hyperbol không liên quan đến sở thích thời gian.","note":""}],"ans":"B","ansnote":"","exp":[["p","Theo khóa, chọn B. Lưu ý quan trọng: với cùng hệ số k, 1/(1+kt) ≥ e^(−kt) với mọi t ≥ 0, nên về toán học chiết khấu hyperbol thường cho giá trị tương lai CAO hơn chứ không thấp hơn chiết khấu mũ (suy giảm chậm hơn ở khoảng cách xa). Vì thế khóa B có thể là do người ra đề nghĩ theo cách khác; nếu đề thi thật có đáp án khác, hãy hỏi giảng viên. C và D chắc chắn sai."]],"rl":[["code","\\text{Mũ: } \\gamma^t = e^{-kt}, \\qquad \\text{Hyperbol: } \\frac{1}{1 + kt}"],["p","Chiết khấu mũ (γ^t) có tỉ lệ chiết khấu mỗi bước cố định nên nhất quán theo thời gian, và đây là dạng chuẩn trong RL. Hyperbol giảm nhanh lúc đầu rồi chậm lại, gây ra thái độ bất nhất quán thời gian (preference reversal) ở con người."]],"ex":[["p","k = 0,1, t = 20: mũ cho e^(−2) ≈ 0,135, hyperbol cho 1/(1+2) ≈ 0,333."]],"tip":[["p","RL dùng chiết khấu mũ γ^t. Hyperbol chỉ xuất hiện khi nói tới hành vi con người/động vật."]],"fig":false},{"id":"exam-90","part":"exam","n":90,"en":"Which task type typically requires sustained effort over time?","vi":"Loại nhiệm vụ nào thường đòi hỏi nỗ lực bền bỉ theo thời gian?","opts":[{"l":"A","en":"Episodic tasks","vi":"Nhiệm vụ theo từng episode.","note":""},{"l":"B","en":"Continuing tasks","vi":"Nhiệm vụ liên tục.","note":""},{"l":"C","en":"Both episodic and continuing tasks","vi":"Cả hai.","note":""},{"l":"D","en":"Neither episodic nor continuing tasks","vi":"Không loại nào.","note":""}],"ans":"B","ansnote":"","exp":[["p","Continuing task không có điểm kết thúc nên agent phải hoạt động và duy trì hiệu quả liên tục. A có điểm dừng sau mỗi episode. C và D ít hợp lý. Đây là câu ngữ nghĩa hơn là thuật ngữ kỹ thuật."]],"rl":[["p","Continuing: T = ∞, dùng γ < 1 hoặc average reward (xem câu 30, 78). Episodic có trạng thái kết thúc, sau đó reset."]],"ex":[["p","Điều khiển nhiệt độ nhà máy 24/7 (continuing). Ván cờ (episodic)."]],"tip":[["p","Continuing = \"chạy mãi không nghỉ\" → cần bền bỉ."]],"fig":false},{"id":"exam-91","part":"exam","n":91,"en":"What does the action value Q(s,a) represent in reinforcement learning?","vi":"Giá trị hành động Q(s,a) biểu diễn điều gì trong học tăng cường?","opts":[{"l":"A","en":"The probability of transitioning to state s from state a","vi":"Xác suất chuyển đến trạng thái s từ trạng thái a.","note":""},{"l":"B","en":"The expected return (total future reward) of taking action a in state s","vi":"Return kỳ vọng (tổng phần thưởng tương lai) khi thực hiện hành động a ở trạng thái s.","note":""},{"l":"C","en":"The immediate reward received after taking action a","vi":"Phần thưởng tức thời nhận được sau khi thực hiện a.","note":""},{"l":"D","en":"The average time it takes to transition from state s to state a","vi":"Thời gian trung bình để chuyển từ trạng thái s sang a.","note":""}],"ans":"B","ansnote":"","exp":[["p","q_π(s,a) = E[G_t | S_t = s, A_t = a]: làm a ở s rồi theo π, kỳ vọng tổng reward chiết khấu. A mô tả xác suất chuyển p. C là R_{t+1}, chỉ một bước. D không phải khái niệm RL."]],"rl":[["code","q_\\pi(s,a) = \\mathbb{E}_\\pi\\Big[\\sum_{k=0}^{\\infty} \\gamma^k R_{t+k+1} \\;\\Big|\\; S_t=s, A_t=a\\Big] = \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_\\pi(s')\\,]"]],"ex":[["p","Ở ô s, \"đi phải\" nhận ngay 0 nhưng dẫn tới đích sau 3 bước với γ = 0,9, reward 10 → q = 0,9²×10 = 8,1 (nếu reward 10 ở bước thứ 3). Phần thưởng tức thời chỉ là 0 nhưng Q = 8,1, nên đáp án C (reward tức thời) sai."]],"tip":[["p","Q = \"Quality\": chất lượng tổng thể (cả tương lai), không phải reward tức thời."]],"fig":false},{"id":"exam-92","part":"exam","n":92,"en":"Which notation is commonly used to represent the action-value function?","vi":"Ký hiệu nào thường được dùng để biểu diễn hàm giá trị hành động?","opts":[{"l":"A","en":"V(s)","vi":"V(s).","note":""},{"l":"B","en":"R(s, a)","vi":"R(s, a).","note":""},{"l":"C","en":"Q(s, a)","vi":"Q(s, a).","note":""},{"l":"D","en":"P(a | s)","vi":"P(a | s).","note":""}],"ans":"C","ansnote":"Trang gốc ghi khóa là B, nhưng Q(s,a) mới là hàm giá trị hành động nên mình chọn C.","exp":[["p","Ký hiệu chuẩn của hàm giá trị hành động là Q(s,a) (hay q_π(s,a)). V(s) là hàm giá trị trạng thái. R(s,a) là phần thưởng kỳ vọng tức thời r(s,a) = E[R_{t+1} | s,a]. P(a|s) là xác suất chọn hành động, tức chính sách π(a|s). Đề nghị kiểm tra lại khi ôn vì câu 91 và 88 cùng cho Q là giá trị hành động."]],"rl":[["p","Ký hiệu cần thuộc: v_π(s) = giá trị trạng thái; q_π(s,a) = giá trị hành động; π(a|s) = chính sách; p(s',r|s,a) = động lực; r(s,a) = reward kỳ vọng."]],"ex":[["p","Q-table 5×4 trong Q-learning: mỗi ô là Q(s,a)."]],"tip":[["p","Q có hai đối số (s,a), V có một (s). Nếu có dấu phẩy giữa hai biến thì thường là Q. Cảnh báo: R(s,a) là bẫy dễ nhầm vì cũng có (s,a)."]],"fig":false},{"id":"exam-93","part":"exam","n":93,"en":"In Policy Evaluation, what is the objective function typically used?","vi":"Trong Đánh giá chính sách (Policy Evaluation), hàm mục tiêu thường được dùng là gì?","opts":[{"l":"A","en":"Bellman Equation","vi":"Phương trình Bellman.","note":""},{"l":"B","en":"Logistic Regression","vi":"Hồi quy logistic.","note":""},{"l":"C","en":"Cost Function","vi":"Hàm chi phí.","note":""},{"l":"D","en":"Gradient Descent","vi":"Gradient descent.","note":""}],"ans":"A","ansnote":"","exp":[["p","Policy evaluation được phát biểu qua phương trình Bellman kỳ vọng, v_π là nghiệm duy nhất. B là bài toán phân loại. C chung chung. D là thuật toán tối ưu hóa, không phải mục tiêu."]],"rl":[["code","v_\\pi(s) = \\sum_a \\pi(a|s) \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_\\pi(s')\\,]"],["p","Với xấp xỉ hàm, mục tiêu thành Mean Squared Value Error (xem câu 44). Lưu ý: ở câu này đề gọi Bellman equation là \"objective\", khá lỏng lẻo."]],"ex":[["p","Gridworld: lặp cập nhật vế phải của Bellman cho đến khi giá trị ổn định."]],"tip":[["p","Policy evaluation ↔ Bellman expectation equation (xem câu 20, 46)."]],"fig":false},{"id":"exam-94","part":"exam","n":94,"en":"Which of the following is NOT a component of the reinforcement learning framework?","vi":"Thành phần nào sau đây KHÔNG thuộc khung học tăng cường?","opts":[{"l":"A","en":"Agent","vi":"Tác nhân.","note":""},{"l":"B","en":"Environment","vi":"Môi trường.","note":""},{"l":"C","en":"Memory","vi":"Bộ nhớ.","note":""},{"l":"D","en":"Reward Signal","vi":"Tín hiệu phần thưởng.","note":""}],"ans":"C","ansnote":"","exp":[["p","Khung RL gồm agent, environment, state, action, reward (và thành phần con: policy, value function, model). \"Memory\" không phải thành phần bắt buộc (một số thuật toán có replay buffer nhưng không phải khung chung)."]],"rl":[["p","Vòng lặp: Agent quan sát S_t → chọn A_t → Environment trả R_{t+1}, S_{t+1}. Thành phần con của agent: policy π, value function v/q, model (tuỳ chọn)."]],"ex":[["p","Robot (agent), căn phòng (environment), +1 khi hút sạch sàn (reward signal)."]],"tip":[["p","Nhớ A-E-R-S-A: Agent, Environment, Reward, State, Action. Không có Memory."]],"fig":false},{"id":"exam-95","part":"exam","n":95,"en":"In what way do rewards contribute to the goal-oriented behavior of an agent?","vi":"Phần thưởng đóng góp vào hành vi hướng mục tiêu của agent theo cách nào?","opts":[{"l":"A","en":"By encouraging trial and error","vi":"Bằng cách khuyến khích thử và sai.","note":""},{"l":"B","en":"By increasing randomness","vi":"Bằng cách tăng tính ngẫu nhiên.","note":""},{"l":"C","en":"By decreasing motivation","vi":"Bằng cách giảm động lực.","note":""},{"l":"D","en":"By providing feedback on progress","vi":"Bằng cách cung cấp phản hồi về tiến độ.","note":""}],"ans":"D","ansnote":"","exp":[["p","Reward là tín hiệu cho agent biết hành động nào đưa gần mục tiêu. A mô tả khám phá, không phải vai trò của reward. B, C trái ngược."]],"rl":[["p","Reward hypothesis: mọi mục tiêu có thể diễn đạt bằng việc tối đa hóa kỳ vọng tổng tín hiệu vô hướng (reward) tích lũy."]],"ex":[["p","Robot đồ chơi nhận +1 khi chạm đích, −0,01 mỗi bước để khuyến khích đi đường ngắn."]],"tip":[["p","Reward = \"phản hồi\" (feedback). Không phải ngẫu nhiên, không phải giảm động lực."]],"fig":false},{"id":"exam-96","part":"exam","n":96,"en":"In reinforcement learning, what is the Bellman equation used for?","vi":"Trong học tăng cường, phương trình Bellman được dùng để làm gì?","opts":[{"l":"A","en":"Calculating the optimal value function","vi":"Tính hàm giá trị tối ưu.","note":""},{"l":"B","en":"Estimating the value of actions","vi":"Ước lượng giá trị của các hành động.","note":""},{"l":"C","en":"Updating the policy","vi":"Cập nhật chính sách.","note":""},{"l":"D","en":"Computing the expected reward","vi":"Tính phần thưởng kỳ vọng.","note":""}],"ans":"A","ansnote":"","exp":[["p","Phương trình Bellman (tối ưu) mô tả v* và q* theo đệ quy, là nền tảng để tính giá trị tối ưu (value iteration, Q-learning). B, D đúng một phần (Bellman kỳ vọng cũng đánh giá giá trị), C là việc của policy improvement; đáp án khóa chọn A vì đây là vai trò điển hình nhất."]],"rl":[["code","v_*(s) = \\max_a \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma v_*(s')\\,], \\qquad q_*(s,a) = \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma \\max_{a'} q_*(s',a')\\,]"],["p","Hai dạng: Bellman expectation (cho v_π, q_π — policy evaluation) và Bellman optimality (cho v*, q* — control)."]],"ex":[["p","Với 2 hành động có giá trị 5 và 8, v*(s) = 8."]],"tip":[["p","Bellman = \"giá trị hiện tại = reward + γ × giá trị điểm tiếp theo\". Optimality có max."]],"fig":false},{"id":"exam-97","part":"exam","n":97,"en":"Which method involves selecting actions based on their probability distribution determined by their estimated value functions?","vi":"Phương pháp nào chọn hành động dựa trên phân phối xác suất được xác định bởi các hàm giá trị ước lượng của chúng?","opts":[{"l":"A","en":"Epsilon-Greedy","vi":"ε-greedy.","note":""},{"l":"B","en":"Upper Confidence Bound (UCB)","vi":"Upper Confidence Bound.","note":""},{"l":"C","en":"Softmax","vi":"Softmax.","note":""},{"l":"D","en":"Monte Carlo Tree Search","vi":"Tìm kiếm cây Monte Carlo.","note":""}],"ans":"C","ansnote":"","exp":[["p","Softmax biến giá trị Q thành xác suất: Q cao thì xác suất cao nhưng mọi hành động đều có cơ hội. A chỉ chia 2 trường hợp (ngẫu nhiên hoặc argmax), không tỉ lệ theo giá trị. B chọn xác định theo cận trên. D là thuật toán tìm kiếm cây."]],"rl":[["code","\\pi(a) = \\frac{e^{Q(a)/\\tau}}{\\sum_{b} e^{Q(b)/\\tau}}"],["p","τ lớn → gần đều (khám phá nhiều); τ nhỏ → gần greedy (xem câu 34)."]],"ex":[["p","Q = (3, 1), τ = 1: π = (0,88; 0,12)."]],"tip":[["p","\"Probability distribution theo value\" = Softmax."]],"fig":false},{"id":"exam-98","part":"exam","n":98,"en":"Which exploration strategy selects actions according to a probability distribution that balances the known rewards with the potential for discovering new rewards?","vi":"Chiến lược khám phá nào chọn hành động theo một phân phối xác suất cân bằng giữa phần thưởng đã biết và khả năng khám phá phần thưởng mới?","opts":[{"l":"A","en":"Softmax Action Selection","vi":"Chọn hành động bằng softmax.","note":""},{"l":"B","en":"Epsilon-Greedy","vi":"ε-greedy.","note":""},{"l":"C","en":"Upper Confidence Bound (UCB)","vi":"Upper Confidence Bound.","note":""},{"l":"D","en":"Temporal Difference Learning","vi":"Học Temporal Difference.","note":""}],"ans":"A","ansnote":"","exp":[["p","Cùng ý với câu 97: softmax cho phân phối xác suất theo giá trị. B chỉ có hai chế độ. C chọn xác định theo cận trên. D không phải chiến lược khám phá."]],"rl":[["p","So sánh: ε-greedy (xs ε ngẫu nhiên, không phân biệt hành động khác), softmax (xs tỉ lệ theo e^{Q/τ}), UCB (chọn định theo Q + c√(ln t / N))."]],"ex":[["p","Ba tay với Q = (5, 4, 1): softmax cho tay 1 và 2 xs cao, tay 3 thấp nhưng vẫn khác 0; ε-greedy cho tay 2 và 3 cùng xs ε/3."]],"tip":[["p","Softmax = \"xác suất tỷ lệ với giá trị\", UCB = \"cộng thêm thưởng cho cái ít thử\", ε-greedy = \"tung đồng xu\"."]],"fig":false},{"id":"exam-99","part":"exam","n":99,"en":"What is the \"exploration-exploitation trade-off\" in reinforcement learning?","vi":"\"Đánh đổi khám phá-khai thác\" trong học tăng cường là gì?","opts":[{"l":"A","en":"The decision between using known information versus gathering new information","vi":"Quyết định giữa dùng thông tin đã biết và thu thập thông tin mới.","note":""},{"l":"B","en":"The choice between high reward and low risk","vi":"Lựa chọn giữa phần thưởng cao và rủi ro thấp.","note":""},{"l":"C","en":"The balance between reward and punishment","vi":"Sự cân bằng giữa thưởng và phạt.","note":""},{"l":"D","en":"The selection between multiple reward mechanisms","vi":"Lựa chọn giữa nhiều cơ chế phần thưởng.","note":""}],"ans":"A","ansnote":"","exp":[["p","Agent phải cân nhắc dùng hành động đang biết là tốt (khai thác) hay thử hành động mới để có thể tìm được lựa chọn tốt hơn (khám phá). B, C, D không phải định nghĩa này."]],"rl":[["p","Khám phá giúp cải thiện ước lượng nhưng tốn cơ hội nhận reward ngay. Khai thác tối đa hóa reward hiện tại nhưng có thể kẹt ở lựa chọn kém. Công cụ: ε-greedy, UCB, softmax, optimistic initial values."]],"ex":[["p","Chọn món quen thuộc (khai thác) hay thử quán mới (khám phá) mỗi bữa tối."]],"tip":[["p","Explore = \"thử\", Exploit = \"dùng\". Trade-off vì bạn không thể vừa thử vừa dùng cùng một lượt."]],"fig":false},{"id":"exam-100","part":"exam","n":100,"en":"In reinforcement learning, what is an agent?","vi":"Trong học tăng cường, agent (tác nhân) là gì?","opts":[{"l":"A","en":"A human supervisor","vi":"Một người giám sát.","note":""},{"l":"B","en":"A software program","vi":"Một chương trình phần mềm.","note":""},{"l":"C","en":"An entity that interacts with the environment","vi":"Một thực thể tương tác với môi trường.","note":""},{"l":"D","en":"A mathematical equation","vi":"Một phương trình toán học.","note":""}],"ans":"C","ansnote":"","exp":[["p","Agent là bất kỳ thực thể quan sát trạng thái, chọn hành động và nhận reward từ môi trường (có thể là phần mềm, robot, hay con người). A không phải agent. B chỉ đúng một phần (agent không nhất thiết là phần mềm). D sai vì phương trình không tương tác."]],"rl":[["p","Agent = người ra quyết định; Environment = mọi thứ bên ngoài agent mà nó không kiểm soát được hoàn toàn. Ranh giới agent-environment là ranh giới quyền kiểm soát."]],"ex":[["p","Xe tự lái: phần mềm điều khiển là agent; đường, xe khác, thời tiết là environment."]],"tip":[["p","Agent = \"kẻ hành động\" (thực thể tương tác với môi trường)."]],"fig":false},{"id":"exam-101","part":"exam","n":101,"en":"What is the key objective of using a Temporal Difference (TD) learning algorithm? (choose the best answer/core idea of TD learning)","vi":"Mục tiêu chính của việc dùng thuật toán học Temporal Difference (TD) là gì? (chọn đáp án tốt nhất / ý tưởng cốt lõi của TD)","opts":[{"l":"A","en":"To estimate the value of a state based on the complete return from a full episode","vi":"Ước lượng giá trị trạng thái dựa trên return đầy đủ của cả episode.","note":""},{"l":"B","en":"To update the value function by using the difference between successive state values","vi":"Cập nhật hàm giá trị bằng hiệu giữa giá trị các trạng thái liên tiếp.","note":""},{"l":"C","en":"To learn the optimal value function without requiring a model of the environment's dynamics","vi":"Học hàm giá trị tối ưu mà không cần mô hình động lực của môi trường.","note":""},{"l":"D","en":"To approximate the total return by bootstrapping from the immediate reward and the estimated value of the next state","vi":"Xấp xỉ tổng return bằng bootstrapping từ reward tức thời và giá trị ước lượng của trạng thái kế tiếp.","note":""}],"ans":"D","ansnote":"","exp":[["p","Ý tưởng cốt lõi của TD là thay return thật G_t (chưa biết) bằng ước lượng R_{t+1} + γV(S_{t+1}) — đó chính là bootstrapping. A mô tả Monte Carlo (cần cả episode). B nghe giống TD nhưng chỉ mô tả cơ chế cập nhật (TD error), chưa nói lên mục tiêu \"xấp xỉ return bằng bootstrapping\". C là đặc điểm của model-free (cũng đúng với MC, Q-learning), không riêng TD. Câu hỏi nhấn \"core idea\" nên chọn D."]],"rl":[["code","V(S_t) \\leftarrow V(S_t) + \\alpha\\,[\\,R_{t+1} + \\gamma V(S_{t+1}) - V(S_t)\\,]"],["p","TD target = R_{t+1} + γV(S_{t+1}); TD error δ_t = target − V(S_t). TD kết hợp MC (học từ kinh nghiệm, không cần mô hình) và DP (bootstrap)."]],"ex":[["p","V(A) = 10, từ A sang B nhận R = 2, V(B) = 8, γ = 1, α = 0,5. Target = 2 + 8 = 10, δ = 0, V(A) giữ nguyên 10. Nếu V(B) = 12 thì target = 14, δ = 4, V(A) ← 10 + 0,5·4 = 12."]],"tip":[["p","TD = \"đoán dựa trên một đoán khác\" (bootstrap). MC phải chờ hết episode; TD cập nhật ngay sau mỗi bước."]],"fig":false},{"id":"exam-102","part":"exam","n":102,"en":"Which of the following methods is associated with distribution models for handling uncertainty in state transitions?","vi":"Phương pháp nào sau đây gắn với mô hình phân phối (distribution models) để xử lý tính bất định trong chuyển trạng thái?","opts":[{"l":"A","en":"Markov Decision Processes (MDPs)","vi":"Quá trình quyết định Markov.","note":""},{"l":"B","en":"Policy Gradient Methods","vi":"Phương pháp gradient chính sách.","note":""},{"l":"C","en":"Particle Filters","vi":"Bộ lọc hạt.","note":""},{"l":"D","en":"Q-Learning","vi":"Q-learning.","note":""}],"ans":"A","ansnote":"","exp":[["p","MDP được định nghĩa bằng hàm động lực p(s', r | s, a) — chính là một distribution model, cho toàn bộ phân phối xác suất của trạng thái kế tiếp và reward. B và D là thuật toán học (model-free), không phải mô hình. C là kỹ thuật suy luận trạng thái ẩn (POMDP/lọc), thiên về sample-based chứ không phải khung cho phân phối chuyển trạng thái của RL."]],"rl":[["p","Distribution model: cho mọi khả năng và xác suất của nó, p(s', r | s, a). Sample model: chỉ trả ra một mẫu (s', r) ngẫu nhiên theo phân phối đó. Distribution model mạnh hơn (từ nó tạo được sample) nhưng khó có hơn."]],"ex":[["p","Đổ xúc xắc: distribution model nói \"mỗi mặt 1/6\"; sample model chỉ đổ và trả về một mặt."]],"tip":[["p","MDP = \"bảng xác suất đầy đủ\" → distribution model."]],"fig":false},{"id":"exam-103","part":"exam","n":103,"en":"Which of the following is a key benefit of using Dyna Architecture?","vi":"Lợi ích chính của việc dùng kiến trúc Dyna là gì?","opts":[{"l":"A","en":"Reduced computational resources","vi":"Giảm tài nguyên tính toán.","note":""},{"l":"B","en":"Increased data redundancy","vi":"Tăng dư thừa dữ liệu.","note":""},{"l":"C","en":"Improved model scalability and adaptability","vi":"Cải thiện khả năng mở rộng và thích nghi của mô hình.","note":""},{"l":"D","en":"Simplified system design","vi":"Đơn giản hóa thiết kế hệ thống.","note":""}],"ans":"C","ansnote":"","exp":[["p","Dyna kết hợp học từ kinh nghiệm thật với planning trên mô hình đã học, nên hiệu quả mẫu cao và thích nghi tốt khi môi trường thay đổi. A sai vì planning tốn thêm tính toán. B vô nghĩa. D sai vì Dyna phức tạp hơn (thêm mô hình + planning)."]],"rl":[["p","Mỗi bước Dyna-Q: (1) hành động thật, cập nhật Q (direct RL); (2) cập nhật mô hình Model(s,a) → (r, s'); (3) lặp n lần planning: lấy cặp (s, a) đã gặp, mô phỏng, cập nhật Q (indirect RL)."]],"ex":[["p","n = 50: mỗi bước thật kèm 50 cập nhật tưởng tượng → học nhanh hơn Q-learning thuần."]],"tip":[["p","Dyna = \"vừa sống thật vừa nằm mơ tập luyện\": thêm planning để tiết kiệm mẫu thật."]],"fig":false},{"id":"exam-104","part":"exam","n":104,"en":"What is the relationship between sample efficiency and sample-based models?","vi":"Mối quan hệ giữa hiệu quả mẫu (sample efficiency) và mô hình dựa trên mẫu (sample-based models) là gì?","opts":[{"l":"A","en":"Sample-based models are more sample-efficient than distribution models","vi":"Mô hình mẫu hiệu quả mẫu hơn mô hình phân phối.","note":""},{"l":"B","en":"Sample-based models are generally less sample-efficient than distribution models","vi":"Mô hình mẫu thường kém hiệu quả mẫu hơn mô hình phân phối.","note":""},{"l":"C","en":"Both types of models have the same sample efficiency","vi":"Cả hai như nhau.","note":""},{"l":"D","en":"Sample efficiency is not a concern in reinforcement learning","vi":"Hiệu quả mẫu không phải vấn đề trong RL.","note":""}],"ans":"A","ansnote":"theo đáp án của đề","exp":[["p","Đề chọn A. Lưu ý: về mặt lý thuyết, distribution model thường cập nhật chính xác hơn (expected update, không nhiễu lấy mẫu) nên B mới là phát biểu \"chuẩn sách\" của Sutton & Barto (sample update gây nhiễu, nhưng rẻ hơn mỗi bước tính). Đây có thể là lỗi khóa/đề; hãy ghi nhớ đáp án A để thi theo đề, nhưng hiểu bản chất ở phần dưới. C và D sai rõ ràng (D sai vì sample efficiency là vấn đề trung tâm của RL)."]],"rl":[["p","Expected update (distribution model): tính trung bình có trọng số trên mọi s' → chính xác, nhưng tốn O(số s') mỗi lần. Sample update (sample model): dùng một s' mẫu → rẻ, có phương sai. Với nhiều s' khả dĩ, sample update thường hiệu quả hơn về công tính toán."]],"ex":[["p","Mỗi trạng thái có 100 trạng thái kế: expected update tốn 100 phép tính; sample update chỉ 1 nhưng nhiễu."]],"tip":[["p","Distribution = chính xác nhưng đắt; Sample = rẻ nhưng nhiễu. Khi thi: chọn theo khóa (A)."]],"fig":false},{"id":"exam-105","part":"exam","n":105,"en":"What does the exploration in Gaussian policies rely on?","vi":"Việc khám phá trong chính sách Gaussian dựa vào điều gì?","opts":[{"l":"A","en":"Random noise added to the mean action","vi":"Nhiễu ngẫu nhiên cộng vào hành động trung bình.","note":""},{"l":"B","en":"Random sampling from a uniform distribution","vi":"Lấy mẫu ngẫu nhiên từ phân phối đều.","note":""},{"l":"C","en":"Fixed exploration rate","vi":"Tỷ lệ khám phá cố định.","note":""},{"l":"D","en":"Adaptive exploration based on reward feedback","vi":"Khám phá thích nghi theo phản hồi reward.","note":""}],"ans":"A","ansnote":"","exp":[["p","Chính sách Gaussian: a ~ N(μ(s), σ²(s)); hành động = trung bình + nhiễu Gaussian, độ lệch chuẩn σ quyết định mức khám phá. B sai (phân phối Gaussian, không đều). C sai vì σ có thể học được. D sai vì khám phá đến từ σ, không trực tiếp từ reward."]],"rl":[["code","\\pi(a|s,\\theta) = \\frac{1}{\\sigma\\sqrt{2\\pi}}\\exp\\!\\Big(-\\frac{(a-\\mu)^2}{2\\sigma^2}\\Big)"],["p","Dùng cho không gian hành động liên tục; σ giảm dần thì policy ngày càng tiến tới tất định."]],"ex":[["p","μ = 2,0, σ = 0,5: hành động thường rơi trong khoảng 1,0–3,0 (±2σ)."]],"tip":[["p","Gaussian = \"trung bình + nhiễu hình chuông\"."]],"fig":false},{"id":"exam-106","part":"exam","n":106,"en":"Which factor influences the stability of policy gradient algorithms during training?","vi":"Yếu tố nào ảnh hưởng đến độ ổn định của thuật toán policy gradient trong quá trình huấn luyện?","opts":[{"l":"A","en":"Learning rate","vi":"Tốc độ học.","note":""},{"l":"B","en":"Discount factor","vi":"Hệ số chiết khấu.","note":""},{"l":"C","en":"Exploration rate","vi":"Tỷ lệ khám phá.","note":""},{"l":"D","en":"Entropy regularization","vi":"Chuẩn hóa entropy.","note":""}],"ans":"A","ansnote":"","exp":[["p","Policy gradient cập nhật θ ← θ + α∇J(θ); α quá lớn làm policy dao động/sụp đổ, quá nhỏ thì học chậm, nên learning rate là yếu tố ảnh hưởng ổn định rõ nhất theo đáp án. B đổi bài toán/độ xa nhìn, không phải tham số ổn định huấn luyện. C, D ảnh hưởng chủ yếu đến khám phá (D có thể giúp ổn định gián tiếp nhưng không phải yếu tố điển hình)."]],"rl":[["code","\\theta_{t+1} = \\theta_t + \\alpha\\,\\widehat{\\nabla J(\\theta_t)}"],["p","Cách làm ổn định hơn: baseline/critic giảm phương sai, trust region (TRPO), clipping (PPO), giảm α dần."]],"ex":[["p","α = 1 khiến policy chuyển từ 50/50 sang 100/0 chỉ sau một bước; α = 0,01 thì chuyển từ từ."]],"tip":[["p","\"Động đất khi huấn luyện → xem learning rate trước\"."]],"fig":false},{"id":"exam-107","part":"exam","n":107,"en":"Which of the following algorithms is commonly used in reinforcement learning?","vi":"Thuật toán nào sau đây thường được dùng trong học tăng cường?","opts":[{"l":"A","en":"k-Nearest Neighbors","vi":"k láng giềng gần nhất.","note":""},{"l":"B","en":"Q-Learning","vi":"Q-learning.","note":""},{"l":"C","en":"Principal Component Analysis","vi":"Phân tích thành phần chính.","note":""},{"l":"D","en":"Decision Trees","vi":"Cây quyết định.","note":""}],"ans":"B","ansnote":"","exp":[["p","Q-learning là thuật toán RL kinh điển (off-policy TD control). A, D là supervised learning, C là unsupervised (giảm chiều) — không phải RL."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\,[\\,R + \\gamma \\max_{a'} Q(S',a') - Q(S,A)\\,]"]],"ex":[["p","Q(S,A) = 2, R = 1, max Q(S',·) = 4, γ = 0,9, α = 0,5: target = 1 + 3,6 = 4,6; Q mới = 2 + 0,5·2,6 = 3,3."]],"tip":[["p","\"Q\" = Quality of action; các thuật toán có reward + state + action là RL."]],"fig":false},{"id":"exam-108","part":"exam","n":108,"en":"What is a potential disadvantage of using Expected Sarsa over Sarsa?","vi":"Nhược điểm tiềm ẩn của Expected Sarsa so với Sarsa là gì?","opts":[{"l":"A","en":"It tends to have higher variance in updates","vi":"Phương sai cập nhật cao hơn.","note":""},{"l":"B","en":"It requires knowledge of the policy's action probabilities","vi":"Cần biết xác suất chọn hành động của policy.","note":""},{"l":"C","en":"It converges more slowly than Sarsa","vi":"Hội tụ chậm hơn Sarsa.","note":""},{"l":"D","en":"It cannot be used in online learning settings","vi":"Không dùng được cho học online.","note":""}],"ans":"B","ansnote":"","exp":[["p","Expected Sarsa tính kỳ vọng Σπ(a'|S')Q(S',a') nên phải biết π(a'|S') và duyệt mọi hành động (tốn tính toán hơn). A sai: nó giảm phương sai vì bỏ nhiễu từ việc lấy mẫu A'. C sai: thường tốt hoặc bằng Sarsa. D sai: vẫn online được."]],"rl":[["code","Q(S,A) \\leftarrow Q(S,A) + \\alpha\\,[\\,R + \\gamma \\sum_{a'} \\pi(a'|S')Q(S',a') - Q(S,A)\\,]"],["p","Sarsa dùng Q(S',A') với A' đã lấy mẫu; Expected Sarsa dùng kỳ vọng → phương sai thấp hơn nhưng tốn công tính toán."]],"ex":[["p","Q(S',·) = (4, 2), π = (0,5; 0,5): kỳ vọng = 3. Sarsa có thể ra 4 hoặc 2 tùy ngẫu nhiên."]],"tip":[["p","Expected Sarsa = \"Sarsa lấy trung bình\": đổi thêm tính toán để lấy ít nhiễu."]],"fig":false},{"id":"exam-109","part":"exam","n":109,"en":"In the sample average method, what does the step size parameter determine?","vi":"Trong phương pháp trung bình mẫu, tham số step size quyết định điều gì?","opts":[{"l":"A","en":"The total number of actions taken","vi":"Tổng số hành động đã thực hiện.","note":""},{"l":"B","en":"The influence of the most recent reward on the estimate","vi":"Mức ảnh hưởng của reward gần nhất lên ước lượng.","note":""},{"l":"C","en":"The number of ads to display","vi":"Số quảng cáo hiển thị.","note":""},{"l":"D","en":"The initial value of Q","vi":"Giá trị khởi tạo của Q.","note":""}],"ans":"B","ansnote":"","exp":[["p","Công thức Q_{n+1} = Q_n + α(R_n − Q_n): α là trọng số cho reward mới nhất. Với sample average α = 1/n (giảm dần); với α hằng thì reward gần đây được coi trọng hơn. A, D không liên quan; C là nhiễu (đề dựa trên ví dụ quảng cáo băng ghế)."]],"rl":[["code","Q_{n+1} = Q_n + \\frac{1}{n}\\,(R_n - Q_n)"],["p","Mọi reward có trọng số bằng nhau khi α = 1/n; α hằng → trung bình mũ, phù hợp bài toán không dừng (non-stationary)."]],"ex":[["p","Q_1 = 4, R_2 = 10, n = 2 → Q_2 = 4 + 0,5·6 = 7. Với α = 0,1: Q_2 = 4,6."]],"tip":[["p","Step size = \"bước đi về phía reward mới\": lớn → nhớ mới, quên cũ."]],"fig":false},{"id":"exam-110","part":"exam","n":110,"en":"Which technique is commonly used to reduce the variance of policy gradient estimates?","vi":"Kỹ thuật nào thường dùng để giảm phương sai của ước lượng policy gradient?","opts":[{"l":"A","en":"Actor-Critic methods","vi":"Phương pháp Actor-Critic.","note":""},{"l":"B","en":"Temporal Difference learning","vi":"Học TD.","note":""},{"l":"C","en":"Monte Carlo Tree Search","vi":"MCTS.","note":""},{"l":"D","en":"Model-based reinforcement learning","vi":"RL dựa trên mô hình.","note":""}],"ans":"A","ansnote":"","exp":[["p","Actor-Critic dùng critic (hàm giá trị) thay return Monte Carlo nhiễu, nên giảm phương sai (đánh đổi: thêm chệch). B là thành phần bên trong critic nhưng không phải kỹ thuật policy gradient nói chung. C, D không nhắm đến giảm phương sai gradient."]],"rl":[["code","\\nabla J(\\theta) = \\mathbb{E}\\big[(G_t - b(S_t))\\,\\nabla\\ln\\pi(A_t|S_t,\\theta)\\big]"],["p","Baseline b(s) (thường V(s)) giảm phương sai mà không làm lệch gradient. Actor-Critic: δ_t = R + γV(S') − V(S) thay cho G_t."]],"ex":[["p","REINFORCE: G dao động 0–100; trừ baseline V = 50 → còn ±50, gradient ổn định hơn."]],"tip":[["p","Actor = người diễn (policy), Critic = giám khảo (value) — giám khảo giúp diễn viên đỡ \"run\"."]],"fig":false},{"id":"exam-111","part":"exam","n":111,"en":"What is the primary purpose of the state value function in reinforcement learning?","vi":"Mục đích chính của hàm giá trị trạng thái trong học tăng cường là gì?","opts":[{"l":"A","en":"To determine the probability of taking a certain action","vi":"Xác định xác suất chọn một hành động.","note":""},{"l":"B","en":"To estimate the future rewards from a given state","vi":"Ước lượng phần thưởng tương lai từ một trạng thái.","note":""},{"l":"C","en":"To record the history of visited states","vi":"Ghi lại lịch sử các trạng thái đã qua.","note":""},{"l":"D","en":"To minimize the error rate of predictions","vi":"Giảm tỷ lệ lỗi dự đoán.","note":""}],"ans":"B","ansnote":"","exp":[["p","V(s) đo \"trạng thái này tốt đến mức nào\" bằng return kỳ vọng từ s về sau. A là vai trò của policy π(a|s). C là trajectory/lịch sử. D là mục tiêu của supervised learning."]],"rl":[["code","v_\\pi(s) = \\mathbb{E}_\\pi[G_t \\mid S_t = s] = \\mathbb{E}_\\pi\\Big[\\sum_{k=0}^{\\infty}\\gamma^k R_{t+k+1}\\,\\Big|\\,S_t=s\\Big]"],["p","Phân biệt: v_π(s) (cho trạng thái) vs q_π(s,a) (cho cặp trạng thái-hành động)."]],"ex":[["p","Trong mê cung, ô sát đích có V cao (γ = 0,9, cách đích 1 bước: V ≈ 0,9), ô xa có V thấp."]],"tip":[["p","V = \"Value of being here\" — giá trị của việc đứng ở đây."]],"fig":false},{"id":"exam-112","part":"exam","n":112,"en":"What is the main challenge associated with using parameterized policies in reinforcement learning?","vi":"Thách thức chính khi dùng chính sách tham số hóa trong học tăng cường là gì?","opts":[{"l":"A","en":"They are computationally expensive","vi":"Tốn chi phí tính toán.","note":""},{"l":"B","en":"They often lead to overfitting","vi":"Thường gây overfitting.","note":""},{"l":"C","en":"They require a large amount of training data","vi":"Cần nhiều dữ liệu huấn luyện.","note":""},{"l":"D","en":"They can suffer from local optima","vi":"Có thể mắc kẹt ở cực trị địa phương.","note":""}],"ans":"D","ansnote":"","exp":[["p","Policy gradient là leo đồi trên J(θ) nên chỉ đảm bảo hội tụ tới cực trị địa phương. A, B, C không phải thách thức đặc trưng (policy tham số thường rẻ và gọn hơn bảng giá trị)."]],"rl":[["p","Ưu: xử lý hành động liên tục, policy ngẫu nhiên, thay đổi mượt. Nhược: cực trị địa phương, phương sai cao, nhạy với learning rate."]],"ex":[["p","Hai \"đỉnh\" có trị J khác nhau: khởi tạo gần đỉnh thấp thì leo mãi ở đó."]],"tip":[["p","Gradient ascent = leo núi trong sương mù: lên đỉnh gần nhất chứ chưa chắc đỉnh cao nhất."]],"fig":false},{"id":"exam-113","part":"exam","n":113,"en":"What is the advantage of using a higher number of sample points in estimating the gradient?","vi":"Lợi ích của việc dùng nhiều điểm mẫu hơn khi ước lượng gradient là gì?","opts":[{"l":"A","en":"Increased accuracy","vi":"Tăng độ chính xác.","note":""},{"l":"B","en":"Decreased computation time","vi":"Giảm thời gian tính toán.","note":""},{"l":"C","en":"Reduced memory usage","vi":"Giảm bộ nhớ.","note":""},{"l":"D","en":"Smaller margin of error","vi":"Biên sai số nhỏ hơn.","note":""}],"ans":"A","ansnote":"","exp":[["p","Nhiều mẫu → ước lượng gần giá trị thật hơn (phương sai giảm ∼ 1/N). B, C sai vì nhiều mẫu tốn thêm thời gian và bộ nhớ. D về bản chất cùng ý với A (sai số nhỏ = chính xác hơn) nhưng đề chọn A là phát biểu chính."]],"rl":[["p","Gradient mẫu: (1/N)Σ g_i (g_i là gradient ước lượng từ mẫu thứ i); phương sai giảm theo 1/N, độ lệch chuẩn giảm theo 1/√N (để giảm sai số ÷ 2 cần gấp 4 lần mẫu)."]],"ex":[["p","N = 100 → N = 400: độ lệch chuẩn ước lượng giảm một nửa."]],"tip":[["p","Nhiều mẫu = chính xác hơn nhưng đắt hơn."]],"fig":false},{"id":"exam-114","part":"exam","n":114,"en":"Which statement best describes Tabular Temporal Difference (TD) learning?","vi":"Phát biểu nào mô tả đúng nhất học Temporal Difference dạng bảng (Tabular TD)?","opts":[{"l":"A","en":"It uses a table to store values for each state-action pair","vi":"Dùng bảng lưu giá trị cho từng cặp trạng thái-hành động.","note":""},{"l":"B","en":"It uses function approximation to estimate value functions","vi":"Dùng xấp xỉ hàm để ước lượng hàm giá trị.","note":""},{"l":"C","en":"It updates values based on rewards and state transitions without using tables","vi":"Cập nhật không dùng bảng.","note":""},{"l":"D","en":"It requires the exact model of the environment","vi":"Cần mô hình chính xác của môi trường.","note":""}],"ans":"A","ansnote":"","exp":[["p","\"Tabular\" nghĩa là lưu mỗi giá trị (V(s) hoặc Q(s,a)) thành một ô riêng trong bảng. B, C trái với \"tabular\" (đó là function approximation). D sai vì TD là model-free."]],"rl":[["p","Tabular phù hợp không gian nhỏ; với không gian lớn/liên tục phải dùng FA (tuyến tính, tile coding, mạng nơ-ron). Tabular là trường hợp đặc biệt của FA tuyến tính với one-hot features."]],"ex":[["p","5 trạng thái × 3 hành động → bảng Q có 15 ô."]],"tip":[["p","Tabular = \"bảng tra cứu\", mỗi ô một giá trị."]],"fig":false},{"id":"exam-115","part":"exam","n":115,"en":"What does the Q-Learning update do in the context of planning?","vi":"Cập nhật Q-learning làm gì trong bối cảnh planning?","opts":[{"l":"A","en":"It generates new states","vi":"Sinh ra trạng thái mới.","note":""},{"l":"B","en":"It improves the policy based on updated action values","vi":"Cải thiện policy dựa trên giá trị hành động đã cập nhật.","note":""},{"l":"C","en":"It eliminates the need for a model","vi":"Loại bỏ nhu cầu dùng mô hình.","note":""},{"l":"D","en":"It only focuses on real-world experiences","vi":"Chỉ tập trung vào kinh nghiệm thực.","note":""}],"ans":"B","ansnote":"","exp":[["p","Trong Dyna-Q, bước planning lấy (s, a) đã gặp, hỏi model để có (r, s'), rồi áp dụng cùng công thức Q-learning → Q cập nhật, policy greedy theo Q cũng tốt hơn. A sai (model sinh, không phải update). C sai vì planning CẦN model. D sai vì planning dùng kinh nghiệm mô phỏng."]],"rl":[["p","Random-sample one-step tabular Q-planning: chọn (S,A) ngẫu nhiên → (R,S') từ model → Q-learning update."]],"ex":[["p","Model nhớ (s, a) → (r = 1, s'). Planning 10 lần chỉ bằng tính toán, không cần hành động thật."]],"tip":[["p","Planning = Q-learning trên dữ liệu \"tưởng tượng\"."]],"fig":false},{"id":"exam-116","part":"exam","n":116,"en":"In expected Sarsa, the weights used in the expectation calculation are based on:","vi":"Trong Expected Sarsa, các trọng số dùng khi tính kỳ vọng dựa trên:","opts":[{"l":"A","en":"The rewards received","vi":"Các reward nhận được.","note":""},{"l":"B","en":"The probability of taking each action under the agent's policy","vi":"Xác suất chọn mỗi hành động theo policy của agent.","note":""},{"l":"C","en":"The number of actions available","vi":"Số hành động khả dụng.","note":""},{"l":"D","en":"The current state of the environment","vi":"Trạng thái hiện tại của môi trường.","note":""}],"ans":"B","ansnote":"","exp":[["p","Kỳ vọng Σπ(a'|S')Q(S',a') dùng π(a'|S') làm trọng số cho từng Q(S',a'). A sai (reward nằm ngoài kỳ vọng). C chỉ đúng khi π đều (1/|A|), không tổng quát. D là điều kiện, không phải trọng số."]],"rl":[["code","\\mathbb{E}_\\pi[Q(S',A')\\mid S'] = \\sum_{a'} \\pi(a'|S')\\,Q(S',a')"],["p","Với ε-greedy: π gán (1−ε + ε/|A|) cho hành động greedy và ε/|A| cho các hành động còn lại. Nếu π là greedy thì Expected Sarsa trở thành Q-learning."]],"ex":[["p","2 hành động, Q = (6, 2), ε = 0,2: π = (0,9; 0,1) → kỳ vọng = 5,4 + 0,2 = 5,6."]],"tip":[["p","Expected = \"trung bình có trọng số π\"."]],"fig":false},{"id":"exam-117","part":"exam","n":117,"en":"Which algorithm is commonly used to solve an MDP?","vi":"Thuật toán nào thường được dùng để giải một MDP?","opts":[{"l":"A","en":"K-means clustering","vi":"Phân cụm K-means.","note":""},{"l":"B","en":"Breadth-first search","vi":"Tìm kiếm theo chiều rộng.","note":""},{"l":"C","en":"Value iteration","vi":"Lặp giá trị.","note":""},{"l":"D","en":"Gradient descent","vi":"Giảm gradient.","note":""}],"ans":"C","ansnote":"","exp":[["p","Value iteration (DP) giải MDP đã biết mô hình bằng cách lặp cập nhật Bellman optimality. A là unsupervised, B là tìm đường trên đồ thị không có xác suất/reward tích lũy, D là tối ưu tham số (có dùng trong policy gradient nhưng không phải thuật toán giải MDP điển hình)."]],"rl":[["code","V_{k+1}(s) = \\max_a \\sum_{s',r} p(s',r|s,a)\\,[\\,r + \\gamma V_k(s')\\,]"],["p","Các thuật toán giải MDP: policy iteration, value iteration (DP, cần mô hình); Q-learning, Sarsa, MC (model-free)."]],"ex":[["p","V_0 = 0; 1 bước với reward 1 → V_1 = 1; lặp đến khi thay đổi nhỏ hơn ngưỡng θ."]],"tip":[["p","Value iteration = \"cứ cập nhật max Bellman cho đến khi V ngừng đổi\"."]],"fig":false},{"id":"exam-118","part":"exam","n":118,"en":"What is a common approach to reduce the variance in Monte Carlo estimates?","vi":"Cách tiếp cận phổ biến nào để giảm phương sai của ước lượng Monte Carlo?","opts":[{"l":"A","en":"Using a discount factor","vi":"Dùng hệ số chiết khấu.","note":""},{"l":"B","en":"Using importance sampling","vi":"Dùng importance sampling.","note":""},{"l":"C","en":"Using eligibility traces","vi":"Dùng eligibility traces.","note":""},{"l":"D","en":"Using linear function approximation","vi":"Dùng xấp xỉ hàm tuyến tính.","note":""}],"ans":"C","ansnote":"theo đáp án của đề","exp":[["p","Theo khóa, C: eligibility traces (TD(λ)) nối MC và TD, cho phép giảm phương sai bằng cách bootstrap một phần (λ < 1). B là câu dễ nhầm: importance sampling dùng để sửa lệch off-policy và thường LÀM TĂNG phương sai (weighted IS giảm bớt). A là định nghĩa return, D không liên quan phương sai MC."]],"rl":[["code","G_t^{\\lambda} = (1-\\lambda)\\sum_{n=1}^{\\infty}\\lambda^{n-1}G_{t:t+n}"],["p","λ = 0 → TD(0) (phương sai thấp, chệch cao); λ = 1 → Monte Carlo (phương sai cao, không chệch). Cho Monte Carlo: ngoài ra có thể dùng baseline, weighted IS."]],"ex":[["p","Return MC dao động mạnh giữa episode; TD(λ = 0,9) trộn với ước lượng bootstrap nên ổn định hơn."]],"tip":[["p","Bias–variance: MC = ít chệch nhiều nhiễu; TD = chệch nhẹ ít nhiễu; λ là núm xoay giữa hai đầu. Importance sampling ≠ giảm phương sai."]],"fig":false},{"id":"exam-119","part":"exam","n":119,"en":"In contrast to Dynamic Programming and Monte Carlo methods, what aspect makes Temporal Difference (TD) methods more suitable for online learning?","vi":"So với Quy hoạch động và Monte Carlo, khía cạnh nào khiến TD phù hợp hơn cho học trực tuyến?","opts":[{"l":"A","en":"TD methods are slower to update values","vi":"TD cập nhật giá trị chậm hơn.","note":""},{"l":"B","en":"TD methods require extensive computational resources","vi":"TD cần nhiều tài nguyên tính toán.","note":""},{"l":"C","en":"TD methods update values based on incomplete sequences","vi":"TD cập nhật dựa trên chuỗi chưa hoàn tất.","note":""},{"l":"D","en":"TD methods are less flexible in adapting to changing environments","vi":"TD kém linh hoạt khi môi trường thay đổi.","note":""}],"ans":"C","ansnote":"","exp":[["p","TD cập nhật ngay sau mỗi bước (không chờ hết episode như MC, không cần quét toàn bộ trạng thái như DP) nên phù hợp học online. A, B, D đều là đặc điểm ngược lại."]],"rl":[["p","DP: cần mô hình, bootstrap, quét mọi trạng thái. MC: không cần mô hình, không bootstrap, chờ hết episode. TD: không cần mô hình, bootstrap, cập nhật mỗi bước, dùng được cho bài toán liên tục (không episode)."]],"ex":[["p","Robot chạy vô hạn không có \"hết episode\": chỉ TD cập nhật được liên tục."]],"tip":[["p","TD = \"học từng bước\" (online), MC = \"học sau trận\", DP = \"học theo sách\" (cần bản đồ)."]],"fig":false},{"id":"exam-120","part":"exam","n":120,"en":"What is the Bellman equation used for in the context of MDPs?","vi":"Phương trình Bellman được dùng để làm gì trong bối cảnh MDP?","opts":[{"l":"A","en":"To determine the optimal policy","vi":"Xác định policy tối ưu.","note":""},{"l":"B","en":"To update the value function","vi":"Cập nhật hàm giá trị.","note":""},{"l":"C","en":"To calculate the transition probabilities","vi":"Tính xác suất chuyển.","note":""},{"l":"D","en":"To find the immediate reward","vi":"Tìm reward tức thời.","note":""}],"ans":"B","ansnote":"","exp":[["p","Bellman cho quan hệ đệ quy giữa giá trị các trạng thái, dùng làm quy tắc cập nhật trong policy evaluation/value iteration. A là bước tiếp theo (cần thêm greedification), C và D là thành phần đầu vào của phương trình chứ không phải mục đích. (So sánh Câu 125: đáp án nêu quan hệ giữa giá trị các trạng thái kế tiếp.)"]],"rl":[["code","v_\\pi(s) = \\sum_a \\pi(a|s)\\sum_{s',r}p(s',r|s,a)\\,[\\,r+\\gamma v_\\pi(s')\\,]"]],"ex":[["p","Một hành động duy nhất, r = 1, γ = 0,9, v(s') = 10 → v(s) = 1 + 9 = 10."]],"tip":[["p","Bellman = \"giá trị hiện tại = reward + γ × giá trị tiếp\"; việc cập nhật V dùng nó."]],"fig":false},{"id":"exam-121","part":"exam","n":121,"en":"In the context of linear function approximation, what is the gradient of the value function approximation?","vi":"Trong xấp xỉ hàm tuyến tính, gradient của hàm giá trị xấp xỉ là gì?","opts":[{"l":"A","en":"The true value of the state","vi":"Giá trị thật của trạng thái.","note":""},{"l":"B","en":"The feature vector in that state","vi":"Vector đặc trưng tại trạng thái đó.","note":""},{"l":"C","en":"The mean squared error","vi":"","note":"số bình phương trung bình"},{"l":"D","en":"The policy value","vi":"Giá trị của policy.","note":""}],"ans":"B","ansnote":"","exp":[["p","Với v̂(s, w) = wᵀx(s), đạo hàm theo w chính là x(s). Đây là lý do cập nhật tuyến tính rất gọn. A là target (không phải gradient), C là hàm mục tiêu, D không liên quan."]],"rl":[["code","\\hat v(s,\\mathbf w)=\\mathbf w^\\top \\mathbf x(s),\\quad \\nabla_{\\mathbf w}\\hat v(s,\\mathbf w)=\\mathbf x(s),\\quad \\mathbf w \\leftarrow \\mathbf w+\\alpha\\,[U_t-\\hat v(S_t,\\mathbf w)]\\,\\mathbf x(S_t)"],["p","U_t là target (G_t cho MC, R + γ v̂(S') cho semi-gradient TD)."]],"ex":[["p","x(s) = (1, 2), w = (0,5; 0,5) → v̂ = 1,5; target 3, α = 0,1: sai số 1,5 → w = (0,65; 0,8)."]],"tip":[["p","Tuyến tính → gradient = feature."]],"fig":false},{"id":"exam-122","part":"exam","n":122,"en":"Which phase of Policy Iteration involves updating the policy based on the current value function?","vi":"Giai đoạn nào của Policy Iteration cập nhật policy dựa trên hàm giá trị hiện tại?","opts":[{"l":"A","en":"Policy Evaluation","vi":"Đánh giá policy.","note":""},{"l":"B","en":"Policy Improvement","vi":"Cải thiện policy.","note":""},{"l":"C","en":"Policy Initialization","vi":"Khởi tạo policy.","note":""},{"l":"D","en":"Policy Iteration","vi":"Chính tên thuật toán (gồm cả hai pha).","note":""}],"ans":"B","ansnote":"","exp":[["p","Policy Improvement làm policy greedy theo v hiện tại. A tính v_π, C chỉ làm một lần ở đầu, D là toàn bộ vòng lặp."]],"rl":[["code","\\pi'(s)=\\arg\\max_a \\sum_{s',r}p(s',r|s,a)\\,[\\,r+\\gamma v_\\pi(s')\\,]"],["p","Policy iteration: π₀ → E → v_π₀ → I → π₁ → ... cho đến khi π không đổi. Đây là một dạng GPI."]],"ex":[["p","v(s1) = 5, v(s2) = 9; từ s0 nếu hướng sang s2 tốt hơn thì policy mới chọn hướng đó."]],"tip":[["p","E = đo điểm (evaluate), I = đổi chiến thuật theo điểm (improve)."]],"fig":false},{"id":"exam-123","part":"exam","n":123,"en":"In the context of function approximation, what does Mu of S represent?","vi":"Trong xấp xỉ hàm, μ(s) biểu thị điều gì?","opts":[{"l":"A","en":"The total number of states","vi":"Tổng số trạng thái.","note":""},{"l":"B","en":"The probability distribution of state visits","vi":"Phân phối xác suất viếng thăm các trạng thái.","note":""},{"l":"C","en":"The error in value function approximation","vi":"","note":"số xấp xỉ hàm giá trị"},{"l":"D","en":"The learning rate of the algorithm","vi":"Tốc độ học.","note":""}],"ans":"B","ansnote":"","exp":[["p","μ(s) là phân phối on-policy của các trạng thái, dùng để trọng số sai số trong mục tiêu VE. A, C, D không đúng."]],"rl":[["code","\\overline{VE}(\\mathbf w)=\\sum_{s}\\mu(s)\\,[\\,v_\\pi(s)-\\hat v(s,\\mathbf w)\\,]^2"],["p","Vì tài nguyên mô hình có hạn, FA phải đánh đổi: đúng hơn ở các trạng thái hay gặp (μ lớn)."]],"ex":[["p","μ = (0,7; 0,3) và sai số² = (1, 4) → VE = 0,7 + 1,2 = 1,9."]],"tip":[["p","μ = \"mức độ ghé thăm\" của từng trạng thái (mu = mức độ)."]],"fig":false},{"id":"exam-124","part":"exam","n":124,"en":"What does the term \"off-policy\" refer to in the context of Expected Sarsa?","vi":"Thuật ngữ \"off-policy\" trong Expected Sarsa nghĩa là gì?","opts":[{"l":"A","en":"Learning from actions that are not taken by the agent","vi":"Học từ những hành động mà agent không thực hiện.","note":""},{"l":"B","en":"Learning from actions that are taken by the agent","vi":"Học từ hành động agent thực hiện.","note":""},{"l":"C","en":"Learning without any prior knowledge of the environment","vi":"Học mà không biết trước môi trường.","note":""},{"l":"D","en":"Learning that does not depend on the current policy","vi":"Học không phụ thuộc policy hiện tại.","note":""}],"ans":"A","ansnote":"","exp":[["p","Off-policy: policy đánh giá/cải thiện (target) khác policy sinh dữ liệu (behavior). Expected Sarsa lấy kỳ vọng trên tất cả hành động, kể cả những hành động agent chưa chọn → đáp án A là cách diễn đạt gần nhất. B là on-policy. C, D không phải định nghĩa (D sai vì vẫn phụ thuộc target policy)."]],"rl":[["p","Expected Sarsa có thể on-policy (target = behavior) hoặc off-policy (target π ≠ behavior b). Không cần importance sampling vì đã lấy kỳ vọng theo π cho bước kế tiếp. Q-learning là trường hợp π = greedy."]],"ex":[["p","Behavior ε-greedy khám phá, target greedy: dữ liệu từ hành động ngẫu nhiên vẫn cập nhật theo greedy."]],"tip":[["p","Off = \"học về cái khác với cái đang làm\"."]],"fig":false},{"id":"exam-125","part":"exam","n":125,"en":"What is the Bellman equation used for in the context of MDPs?","vi":"Phương trình Bellman được dùng để làm gì trong bối cảnh MDP?","opts":[{"l":"A","en":"To calculate the shortest path between states","vi":"Tính đường đi ngắn nhất giữa các trạng thái.","note":""},{"l":"B","en":"To update the policy in reinforcement learning","vi":"Cập nhật policy.","note":""},{"l":"C","en":"To express the relationship between the value of a state and the values of its successor states","vi":"Diễn tả quan hệ giữa giá trị của một trạng thái và giá trị các trạng thái kế tiếp.","note":""},{"l":"D","en":"To compute the transition probabilities between states to get maximum rewards","vi":"Tính xác suất chuyển để đạt reward tối đa.","note":""}],"ans":"C","ansnote":"","exp":[["p","Đây là định nghĩa đúng nhất của Bellman: v(s) liên hệ đệ quy với v(s'). A là bài toán đồ thị. B là việc của policy improvement. D nhầm: xác suất chuyển là đầu vào của MDP, không phải thứ Bellman tính."]],"rl":[["code","v_\\pi(s)=\\mathbb{E}_\\pi[R_{t+1}+\\gamma v_\\pi(S_{t+1})\\mid S_t=s]"]],"ex":[["p","Các trạng thái kế s₁, s₂ với xs 0,5 và v = 10, 20; r = 0, γ = 1 → v(s) = 15."]],"tip":[["p","Bellman = \"giá trị ở đây = trung bình (reward + γ giá trị kế tiếp)\"."]],"fig":false},{"id":"exam-126","part":"exam","n":126,"en":"What distinguishes Temporal Difference (TD) methods from Monte Carlo methods regarding the handling of incomplete episodes?","vi":"Điều gì phân biệt TD với Monte Carlo khi xử lý các episode chưa kết thúc?","opts":[{"l":"A","en":"TD methods require complete episodes for updating values","vi":"TD cần episode hoàn chỉnh để cập nhật.","note":""},{"l":"B","en":"TD methods update values based on incomplete episodes","vi":"TD cập nhật giá trị dựa trên episode chưa hoàn tất.","note":""},{"l":"C","en":"TD methods cannot handle incomplete episodes efficiently","vi":"TD không xử lý tốt episode dở dang.","note":""},{"l":"D","en":"TD methods do not rely on experiences for learning","vi":"TD không dùng kinh nghiệm để học.","note":""}],"ans":"B","ansnote":"","exp":[["p","TD bootstrap từ ước lượng V(S') nên không cần biết return cuối cùng, cập nhật được ngay giữa episode. A mô tả MC. C ngược thực tế. D sai vì TD học từ kinh nghiệm (model-free)."]],"rl":[["p","MC cần G_t = tổng reward đến hết episode; TD chỉ cần (S, A, R, S'). Vì vậy TD dùng được cho cả bài toán liên tục không có điểm kết thúc."]],"ex":[["p","Episode 1000 bước: MC phải chờ bước 1000; TD cập nhật ở mỗi bước."]],"tip":[["p","MC = chờ cuối phim mới chấm điểm; TD = chấm từng cảnh."]],"fig":false},{"id":"exam-127","part":"exam","n":127,"en":"Which problem arises due to the use of linear function approximation in reinforcement learning?","vi":"Vấn đề nào phát sinh do dùng xấp xỉ hàm tuyến tính trong học tăng cường?","opts":[{"l":"A","en":"Overfitting","vi":"Quá khớp.","note":""},{"l":"B","en":"Curse of dimensionality","vi":"Lời nguyền số chiều.","note":""},{"l":"C","en":"Underfitting","vi":"Thiếu khớp.","note":""},{"l":"D","en":"Vanishing gradients","vi":"Biến mất gradient.","note":""}],"ans":"C","ansnote":"","exp":[["p","Mô hình tuyến tính có năng lực biểu diễn thấp, không nắm được quan hệ phi tuyến → dễ underfit. A xảy ra với mô hình quá mạnh. B là vấn đề của bảng tabular (FA giúp giảm bớt). D đặc trưng mạng sâu."]],"rl":[["p","FA tuyến tính: v̂ = wᵀx(s). Muốn biểu diễn phi tuyến thì phải tự thiết kế feature (tile coding, polynomial, Fourier) hoặc dùng mạng nơ-ron."]],"ex":[["p","V là hàm chữ U theo vị trí; chỉ dùng feature x(s) = s thì đường thẳng không khớp được."]],"tip":[["p","Tuyến tính = \"thước thẳng\" không vẽ được đường cong → underfit."]],"fig":false},{"id":"exam-128","part":"exam","n":128,"en":"In the context of Temporal Difference (TD), which of the following is NOT a step in the TD(0) algorithm?","vi":"Trong TD, đâu KHÔNG phải một bước của thuật toán TD(0)?","opts":[{"l":"A","en":"Prediction","vi":"Dự đoán.","note":""},{"l":"B","en":"Evaluation","vi":"Đánh giá.","note":""},{"l":"C","en":"Backpropagation","vi":"Lan truyền ngược.","note":""},{"l":"D","en":"Bootstrapping","vi":"Bootstrapping.","note":""}],"ans":"C","ansnote":"","exp":[["p","TD(0) tabular không dùng backprop (không có mạng nơ-ron). Prediction/evaluation (ước lượng v_π) và bootstrapping là phần cốt lõi."]],"rl":[["p","Thuật toán TD(0): khởi tạo V; lặp: chọn A theo π, quan sát R, S'; V(S) ← V(S) + α[R + γV(S') − V(S)]."]],"ex":[["p","V(S) = 0, R = 1, V(S') = 2, γ = 1, α = 0,5 → V(S) = 0 + 0,5·3 = 1,5."]],"tip":[["p","TD(0) = \"1 bước nhìn trước\" (0 = không dùng trace), backprop thuộc deep learning."]],"fig":false},{"id":"exam-129","part":"exam","n":129,"en":"What is the primary purpose of Dyna Architecture?","vi":"Mục đích chính của kiến trúc Dyna là gì?","opts":[{"l":"A","en":"To develop operating systems","vi":"Phát triển hệ điều hành.","note":""},{"l":"B","en":"To design scalable web servers","vi":"Thiết kế máy chủ web.","note":""},{"l":"C","en":"To model complex dynamic systems","vi":"Mô hình hóa các hệ động phức tạp.","note":""},{"l":"D","en":"To manage database transactions","vi":"Quản lý giao dịch cơ sở dữ liệu.","note":""}],"ans":"C","ansnote":"","exp":[["p","Trong 4 lựa chọn, chỉ C liên quan đến việc mô hình hóa hệ động (model của môi trường). Thực ra Dyna = tích hợp học trực tiếp, học mô hình và planning. A, B, D là lựa chọn nhiễu ngoài lĩnh vực."]],"rl":[["p","Dyna: trải nghiệm thật → (1) cập nhật Q trực tiếp; (2) học model; (3) planning bằng kinh nghiệm mô phỏng. Xem Câu 103."]],"ex":[["p","Model được cập nhật mỗi bước thật; sau đó planning 20 lần trên model."]],"tip":[["p","Dyna = \"Dynamic + planning\": thêm mô hình để tưởng tượng."]],"fig":false},{"id":"exam-130","part":"exam","n":130,"en":"Which of the following is a key component of Monte Carlo simulations?","vi":"Thành phần chính nào sau đây của mô phỏng Monte Carlo?","opts":[{"l":"A","en":"Deterministic algorithms","vi":"Thuật toán xác định.","note":""},{"l":"B","en":"Random sampling","vi":"Lấy mẫu ngẫu nhiên.","note":""},{"l":"C","en":"Fixed input values","vi":"Giá trị đầu vào cố định.","note":""},{"l":"D","en":"Analytical solutions","vi":"Nghiệm giải tích.","note":""}],"ans":"B","ansnote":"","exp":[["p","Monte Carlo ước lượng bằng cách lấy mẫu ngẫu nhiên nhiều lần rồi lấy trung bình. A, C, D đều ngược bản chất ngẫu nhiên."]],"rl":[["code","v_\\pi(s)\\approx \\frac{1}{N}\\sum_{i=1}^{N}G^{(i)}(s)"],["p","MC trong RL: sinh episode theo π, lấy trung bình return (first-visit hoặc every-visit)."]],"ex":[["p","Return 3 episode từ s: 4, 6, 8 → v(s) ≈ 6."]],"tip":[["p","MC = \"Monte Carlo = của sòng bạc\": tung đi tung lại rồi lấy trung bình."]],"fig":false},{"id":"exam-131","part":"exam","n":131,"en":"In reinforcement learning, the state value function V(s) represents:","vi":"Trong học tăng cường, hàm giá trị trạng thái V(s) biểu thị:","opts":[{"l":"A","en":"The immediate reward received after taking an action in state s","vi":"Reward tức thời sau khi thực hiện hành động ở trạng thái s.","note":""},{"l":"B","en":"The total accumulated reward from state s","vi":"Tổng reward tích lũy từ trạng thái s.","note":""},{"l":"C","en":"The expected return starting from state s","vi":"Return kỳ vọng bắt đầu từ trạng thái s.","note":""},{"l":"D","en":"The likelihood of transitioning from state s to another state","vi":"Khả năng chuyển từ s sang trạng thái khác.","note":""}],"ans":"C","ansnote":"","exp":[["p","V(s) là KỲ VỌNG của return (có chiết khấu) nếu bắt đầu từ s và theo π. A là reward tức thời r. B gần đúng nhưng thiếu từ \"kỳ vọng\" (một quỹ đạo cụ thể chỉ cho một return đơn lẻ, không phải V). D là xác suất chuyển p(s'|s,a)."]],"rl":[["code","V(s)=\\mathbb{E}[G_t\\mid S_t=s],\\quad G_t=R_{t+1}+\\gamma R_{t+2}+\\gamma^2R_{t+3}+\\cdots"]],"ex":[["p","Từ s, 50% có return 10, 50% có return 0 → V(s) = 5 (không phải 10)."]],"tip":[["p","Chữ \"expected\" quyết định: V = trung bình return, không phải tổng một lần chạy."]],"fig":false},{"id":"exam-132","part":"exam","n":132,"en":"What is the main purpose of using optimistic initial values in function approximation?","vi":"Mục đích chính của việc dùng giá trị khởi tạo lạc quan (optimistic initial values) trong xấp xỉ hàm là gì?","opts":[{"l":"A","en":"To ensure faster convergence","vi":"Đảm bảo hội tụ nhanh hơn.","note":""},{"l":"B","en":"To encourage exploration","vi":"Khuyến khích khám phá.","note":""},{"l":"C","en":"To minimize errors","vi":"Giảm thiểu lỗi.","note":""},{"l":"D","en":"To guarantee optimal solutions","vi":"Đảm bảo nghiệm tối ưu.","note":""}],"ans":"B","ansnote":"","exp":[["p","Khởi tạo Q cao hơn giá trị thật → mọi hành động đều \"thất vọng\" khi thử, agent sẽ tiếp tục thử các hành động còn lại. A, C, D không được đảm bảo (và optimistic chỉ hiệu quả lâu dài cho bài toán stationary)."]],"rl":[["p","Với bandit: Q_1(a) = +5 trong khi reward thực ≈ 0 → khai thác greedy vẫn khám phá đủ. Với FA tuyến tính/tile coding, có thể đặt trọng số khởi tạo lớn để tạo hiệu ứng tương tự."]],"ex":[["p","2 tay máy, Q₀ = 5 cho cả hai; thử tay 1 được 1 → Q giảm, tay 2 vẫn 5 → chọn tay 2."]],"tip":[["p","Lạc quan ban đầu → thất vọng dần → thử hết mọi thứ."]],"fig":false},{"id":"exam-133","part":"exam","n":133,"en":"In the Monte Carlo prediction method, what is the purpose of using the policy π?","vi":"Trong phương pháp dự đoán Monte Carlo, mục đích dùng policy π là gì?","opts":[{"l":"A","en":"To determine the sequence of states","vi":"Xác định chuỗi trạng thái.","note":""},{"l":"B","en":"To generate episodes","vi":"Sinh ra các episode.","note":""},{"l":"C","en":"To update the value function","vi":"Cập nhật hàm giá trị.","note":""},{"l":"D","en":"To ensure convergence of the algorithm","vi":"Đảm bảo hội tụ.","note":""}],"ans":"B","ansnote":"","exp":[["p","MC prediction đánh giá v_π: agent chạy theo π để sinh episode, rồi trung bình return. C là việc của thuật toán (sau khi có return), không phải vai trò của π. A không chính xác (chuỗi trạng thái do cả môi trường). D đảm bảo hội tụ cần thêm điều kiện."]],"rl":[["p","First-visit MC: mỗi episode, với lần đầu tiên s xuất hiện, lấy G và thêm vào Returns(s); V(s) = trung bình Returns(s). Off-policy: episode do b sinh, hiệu chỉnh bằng importance sampling."]],"ex":[["p","Chạy theo π ba episode, thấy s với G = 2, 4, 6 → V(s) = 4."]],"tip":[["p","π = \"người chơi\" sinh dữ liệu; MC = \"người chấm\" tổng kết."]],"fig":false},{"id":"exam-134","part":"exam","n":134,"en":"What does the term \"semi-gradient\" refer to in the context of linear semi-gradient Temporal Difference learning?","vi":"Thuật ngữ \"semi-gradient\" trong học TD bán gradient tuyến tính nghĩa là gì?","opts":[{"l":"A","en":"Using gradients to update the table values","vi":"Dùng gradient để cập nhật giá trị trong bảng.","note":""},{"l":"B","en":"Approximating gradients using a non-linear function","vi":"Xấp xỉ gradient bằng hàm phi tuyến.","note":""},{"l":"C","en":"Using part of the gradient information to update parameters","vi":"Dùng một phần thông tin gradient để cập nhật tham số.","note":""},{"l":"D","en":"Calculating exact gradients for function updates","vi":"Tính gradient chính xác.","note":""}],"ans":"C","ansnote":"","exp":[["p","Trong TD, target U_t = R + γv̂(S', w) cũng phụ thuộc w nhưng ta COI NÓ LÀ HẰNG khi lấy đạo hàm → chỉ dùng một phần gradient (phần của v̂(S, w)), nên gọi là semi-gradient. D sai vì không phải gradient đầy đủ. A, B không đúng ý nghĩa."]],"rl":[["code","\\mathbf w \\leftarrow \\mathbf w + \\alpha\\,[R+\\gamma\\hat v(S',\\mathbf w)-\\hat v(S,\\mathbf w)]\\,\\nabla\\hat v(S,\\mathbf w)"],["p","Semi-gradient TD không phải gradient descent của bất kỳ hàm mục tiêu nào, nhưng với tuyến tính on-policy vẫn hội tụ (tới TD fixed point). Off-policy + bootstrapping + FA = deadly triad."]],"ex":[["p","Gradient đầy đủ sẽ thêm −γ∇v̂(S') ở vế phải; semi-gradient bỏ nó."]],"tip":[["p","Semi = nửa: chỉ đạo hàm \"nửa\" đầu của sai số."]],"fig":false},{"id":"exam-135","part":"exam","n":135,"en":"In reinforcement learning, what does a stochastic policy do?","vi":"Trong học tăng cường, chính sách ngẫu nhiên (stochastic policy) làm gì?","opts":[{"l":"A","en":"Selects actions randomly with equal probability","vi":"Chọn hành động ngẫu nhiên với xác suất bằng nhau.","note":""},{"l":"B","en":"Selects the same action for a given state every time","vi":"Luôn chọn cùng một hành động cho một trạng thái.","note":""},{"l":"C","en":"Selects actions based on a probability distribution","vi":"Chọn hành động dựa trên phân phối xác suất.","note":""},{"l":"D","en":"Does not select any action","vi":"Không chọn hành động nào.","note":""}],"ans":"C","ansnote":"","exp":[["p","Stochastic policy cho π(a|s) là phân phối bất kỳ (không nhất thiết đều). A là trường hợp đặc biệt (uniform). B là deterministic. D vô lý."]],"rl":[["p","Deterministic: a = π(s). Stochastic: π(a|s) = P(A_t = a | S_t = s), Σ_a π(a|s) = 1. Policy ngẫu nhiên cần thiết cho khám phá và cho môi trường bất định/đối kháng."]],"ex":[["p","π(left|s) = 0,7, π(right|s) = 0,3."]],"tip":[["p","Stochastic = \"tung xúc xắc có trọng số\" (có thể không đều)."]],"fig":false},{"id":"exam-136","part":"exam","n":136,"en":"What does the term \"greedification\" refer to in the context of policy improvement?","vi":"Thuật ngữ \"greedification\" trong cải thiện policy chỉ điều gì?","opts":[{"l":"A","en":"Making a policy more random","vi":"Làm policy ngẫu nhiên hơn.","note":""},{"l":"B","en":"Selecting actions that maximize the value function","vi":"Chọn hành động tối đa hóa hàm giá trị.","note":""},{"l":"C","en":"Evaluating the performance of a policy","vi":"Đánh giá hiệu năng của policy.","note":""},{"l":"D","en":"Following the original policy without changes","vi":"Giữ nguyên policy gốc.","note":""}],"ans":"B","ansnote":"","exp":[["p","Greedification = làm policy \"tham lam\" theo hàm giá trị hiện tại: π'(s) = argmax_a q_π(s,a). A ngược (greedy làm policy xác định hơn). C là policy evaluation. D là không đổi."]],"rl":[["code","\\pi'(s)=\\arg\\max_a q_\\pi(s,a)\\quad\\Rightarrow\\quad v_{\\pi'}(s)\\ge v_\\pi(s)\\ \\ \\forall s"],["p","Policy improvement theorem: greedy theo q_π không bao giờ tệ hơn π."]],"ex":[["p","q(s, ·) = (3, 7, 5) → π'(s) = hành động 2."]],"tip":[["p","Greed = tham lam → lấy max."]],"fig":false},{"id":"exam-137","part":"exam","n":137,"en":"Which of the following is NOT a typical component of a reinforcement learning model?","vi":"Thành phần nào sau đây KHÔNG phải là thành phần điển hình của một mô hình (model) học tăng cường?","opts":[{"l":"A","en":"State transition probabilities","vi":"Xác suất chuyển trạng thái.","note":""},{"l":"B","en":"Reward function","vi":"Hàm phần thưởng.","note":""},{"l":"C","en":"Policy network","vi":"Mạng policy.","note":""},{"l":"D","en":"Action space","vi":"Không gian hành động.","note":""}],"ans":"C","ansnote":"","exp":[["p","\"Model\" trong RL là mô hình MÔI TRƯỜNG: chuyển trạng thái p, hàm reward r (và không gian S, A). Policy network là thành phần của AGENT (biểu diễn π), không thuộc model môi trường."]],"rl":[["p","Các thành phần RL: policy, reward signal, value function, (tùy chọn) model. MDP = (S, A, p, r, γ)."]],"ex":[["p","Model trong Dyna: Model(s,a) → (r, s'). Policy network: mạng nhận s → xs các a."]],"tip":[["p","Model = \"bản sao môi trường\"; Policy = \"bộ não agent\"."]],"fig":false},{"id":"exam-138","part":"exam","n":138,"en":"In an experiment, a pigeon is trained to peck a key when it sees a red light but not when it sees a green light. This is an example of:","vi":"Trong một thí nghiệm, chim bồ câu được huấn luyện mổ vào nút khi thấy đèn đỏ nhưng không mổ khi thấy đèn xanh. Đây là ví dụ của:","opts":[{"l":"A","en":"Generalization","vi":"Khái quát hóa.","note":""},{"l":"B","en":"Spontaneous recovery","vi":"Hồi phục tự phát.","note":""},{"l":"C","en":"Discrimination","vi":"Phân biệt kích thích.","note":""},{"l":"D","en":"Habituation","vi":"Quen hóa.","note":""}],"ans":"C","ansnote":"","exp":[["p","Phản ứng khác nhau với các kích thích khác nhau (mổ khi đỏ, không mổ khi xanh) là discrimination. A: phản ứng giống nhau với kích thích tương tự (ví dụ mổ cả đỏ lẫn cam). B: phản ứng đã dập tắt xuất hiện lại sau nghỉ. D: giảm phản ứng với kích thích lặp lại vô hại."]],"rl":[["p","Đây là kiến thức tâm lý học học tập (operant conditioning), nền tảng để RL hình thành: discriminative stimulus ≈ trạng thái, peck ≈ action, thức ăn ≈ reward. Trong RL, học π(a|s) khác nhau cho s khác nhau chính là discrimination."]],"ex":[["p","Chó ngồi khi nghe \"sit\" nhưng không ngồi khi nghe \"stand\" = discrimination."]],"tip":[["p","Discrimination = \"phân biệt\" (đỏ ≠ xanh); Generalization = \"gộp chung\" (đỏ ≈ cam)."]],"fig":false},{"id":"exam-139","part":"exam","n":139,"en":"How many components does the feature vector have when there are four features and three actions in a stacked representation?","vi":"Vector đặc trưng có bao nhiêu thành phần khi có bốn đặc trưng và ba hành động trong biểu diễn xếp chồng (stacked)?","opts":[{"l":"A","en":"4","vi":"","note":""},{"l":"B","en":"7","vi":"","note":""},{"l":"C","en":"12","vi":"","note":""},{"l":"D","en":"16","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Biểu diễn xếp chồng: mỗi hành động có một khối 4 trọng số riêng → vector dài 4 × 3 = 12; chỉ khối của hành động đang xét mới khác 0, các khối còn lại = 0. A chỉ đếm đặc trưng, B = 4 + 3 (cộng), D = 4² (không có cơ sở)."]],"rl":[["code","\\hat q(s,a_i,\\mathbf w)=\\mathbf w^\\top \\mathbf x(s,a_i),\\quad \\mathbf x(s,a_i)=[\\,\\mathbf 0,\\ldots,\\mathbf x(s),\\ldots,\\mathbf 0\\,]"]],"ex":[["p","x(s) = (a, b, c, d); đối với a₂: (0,0,0,0 | a,b,c,d | 0,0,0,0)."]],"tip":[["p","Stacked = xếp chồng → nhân (features × actions)."]],"fig":false},{"id":"exam-140","part":"exam","n":140,"en":"In policy iteration, what is the role of the policy evaluation step?","vi":"Trong policy iteration, bước đánh giá policy (policy evaluation) có vai trò gì?","opts":[{"l":"A","en":"To improve the policy based on current estimates of the value function","vi":"Cải thiện policy theo ước lượng giá trị hiện tại.","note":""},{"l":"B","en":"To randomly update the policy","vi":"Cập nhật policy ngẫu nhiên.","note":""},{"l":"C","en":"To compute the value function of the current policy","vi":"Tính hàm giá trị của policy hiện tại.","note":""},{"l":"D","en":"To explore different policies without updating them","vi":"Khám phá các policy khác mà không cập nhật.","note":""}],"ans":"C","ansnote":"","exp":[["p","Evaluation tính v_π cho π hiện tại (lặp Bellman expectation). A là improvement. B, D không đúng."]],"rl":[["code","v_{k+1}(s)=\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)\\,[\\,r+\\gamma v_k(s')\\,]"]],"ex":[["p","Policy cho (s → s') với r = 1, γ = 0,5, v_k(s') = 4 → v_{k+1}(s) = 1 + 2 = 3."]],"tip":[["p","E = \"chấm điểm policy\", I = \"sửa policy theo điểm\" (xem Câu 122)."]],"fig":false},{"id":"exam-141","part":"exam","n":141,"en":"Which of the following exploration strategies is commonly used with SARSA?","vi":"Chiến lược khám phá nào sau đây thường được dùng với SARSA?","opts":[{"l":"A","en":"Softmax action selection","vi":"Chọn hành động bằng softmax.","note":""},{"l":"B","en":"Upper Confidence Bound (UCB)","vi":"Upper Confidence Bound.","note":""},{"l":"C","en":"Epsilon-greedy","vi":"ε-greedy.","note":""},{"l":"D","en":"Boltzmann exploration","vi":"Khám phá Boltzmann (chính là softmax).","note":""}],"ans":"C","ansnote":"","exp":[["p","SARSA (và Q-learning) trong sách Sutton & Barto điển hình dùng ε-greedy. A và D thực ra là cùng một kỹ thuật (Boltzmann = softmax) và cũng dùng được, nhưng đáp án khóa là phổ biến nhất. UCB chủ yếu dùng cho bandit."]],"rl":[["p","On-policy SARSA cần policy khám phá (soft policy) để mọi (s,a) đều được thăm. ε-greedy giữ xác suất tối thiểu ε/|A| cho mọi hành động."]],"ex":[["p","ε = 0,1 với 4 hành động: hành động greedy có xs 0,925; mỗi hành động khác 0,025."]],"tip":[["p","SARSA + ε-greedy = cặp đôi đơn giản nhất."]],"fig":false},{"id":"exam-142","part":"exam","n":142,"en":"What advantage does Tile Coding provide compared to a single large lookup table?","vi":"Tile Coding có lợi thế gì so với một bảng tra cứu lớn duy nhất?","opts":[{"l":"A","en":"Increased computational speed","vi":"Tăng tốc độ tính toán.","note":""},{"l":"B","en":"Reduced overfitting","vi":"Giảm overfitting.","note":""},{"l":"C","en":"More memory efficiency","vi":"Tiết kiệm bộ nhớ hơn.","note":""},{"l":"D","en":"Higher resolution of state representation","vi":"Độ phân giải biểu diễn trạng thái cao hơn.","note":""}],"ans":"C","ansnote":"","exp":[["p","Nhiều lưới tile chồng lên nhau, mỗi lưới thô; độ phân giải mịn đạt được nhờ chồng lớp mà không cần bảng cực lớn → dùng ít ô nhớ hơn. D gần đúng (độ phân giải hiệu dụng cao) nhưng đáp án nhấn mạnh ưu điểm bộ nhớ. A, B không phải lợi thế chính."]],"rl":[["p","Tile coding: mỗi lưới (tiling) chia không gian thành các ô (tile), các tiling lệch nhau. Mỗi trạng thái kích hoạt đúng 1 tile/tiling → feature nhị phân thưa; v̂ = Σ w_i trong các tile active; α thường chia cho số tiling."]],"ex":[["p","8 tiling, mỗi lưới 10×10: chỉ 800 trọng số thay vì bảng cực mịn cỡ 80×80 = 6400 ô, mà vẫn tổng quát tốt giữa các trạng thái gần nhau."]],"tip":[["p","Tile = \"nghép gạch chồng lệch\" → ít gạch, phủ mịn."]],"fig":false},{"id":"exam-143","part":"exam","n":143,"en":"Which type of reinforcement learning model typically uses Monte Carlo simulations to estimate values?","vi":"Loại mô hình RL nào thường dùng mô phỏng Monte Carlo để ước lượng giá trị?","opts":[{"l":"A","en":"Sample-based models","vi":"Mô hình dựa trên mẫu.","note":""},{"l":"B","en":"Distribution models","vi":"Mô hình phân phối.","note":""},{"l":"C","en":"Both","vi":"Cả hai.","note":""},{"l":"D","en":"Neither","vi":"Không loại nào.","note":""}],"ans":"A","ansnote":"","exp":[["p","Sample model sinh mẫu chuyển trạng thái để mô phỏng cả episode, rồi trung bình return (Monte Carlo). Distribution model có thể tính kỳ vọng trực tiếp (DP), không cần mô phỏng mẫu."]],"rl":[["p","Sample model: s, a → (r, s') ngẫu nhiên. Distribution model: s, a → toàn bộ p(s', r). Xem Câu 102 và 104."]],"ex":[["p","Chạy 1000 lần mô phỏng từ s bằng sample model, lấy trung bình return → ước lượng v(s)."]],"tip":[["p","Sample → Monte Carlo (cùng chữ \"mẫu\"); Distribution → DP (tính trực tiếp)."]],"fig":false},{"id":"exam-144","part":"exam","n":144,"en":"In Policy Iteration, which step involves evaluating the current policy's performance and updating the value function?","vi":"Trong Policy Iteration, bước nào đánh giá hiệu năng policy hiện tại và cập nhật hàm giá trị?","opts":[{"l":"A","en":"Policy Evaluation","vi":"Đánh giá policy.","note":""},{"l":"B","en":"Policy Improvement","vi":"Cải thiện policy.","note":""},{"l":"C","en":"Policy Initialization","vi":"Khởi tạo policy.","note":""},{"l":"D","en":"Policy Iteration","vi":"Chính thuật toán.","note":""}],"ans":"A","ansnote":"","exp":[["p","Evaluation cập nhật V để phản ánh π hiện tại. B sửa π (không cập nhật V), C chỉ là khởi đầu, D là toàn bộ thuật toán."]],"rl":[["p","Chu kỳ: π → (E) V_π → (I) π' = greedy(V_π) → ... Xem Câu 122 và 140."]],"ex":[["p","Sau khi cập nhật π, V cũ không còn đúng → phải chạy lại Evaluation."]],"tip":[["p","E cập nhật V, I cập nhật π."]],"fig":false},{"id":"exam-145","part":"exam","n":145,"en":"Which of the following is a primary characteristic of a distribution model in reinforcement learning?","vi":"Đặc điểm chính của mô hình phân phối trong RL là gì?","opts":[{"l":"A","en":"It directly samples actions based on a policy","vi":"Trực tiếp lấy mẫu hành động theo policy.","note":""},{"l":"B","en":"It approximates the transition dynamics of the environment","vi":"Xấp xỉ động lực chuyển trạng thái của môi trường.","note":""},{"l":"C","en":"It only updates after the entire episode ends","vi":"Chỉ cập nhật sau khi episode kết thúc.","note":""},{"l":"D","en":"It requires a deterministic policy","vi":"Cần policy xác định.","note":""}],"ans":"B","ansnote":"","exp":[["p","Distribution model mô tả động lực môi trường p(s', r | s, a). A là việc của policy. C là đặc điểm của Monte Carlo. D không liên quan."]],"rl":[["code","p(s',r\\mid s,a)=\\Pr\\{S_{t+1}=s',R_{t+1}=r\\mid S_t=s,A_t=a\\}"],["p","Cho phép tính kỳ vọng đầy đủ (expected update) trong DP, nhưng khó có trong thực tế."]],"ex":[["p","(s,a) → s₁ với 0,8, s₂ với 0,2; kỳ vọng = 0,8·v(s₁) + 0,2·v(s₂)."]],"tip":[["p","Distribution = \"bảng xác suất đầy đủ\", Sample = \"một lần tung đồng xu\"."]],"fig":false},{"id":"exam-146","part":"exam","n":146,"en":"Which term describes a methodical approach to handling episodic tasks?","vi":"Thuật ngữ nào mô tả cách tiếp cận có hệ thống để xử lý các tác vụ theo episode?","opts":[{"l":"A","en":"Ad hoc management","vi":"Quản lý tùy hứng.","note":""},{"l":"B","en":"Reactive management","vi":"Quản lý bị động.","note":""},{"l":"C","en":"Proactive management","vi":"Quản lý chủ động.","note":""},{"l":"D","en":"Time-blocking","vi":"Chia khối thời gian.","note":""}],"ans":"C","ansnote":"","exp":[["p","Đây là câu ngoài lề (thuộc kiểu câu quản lý, không phải kiến thức RL). \"Methodical\" (có hệ thống, lên kế hoạch trước) → proactive. A tùy hứng, B chỉ phản ứng khi có sự cố, D là kỹ thuật quản lý thời gian chứ không phải “cách tiếp cận” chung."]],"rl":[["p","Episodic task = bài toán có điểm kết thúc (ván cờ, mê cung); các episode độc lập. Phân biệt với continuing task (không kết thúc, dùng γ < 1 hoặc average reward)."]],"ex":[["p","Mỗi ván cờ vua là 1 episode; return tính từ bước hiện tại đến khi kết thúc."]],"tip":[["p","Methodical = có kế hoạch = Proactive."]],"fig":false},{"id":"exam-147","part":"exam","n":147,"en":"Which term describes the probability distribution over next states given a current state and action in an MDP?","vi":"Thuật ngữ nào mô tả phân phối xác suất trên các trạng thái kế tiếp cho trạng thái và hành động hiện tại trong MDP?","opts":[{"l":"A","en":"Policy","vi":"Chính sách.","note":""},{"l":"B","en":"Reward function","vi":"Hàm phần thưởng.","note":""},{"l":"C","en":"Transition model","vi":"Mô hình chuyển trạng thái.","note":""},{"l":"D","en":"Value function","vi":"Hàm giá trị.","note":""}],"ans":"C","ansnote":"","exp":[["p","Transition model p(s'|s,a) cho xác suất sang s'. A là π(a|s), B là r(s,a), D là v(s) hay q(s,a)."]],"rl":[["code","p(s'|s,a)=\\sum_{r}p(s',r|s,a)"],["p","Bộ năm của MDP: (S, A, p, r, γ)."]],"ex":[["p","Trạng thái \"đứng\" + hành động \"đi\" → \"đi\" 0,9, \"ngã\" 0,1."]],"tip":[["p","Transition = \"chuyển\" → xác suất chuyển trạng thái. Policy = chọn hành động; Transition = môi trường \"trả lời\"."]],"fig":false},{"id":"exam-148","part":"exam","n":148,"en":"What is the purpose of the accumulated product of important sampling ratios (W) in the off-policy Monte Carlo prediction algorithm?","vi":"Mục đích của tích lũy các tỷ lệ importance sampling (W) trong thuật toán dự đoán Monte Carlo off-policy là gì?","opts":[{"l":"A","en":"To store all past values of Rho","vi":"Lưu mọi giá trị ρ quá khứ.","note":""},{"l":"B","en":"To correct the returns generated by the behavior policy","vi":"Hiệu chỉnh các return sinh ra bởi behavior policy.","note":""},{"l":"C","en":"To calculate the average reward","vi":"Tính reward trung bình.","note":""},{"l":"D","en":"To simplify the algorithm","vi":"Đơn giản hóa thuật toán.","note":""}],"ans":"B","ansnote":"","exp":[["p","Episode do behavior policy b sinh, nhưng ta muốn ước lượng v_π → nhân return với tích ρ = ∏ π/b để sửa lệch. A, C, D không phải mục đích."]],"rl":[["code","\\rho_{t:T-1}=\\prod_{k=t}^{T-1}\\frac{\\pi(A_k|S_k)}{b(A_k|S_k)},\\qquad V(s)=\\frac{\\sum_t\\rho_{t:T-1}G_t}{\\sum_t\\rho_{t:T-1}}\\ \\text{(weighted)}"],["p","Cần điều kiện coverage: b(a|s) > 0 khi π(a|s) > 0. Incremental: W ← W·π/b, C(s) += W, V += (W/C)(G − V)."]],"ex":[["p","π(a|s) = 1, b(a|s) = 0,5 → W = 2: return được nhân đôi vì π thích hành động này gấp đôi b."]],"tip":[["p","W = \"hệ số quy đổi\" từ b sang π. IS sửa lệch nhưng làm tăng phương sai."]],"fig":false},{"id":"exam-149","part":"exam","n":149,"en":"What is the advantage of using policy gradient methods over value-based methods like Q-learning?","vi":"Ưu điểm của phương pháp policy gradient so với phương pháp dựa trên giá trị như Q-learning là gì?","opts":[{"l":"A","en":"Better convergence guarantees","vi":"Bảo đảm hội tụ tốt hơn.","note":""},{"l":"B","en":"Simpler implementation","vi":"Cài đặt đơn giản hơn.","note":""},{"l":"C","en":"More efficient memory usage","vi":"Dùng bộ nhớ hiệu quả hơn.","note":""},{"l":"D","en":"Ability to handle continuous action spaces","vi":"Xử lý được không gian hành động liên tục.","note":""}],"ans":"D","ansnote":"","exp":[["p","Q-learning cần max_a Q(s,a) — khó khi a liên tục. Policy gradient tham số hóa trực tiếp π(a|s) (ví dụ Gaussian) nên xử lý tự nhiên. A sai (chỉ hội tụ cực trị cục bộ). B sai (thêm baseline, critic... phức tạp). C không phải ưu điểm điển hình."]],"rl":[["p","Ưu: hành động liên tục, policy ngẫu nhiên, thay đổi policy mượt (ít dao động hơn ε-greedy). Nhược: phương sai cao, hội tụ cực trị cục bộ, cần nhiều mẫu."]],"ex":[["p","Lái xe: góc lái là số thực; π = N(μ(s), σ²) → lấy mẫu góc lái trực tiếp, không cần rời rạc hóa."]],"tip":[["p","Liên tục? → Policy gradient."]],"fig":false},{"id":"exam-150","part":"exam","n":150,"en":"What differentiates off-policy Q-learning from on-policy methods like SARSA?","vi":"Điểm khác nhau giữa Q-learning (off-policy) và các phương pháp on-policy như SARSA là gì?","opts":[{"l":"A","en":"Q-learning uses past experiences while SARSA uses future predictions","vi":"Q-learning dùng kinh nghiệm quá khứ còn SARSA dùng dự đoán tương lai.","note":""},{"l":"B","en":"Q-learning updates using the highest Q-value of the next state, while SARSA updates using the action actually taken","vi":"Q-learning cập nhật bằng Q lớn nhất của trạng thái kế, còn SARSA dùng hành động thực sự đã chọn.","note":""},{"l":"C","en":"Q-learning requires a model of the environment, while SARSA does not","vi":"Q-learning cần mô hình môi trường, SARSA thì không.","note":""},{"l":"D","en":"Q-learning is based on deterministic policies, while SARSA is based on stochastic policies","vi":"Q-learning dựa trên policy xác định, SARSA dựa trên policy ngẫu nhiên.","note":""}],"ans":"B","ansnote":"","exp":[["p","Đúng định nghĩa: Q-learning dùng max_a' Q(S',a') (target policy greedy), SARSA dùng Q(S',A') với A' đã thực hiện (behavior policy). A mô tả sai cả hai. C sai (cả hai model-free). D sai (cả hai đều có thể học với policy ε-greedy; khác biệt chính ở target)."]],"rl":[["code","\\text{Q-learning: } R+\\gamma\\max_{a'}Q(S',a'),\\qquad \\text{SARSA: } R+\\gamma Q(S',A')"],["p","Ví dụ kinh điển Cliff Walking: SARSA học đường an toàn (tránh mép vực vì tính đến khám phá), Q-learning học đường tối ưu sát vách nhưng đôi khi rơi khi ε-greedy."]],"ex":[["p","Q(S',·) = (4, 2), A' chọn ngẫu nhiên là hành động 2: Q-learning dùng 4, SARSA dùng 2."]],"tip":[["p","SARSA = S-A-R-S'-A' (dùng cả A' thực tế); Q-learning = \"Q lấy max\", không quan tâm A' thực tế."]],"fig":false},{"id":"exam-151","part":"exam","n":151,"en":"What is the main advantage of using linear function approximation in reinforcement learning?","vi":"Ưu điểm chính của xấp xỉ hàm tuyến tính trong học tăng cường là gì?","opts":[{"l":"A","en":"It provides perfect accuracy","vi":"Cho độ chính xác hoàn hảo.","note":""},{"l":"B","en":"It is computationally inexpensive and easy to implement","vi":"Rẻ về tính toán và dễ cài đặt.","note":""},{"l":"C","en":"It ensures convergence to the optimal policy","vi":"Đảm bảo hội tụ đến policy tối ưu.","note":""},{"l":"D","en":"It eliminates the need for exploration","vi":"Loại bỏ nhu cầu khám phá.","note":""}],"ans":"B","ansnote":"","exp":[["p","v̂ = wᵀx(s) chỉ là tích vô hướng, gradient = x(s) nên cập nhật rất rẻ và dễ cài. A sai (chỉ xấp xỉ). C sai (chỉ hội tụ tới TD fixed point, không phải tối ưu). D sai (vẫn cần khám phá)."]],"rl":[["code","\\hat v(s,\\mathbf w)=\\mathbf w^\\top\\mathbf x(s),\\qquad \\nabla\\hat v=\\mathbf x(s)"],["p","Linear + on-policy semi-gradient TD hội tụ (điểm cố định TD); mục tiêu VE là lồi (một cực trị toàn cục)."]],"ex":[["p","3 feature: mỗi cập nhật chỉ tốn 3 phép nhân-cộng, không cần backprop."]],"tip":[["p","Linear = đơn giản, nhanh, rẻ (nhưng năng lực biểu diễn hạn chế)."]],"fig":false},{"id":"exam-152","part":"exam","n":152,"en":"In Actor-Critic with Softmax Policies, how is the action chosen based on the softmax probabilities?","vi":"Trong Actor-Critic với policy softmax, hành động được chọn như thế nào dựa trên xác suất softmax?","opts":[{"l":"A","en":"The action with the highest probability is chosen","vi":"Chọn hành động có xác suất cao nhất.","note":""},{"l":"B","en":"The action is randomly sampled from the distribution","vi":"Hành động được lấy mẫu ngẫu nhiên từ phân phối.","note":""},{"l":"C","en":"The action with the lowest probability is chosen","vi":"Chọn hành động có xác suất thấp nhất.","note":""},{"l":"D","en":"The action with the maximum advantage is chosen","vi":"Chọn hành động có advantage lớn nhất.","note":""}],"ans":"B","ansnote":"","exp":[["p","Policy softmax π(a|s) là một phân phối; hành động được LẤY MẪU theo phân phối đó, giữ được khám phá. A là greedy/argmax (mất ngẫu nhiên, không khả vi được). C vô lý. D không phải cách chọn hành động (advantage dùng để cập nhật)."]],"rl":[["code","\\pi(a|s,\\theta)=\\frac{e^{h(s,a,\\theta)}}{\\sum_b e^{h(s,b,\\theta)}},\\qquad \\nabla\\ln\\pi(a|s)=\\nabla h(s,a)-\\sum_b\\pi(b|s)\\nabla h(s,b)"],["p","Actor = policy softmax, Critic = V(s) cho δ = R + γV(S') − V(S)."]],"ex":[["p","π = (0,6; 0,3; 0,1): chọn hành động 1/2/3 với tỷ lệ 60/30/10%."]],"tip":[["p","Softmax cho xác suất → hãy \"quay vòng quay\" chứ không \"chọn max\"."]],"fig":false},{"id":"exam-153","part":"exam","n":153,"en":"What is the difference between a policy and a value function in an MDP? (choose the best answer)","vi":"Sự khác nhau giữa policy và hàm giá trị trong MDP là gì? (chọn đáp án tốt nhất)","opts":[{"l":"A","en":"A policy defines the reward for a state, while a value function defines the action to take","vi":"Policy xác định reward của trạng thái, hàm giá trị xác định hành động cần làm.","note":""},{"l":"B","en":"A policy is a long-term plan, while a value function is a short-term estimate","vi":"Policy là kế hoạch dài hạn, hàm giá trị là ước lượng ngắn hạn.","note":""},{"l":"C","en":"A policy defines the agent's behavior, while a value function estimates the desirability of a state or action","vi":"Policy xác định hành vi của agent, hàm giá trị ước lượng mức độ đáng mong muốn của trạng thái/hành động.","note":""},{"l":"D","en":"A policy is a mapping from states to actions, while a value function estimates the future rewards from a state","vi":"Policy là ánh xạ từ trạng thái sang hành động, hàm giá trị ước lượng phần thưởng tương lai từ một trạng thái.","note":""}],"ans":"D","ansnote":"theo đáp án của đề; C cũng gần đúng","exp":[["p","D nêu đúng định nghĩa hình thức: π: S → A (hoặc phân phối trên A), v: S → ℝ là kỳ vọng return. C cũng khá chính xác nếu hiểu \"desirability\" là giá trị, nhưng ít cụ thể hơn, nên khóa chọn D. A đảo ngược vai trò. B sai (cả hai không phân biệt theo “dài/ngắn hạn”)."]],"rl":[["p","Policy: π(a|s). Value: v_π(s) = E[G_t | S_t = s], q_π(s,a). Policy cho biết LÀM GÌ, value cho biết TỐT ĐẾN ĐÂU. Từ q có thể suy ra policy (greedy)."]],"ex":[["p","Ở ô s: π(s) = \"phải\" (policy); v(s) = +5 (giá trị ở đó)."]],"tip":[["p","Policy = \"bản chỉ đường\" (đi hướng nào), Value = \"điểm số địa điểm\" (đứng đó tốt đến đâu)."]],"fig":false},{"id":"exam-154","part":"exam","n":154,"en":"Which algorithm uses the state value function to iteratively improve the policy until it converges to the optimal policy?","vi":"Thuật toán nào dùng hàm giá trị trạng thái để lặp cải thiện policy cho đến khi hội tụ về policy tối ưu?","opts":[{"l":"A","en":"Monte Carlo methods","vi":"Phương pháp Monte Carlo.","note":""},{"l":"B","en":"Q-learning","vi":"Q-learning.","note":""},{"l":"C","en":"Policy iteration","vi":"Policy iteration.","note":""},{"l":"D","en":"Temporal Difference learning","vi":"Học TD.","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy iteration xen kẽ evaluation (tính v_π) và improvement (greedy) cho đến khi π ổn định = π*. A, D thiên về ước lượng từ mẫu (không nhấn mạnh vòng lặp evaluation–improvement). B học Q và dùng max, không phải vòng lặp v_π theo π."]],"rl":[["p","Policy iteration hội tụ sau hữu hạn bước (MDP hữu hạn). Value iteration gộp E và I thành một bước max Bellman. GPI là khung tổng quát."]],"ex":[["p","π₀ ngẫu nhiên → v_π₀ → π₁ greedy → v_π₁ → π₂ = π₁ → dừng."]],"tip":[["p","Policy Iteration = \"đo rồi đổi, đo rồi đổi\" cho đến khi hết đổi."]],"fig":false},{"id":"exam-155","part":"exam","n":155,"en":"In Q-learning, how is the action value updated for a given state-action pair?","vi":"Trong Q-learning, giá trị hành động của một cặp trạng thái-hành động được cập nhật như thế nào?","opts":[{"l":"A","en":"Using the expected return","vi":"Dùng return kỳ vọng.","note":""},{"l":"B","en":"Using the maximum action value of the next state","vi":"Dùng giá trị hành động lớn nhất của trạng thái kế tiếp.","note":""},{"l":"C","en":"Using the discounted reward of the next state","vi":"Dùng reward chiết khấu của trạng thái kế.","note":""},{"l":"D","en":"Using the average of all action values","vi":"Dùng trung bình mọi giá trị hành động.","note":""}],"ans":"B","ansnote":"","exp":[["p","Target Q-learning = R + γ max_a' Q(S', a'). A là Monte Carlo/định nghĩa chung. C thiếu phần bootstrap max. D là Expected Sarsa với π đều (không phải Q-learning)."]],"rl":[["code","Q(S,A)\\leftarrow Q(S,A)+\\alpha\\,[R+\\gamma\\max_{a'}Q(S',a')-Q(S,A)]"]],"ex":[["p","Q(S,A) = 1, R = 0, max Q(S',·) = 5, γ = 0,9, α = 0,1 → Q = 1 + 0,1·(4,5 − 1) = 1,35."]],"tip":[["p","Q-learning = \"Quick max\": lấy max của bước kế (xem Câu 150)."]],"fig":false},{"id":"exam-156","part":"exam","n":156,"en":"In reinforcement learning, what is a common downside of pure exploitation without exploration?","vi":"Trong học tăng cường, nhược điểm phổ biến của việc chỉ khai thác mà không khám phá là gì?","opts":[{"l":"A","en":"Increased computational complexity","vi":"Độ phức tạp tính toán tăng.","note":""},{"l":"B","en":"Missing out on potentially better actions that haven't been tried enough","vi":"Bỏ lỡ những hành động có thể tốt hơn nhưng chưa được thử đủ.","note":""},{"l":"C","en":"High variance in reward estimation","vi":"Phương sai cao khi ước lượng reward.","note":""},{"l":"D","en":"Difficulty in policy convergence to get maximum the total rewards","vi":"Khó hội tụ policy để đạt tổng reward tối đa.","note":""}],"ans":"B","ansnote":"","exp":[["p","Greedy thuần túy dễ kẹt ở hành động “tạm tốt” dựa trên ước lượng còn nghèo nàn, không bao giờ thử để phát hiện lựa chọn tốt hơn. A sai (greedy rẻ hơn). C không phải vấn đề chính. D gần đúng nhưng ý chính xác là B (vì không khám phá nên mắc kẹt ở policy kém)."]],"rl":[["p","Giải pháp: ε-greedy, UCB, softmax, optimistic initial values. Với bandit 10 tay, greedy có thể chọn mãi tay kém (xem biểu đồ trong Sutton & Barto, Ch.2)."]],"ex":[["p","Tay A thử 1 lần được 1; tay B chưa thử (thật ra trung bình 5). Greedy mãi chọn A."]],"tip":[["p","“Chỉ chơi món quen” → bỏ lỡ món ngon hơn."]],"fig":false},{"id":"exam-157","part":"exam","n":157,"en":"Which of the following methods is NOT used for Policy Evaluation?","vi":"Phương pháp nào sau đây KHÔNG được dùng cho đánh giá policy?","opts":[{"l":"A","en":"Temporal Difference Learning","vi":"Học TD.","note":""},{"l":"B","en":"Monte Carlo methods","vi":"Monte Carlo.","note":""},{"l":"C","en":"Dynamic Programming","vi":"Quy hoạch động.","note":""},{"l":"D","en":"Deep Q-Networks","vi":"Mạng Deep Q.","note":""}],"ans":"D","ansnote":"","exp":[["p","Policy evaluation ước lượng v_π bằng DP, MC, TD. DQN là thuật toán control (học Q* để tìm policy tối ưu), không phải phương pháp evaluation cho một policy cố định."]],"rl":[["p","Prediction (evaluation): cố định π, ước lượng v_π → DP/MC/TD. Control: tìm π* → policy iteration, Q-learning, SARSA, DQN."]],"ex":[["p","Đo “chiến thuật hiện tại tốt đến đâu” = prediction; tìm chiến thuật tốt nhất = control."]],"tip":[["p","Prediction = chấm điểm; Control = tìm cách được điểm cao nhất."]],"fig":false},{"id":"exam-158","part":"exam","n":158,"en":"How is the reward function related to the policy in reinforcement learning?","vi":"Hàm phần thưởng liên hệ với policy như thế nào trong học tăng cường?","opts":[{"l":"A","en":"The reward function determines the optimal policy","vi":"Hàm reward quyết định policy tối ưu.","note":""},{"l":"B","en":"The reward function is irrelevant to the policy based on the value function","vi":"Hàm reward không liên quan đến policy dựa trên hàm giá trị.","note":""},{"l":"C","en":"The policy is designed to maximize the cumulative reward based on the reward function","vi":"Policy được thiết kế để tối đa hóa reward tích lũy theo hàm reward.","note":""},{"l":"D","en":"The policy defines the reward function","vi":"Policy xác định hàm reward.","note":""}],"ans":"C","ansnote":"","exp":[["p","Mục tiêu RL: tìm π tối đa hóa E[G_t] — return được tính từ reward. A hơi đúng nhưng không chính xác (reward + động lực MDP + γ mới xác định π*). B sai. D đảo ngược quan hệ."]],"rl":[["p","Reward hypothesis: mọi mục tiêu có thể diễn đạt bằng tối đa hóa kỳ vọng tổng reward vô hướng. Thiết kế reward sai → agent học hành vi không mong muốn (reward hacking)."]],"ex":[["p","Reward +1 khi tới đích, −0,01 mỗi bước → policy tối ưu đi đường ngắn nhất."]],"tip":[["p","Reward là “đề bài”, policy là “cách giải” tối ưu đề đó."]],"fig":false},{"id":"exam-159","part":"exam","n":159,"en":"In the context of Markov Decision Processes (MDPs), what does the Bellman equation help to compute?","vi":"Trong MDP, phương trình Bellman giúp tính điều gì?","opts":[{"l":"A","en":"The transition probabilities","vi":"Xác suất chuyển.","note":""},{"l":"B","en":"The optimal policy","vi":"Policy tối ưu.","note":""},{"l":"C","en":"The reward function","vi":"Hàm reward.","note":""},{"l":"D","en":"The state space","vi":"Không gian trạng thái.","note":""}],"ans":"B","ansnote":"","exp":[["p","Phương trình Bellman (optimality) cho v*, q*, từ đó suy ra π* (greedy theo q*). A, C, D là đầu vào của MDP, không phải thứ Bellman tính. (Chi tiết hơn: Bellman tính hàm giá trị; policy tối ưu là hệ quả.)"]],"rl":[["code","\\pi_*(s)=\\arg\\max_a q_*(s,a),\\qquad q_*(s,a)=\\sum_{s',r}p(s',r|s,a)\\,[\\,r+\\gamma\\max_{a'}q_*(s',a')\\,]"],["p","Xem Câu 96, 120, 125 (các câu Bellman cùng chủ đề nhưng đáp án khác nhau tùy cách diễn đạt)."]],"ex":[["p","q*(s, trái) = 3, q*(s, phải) = 7 → π*(s) = phải."]],"tip":[["p","Bellman → giá trị → greedy → policy tối ưu. Khi đề có “optimal”, chọn Bellman optimality."]],"fig":false},{"id":"exam-160","part":"exam","n":160,"en":"What does the term \"iterative\" signify in Iterative Policy Evaluation?","vi":"Thuật ngữ \"iterative\" (lặp) trong Iterative Policy Evaluation có nghĩa là gì?","opts":[{"l":"A","en":"The process involves repeated computation until convergence","vi":"Quá trình tính lặp lại cho đến khi hội tụ.","note":""},{"l":"B","en":"It updates the policy in every iteration","vi":"Cập nhật policy mỗi vòng lặp.","note":""},{"l":"C","en":"It requires iterating through all possible states","vi":"Phải duyệt mọi trạng thái.","note":""},{"l":"D","en":"It involves iterating through different reinforcement learning algorithms","vi":"Lặp qua các thuật toán RL khác nhau.","note":""}],"ans":"A","ansnote":"","exp":[["p","Iterative Policy Evaluation cập nhật v_k → v_{k+1} lặp đi lặp lại cho đến khi thay đổi < θ. B sai (policy giữ nguyên khi evaluation). C là chi tiết một lần quét, không phải ý của “iterative”. D vô nghĩa."]],"rl":[["code","\\Delta=\\max_s|v_{k+1}(s)-v_k(s)|<\\theta\\ \\Rightarrow\\ \\text{stop}"]],"ex":[["p","v_0 = 0 → v_1 = 1 → v_2 = 1,9 → … → hội tụ đến ~10 (nếu γ = 0,9, r = 1)."]],"tip":[["p","Iterative = “lặp cho đến khi ngừng đổi” (Δ < θ)."]],"fig":false},{"id":"exam-161","part":"exam","n":161,"en":"What is the purpose of the discount factor (gamma, γ) in reinforcement learning?","vi":"Mục đích của hệ số chiết khấu (gamma, γ) trong học tăng cường là gì?","opts":[{"l":"A","en":"To control the learning rate of the agent","vi":"Điều khiển tốc độ học của agent.","note":""},{"l":"B","en":"To prioritize recent rewards over distant future rewards","vi":"Ưu tiên reward gần hơn reward xa trong tương lai.","note":""},{"l":"C","en":"To balance exploration and exploitation","vi":"Cân bằng khám phá và khai thác.","note":""},{"l":"D","en":"To determine the convergence rate of the algorithm","vi":"Quyết định tốc độ hội tụ.","note":""}],"ans":"B","ansnote":"","exp":[["p","γ ∈ [0,1] giảm trọng số reward theo thời gian: reward sau k bước được nhân γ^k. A là α. C là ε (hoặc c, τ). D không phải mục đích chính của γ (dù γ < 1 giúp return hữu hạn)."]],"rl":[["code","G_t=\\sum_{k=0}^{\\infty}\\gamma^kR_{t+k+1}\\ \\le\\ \\frac{R_{\\max}}{1-\\gamma}"],["p","γ = 0: chỉ quan tâm reward tức thời (“cận thị”); γ → 1: nhìn xa. Với continuing task cần γ < 1 để return hữu hạn."]],"ex":[["p","R = 10 sau 3 bước, γ = 0,9 → giá trị hiện tại = 10 × 0,9² = 8,1 (nếu R nhận ở R_{t+3})."]],"tip":[["p","γ = “lãi suất chiết khấu”: tiền nhận sớm có giá hơn tiền nhận muộn. α = học, ε = khám phá, γ = tầm nhìn."]],"fig":false},{"id":"exam-162","part":"exam","n":162,"en":"Which method adjusts the exploration-exploitation balance by dynamically altering the reward estimates based on their uncertainty?","vi":"Phương pháp nào điều chỉnh cân bằng khám phá–khai thác bằng cách thay đổi động các ước lượng reward dựa trên độ bất định của chúng?","opts":[{"l":"A","en":"Thompson Sampling","vi":"Thompson Sampling.","note":""},{"l":"B","en":"Epsilon-Greedy","vi":"ε-greedy.","note":""},{"l":"C","en":"Q-Learning","vi":"Q-learning.","note":""},{"l":"D","en":"Upper Confidence Bound (UCB)","vi":"Upper Confidence Bound.","note":""}],"ans":"D","ansnote":"","exp":[["p","UCB cộng một “phần thưởng bất định” vào Q: hành động ít được thử có bất định cao → điểm cao → được chọn. A cũng dựa trên độ bất định (Bayes) nhưng là lấy mẫu từ phân phối hậu nghiệm, không “đổi ước lượng”; đáp án khóa là UCB. B không dùng độ bất định. C không phải chiến lược khám phá."]],"rl":[["code","A_t=\\arg\\max_a\\Big[Q_t(a)+c\\sqrt{\\frac{\\ln t}{N_t(a)}}\\Big]"],["p","N_t(a) nhỏ → bổng lớn → dễ được chọn; N_t(a) = 0 coi như được chọn trước."]],"ex":[["p","t = 100, c = 2: tay A Q = 1 thử 80 lần → bổng ≈ 0,48; tay B Q = 0,8 thử 5 lần → bổng ≈ 1,92 → UCB chọn B."]],"tip":[["p","UCB = “lạc quan trước sự bất định”: chưa biết rõ thì cứ thử."]],"fig":false},{"id":"exam-163","part":"exam","n":163,"en":"If you're preparing for an exam by studying a little bit each day, what type of task is this?","vi":"Nếu bạn ôn thi bằng cách học một chút mỗi ngày, đây là loại tác vụ gì?","opts":[{"l":"A","en":"Episodic task","vi":"Tác vụ theo episode.","note":""},{"l":"B","en":"Continuing task","vi":"Tác vụ liên tục.","note":""},{"l":"C","en":"Project-based task","vi":"Tác vụ theo dự án.","note":""},{"l":"D","en":"Occasional task","vi":"Tác vụ thỉnh thoảng.","note":""}],"ans":"B","ansnote":"theo đáp án của đề","exp":[["p","Học đều đặn mỗi ngày, không có “ranh giới episode” rõ ràng → đúng kiểu tác vụ liên tục. (Chú ý: có thể coi “ôn đến kỳ thi” là episodic vì có điểm kết; hãy theo đáp án của đề.) C, D không phải thuật ngữ RL."]],"rl":[["p","Episodic: có trạng thái kết thúc, các episode độc lập (chơi game). Continuing: không kết thúc, cần γ < 1 hoặc average reward (điều khiển nhiệt độ liên tục)."]],"ex":[["p","Cờ vua = episodic; quản lý tồn kho 24/7 = continuing."]],"tip":[["p","“Học một chút mỗi ngày, không dừng” → Continuing."]],"fig":false},{"id":"exam-164","part":"exam","n":164,"en":"Which algorithm commonly uses the Bellman equation to update the value function?","vi":"Thuật toán nào thường dùng phương trình Bellman để cập nhật hàm giá trị?","opts":[{"l":"A","en":"K-means clustering","vi":"Phân cụm K-means.","note":""},{"l":"B","en":"Q-learning","vi":"Q-learning.","note":""},{"l":"C","en":"Principal Component Analysis (PCA)","vi":"PCA.","note":""},{"l":"D","en":"Gradient descent","vi":"Giảm gradient.","note":""}],"ans":"B","ansnote":"","exp":[["p","Q-learning cập nhật Q bằng Bellman optimality (bootstrap max). A, C là unsupervised. D là tối ưu hóa tổng quát, không dùng Bellman."]],"rl":[["p","Các thuật toán dựa trên Bellman: value iteration, policy iteration (DP); Q-learning, SARSA, TD (sample-based)."]],"ex":[["p","Xem công thức Q-learning ở Câu 155."]],"tip":[["p","Có “value/Q” + “bootstrap” → Bellman."]],"fig":false},{"id":"exam-165","part":"exam","n":165,"en":"Which characteristic distinguishes Policy Iteration from other reinforcement learning methods?","vi":"Đặc điểm nào phân biệt Policy Iteration với các phương pháp RL khác?","opts":[{"l":"A","en":"It focuses solely on immediate rewards","vi":"Chỉ tập trung vào reward tức thời.","note":""},{"l":"B","en":"It disregards the exploration phase","vi":"Bỏ qua pha khám phá.","note":""},{"l":"C","en":"It iteratively improves both policy and value function","vi":"Lặp cải thiện cả policy và hàm giá trị.","note":""},{"l":"D","en":"None of the above","vi":"Không đáp án nào.","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy iteration xen kẽ evaluation (cập nhật V) và improvement (cập nhật π). A sai. B có thể đúng nhưng không phải đặc trưng phân biệt chính. D sai vì C đúng."]],"rl":[["p","PI = DP cần mô hình; GPI: evaluation và improvement tương tác, không nhất thiết hoàn thành từng bước (MC, TD, DQN càng là GPI)."]],"ex":[["p","Xem Câu 122 và 154."]],"tip":[["p","PI = “hai chân đi luân phiên” (E và I)."]],"fig":false},{"id":"exam-166","part":"exam","n":166,"en":"Which type of policy directly associates actions with states without using a value function?","vi":"Loại policy nào liên kết trực tiếp hành động với trạng thái mà không dùng hàm giá trị?","opts":[{"l":"A","en":"Value-based policy","vi":"Policy dựa trên giá trị.","note":""},{"l":"B","en":"Model-based policy","vi":"Policy dựa trên mô hình.","note":""},{"l":"C","en":"Policy-based policy","vi":"Policy dựa trên policy (tham số hóa trực tiếp).","note":""},{"l":"D","en":"Q-learning policy","vi":"Policy của Q-learning.","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy-based (policy gradient) học trực tiếp π(a|s,θ) mà không cần hàm giá trị. A và D lấy policy từ Q (greedy). B dùng mô hình môi trường."]],"rl":[["p","Ba nhóm: value-based (học Q, policy suy ra), policy-based (học π trực tiếp, ví dụ REINFORCE), actor-critic (học cả hai)."]],"ex":[["p","REINFORCE: θ ← θ + α G_t ∇lnπ(A_t|S_t,θ), không cần Q."]],"tip":[["p","Value-based = “học điểm rồi chọn”; Policy-based = “học thẳng cách chơi”."]],"fig":false},{"id":"exam-167","part":"exam","n":167,"en":"Which of the following is NOT a characteristic of the action-value function?","vi":"Điều nào sau đây KHÔNG phải đặc điểm của hàm giá trị hành động?","opts":[{"l":"A","en":"It depends on both the state and the action","vi":"Phụ thuộc cả trạng thái và hành động.","note":""},{"l":"B","en":"It can be used to derive the policy","vi":"Có thể dùng để suy ra policy.","note":""},{"l":"C","en":"It only considers the immediate reward","vi":"Chỉ xét reward tức thời.","note":""},{"l":"D","en":"It is used to estimate the expected return","vi":"Dùng để ước lượng return kỳ vọng.","note":""}],"ans":"C","ansnote":"","exp":[["p","q(s,a) là kỳ vọng RETURN dài hạn, không chỉ reward tức thời. A, B, D đều đúng."]],"rl":[["code","q_\\pi(s,a)=\\mathbb{E}_\\pi[G_t\\mid S_t=s,A_t=a],\\qquad \\pi'(s)=\\arg\\max_a q(s,a)"]],"ex":[["p","Reward tức thời của (s,a) = 0 nhưng q = 8,1 vì dẫn đến mục tiêu sau 2 bước (γ = 0,9, R = 10)."]],"tip":[["p","Giá trị ≠ reward tức thời: value = “tương lai tông hợp”."]],"fig":false},{"id":"exam-168","part":"exam","n":168,"en":"Which of the following statements is true about the SARSA algorithm?","vi":"Phát biểu nào đúng về thuật toán SARSA?","opts":[{"l":"A","en":"SARSA is an off-policy algorithm","vi":"SARSA là off-policy.","note":""},{"l":"B","en":"SARSA always converges to the optimal policy","vi":"SARSA luôn hội tụ đến policy tối ưu.","note":""},{"l":"C","en":"SARSA updates the Q-values using the action taken by the policy","vi":"SARSA cập nhật Q bằng hành động mà policy đã chọn.","note":""},{"l":"D","en":"SARSA requires a model of the environment","vi":"SARSA cần mô hình môi trường.","note":""}],"ans":"C","ansnote":"","exp":[["p","SARSA là on-policy: target = R + γQ(S',A') với A' là hành động thực sự chọn. A sai (on-policy). B sai (chỉ hội tụ tới π* nếu ε giảm dần và thỏa điều kiện). D sai (model-free)."]],"rl":[["code","Q(S,A)\\leftarrow Q(S,A)+\\alpha\\,[R+\\gamma Q(S',A')-Q(S,A)]"],["p","Chuỗi dữ liệu: S, A, R, S', A' → tên “SARSA”."]],"ex":[["p","Q(S,A) = 2, R = 1, Q(S',A') = 3, γ = 1, α = 0,5 → Q = 2 + 0,5·2 = 3."]],"tip":[["p","SARSA = năm chữ cái = năm thành phần dữ liệu cần cho mỗi cập nhật."]],"fig":false},{"id":"exam-169","part":"exam","n":169,"en":"In off-policy Monte Carlo prediction, how is the return corrected?","vi":"Trong dự đoán Monte Carlo off-policy, return được hiệu chỉnh như thế nào?","opts":[{"l":"A","en":"By averaging all returns without any adjustments","vi":"Trung bình mọi return, không hiệu chỉnh.","note":""},{"l":"B","en":"By using the importance sampling ratio","vi":"Dùng tỷ lệ importance sampling.","note":""},{"l":"C","en":"By discarding the returns from the behavior policy","vi":"Bỏ return từ behavior policy.","note":""},{"l":"D","en":"By applying a discount factor","vi":"Áp dụng hệ số chiết khấu.","note":""}],"ans":"B","ansnote":"","exp":[["p","Return sinh bởi b phải nhân ρ = ∏ π/b để ước lượng kỳ vọng dưới π. A gây lệch. C vô lý (mất hết dữ liệu). D ảnh hưởng return nhưng không sửa lệch policy."]],"rl":[["p","Ordinary IS: V = trung bình(ρ G); Weighted IS: V = ΣρG / Σρ (lệch nhẹ nhưng phương sai thấp hơn). Xem Câu 148."]],"ex":[["p","ρ = 2, G = 5 → đóng góp 10 vào tổng IS."]],"tip":[["p","Off-policy MC = “người dịch” ρ dịch từ b sang π."]],"fig":false},{"id":"exam-170","part":"exam","n":170,"en":"Which method is commonly used to improve the efficiency of learning in a sample model?","vi":"Phương pháp nào thường được dùng để cải thiện hiệu quả học trong một mô hình mẫu (sample model)?","opts":[{"l":"A","en":"Bootstrapping","vi":"Bootstrapping.","note":""},{"l":"B","en":"Experience replay","vi":"Phát lại kinh nghiệm.","note":""},{"l":"C","en":"Model-free updates","vi":"Cập nhật model-free.","note":""},{"l":"D","en":"Cross-entropy method","vi":"Phương pháp cross-entropy.","note":""}],"ans":"B","ansnote":"","exp":[["p","Experience replay lưu kinh nghiệm để dùng lại nhiều lần (gần với mô hình mẫu của Dyna), tăng hiệu quả mẫu. A là kỹ thuật cập nhật chung, C ngược với ý tưởng có mô hình, D là tối ưu ngẫu nhiên khác."]],"rl":[["p","Replay buffer: lưu (s,a,r,s'), lấy mẫu ngẫu nhiên để học (DQN) — gần với “model” không tham số của Dyna. Prioritized replay: ưu tiên kinh nghiệm có TD error lớn."]],"ex":[["p","Mỗi bước thật, lấy 32 mẫu từ buffer để cập nhật."]],"tip":[["p","Replay = “xem lại bài cũ để học thêm”."]],"fig":false},{"id":"exam-171","part":"exam","n":171,"en":"What is the role of the model in the Dyna architecture?","vi":"Vai trò của mô hình (model) trong kiến trúc Dyna là gì?","opts":[{"l":"A","en":"To replace the environment","vi":"Thay thế môi trường.","note":""},{"l":"B","en":"To generate random rewards","vi":"Sinh reward ngẫu nhiên.","note":""},{"l":"C","en":"To simulate transitions for planning","vi":"Mô phỏng các chuyển trạng thái để planning.","note":""},{"l":"D","en":"To store past experiences","vi":"Lưu kinh nghiệm đã qua.","note":""}],"ans":"C","ansnote":"","exp":[["p","Model nhớ (s,a) → (r,s'), dùng để sinh kinh nghiệm giả cho bước planning. A sai (không thay thế môi trường thật). B sai. D gần đúng với Dyna-Q dạng bảng (model lưu cặp quan sát) nhưng mục đích chính là mô phỏng."]],"rl":[["p","Dyna-Q: (a) trải nghiệm thật → cập nhật Q; (b) cập nhật Model; (c) n lần planning từ Model. Xem Câu 103, 129."]],"ex":[["p","Model(s,a) = (r = 1, s'); planning cập nhật Q(s,a) mà không cần quay lại môi trường."]],"tip":[["p","Model = “nằm mơ tập luyện”."]],"fig":false},{"id":"exam-172","part":"exam","n":172,"en":"Which statistical concept is importance sampling based on?","vi":"Importance sampling dựa trên khái niệm thống kê nào?","opts":[{"l":"A","en":"Central Limit Theorem","vi":"Định lý giới hạn trung tâm.","note":""},{"l":"B","en":"Law of Large Numbers","vi":"Luật số lớn.","note":""},{"l":"C","en":"Bayes' Theorem","vi":"Định lý Bayes.","note":""},{"l":"D","en":"Markov Chain Monte Carlo","vi":"MCMC.","note":""}],"ans":"B","ansnote":"theo đáp án của đề","exp":[["p","Importance sampling ước lượng kỳ vọng bằng trung bình mẫu có trọng số, hội tụ nhờ Luật số lớn khi số mẫu tăng. Thực ra nó còn dựa trên đổi biến đoạn/đổi phân phối (E_p[f] = E_q[f·p/q]); đáp án khóa chọn B. A dùng cho phân phối trung bình mẫu. C là suy luận xác suất, D là lấy mẫu chuỗi Markov."]],"rl":[["code","\\mathbb{E}_{x\\sim p}[f(x)]=\\mathbb{E}_{x\\sim q}\\Big[f(x)\\frac{p(x)}{q(x)}\\Big]\\approx\\frac1N\\sum_i f(x_i)\\frac{p(x_i)}{q(x_i)}"]],"ex":[["p","q = (0,5; 0,5), p = (0,9; 0,1), f = (10, 0) → E_p = 9; mẫu từ q với trọng số p/q = (1,8; 0,2) cho ước lượng → 9."]],"tip":[["p","“Nhiều mẫu → gần giá trị thật” = Law of Large Numbers."]],"fig":false},{"id":"exam-173","part":"exam","n":173,"en":"In one-step tabular Q-learning, how is the optimal action in a state determined during the learning phase?","vi":"Trong Q-learning dạng bảng một bước, hành động tối ưu tại một trạng thái được xác định như thế nào trong giai đoạn học?","opts":[{"l":"A","en":"By selecting actions randomly","vi":"Chọn hành động ngẫu nhiên.","note":""},{"l":"B","en":"By selecting the action with the highest Q-value","vi":"Chọn hành động có Q cao nhất.","note":""},{"l":"C","en":"By using a predefined action sequence","vi":"Dùng chuỗi hành động định sẵn.","note":""},{"l":"D","en":"By always choosing the first action","vi":"Luôn chọn hành động đầu tiên.","note":""}],"ans":"B","ansnote":"","exp":[["p","Hành động tối ưu theo nghĩa greedy là argmax_a Q(s,a). (Khi HỌC, hành vi thực tế vẫn có thể ε-greedy để khám phá; nhưng “optimal action” là argmax.) A, C, D không được nhắc tới trong thuật toán."]],"rl":[["p","Q-learning: behavior ε-greedy, target greedy. Policy greedy cuối cùng π(s) = argmax_a Q(s,a)."]],"ex":[["p","Q(s,·) = (2, 5, 1) → hành động tối ưu là 2."]],"tip":[["p","Optimal = argmax Q."]],"fig":false},{"id":"exam-174","part":"exam","n":174,"en":"In Q-learning, what does it mean when the Q-values have converged?","vi":"Trong Q-learning, Q-values đã hội tụ có nghĩa là gì?","opts":[{"l":"A","en":"The agent continues to explore all possible actions","vi":"Agent tiếp tục khám phá mọi hành động.","note":""},{"l":"B","en":"The Q-values no longer change significantly","vi":"Q-values không còn thay đổi đáng kể.","note":""},{"l":"C","en":"The agent stops learning and takes random actions","vi":"Agent ngừng học và hành động ngẫu nhiên.","note":""},{"l":"D","en":"The agent updates the Q-values for every action","vi":"Cập nhật Q cho mọi hành động.","note":""}],"ans":"B","ansnote":"","exp":[["p","Hội tụ = Q ổn định quanh Q* (cập nhật không làm đổi đáng kể). A, C, D mô tả hành vi khác."]],"rl":[["p","Q-learning hội tụ về Q* nếu mọi (s,a) được thăm vô hạn lần và α thỏa điều kiện Robbins–Monro (Σα = ∞, Σα² < ∞)."]],"ex":[["p","Q(s,a) qua 5 lần cập nhật: 3,2 → 3,25 → 3,26 → 3,26 → 3,26: đã hội tụ."]],"tip":[["p","Hội tụ = “ngừng dao động”."]],"fig":false},{"id":"exam-175","part":"exam","n":175,"en":"In which of the following scenarios would TD Prediction be most useful?","vi":"Trong tình huống nào dưới đây TD Prediction hữu ích nhất?","opts":[{"l":"A","en":"When we need to find the optimal policy in a simple grid world","vi":"Khi cần tìm policy tối ưu trong grid world đơn giản.","note":""},{"l":"B","en":"When we have a large state space and need to estimate the state values for a given policy","vi":"Khi có không gian trạng thái lớn và cần ước lượng giá trị trạng thái cho một policy cho trước.","note":""},{"l":"C","en":"When we want to learn a model of the environment's transition dynamics","vi":"Khi muốn học mô hình động lực chuyển trạng thái.","note":""},{"l":"D","en":"When we need to solve a multi-armed bandit problem","vi":"Khi giải bài toán bandit nhiều tay.","note":""}],"ans":"B","ansnote":"","exp":[["p","“Prediction” = ước lượng v_π cho π cho trước; TD phù hợp với không gian lớn (kết hợp FA) và học online. A là control. C là học model. D là bandit (không có trạng thái kế tiếp)."]],"rl":[["p","TD prediction: V(S) ← V(S) + α[R + γV(S') − V(S)]; kết hợp linear FA/NN để mở rộng."]],"ex":[["p","Đánh giá một chiến thuật của robot trong môi trường với hàng triệu trạng thái bằng TD + FA."]],"tip":[["p","Prediction = “đo giá trị của policy cố định”; Control = “tìm policy tốt nhất”."]],"fig":false},{"id":"exam-176","part":"exam","n":176,"en":"Which algorithm is an example of a planning method in reinforcement learning?","vi":"Thuật toán nào là ví dụ về phương pháp lập kế hoạch (planning) trong RL?","opts":[{"l":"A","en":"Q-learning","vi":"Q-learning.","note":""},{"l":"B","en":"Deep Q-Networks (DQN)","vi":"DQN.","note":""},{"l":"C","en":"Monte Carlo Tree Search (MCTS)","vi":"Tìm kiếm cây Monte Carlo.","note":""},{"l":"D","en":"SARSA","vi":"SARSA.","note":""}],"ans":"C","ansnote":"","exp":[["p","MCTS dùng mô hình để mô phỏng và xây cây tìm kiếm tại thời điểm quyết định → planning. A, B, D là học model-free từ kinh nghiệm thật."]],"rl":[["p","MCTS: 4 bước lặp: Selection (UCB) → Expansion → Simulation (rollout) → Backup. Chọn nhánh theo UCT = Q + c√(ln N / n). Planning khác: Dyna, value iteration."]],"ex":[["p","AlphaGo dùng MCTS để chọn nước đi tốt nhất từ thế cờ hiện tại."]],"tip":[["p","Planning = “nhắm trước trên bản đồ”; model-free = “cứ đi rồi học”."]],"fig":false},{"id":"exam-177","part":"exam","n":177,"en":"In the Windy Gridworld, what does the wind do to the agent's movement?","vi":"Trong Windy Gridworld, gió tác động thế nào lên chuyển động của agent?","opts":[{"l":"A","en":"It has no effect on the agent's movement","vi":"Không ảnh hưởng.","note":""},{"l":"B","en":"It pushes the agent downwards","vi":"Đẩy agent xuống dưới.","note":""},{"l":"C","en":"It pushes the agent upwards as it moves through windy states","vi":"Đẩy agent lên trên khi đi qua các ô có gió.","note":""},{"l":"D","en":"It randomly changes the agent's direction","vi":"Đổi hướng ngẫu nhiên.","note":""}],"ans":"C","ansnote":"","exp":[["p","Trong ví dụ Sutton & Barto (Example 6.5), mỗi cột có “suức gió” đẩy agent lên (thêm vào dịch chuyển dọc) một số ô bằng cường độ gió của cột đó. A sai. B sai hướng. D sai (phiên bản gốc xác định, không ngẫu nhiên)."]],"rl":[["p","Windy Gridworld: lưới 7×10, gió cường độ 0/1/2 theo cột, reward −1 mỗi bước, episodic, undiscounted. Dùng để minh họa SARSA (đường đi ngắn nhất = 15 bước)."]],"ex":[["p","Ở cột gió = 1, hành động “phải” → sang phải 1 ô và lên 1 ô."]],"tip":[["p","Wind = “thổi bay lên” (upward) — giống gió thổi diều."]],"fig":false},{"id":"exam-178","part":"exam","n":178,"en":"Which of the following best describes an off-policy algorithm?","vi":"Phát biểu nào mô tả đúng nhất một thuật toán off-policy?","opts":[{"l":"A","en":"It optimizes the policy based on past experiences only","vi":"Tối ưu policy chỉ dựa trên kinh nghiệm quá khứ.","note":""},{"l":"B","en":"It updates the policy based on the actions taken by the agent","vi":"Cập nhật policy dựa trên hành động agent thực hiện.","note":""},{"l":"C","en":"It learns from actions that are not necessarily taken by the current policy","vi":"Học từ những hành động không nhất thiết do policy hiện tại chọn.","note":""},{"l":"D","en":"It only learns from the actions dictated by the current policy","vi":"Chỉ học từ hành động do policy hiện tại quyết định.","note":""}],"ans":"C","ansnote":"","exp":[["p","Off-policy: học về target policy π từ dữ liệu do behavior policy b sinh ra. B và D là on-policy. A không định nghĩa off-policy (on-policy cũng có thể dùng kinh nghiệm quá khứ trong buffer như TD)."]],"rl":[["p","Off-policy: Q-learning, off-policy MC (IS), Expected Sarsa khác policy. Lợi: học π* khi đang khám phá, học từ dữ liệu người/policy cũ. Cần coverage: b(a|s) > 0 khi π(a|s) > 0."]],"ex":[["p","Xem robot tập (behavior ngẫu nhiên) để học π tối ưu."]],"tip":[["p","Off = học “khác với cái đang làm”; On = học “cái đang làm”."]],"fig":false},{"id":"exam-179","part":"exam","n":179,"en":"What is the Bellman equation in the context of Q-learning?","vi":"Phương trình Bellman trong bối cảnh Q-learning là gì?","opts":[{"l":"A","en":"It provides the optimal policy directly","vi":"Cho trực tiếp policy tối ưu.","note":""},{"l":"B","en":"It updates the policy based on rewards received","vi":"Cập nhật policy theo reward nhận được.","note":""},{"l":"C","en":"It recursively updates the Q-values using the maximum future reward","vi":"Cập nhật đệ quy Q bằng reward tương lai lớn nhất.","note":""},{"l":"D","en":"It sets the learning rate for the agent","vi":"Đặt tốc độ học.","note":""}],"ans":"C","ansnote":"","exp":[["p","Bellman optimality: q*(s,a) = E[R + γ max_a' q*(S',a')]; Q-learning xấp xỉ nó bằng cập nhật TD. A, B, D sai vai trò."]],"rl":[["code","q_*(s,a)=\\mathbb{E}\\big[R_{t+1}+\\gamma\\max_{a'}q_*(S_{t+1},a')\\mid S_t=s,A_t=a\\big]"]],"ex":[["p","R = 2, γ = 0,5, max Q(S',·) = 6 → target = 2 + 3 = 5."]],"tip":[["p","Q-learning = “hiện tại = reward + γ × max tương lai”."]],"fig":false},{"id":"exam-180","part":"exam","n":180,"en":"Why is it beneficial to update Q-values randomly in Random Tabular Q-planning?","vi":"Vì sao việc cập nhật Q-values ngẫu nhiên lại có lợi trong Random Tabular Q-planning?","opts":[{"l":"A","en":"It ensures that all state-action pairs are updated equally","vi":"Đảm bảo mọi cặp (s,a) được cập nhật như nhau.","note":""},{"l":"B","en":"It helps in better exploration of the state-action space","vi":"Giúp khám phá tốt hơn không gian trạng thái-hành động.","note":""},{"l":"C","en":"It makes the algorithm simpler to implement","vi":"Thuật toán dễ cài đặt hơn.","note":""},{"l":"D","en":"It guarantees convergence to the optimal policy","vi":"Đảm bảo hội tụ đến policy tối ưu.","note":""}],"ans":"B","ansnote":"","exp":[["p","Chọn (s,a) ngẫu nhiên trải đều các cặp có thể, giúp các cặp ít gặp vẫn được cập nhật (bề mặt khám phá không gian). A sai (ngẫu nhiên không đảm bảo “như nhau”). C không phải lý do. D quá mạnh (cần thêm điều kiện)."]],"rl":[["p","Random-sample one-step tabular Q-planning: lặp (1) chọn (S,A) ngẫu nhiên từ những cặp đã gặp; (2) hỏi model → (R,S'); (3) Q-learning update. Xem Câu 115."]],"ex":[["p","Model có 100 cặp (s,a): mỗi lần planning chọn 1 cặp ngẫu nhiên thay vì luôn cùng cặp gần nhất."]],"tip":[["p","Random → “phủ đều” (khám phá), không “bảo đảm bằng nhau”."]],"fig":false},{"id":"exam-181","part":"exam","n":181,"en":"In importance sampling, what role do importance weights play?","vi":"Trong importance sampling, các trọng số quan trọng (importance weights) đóng vai trò gì?","opts":[{"l":"A","en":"They determine the probability of each sample","vi":"Quyết định xác suất của mỗi mẫu.","note":""},{"l":"B","en":"They adjust the contribution of each sample to the estimate","vi":"Điều chỉnh đóng góp của mỗi mẫu vào ước lượng.","note":""},{"l":"C","en":"They control the variance of the estimator","vi":"Kiểm soát phương sai của ước lượng.","note":""},{"l":"D","en":"They are irrelevant in importance sampling","vi":"Không liên quan.","note":""}],"ans":"B","ansnote":"","exp":[["p","Trọng số w = p(x)/q(x) co/giãn đóng góp của mẫu lấy từ q để ước lượng kỳ vọng dưới p. A sai (xác suất mẫu do q quyết định). C sai (weights thường LÀM TĂNG phương sai; weighted IS chỉ giảm bớt). D vô lý."]],"rl":[["p","Ordinary IS: V = (1/n)Σρ_iG_i. Weighted IS: V = Σρ_iG_i/Σρ_i. Ordinary không lệch nhưng phương sai có thể vô hạn; weighted lệch nhẹ nhưng phương sai hữu hạn."]],"ex":[["p","ρ = 0,2 → mẫu này “họ số” ít; ρ = 5 → mẫu “họ số” nhiều."]],"tip":[["p","Weights = “hệ số điều chỉnh đóng góp”."]],"fig":false},{"id":"exam-182","part":"exam","n":182,"en":"What does Temporal Difference offer that traditional learning environments often lack?","vi":"Temporal Difference mang lại điều gì mà môi trường học tập truyền thống thường thiếu?","opts":[{"l":"A","en":"Interactive simulations","vi":"Các mô phỏng tương tác.","note":""},{"l":"B","en":"Passive learning experiences","vi":"Trải nghiệm học thụ động.","note":""},{"l":"C","en":"Inflexible scheduling","vi":"Lịch cố định cứng nhắc.","note":""},{"l":"D","en":"Static course content","vi":"Nội dung khóa học tĩnh.","note":""}],"ans":"A","ansnote":"theo đáp án của đề","exp":[["p","Đây là câu “nhiễu” nằm ngoài nội dung RL: “Temporal Difference” ở đây bị dùng như tên một môi trường học tập. Trong 4 lựa chọn chỉ A (tương tác) là tích cực; B, C, D đều mang nghĩa tiêu cực. Theo đáp án: A."]],"rl":[["p","Về ý nghĩa RL, điểm “tương tác” của TD là: học trực tuyến từng bước từ tương tác với môi trường (xem Câu 119)."]],"ex":[["p","TD cập nhật ngay sau mỗi bước tương tác, không chờ hết episode."]],"tip":[["p","Trong đáp án nhìn “tích cực” (Interactive) hơn “tĩnh” (Passive/Static/Inflexible)."]],"fig":false},{"id":"exam-183","part":"exam","n":183,"en":"What happens to SARSA's learning rate when the step size parameter (Alpha) is decreased?","vi":"Điều gì xảy ra với tốc độ học của SARSA khi tham số step size (Alpha) giảm?","opts":[{"l":"A","en":"It learns faster","vi":"Học nhanh hơn.","note":""},{"l":"B","en":"It learns more slowly but may find a better policy","vi":"Học chậm hơn nhưng có thể tìm được policy tốt hơn.","note":""},{"l":"C","en":"It has no effect on learning","vi":"Không ảnh hưởng.","note":""},{"l":"D","en":"It learns the same rate as before","vi":"Học cùng tốc độ như trước.","note":""}],"ans":"B","ansnote":"","exp":[["p","α nhỏ → mỗi cập nhật dịch Q ít hơn → chậm hơn nhưng ít nhiễu, độ chính xác cuối cao hơn. A, C, D sai."]],"rl":[["p","Đánh đổi: α lớn → nhanh nhưng dao động; α nhỏ → chậm nhưng ổn định. Thường giảm α dần theo thời gian."]],"ex":[["p","Q = 0, target = 10: α = 0,5 → Q = 5; α = 0,1 → Q = 1 (tiến ít mỗi bước)."]],"tip":[["p","α nhỏ = “bước ngắn, chắc chắn”."]],"fig":false},{"id":"exam-184","part":"exam","n":184,"en":"What is the main goal of Monte Carlo estimation?","vi":"Mục tiêu chính của ước lượng Monte Carlo là gì?","opts":[{"l":"A","en":"To minimize the number of actions taken","vi":"Giảm số hành động.","note":""},{"l":"B","en":"To estimate the value of each state by computing a sample average over returns","vi":"Ước lượng giá trị mỗi trạng thái bằng trung bình mẫu các return.","note":""},{"l":"C","en":"To maximize the rewards in a single episode","vi":"Tối đa hóa reward trong một episode.","note":""},{"l":"D","en":"To create a deterministic policy","vi":"Tạo policy xác định.","note":""}],"ans":"B","ansnote":"","exp":[["p","MC: V(s) = trung bình các return quan sát được sau khi ghé thăm s. A, C, D không phải mục tiêu của ước lượng."]],"rl":[["p","First-visit/every-visit; không bootstrap, không cần model, chỉ dùng được với episodic task."]],"ex":[["p","Return từ s qua 4 episode: 2, 6, 4, 8 → V(s) = 5."]],"tip":[["p","MC = “trung bình các return thực tế”."]],"fig":false},{"id":"exam-185","part":"exam","n":185,"en":"What does an Epsilon greedy policy primarily do?","vi":"Policy ε-greedy chủ yếu làm gì?","opts":[{"l":"A","en":"Always selects the greedy action","vi":"Luôn chọn hành động greedy.","note":""},{"l":"B","en":"Randomly selects actions without any preference","vi":"Chọn ngẫu nhiên không ưu tiên.","note":""},{"l":"C","en":"Mostly selects the greedy action but occasionally explores randomly","vi":"Phần lớn chọn greedy nhưng thỉnh thoảng khám phá ngẫu nhiên.","note":""},{"l":"D","en":"Ignores the current action value estimates","vi":"Bỏ qua ước lượng giá trị hiện tại.","note":""}],"ans":"C","ansnote":"","exp":[["p","Với xác suất 1 − ε chọn greedy, với ε chọn ngẫu nhiên. A là greedy thuần, B là ε = 1, D vô lý."]],"rl":[["code","\\pi(a|s)=\\begin{cases}1-\\varepsilon+\\varepsilon/|A| & a=\\arg\\max Q\\\\ \\varepsilon/|A| & \\text{otherwise}\\end{cases}"]],"ex":[["p","ε = 0,1, 4 hành động → greedy 0,925, còn lại 0,025."]],"tip":[["p","ε = “xác suất tung đồng xu” để khám phá."]],"fig":false},{"id":"exam-186","part":"exam","n":186,"en":"What is the primary difference between Monte Carlo methods and dynamic programming?","vi":"Sự khác biệt chính giữa phương pháp Monte Carlo và quy hoạch động là gì?","opts":[{"l":"A","en":"Monte Carlo methods require a model of the environment","vi":"MC cần mô hình môi trường.","note":""},{"l":"B","en":"Dynamic programming learns directly from experience","vi":"DP học trực tiếp từ kinh nghiệm.","note":""},{"l":"C","en":"Monte Carlo methods estimate the value of individual states independently","vi":"MC ước lượng giá trị từng trạng thái một cách độc lập.","note":""},{"l":"D","en":"Dynamic programming does not use episodes","vi":"DP không dùng episode.","note":""}],"ans":"C","ansnote":"","exp":[["p","MC không bootstrap: v(s) ước lượng từ return thực của chính s, không phụ thuộc ước lượng của trạng thái khác; DP bootstrap (v(s) dựa vào v(s')). A, B đảo ngược (DP cần model; MC học từ kinh nghiệm). D sai vì DP không cần episode (đúng) nhưng đây không phải khác biệt chính."]],"rl":[["p","DP: model + bootstrap; MC: không model, không bootstrap, chờ hết episode; TD: không model + bootstrap. Chi phí MC cho mỗi trạng thái không phụ thuộc số trạng thái khác."]],"ex":[["p","Cần ước lượng v(s_A): MC chỉ chạy từ A; DP phải biết v của các trạng thái kế."]],"tip":[["p","MC = “mỗi trạng thái độc lập”; DP = “trạng thái phụ thuộc lẫn nhau”."]],"fig":false},{"id":"exam-187","part":"exam","n":187,"en":"Why might Expected Sarsa be preferred in an environment with high variance in rewards?","vi":"Vì sao Expected Sarsa có thể được ưu tiên trong môi trường có phương sai reward cao?","opts":[{"l":"A","en":"Because it updates the Q-values less frequently","vi":"Vì cập nhật Q ít thường xuyên hơn.","note":""},{"l":"B","en":"Because it uses the expected value which smooths out the updates","vi":"Vì dùng giá trị kỳ vọng nên làm mịn các cập nhật.","note":""},{"l":"C","en":"Because it disregards the rewards","vi":"Vì bỏ qua reward.","note":""},{"l":"D","en":"Because it focuses only on the maximum reward","vi":"Vì chỉ tập trung vào reward lớn nhất.","note":""}],"ans":"B","ansnote":"","exp":[["p","Expected Sarsa thay mẫu A' bằng kỳ vọng theo π → loại bỏ phương sai do chọn hành động, cập nhật mượt hơn (xem Câu 108, 116). A sai (cập nhật mỗi bước như nhau). C và D sai (D là Q-learning)."]],"rl":[["p","Phương sai của Sarsa = phương sai mẫu (R, S') + phương sai mẫu A'; Expected Sarsa bỏ phần thứ hai. Lưu ý: phương sai của CHÍNH reward vẫn còn."]],"ex":[["p","Q(S',·) = (10, 0), π đều: Sarsa lúc ra 10 lúc ra 0 (dao động); Expected Sarsa luôn 5."]],"tip":[["p","Expected = “lấy trung bình cho êm”."]],"fig":false},{"id":"exam-188","part":"exam","n":188,"en":"What is one approach to aggregating states in continuous state spaces?","vi":"Một cách để gộp trạng thái (state aggregation) trong không gian trạng thái liên tục là gì?","opts":[{"l":"A","en":"Using discrete state spaces only","vi":"Chỉ dùng không gian rời rạc.","note":""},{"l":"B","en":"Clustering states based on feature similarity","vi":"Gom cụm các trạng thái theo độ tương đồng đặc trưng.","note":""},{"l":"C","en":"Ignoring state features altogether","vi":"Bỏ qua đặc trưng trạng thái.","note":""},{"l":"D","en":"Randomly grouping states","vi":"Gộp trạng thái ngẫu nhiên.","note":""}],"ans":"B","ansnote":"","exp":[["p","State aggregation gom các trạng thái gần/tương tự thành nhóm và mỗi nhóm dùng chung một giá trị. A không xử lý liên tục. C, D không hợp lý."]],"rl":[["p","State aggregation là trường hợp đặc biệt của FA tuyến tính (feature one-hot theo nhóm); gradient = 1 ở nhóm của s, 0 ở các nhóm khác."]],"ex":[["p","Vị trí xe trong [0,1000] chia 10 nhóm, mỗi nhóm 100 đơn vị → 10 giá trị."]],"tip":[["p","Aggregation = “gom lại”, nhóm gần nhau."]],"fig":false},{"id":"exam-189","part":"exam","n":189,"en":"How can generalization be reduced in a learning environment?","vi":"Làm thế nào để giảm khái quát hóa (generalization) trong môi trường học tập?","opts":[{"l":"A","en":"By reinforcing behaviors inconsistently","vi":"Củng cố hành vi không nhất quán.","note":""},{"l":"B","en":"By using a variety of stimuli during training","vi":"Dùng nhiều loại kích thích trong huấn luyện.","note":""},{"l":"C","en":"By providing specific cues for different responses","vi":"Đưa ra tín hiệu cụ thể cho từng phản ứng.","note":""},{"l":"D","en":"By not reinforcing any behavior","vi":"Không củng cố hành vi nào.","note":""}],"ans":"C","ansnote":"","exp":[["p","Tín hiệu rõ ràng, khác biệt cho từng phản ứng → học discrimination, giảm đáp ứng chung chung (generalization). B thì ngược lại (nhiều kích thích → tăng tổng quát). A, D gây không học được."]],"rl":[["p","Trong FA, generalization = cập nhật ở s ảnh hưởng đến các trạng thái gần. Tile coding rộng → generalize nhiều; hẹp → ít (discrimination cao). Xem Câu 138."]],"ex":[["p","Tile 0,5 → generalize nhiều; tile 0,05 → generalize ít."]],"tip":[["p","Generalization ↑ khi kích thích “giống nhau”; discrimination ↑ khi tín hiệu “khác nhau”."]],"fig":false},{"id":"exam-190","part":"exam","n":190,"en":"Tile Coding is most commonly associated with which type of function approximation in reinforcement learning?","vi":"Tile Coding thường gắn với loại xấp xỉ hàm nào trong RL?","opts":[{"l":"A","en":"Linear function approximation","vi":"Xấp xỉ hàm tuyến tính.","note":""},{"l":"B","en":"Non-linear function approximation","vi":"Xấp xỉ hàm phi tuyến.","note":""},{"l":"C","en":"Polynomial function approximation","vi":"Xấp xỉ đa thức.","note":""},{"l":"D","en":"Radial basis function approximation","vi":"Xấp xỉ hàm cơ sở bán kính (RBF).","note":""}],"ans":"A","ansnote":"","exp":[["p","Tile coding tạo feature nhị phân thưa; giá trị = tổng trọng số các tile active → mô hình tuyến tính theo feature. B, C, D là các họ feature/mô hình khác."]],"rl":[["p","v̂(s,w) = Σ w_i x_i(s), x_i ∈ {0,1}; cập nhật: w ← w + (α/n_tilings)·δ·x. Xem Câu 142."]],"ex":[["p","8 tiling → mỗi trạng thái kích hoạt 8 feature, v̂ là tổng 8 trọng số."]],"tip":[["p","Tile = feature 0/1 → tuyến tính."]],"fig":false},{"id":"exam-191","part":"exam","n":191,"en":"What is the main objective of Actor-Critic algorithms?","vi":"Mục tiêu chính của các thuật toán Actor-Critic là gì?","opts":[{"l":"A","en":"To solely maximize the critic's value function","vi":"Chỉ tối đa hóa hàm giá trị của critic.","note":""},{"l":"B","en":"To learn both a policy (actor) and a value function (critic)","vi":"Học đồng thời policy (actor) và hàm giá trị (critic).","note":""},{"l":"C","en":"To minimize the actor's policy gradient","vi":"Cực tiểu hóa policy gradient của actor.","note":""},{"l":"D","en":"To eliminate the role of the critic in reinforcement learning","vi":"Loại bỏ vai trò của critic.","note":""}],"ans":"B","ansnote":"","exp":[["p","Actor cập nhật policy theo hướng dẫn của critic; critic ước lượng V (TD) để giảm phương sai. A sai (critic học để ước lượng, không “tối đa hóa”). C sai (actor TỐI ĐA hóa J chứ không cực tiểu). D ngược bản chất."]],"rl":[["code","\\delta_t=R_{t+1}+\\gamma\\hat v(S_{t+1},\\mathbf w)-\\hat v(S_t,\\mathbf w),\\quad \\mathbf w\\leftarrow\\mathbf w+\\alpha^{w}\\delta_t\\nabla\\hat v,\\quad \\theta\\leftarrow\\theta+\\alpha^{\\theta}\\delta_t\\nabla\\ln\\pi(A_t|S_t,\\theta)"]],"ex":[["p","δ > 0 (kết quả tốt hơn dự đoán) → tăng xs của hành động vừa làm."]],"tip":[["p","Actor = diễn viên, Critic = giám khảo → học cả hai."]],"fig":false},{"id":"exam-192","part":"exam","n":192,"en":"In which field of study is the estimation of gradients using samples commonly applied?","vi":"Ước lượng gradient bằng mẫu thường được áp dụng trong lĩnh vực nào?","opts":[{"l":"A","en":"Quantum physics","vi":"Vật lý lượng tử.","note":""},{"l":"B","en":"Computer graphics","vi":"Đồ họa máy tính.","note":""},{"l":"C","en":"Sociology","vi":"Xã hội học.","note":""},{"l":"D","en":"Linguistics","vi":"Ngôn ngữ học.","note":""}],"ans":"B","ansnote":"theo đáp án của đề","exp":[["p","Đây là câu ngoài lề: Monte Carlo/gradient từ mẫu được dùng nhiều trong đồ họa (path tracing, differentiable rendering). C, D là khoa học xã hội/ngôn ngữ ít dùng; A cũng có thể dùng nhưng đáp án khóa chọn B."]],"rl":[["p","Trong RL: ước lượng ∇J(θ) bằng mẫu (REINFORCE, score-function estimator); cùng ý tưởng với Monte Carlo gradient estimation."]],"ex":[["p","∇J ≈ (1/N)Σ G_i ∇lnπ(A_i|S_i)."]],"tip":[["p","Gradient từ mẫu = Monte Carlo → nhớ “đồ họa/render” trong câu này."]],"fig":false},{"id":"exam-193","part":"exam","n":193,"en":"What does the average reward in reinforcement learning represent?","vi":"Reward trung bình trong học tăng cường biểu thị điều gì?","opts":[{"l":"A","en":"The total reward accumulated during an episode","vi":"Tổng reward tích lũy trong một episode.","note":""},{"l":"B","en":"The reward obtained at each time step","vi":"Reward nhận được ở mỗi bước thời gian.","note":""},{"l":"C","en":"The mean reward received over multiple episodes","vi":"Reward trung bình qua nhiều episode.","note":""},{"l":"D","en":"The maximum reward achievable in the environment","vi":"Reward tối đa đạt được.","note":""}],"ans":"B","ansnote":"theo đáp án của đề","exp":[["p","Average reward r(π) = tốc độ reward kỳ vọng mỗi bước trong dài hạn (per time step); đúng với B ở ý “mỗi bước”. A là return episodic. C nói “qua nhiều episode” — ý của bài toán liên tục là theo thời gian, không theo episode. D sai."]],"rl":[["code","r(\\pi)=\\lim_{h\\to\\infty}\\frac1h\\sum_{t=1}^{h}\\mathbb{E}[R_t\\mid S_0,A_{0:t-1}\\sim\\pi]=\\sum_s\\mu_\\pi(s)\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)\\,r"],["p","Diễn đạt khác trong continuing task, không dùng γ; định nghĩa differential return G_t = Σ (R_{t+k} − r(π))."]],"ex":[["p","Bộ điều nhiệt mỗi giây nhận −1, 0, −2: reward trung bình ≈ −1 mỗi bước."]],"tip":[["p","Average reward = “lương mỗi bước”."]],"fig":false},{"id":"exam-194","part":"exam","n":194,"en":"In linear function approximation, the value function is typically represented as a linear combination of:","vi":"Trong xấp xỉ hàm tuyến tính, hàm giá trị thường được biểu diễn là tổ hợp tuyến tính của:","opts":[{"l":"A","en":"Rewards (phần thưởng)","vi":"","note":""},{"l":"B","en":"Actions (hành động)","vi":"","note":""},{"l":"C","en":"Features (đặc trưng)","vi":"","note":""},{"l":"D","en":"States (trạng thái)","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","v̂(s,w) = Σ w_i x_i(s): tổ hợp tuyến tính của các FEATURE của trạng thái, không phải của chính trạng thái (D) — nếu là trạng thái thô, hàm chỉ là đường thẳng. A, B không đúng."]],"rl":[["code","\\hat v(s,\\mathbf w)=\\sum_{i=1}^{d}w_i\\,x_i(s)=\\mathbf w^\\top\\mathbf x(s)"],["p","Feature: polynomial, Fourier, tile coding, RBF, ..."]],"ex":[["p","x(s) = (1, s, s²) → v̂ = w₀ + w₁s + w₂s² (tuyến tính theo w, phi tuyến theo s)."]],"tip":[["p","“Tuyến tính theo w”, không nhất thiết theo s."]],"fig":false},{"id":"exam-195","part":"exam","n":195,"en":"How does the concept of average reward differ from the concept of cumulative reward?","vi":"Khái niệm reward trung bình khác với reward tích lũy như thế nào?","opts":[{"l":"A","en":"Average reward considers only the rewards obtained at specific time steps","vi":"Trung bình chỉ xét reward ở một số bước.","note":""},{"l":"B","en":"Cumulative reward is the sum of all rewards received, while average reward is the mean of those rewards","vi":"Tích lũy là tổng mọi reward nhận được, còn trung bình là giá trị trung bình của chúng.","note":""},{"l":"C","en":"Average reward measures the total reward over all episodes, while cumulative reward measures reward at each time step","vi":"Trung bình đo tổng qua mọi episode, tích lũy đo ở mỗi bước.","note":""},{"l":"D","en":"They are synonymous and can be used interchangeably","vi":"Hai khái niệm đồng nghĩa.","note":""}],"ans":"B","ansnote":"","exp":[["p","Cumulative = ΣR_t; average = (1/T)ΣR_t. A, C đảo vai trò/sai. D sai."]],"rl":[["p","Cumulative (return) có thể vô hạn trong continuing task nên phải chiết khấu (γ < 1) hoặc dùng average reward."]],"ex":[["p","Reward 4, 6, 2 trong 3 bước: tích lũy = 12, trung bình = 4."]],"tip":[["p","Cumulative = tổng; Average = tổng ÷ số bước."]],"fig":false},{"id":"exam-196","part":"exam","n":196,"en":"How does context influence generalization in learning?","vi":"Ngữ cảnh (context) ảnh hưởng đến khái quát hóa trong học tập như thế nào?","opts":[{"l":"A","en":"Context always limits the ability to generalize","vi":"Ngữ cảnh luôn hạn chế khả năng khái quát hóa.","note":""},{"l":"B","en":"Similar contexts can enhance the transfer of learning","vi":"Các ngữ cảnh tương tự có thể tăng cường sự chuyển giao kiến thức.","note":""},{"l":"C","en":"Different contexts prevent the application of learned knowledge","vi":"Ngữ cảnh khác nhau ngăn việc áp dụng kiến thức đã học.","note":""},{"l":"D","en":"Context has no significant effect on learning outcomes","vi":"Ngữ cảnh không ảnh hưởng đáng kể.","note":""}],"ans":"B","ansnote":"","exp":[["p","Ngữ cảnh giống nhau → sự chuyển giao (transfer) tốt hơn. A, C quá tuyệt đối (“luôn luôn”, “prevent”). D sai vì ngữ cảnh có ảnh hưởng."]],"rl":[["p","Trong RL: generalization giữa các trạng thái tương tự (FA), transfer learning giữa tác vụ/môi trường gần nhau; ngược lại discrimination khi cần phân biệt."]],"ex":[["p","Huấn luyện robot trong phòng mô phỏng giống thực tế → chuyển sang thực tế tốt hơn."]],"tip":[["p","“Cái gì giống nhau thì học chuyển được”."]],"fig":false},{"id":"exam-197","part":"exam","n":197,"en":"What is the main advantage of using a Gaussian policy in continuous action spaces?","vi":"Ưu điểm chính của policy Gaussian trong không gian hành động liên tục là gì?","opts":[{"l":"A","en":"Simplicity of implementation","vi":"Đơn giản khi cài đặt.","note":""},{"l":"B","en":"Ability to handle discrete actions","vi":"Xử lý được hành động rời rạc.","note":""},{"l":"C","en":"Smoothness and expressiveness","vi":"Tính mượt và khả năng biểu diễn.","note":""},{"l":"D","en":"Faster convergence rate","vi":"Hội tụ nhanh hơn.","note":""}],"ans":"C","ansnote":"","exp":[["p","Gaussian cho phân phối liên tục, khả vi, có μ và σ học được → hành động mượt và biểu diễn được nhiều mức khám phá. B sai (dành cho liên tục). A, D không phải ưu điểm đặc trưng."]],"rl":[["code","\\nabla\\ln\\pi(a|s)=\\frac{(a-\\mu)}{\\sigma^2}\\nabla\\mu+\\frac{(a-\\mu)^2-\\sigma^2}{\\sigma^3}\\nabla\\sigma"],["p","Xem Câu 105, 199."]],"ex":[["p","μ(s) = 0,3 góc lái, σ = 0,1 → hành động sinh ra xấp xỉ 0,3 ± 0,1."]],"tip":[["p","Gaussian = “mượt như chuông”."]],"fig":false},{"id":"exam-198","part":"exam","n":198,"en":"Coarse coding can be seen as a form of which of the following in the context of state aggregation?","vi":"Trong bối cảnh state aggregation, coarse coding có thể xem là một dạng của điều nào?","opts":[{"l":"A","en":"Clustering","vi":"Gom cụm.","note":""},{"l":"B","en":"Overfitting","vi":"Quá khớp.","note":""},{"l":"C","en":"Exact encoding","vi":"Mã hóa chính xác.","note":""},{"l":"D","en":"Model-free learning","vi":"Học model-free.","note":""}],"ans":"A","ansnote":"","exp":[["p","Coarse coding phủ mỗi trạng thái bởi nhiều vùng chồng lấn (vòng tròn); các trạng thái cùng thuộc một số vùng được gộp mềm → giống gom cụm chồng lấn. B là vấn đề của mô hình quá mạnh. C sai (coarse = thô). D không liên quan."]],"rl":[["p","Coarse coding: feature nhị phân (có/không trong vòng). Vùng lớn → generalize rộng, vùng nhỏ → chi tiết. Tile coding là dạng coarse coding với hình dạng lưới."]],"ex":[["p","20 vòng tròn chồng lên nhau; trạng thái s nằm trong 5 vòng → 5 feature = 1."]],"tip":[["p","Coarse = “thô” nhưng chồng lớp → mịn; khác Exact."]],"fig":false},{"id":"exam-199","part":"exam","n":199,"en":"Which algorithm often employs Gaussian policies in reinforcement learning?","vi":"Thuật toán nào thường dùng policy Gaussian trong học tăng cường?","opts":[{"l":"A","en":"Q-Learning","vi":"Q-learning.","note":""},{"l":"B","en":"Deep Q-Networks (DQN)","vi":"DQN.","note":""},{"l":"C","en":"Policy Gradient methods","vi":"Phương pháp policy gradient.","note":""},{"l":"D","en":"Temporal Difference Learning","vi":"Học TD.","note":""}],"ans":"C","ansnote":"","exp":[["p","Gaussian là dạng tham số hóa policy cho hành động liên tục, dùng trong REINFORCE, actor-critic, PPO... A, B, D học Q(s,a) → khó cho hành động liên tục (DQN dùng cho hành động rời rạc)."]],"rl":[["p","Policy gradient + Gaussian: π(a|s) = N(μ_θ(s), σ_θ²(s)); cập nhật θ theo ∇lnπ. Xem Câu 105, 149."]],"ex":[["p","Robot tay máy: mỗi khớp là một mô-men lực liên tục → policy Gaussian."]],"tip":[["p","Liên tục + policy = Gaussian + Policy Gradient."]],"fig":false},{"id":"exam-200","part":"exam","n":200,"en":"What is the advantage of using parameterized policies in reinforcement learning?","vi":"Ưu điểm của việc dùng policy tham số hóa trong học tăng cường là gì?","opts":[{"l":"A","en":"They are simpler to implement","vi":"Đơn giản hơn khi cài đặt.","note":""},{"l":"B","en":"They provide more flexibility in learning complex behaviors","vi":"Linh hoạt hơn khi học hành vi phức tạp.","note":""},{"l":"C","en":"They converge faster to optimal solutions","vi":"Hội tụ nhanh hơn đến nghiệm tối ưu.","note":""},{"l":"D","en":"They require less computational resources","vi":"Cần ít tài nguyên tính toán hơn.","note":""}],"ans":"B","ansnote":"","exp":[["p","π(a|s,θ) có thể là mạng nơ-ron, biểu diễn hành vi phức tạp, có hành động liên tục, ngẫu nhiên. A, C, D không phải ưu điểm đảm bảo (xem Câu 112 và 149)."]],"rl":[["p","Policy tham số: softmax (rời rạc), Gaussian (liên tục); cập nhật bằng ∇J(θ). Ưu: liên tục, stochastic, thay đổi mượt; nhược: local optimum, phương sai cao."]],"ex":[["p","Mạng nơ-ron 2 lớp nhận ảnh → xs 4 hành động."]],"tip":[["p","Parameterized = “linh hoạt” (tham số chỉnh được), đánh đổi là nhiễu và địa phương."]],"fig":false},{"id":"c1-1","part":"c1","n":1,"en":"What is the incremental rule (sample average) for action values?","vi":"Quy tắc cập nhật tăng dần (trung bình mẫu) cho giá trị hành động là gì?","opts":[{"l":"A","en":"Q(n+1) = Q(n) + (1/n)[R(n) + Q(n)]","vi":"","note":"dấu: cộng thay vì trừ"},{"l":"B","en":"Q(n+1) = Q(n) + (1/n)[R(n) − Q(n)]","vi":"","note":""},{"l":"C","en":"Q(n+1) = Q(n) + (1/n)[Q(n)]","vi":"thiếu reward R(n).","note":""},{"l":"D","en":"Q(n+1) = Q(n) − (1/n)[R(n) − Q(n)]","vi":"","note":"dấu trước phân số"}],"ans":"B","ansnote":"","exp":[["p","Trung bình mẫu Q(n+1) = (1/n)ΣR_i biến đổi thành Q(n+1) = Q(n) + (1/n)[R(n) − Q(n)]. Hiệu R(n) − Q(n) là “sai số”, cộng một phần 1/n của sai số đó vào ước lượng cũ. A cộng sai số thành cộng R + Q (sai). C không có reward nên không học. D trừ nên ước lượng đi xa khỏi reward."]],"rl":[["code","Q_{n+1}=Q_n+\\alpha_n\\,[R_n-Q_n],\\qquad \\alpha_n=\\tfrac1n\\ \\text{(sample average)}"],["p","Cấu trúc chung: ước lượng mới = ước lượng cũ + step size × (target − ước lượng cũ). Đây là mẫu sẽ xuất hiện lại trong TD, Q-learning, SARSA."]],"ex":[["p","Q₁ = 4; lần 2 nhận R = 10, n = 2: Q₂ = 4 + (1/2)(10 − 4) = 7 (bằng trung bình (4+10)/2 = 7)."]],"tip":[["p","“Ước lượng mới = cũ + bước × (thực tế − cũ)”. Dấu TRỪ giữa R và Q, dấu CỘNG trước phân số."]],"fig":false},{"id":"c1-2","part":"c1","n":2,"en":"Equation 2.5 (from Sutton & Barto, 2nd edition) is a key update rule used throughout the Specialization: q(n+1) = q(n) + α(n)[R(n) − q(n)]. The blue line is the target; the red line is our estimate over time. Given the estimate update in red, what was the value of the step size parameter used on each time step? (Figure: the estimate moves about half of the remaining error toward the target each step.)","vi":"Phương trình 2.5 (S&B, bản 2) là quy tắc cập nhật cốt lõi. Đường xanh là mục tiêu (target), đường đỏ là ước lượng theo thời gian. Dựa vào đường đỏ, step size đã dùng mỗi bước là bao nhiêu? (Hình: mỗi bước ước lượng tiến khoảng một nửa phần sai số còn lại.)","opts":[{"l":"A","en":"1,0","vi":"","note":""},{"l":"B","en":"1/2","vi":"","note":""},{"l":"C","en":"1/8","vi":"","note":""},{"l":"D","en":"1/(t − 1)","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Mỗi bước ước lượng đi đúng α lần khoảng cách còn lại tới target. Thấy tiến một nửa mỗi lần → α = 1/2. Nếu α = 1,0 ước lượng nhảy thẳng tới target. α = 1/8 chỉ tiến rất chậm. 1/(t−1) giảm dần theo thời gian."]],"rl":[["p","Sau k bước với α hằng, sai số còn lại = (1 − α)^k × sai số ban đầu. α = 1/2: sai số gảm ½ mỗi bước."]],"ex":[["p","Ước lượng = 0, target = 8, α = 1/2 → 4 → 6 → 7 → 7,5 → ..."]],"tip":[["p","“Đi ½ quãng còn lại” = α = 1/2."]],"fig":false},{"id":"c1-3","part":"c1","n":3,"en":"(Same setup as Question 2.) Given the estimate update in red, what was the step size used? (Figure: the estimate moves about 1/8 of the remaining error each step.)","vi":"(Cùng bối cảnh như Câu 2.) Dựa vào đường đỏ, step size là bao nhiêu? (Hình: mỗi bước ước lượng chỉ tiến khoảng 1/8 sai số.)","opts":[{"l":"A","en":"1,0","vi":"","note":""},{"l":"B","en":"1/8","vi":"","note":""},{"l":"C","en":"1/(t − 1)","vi":"","note":""},{"l":"D","en":"1/2","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Ước lượng hội tụ rất chậm và mịn → step size nhỏ. 1/8 phù hợp với đường cong “dốc nhẹ” trong hình. A là bước nhảy. D (1/2) sẽ nhanh hơn nhiều. C phải giảm theo thời gian, không đều."]],"rl":[["p","Step size nhỏ → ít nhiễu nhưng phản ứng chậm; step size lớn → nhanh nhưng nhiễu. Trong bài toán không dừng (non-stationary), α hằng tốt hơn 1/n."]],"ex":[["p","Target = 8, ước lượng 0, α = 1/8: 1 → 1,875 → 2,64 → ..."]],"tip":[["p","Càng chậm → α càng nhỏ."]],"fig":false},{"id":"c1-4","part":"c1","n":4,"en":"(Same setup as Question 2.) Given the estimate update in red, what was the step size used? (Figure: at each step the estimate jumps exactly to the previous target value.)","vi":"(Cùng bối cảnh Câu 2.) Dựa vào đường đỏ, step size là bao nhiêu? (Hình: mỗi bước ước lượng nhảy thẳng đến đúng giá trị target trước đó.)","opts":[{"l":"A","en":"1/2","vi":"","note":""},{"l":"B","en":"1/8","vi":"","note":""},{"l":"C","en":"1,0","vi":"","note":""},{"l":"D","en":"1/(t − 1)","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Với α = 1: q(n+1) = q(n) + 1·(R(n) − q(n)) = R(n). Ước lượng bằng ngay reward gần nhất, nên đường đỏ “bám” target với độ trễ 1 bước. Các đáp án còn lại cho đường mịn hơn."]],"rl":[["p","α = 1 → “chỉ nhớ cái gần nhất”; α = 0 → không học."]],"ex":[["p","R(n) = 5 → q(n+1) = 5 bất kể q(n)."]],"tip":[["p","α = 1 → “cái gì vừa thấy là cái đó”."]],"fig":false},{"id":"c1-5","part":"c1","n":5,"en":"(Same setup as Question 2.) Given the estimate update in red, what was the step size used? (Figure: at first the estimate jumps the whole way to the target, then updates get smaller and smaller.)","vi":"(Cùng bối cảnh Câu 2.) Dựa vào đường đỏ, step size là bao nhiêu? (Hình: lúc đầu ước lượng cập nhật hết, sau đó càng lúc càng cập nhật ít đi.)","opts":[{"l":"A","en":"1,0","vi":"","note":""},{"l":"B","en":"1/2","vi":"","note":""},{"l":"C","en":"1/8","vi":"","note":""},{"l":"D","en":"1/(t − 1)","vi":"","note":""}],"ans":"D","ansnote":"","exp":[["p","Step size giảm dần theo thời gian: ở bước đầu α = 1 (nhảy hết), rồi ½, ⅓, ¼... → đó chính là trung bình mẫu 1/n (đánh nhãn 1/(t−1) khi t đã tính từ 2). α hằng (A, B, C) không tạo ra xu hướng “càng lúc càng cập nhật ít”."]],"rl":[["p","α = 1/n → ước lượng là trung bình đều của mọi reward, thích hợp bài toán dừng (stationary); α hằng → trung bình mũ (reward gần quan trọng hơn), thích hợp không dừng."]],"ex":[["p","α: 1, 1/2, 1/3, 1/4 → Q = trung bình các reward đã thấy."]],"tip":[["p","Cập nhật giảm dần → 1/n; cập nhật đều → hằng."]],"fig":false},{"id":"c1-6","part":"c1","n":6,"en":"What is the exploration/exploitation tradeoff?","vi":"Đánh đổi giữa khám phá và khai thác là gì?","opts":[{"l":"A","en":"The agent wants to explore the environment to learn as much as possible about the various actions, so that once it knows every arm's true value it can choose the best one for the rest of the time","vi":"Agent muốn khám phá để biết giá trị thật của mọi tay rồi chọn tay tốt nhất suốt đời (bỏ qua sự đánh đổi).","note":""},{"l":"B","en":"The agent wants to explore to get more accurate estimates of its values. The agent also wants to exploit to get more reward. The agent cannot, however, choose to do both simultaneously","vi":"Agent muốn khám phá để ước lượng chính xác hơn, cũng muốn khai thác để nhận nhiều reward hơn, nhưng không thể làm cả hai cùng lúc.","note":""},{"l":"C","en":"The agent wants to maximize the amount of reward it receives over its lifetime. To do so it needs to avoid the action it believes is worst to exploit what it knows. However to discover which arm is truly worst it needs to explore different actions, which potentially will lead it to take the worst action at times","vi":"Agent muốn tối đa hóa reward cả đời; để khai thác phải tránh hành động tệ nhất, nhưng muốn biết tay nào tệ nhất thật sự thì phải khám phá, có lúc sẽ chọn trúng tay tệ nhất.","note":""}],"ans":"B","ansnote":"","exp":[["p","B nêu đúng bản chất: cùng một lượt chọn chỉ làm được một việc (thử hay dùng), nên phải đánh đổi. A bỏ qua chi phí của việc khám phá và giả định biết hết giá trị. C nghe phức tạp nhưng mô tả sai: khám phá không chỉ để tìm tay tệ nhất mà để tìm tay tốt nhất."]],"rl":[["p","Chiến lược: ε-greedy, UCB, softmax, optimistic initial values, Thompson sampling. Xem thêm Câu 99 (đề thi)."]],"ex":[["p","3 máy slot: Q = (2, 5, ?); khai thác = chọn máy 2; khám phá = thử máy 3 (có thể tốt hơn)."]],"tip":[["p","Explore = thử; Exploit = dùng; không thể vừa thử vừa dùng trong cùng một lượt."]],"fig":false},{"id":"c1-7","part":"c1","n":7,"en":"Why did epsilon of 0.1 perform better over 1000 steps than epsilon of 0.01? (Figure: average reward over time for the two agents on the 10-armed testbed.)","vi":"Vì sao ε = 0,1 lại tốt hơn ε = 0,01 trong 1000 bước? (Hình: reward trung bình theo thời gian của hai agent trên bài toán 10 tay.)","opts":[{"l":"A","en":"Epsilon of 0.1 is the optimal value for epsilon in general","vi":"ε = 0,1 là giá trị tối ưu nói chung.","note":""},{"l":"B","en":"The 0.01 agent explored too much causing the arm to choose a bad action too often","vi":"Agent 0,01 khám phá quá nhiều nên chọn hành động xấu quá thường.","note":""},{"l":"C","en":"The 0.01 agent did not explore enough. Thus it ended up selecting a suboptimal arm for longer","vi":"Agent 0,01 khám phá không đủ nên chọn tay không tối ưu lâu hơn.","note":""}],"ans":"C","ansnote":"","exp":[["p","ε = 0,01 chỉ thử ngẫu nhiên 1% thời gian nên rất chậm phát hiện tay tốt nhất; trong 1000 bước nó vẫn “không đủ thông tin”. A sai vì không có ε tối ưu tổng quát. B sai vì 0,01 khám phá ÍT hơn, không phải nhiều hơn."]],"rl":[["p","ε nhỏ: ban đầu chậm nhưng về sau có thể đạt reward cao hơn (ít lãng phí); ε lớn: học nhanh nhưng chạm trần thấp do khám phá quá nhiều. Thời hạn đủ dài, ε nhỏ thắng."]],"ex":[["p","Testbed 10 tay: sau 1000 bước, ε = 0,1 đạt reward trung bình cao hơn; ε = 0,01 vẫn đang leo chậm."]],"tip":[["p","ε quá nhỏ = “quá nhát”; ε quá lớn = “quá bốc đồng”. Trên đời ngắn ε vừa đúng; lâu dài ε nhỏ thắng."]],"fig":false},{"id":"c1-8","part":"c1","n":8,"en":"If exploration is so great why did epsilon of 0.0 (a greedy agent) perform better than epsilon of 0.4? (Figure: average reward vs. steps.)","vi":"Nếu khám phá tốt đến vậy, sao ε = 0,0 (agent greedy) lại tốt hơn ε = 0,4? (Hình: reward trung bình theo số bước.)","opts":[{"l":"A","en":"Epsilon of 0.0 is greedy, thus it will always choose the optimal arm","vi":"ε = 0,0 là greedy nên luôn chọn tay tối ưu.","note":""},{"l":"B","en":"Epsilon of 0.4 explores too often that it takes many sub-optimal actions causing it to do worse over the long term","vi":"ε = 0,4 khám phá quá nhiều nên chọn nhiều hành động kém, tệ hơn về lâu dài.","note":""},{"l":"C","en":"Epsilon of 0.4 doesn't explore often enough to find the optimal action","vi":"ε = 0,4 khám phá không đủ để tìm ra hành động tối ưu.","note":""}],"ans":"B","ansnote":"","exp":[["p","Với ε = 0,4, 40% bước là ngẫu nhiên nên dù ước lượng đã đúng vẫn phải chịu tổn thất lớn vì chọn hành động kém. A sai: greedy KHÔNG đảm bảo chọn tay tối ưu (có thể kẹt ở tay xấu). C ngược thực tế (0,4 khám phá rất nhiều)."]],"rl":[["p","Reward kỳ vọng tối đa của ε-greedy ≈ (1−ε)·Q_max + ε·Q_avg: ε càng lớn trần càng thấp. Greedy thắng ε = 0,4 vì chính sự khám phá dư thừa này, dù greedy có rủi ro."]],"ex":[["p","Q_max = 1,5, Q_avg = 0: ε = 0,4 → trung bình tối đa 0,9; greedy trúng tay tốt → 1,5."]],"tip":[["p","Khám phá quá tay cũng là lãng phí."]],"fig":false},{"id":"c1-9","part":"c1","n":9,"en":"The learner and decision maker is the _______.","vi":"Thực thể học và ra quyết định là _______.","opts":[{"l":"A","en":"Reward","vi":"","note":""},{"l":"B","en":"Agent (tác nhân)","vi":"","note":""},{"l":"C","en":"Environment (môi trường)","vi":"","note":""},{"l":"D","en":"State (trạng thái)","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Agent là bên học và quyết định hành động. Environment là mọi thứ bên ngoài agent, phản hồi bằng state và reward. Reward, state là thông tin, không phải thực thể."]],"rl":[["p","Vòng lặp: S_t → A_t → (R_{t+1}, S_{t+1}). Xem Câu 100."]],"ex":[["p","Chơi cờ: người chơi = agent; bàn cờ + đối thủ = environment."]],"tip":[["p","Agent = “người học”."]],"fig":false},{"id":"c1-10","part":"c1","n":10,"en":"At each time step the agent takes an _______.","vi":"Ở mỗi bước thời gian, agent thực hiện một _______.","opts":[{"l":"A","en":"Environment","vi":"","note":""},{"l":"B","en":"State","vi":"","note":""},{"l":"C","en":"Reward","vi":"","note":""},{"l":"D","en":"Action (hành động)","vi":"","note":""}],"ans":"D","ansnote":"","exp":[["p","Agent chọn action; state và reward do environment trả về. A là thực thể, không phải thứ “take”."]],"rl":[["p","Thứ tự tương tác: agent quan sát S_t → chọn A_t → environment trả R_{t+1}, S_{t+1}."]],"ex":[["p","Robot ở ô (2,3) → chọn “sang phải” → nhận reward −1, sang ô (2,4)."]],"tip":[["p","Agent LUÔN “làm” (Action); environment LUÔN “trả lời” (State, Reward)."]],"fig":false},{"id":"c1-11","part":"c1","n":11,"en":"Imagine the agent is learning in an episodic problem. Which of the following is true?","vi":"Giả sử agent đang học trong một bài toán theo episode. Phát biểu nào đúng?","opts":[{"l":"A","en":"The number of steps in an episode is always the same","vi":"Số bước trong mỗi episode luôn như nhau.","note":""},{"l":"B","en":"The number of steps in an episode is stochastic: each episode can have a different number of steps","vi":"Số bước là ngẫu nhiên, mỗi episode có thể có số bước khác nhau.","note":""},{"l":"C","en":"The agent takes the same action at each step during an episode","vi":"Agent thực hiện cùng một hành động ở mọi bước.","note":""}],"ans":"B","ansnote":"","exp":[["p","Episode kết thúc khi đạt trạng thái kết thúc, thời điểm đó phụ thuộc hành động và động lực môi trường nên độ dài thay đổi. A sai (chỉ đúng với trường hợp đặc biệt). C vô lý."]],"rl":[["p","Episodic: có trạng thái kết thúc, episode độc lập, T là biến ngẫu nhiên. Continuing: không kết thúc."]],"ex":[["p","Ván cờ vua: ván 30 nước, ván 80 nước."]],"tip":[["p","Episode = “một ván”: mỗi ván dài ngắn khác nhau."]],"fig":false},{"id":"c1-12","part":"c1","n":12,"en":"If the reward is always +1, what is the sum of the discounted infinite return when γ < 1? G_t = Σ_{k=0}^{∞} γ^k R_{t+k+1}","vi":"Nếu reward luôn là +1 thì tổng return chiết khấu vô hạn bằng bao nhiêu khi γ < 1?","opts":[{"l":"A","en":"G_t = 1/(1 − γ)","vi":"","note":""},{"l":"B","en":"Vô cực","vi":"","note":""},{"l":"C","en":"G_t = γ/(1 − γ)","vi":"","note":""},{"l":"D","en":"G_t = 1·γ^k","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Đây là chuỗi hình học: Σ γ^k = 1/(1 − γ). B chỉ đúng khi γ = 1. C bỏ mất số hạng đầu (k = 0). D là một số hạng, không phải tổng."]],"rl":[["code","G_t=\\sum_{k=0}^{\\infty}\\gamma^k\\cdot1=\\frac{1}{1-\\gamma}\\quad(\\gamma<1)"],["p","Reward bị chặn R_max → return ≤ R_max/(1 − γ), đây là lý do γ < 1 giúp return hữu hạn."]],"ex":[["p","γ = 0,9 → G = 1/0,1 = 10. γ = 0,5 → G = 2."]],"tip":[["p","Tổng cấp số nhân “1 chia (1 trừ tỉ số)”."]],"fig":false},{"id":"c1-13","part":"c1","n":13,"en":"How does the magnitude of the discount factor (γ) affect learning?","vi":"Độ lớn của hệ số chiết khấu γ ảnh hưởng đến việc học như thế nào?","opts":[{"l":"A","en":"The magnitude of the discount factor has no effect on the agent","vi":"Không ảnh hưởng.","note":""},{"l":"B","en":"With a larger discount factor the agent is more far-sighted and considers rewards farther into the future","vi":"γ lớn: agent nhìn xa hơn, tính đến reward xa trong tương lai.","note":""},{"l":"C","en":"With a smaller discount factor the agent is more far-sighted","vi":"γ nhỏ: agent nhìn xa hơn.","note":""}],"ans":"B","ansnote":"","exp":[["p","γ càng gần 1 thì reward xa càng ít bị giảm trọng số → agent “nhìn xa”. C ngược lại (γ nhỏ = cận thị). A sai vì γ thay đổi policy tối ưu."]],"rl":[["p","γ = 0: tham lam tức thời. γ → 1: cân nhắc dài hạn; nhưng học chậm/khó hơn (return lớn, phương sai cao). Xem Câu 161."]],"ex":[["p","Reward 10 sau 10 bước: γ = 0,9 → 3,5; γ = 0,5 → ~0,01."]],"tip":[["p","γ lớn = nhìn xa; γ nhỏ = ngắn hạn."]],"fig":false},{"id":"c1-14","part":"c1","n":14,"en":"Suppose γ = 0.8 and we observe the following rewards: R₁ = −3, R₂ = 5, R₃ = 2, R₄ = 7, R₅ = 1, with T = 5. What is G₀? Hint: work backwards and recall G_t = R_{t+1} + γG_{t+1}.","vi":"Cho γ = 0,8 và chuỗi reward: R₁ = −3, R₂ = 5, R₃ = 2, R₄ = 7, R₅ = 1, T = 5. Tính G₀? Gợi ý: tính ngược, G_t = R_{t+1} + γG_{t+1}.","opts":[{"l":"A","en":"11,592","vi":"","note":""},{"l":"B","en":"6,2736","vi":"","note":""},{"l":"C","en":"12","vi":"","note":""},{"l":"D","en":"−3","vi":"","note":""},{"l":"E","en":"8,24","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Tính ngược từ cuối: G₅ = 0; G₄ = R₅ + γG₅ = 1; G₃ = R₄ + 0,8·1 = 7,8; G₂ = R₃ + 0,8·7,8 = 2 + 6,24 = 8,24; G₁ = R₂ + 0,8·8,24 = 5 + 6,592 = 11,592; G₀ = R₁ + 0,8·11,592 = −3 + 9,2736 = 6,2736. Chuý ý: 11,592 là G₁ (bẫy A) và 8,24 là G₂ (bẫy E)."]],"rl":[["p","G_t = R_{t+1} + γG_{t+1}, G_T = 0. Luôn tính từ cuối về đầu để đỡ sai số."]],"ex":[["p","(Bài này chính là ví dụ tính toán.)"]],"tip":[["p","“Ngược từ cuối” + “R_{t+1}” (reward sau bước t được đánh chỉ số t+1); G₀ dùng R₁."]],"fig":false},{"id":"c1-15","part":"c1","n":15,"en":"What does MDP stand for?","vi":"MDP viết tắt của gì?","opts":[{"l":"A","en":"Markov Decision Protocol","vi":"Giao thức quyết định Markov.","note":""},{"l":"B","en":"Markov Deterministic Policy","vi":"Policy xác định Markov.","note":""},{"l":"C","en":"Markov Decision Process","vi":"Quá trình quyết định Markov.","note":""},{"l":"D","en":"Meaningful Decision Process","vi":"Quá trình quyết định có ý nghĩa.","note":""}],"ans":"C","ansnote":"","exp":[["p","MDP = Markov Decision Process, gồm (S, A, p, r, γ) với tính Markov: trạng thái kế chỉ phụ thuộc trạng thái-hành động hiện tại. A, B, D là tên sai."]],"rl":[["code","p(s',r\\mid s,a)=\\Pr\\{S_{t+1}=s',R_{t+1}=r\\mid S_t=s,A_t=a\\}"],["p","Mỗi MDP có: tập trạng thái S, hành động A, động lực p, reward r, γ."]],"ex":[["p","Trò chơi grid: S = ô lưới, A = {lên, xuống, trái, phải}."]],"tip":[["p","MDP = Markov + Decision + Process (ra quyết định theo quá trình Markov)."]],"fig":false},{"id":"c1-16","part":"c1","n":16,"en":"Consider using reinforcement learning to control the motion of a robot arm to pick up objects and place them into new positions. The actions in this case might be the voltages applied to each motor at each joint, and the states might be the latest readings of joint angles and velocities. The reward might be +1 for each object successfully picked up and placed. To encourage smooth movements, on each time step a small, negative reward can be given as a function of the moment-to-moment “jerkiness” of the motion. Is this a valid MDP?","vi":"Xét việc dùng học tăng cường để điều khiển chuyển động của một cánh tay robot gắp đồ vật và đặt vào vị trí mới. Hành động có thể là điện áp đặt lên từng động cơ ở mỗi khớp, trạng thái có thể là các số đọc mới nhất của góc khớp và vận tốc. Reward có thể là +1 cho mỗi vật được gắp và đặt thành công. Để khuyến khích chuyển động mượt, ở mỗi bước thời gian có thể cho một reward âm nhỏ là hàm của độ “giật” tức thời của chuyển động. Đây có phải là một MDP hợp lệ không?","opts":[{"l":"A","en":"Yes","vi":"Có.","note":""},{"l":"B","en":"No","vi":"Không.","note":""}],"ans":"A","ansnote":"","exp":[["p","Một MDP chỉ cần có tập trạng thái, tập hành động, động lực chuyển trạng thái và hàm reward; việc hành động là liên tục (điện áp) hay reward có thành phần âm đều không làm mất tính hợp lệ. Trạng thái (góc khớp + vận tốc) đủ để dự đoán bước kế tiếp nên thỏa tính Markov. Đáp án B sai vì nhầm rằng reward âm hoặc hành động liên tục là không hợp lệ."]],"rl":[["p","MDP không đòi hỏi S, A rời rạc; reward có thể âm, có thể là hàm của (s, a, s'). Đây là ví dụ điều khiển liên tục (continuous control). Reward shaping bằng penalty “jerk” là kỹ thuật phổ biến."]],"ex":[["p","Tổng reward một ván: +1 × 5 vật − tổng penalty nhỏ (ví dụ 0,01 mỗi bước × 200 bước = −2) → 3. Agent học vừa gắp nhiều vừa chuyển động mượt."]],"tip":[["p","“MDP = bộ năm (S, A, p, r, γ)”: miễn đủ năm thành phần và tính Markov thì hợp lệ, bất kể liên tục hay reward âm."]],"fig":false},{"id":"c1-17","part":"c1","n":17,"en":"Case 1: Imagine that you are a vision system. When you are first turned on for the day, an image floods into your camera. You can see lots of things, but not all things. You can't see objects that are occluded, and of course you can't see objects that are behind you. After seeing that first scene, do you have access to the Markov state of the environment? Case 2: Imagine that the vision system never worked properly: it always returned the same static image, forever. Would you have access to the Markov state then? (Hint: Reason about P(S_{t+1} | S_t, ..., S_0), where S_t = AllWhitePixels)","vi":"Trường hợp 1: Bạn là một hệ thống thị giác. Khi vừa bật lên trong ngày, một hình ảnh tràn vào camera. Bạn thấy nhiều thứ nhưng không phải tất cả: không thấy vật bị che khuất và dĩ nhiên không thấy vật ở phía sau. Sau khi thấy cảnh đầu tiên, bạn có truy cập được trạng thái Markov của môi trường không? Trường hợp 2: Hệ thống thị giác không bao giờ hoạt động đúng: nó luôn trả về cùng một ảnh tĩnh mãi mãi. Khi đó bạn có truy cập được trạng thái Markov không? (Gợi ý: xét P(S_{t+1} | S_t, ..., S_0), với S_t = ảnh toàn pixel trắng)","opts":[{"l":"A","en":"You have access to the Markov state in both Case 1 and 2","vi":"Có trạng thái Markov ở cả Trường hợp 1 và 2.","note":""},{"l":"B","en":"You have access to the Markov state in Case 1, but you don’t have access to the Markov state in Case 2","vi":"Có ở TH1, không có ở TH2.","note":""},{"l":"C","en":"You don’t have access to the Markov state in Case 1, but you do have access to the Markov state in Case 2","vi":"Không có ở TH1, có ở TH2.","note":""},{"l":"D","en":"You don’t have access to the Markov state in both Case 1 and 2","vi":"Không có ở cả hai.","note":""}],"ans":"A","ansnote":"theo đáp án của đề","exp":[["p","Theo gợi ý, ở TH2 ảnh luôn là ảnh trắng nên P(S_{t+1} | S_t, …, S_0) = P(S_{t+1} | S_t) = 1 cho ảnh trắng kế tiếp: quá khứ không cung cấp thêm thông tin nào, nên tính Markov được thỏa (đây là trường hợp tầm thường). Đề cũng xem TH1 là có trạng thái Markov: “trạng thái” ở đây là cái agent quan sát được, và dự đoán tương lai dựa trên quan sát hiện tại là đủ trong mô hình mà đề đặt ra. Lưu ý: nếu hiểu “trạng thái Markov” là toàn bộ trạng thái thật của môi trường (kể cả vật bị che), thì TH1 là bài toán quan sát một phần (POMDP). Câu này gây tranh luận, hãy nhớ đáp án A theo đề."]],"rl":[["p","Tính Markov: P(S_{t+1} | S_t, A_t, S_{t-1}, …, S_0) = P(S_{t+1} | S_t, A_t). Quan sát một phần → POMDP; cách khắc phục: dùng lịch sử, RNN, belief state."]],"ex":[["p","Chơi Atari chỉ nhìn 1 khung hình không biết vận tốc bóng → không Markov; ghép 4 khung hình liên tiếp thì gần Markov."]],"tip":[["p","Trạng thái Markov = “quá khứ không thêm thông tin về tương lai”. Ảnh tĩnh mãi mãi thì quá khứ chẳng có gì thêm, nên tầm thường là Markov."]],"fig":false},{"id":"c1-18","part":"c1","n":18,"en":"What is the reward hypothesis?","vi":"Giả thuyết reward (reward hypothesis) là gì?","opts":[{"l":"A","en":"Ignore rewards and find other signals","vi":"Bỏ qua reward và tìm tín hiệu khác.","note":""},{"l":"B","en":"That all of what we mean by goals and purposes can be well thought of as the maximization of the expected value of the cumulative sum of a received scalar signal (called reward)","vi":"Mọi điều ta gọi là mục tiêu và mục đích đều có thể xem là việc tối đa hóa giá trị kỳ vọng của tổng tích lũy một tín hiệu vô hướng nhận được (gọi là reward).","note":""},{"l":"C","en":"The same but minimization","vi":"Giống B nhưng là tối thiểu hóa.","note":""},{"l":"D","en":"Always take the action that gives you the best reward at that point","vi":"Luôn chọn hành động cho reward tốt nhất tại thời điểm đó.","note":""}],"ans":"B","ansnote":"","exp":[["p","Đây là định nghĩa của Sutton và Barto: mục tiêu = tối đa hóa kỳ vọng của tổng reward tích lũy (return). A vô nghĩa. C sai chiều (tối thiểu hóa). D là chiến lược tham lam tức thời, bỏ qua tích lũy dài hạn."]],"rl":[["p","Reward là một đại lượng vô hướng. Mục tiêu: max E[G_t], không phải max reward tức thời."],["code","\\max_\\pi \\; \\mathbb{E}_\\pi[G_t],\\quad G_t=\\sum_{k=0}^{\\infty}\\gamma^k R_{t+k+1}"]],"ex":[["p","Robot đi đến đích: reward −1 mỗi bước → tối đa hóa tổng = đi nhanh nhất."]],"tip":[["p","Reward hypothesis = “mục tiêu = tối đa tổng reward kỳ vọng”. Từ khóa: maximization + expected + cumulative + scalar."]],"fig":false},{"id":"c1-19","part":"c1","n":19,"en":"Imagine an agent is in a maze-like gridworld. You would like the agent to find the goal as quickly as possible. You give the agent a reward of +1 when it reaches the goal and the discount rate is 1.0, because this is an episodic task. When you run the agent it finds the goal, but does not seem to care how long it takes to complete each episode. How could you fix this? (Select all that apply)","vi":"Agent trong mê cung dạng gridworld, bạn muốn nó tìm đích nhanh nhất có thể. Bạn cho reward +1 khi đến đích và γ = 1,0 vì đây là bài toán episodic. Khi chạy, agent tìm được đích nhưng dường như không quan tâm mất bao lâu. Làm thế nào để sửa? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Give the agent −1 at each time step","vi":"Cho agent −1 ở mỗi bước thời gian.","note":""},{"l":"B","en":"Give the agent a reward of +1 at every time step","vi":"Cho +1 ở mọi bước.","note":""},{"l":"C","en":"Set a discount rate less than 1 and greater than 0, like 0.9","vi":"Đặt γ trong (0, 1), ví dụ 0,9.","note":""},{"l":"D","en":"Give the agent a reward of 0 at every time step so it wants to leave","vi":"Cho 0 ở mọi bước để nó muốn rời đi.","note":""}],"ans":"AC","ansnote":"","exp":[["p","Với γ = 1 và chỉ +1 ở đích, mọi đường đến đích đều có return = 1, nên agent không phân biệt đường dài hay ngắn. A: phạt −1 mỗi bước → đường ngắn có return cao hơn. C: γ < 1 → reward ở đích đến muộn bị chiết khấu mạnh hơn → return đường ngắn lớn hơn. B sai: +1 mỗi bước thì agent muốn kéo dài episode để thu thêm reward. D sai: reward 0 vẫn không tạo khác biệt về độ dài (và không “muốn rời đi”)."]],"rl":[["p","Hai cách khuyến khích tốc độ: reward âm mỗi bước (time penalty) hoặc chiết khấu γ < 1."]],"ex":[["p","Đường ngắn 5 bước, đường dài 10 bước, γ = 0,9: return = 0,9⁴ = 0,656 so với 0,9⁹ = 0,387 → chọn đường ngắn. Với −1 mỗi bước và +1 ở đích γ = 1: return = −4 + 1 = −3 so với −9 + 1 = −8."]],"tip":[["p","Muốn nhanh = “phạt thời gian” (−1/bước) hoặc “chiết khấu” (γ < 1). Đừng thưởng +1 mỗi bước (khuyến khích câu giờ)."]],"fig":false},{"id":"c1-20","part":"c1","n":20,"en":"When may you want to formulate a problem as continuing?","vi":"Khi nào nên mô hình hóa bài toán là continuing (liên tục, không kết thúc)?","opts":[{"l":"A","en":"When the agent-environment interaction does not naturally break into sequences. Each new episode begins independently of how the previous episode ended","vi":"Khi tương tác agent–môi trường không tự nhiên chia thành các chuỗi (đề viết thêm vế sau về episode, theo đáp án của đề).","note":""},{"l":"B","en":"When the agent-environment interaction naturally breaks into sequences and each sequence begins independently of how the previous sequence ended","vi":"Khi tương tác tự nhiên chia thành các chuỗi và mỗi chuỗi bắt đầu độc lập với chuỗi trước.","note":""}],"ans":"A","ansnote":"","exp":[["p","Continuing task = tương tác không có điểm kết thúc tự nhiên (không có trạng thái cuối), như điều khiển nhiệt độ liên tục, điều phối server. B mô tả bài toán episodic (chia thành các episode độc lập). Lưu ý: phần sau của phương án A trong đề có câu chữ hơi lẫn với episodic, nhưng vế đầu “does not naturally break into sequences” mới là dấu hiệu của continuing."]],"rl":[["p","Continuing: T = ∞, cần γ < 1 hoặc dùng average reward để return hữu hạn. Episodic: có trạng thái cuối, return = tổng hữu hạn."]],"ex":[["p","Robot giữ cân bằng cả ngày (continuing) và ván cờ (episodic)."]],"tip":[["p","Continuing = “chạy mãi, không có hồi kết”; episodic = “có tập (episode), có hồi kết”."]],"fig":false},{"id":"c1-21","part":"c1","n":21,"en":"A policy is a function which maps ____ to ____.","vi":"Policy là một hàm ánh xạ ____ sang ____.","opts":[{"l":"A","en":"States to values","vi":"Trạng thái sang giá trị.","note":""},{"l":"B","en":"Actions to probability distributions over values","vi":"Hành động sang phân phối xác suất trên các giá trị.","note":""},{"l":"C","en":"States to probability distributions over actions","vi":"Trạng thái sang phân phối xác suất trên các hành động.","note":""},{"l":"D","en":"Actions to probabilities","vi":"Hành động sang xác suất.","note":""},{"l":"E","en":"States to actions","vi":"Trạng thái sang hành động.","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy tổng quát (stochastic) là π(a|s): với mỗi trạng thái s cho phân phối xác suất trên các hành động. A là hàm giá trị V, không phải policy. B, D đảo chiều (input phải là trạng thái). E chỉ là trường hợp riêng (policy xác định) nên không đủ tổng quát."]],"rl":[["code","\\pi(a\\mid s)=\\Pr\\{A_t=a\\mid S_t=s\\},\\qquad \\sum_a \\pi(a\\mid s)=1"],["p","Policy xác định: π(s) = a. Policy ngẫu nhiên: π(a|s)."]],"ex":[["p","ε-greedy đối với 4 hành động, ε = 0,2: hành động greedy có xác suất 0,8 + 0,05 = 0,85; mỗi hành động khác 0,05."]],"tip":[["p","“State vào, Action ra (dưới dạng xác suất)”. Value (V, Q) cho ra số thực, policy cho ra hành động."]],"fig":false},{"id":"c1-22","part":"c1","n":22,"en":"The term “backup” most closely resembles the term ___ in meaning.","vi":"Thuật ngữ “backup” gần nghĩa nhất với thuật ngữ ___.","opts":[{"l":"A","en":"Value","vi":"Giá trị","note":""},{"l":"B","en":"Update","vi":"Cập nhật","note":""},{"l":"C","en":"Diagram","vi":"Sơ đồ","note":""}],"ans":"B","ansnote":"","exp":[["p","Trong sách Sutton–Barto, “backup” là thao tác cập nhật giá trị của một trạng thái (hoặc cặp trạng thái–hành động) dựa trên giá trị của các trạng thái kế tiếp, nên tương đương “update”. “Backup diagram” là sơ đồ minh họa các phép cập nhật này, nhưng bản thân “backup” không phải là diagram hay value."]],"rl":[["p","Backup = chuyển thông tin giá trị ngược từ trạng thái tương lai về trạng thái hiện tại. Ví dụ backup của Bellman và của TD:"],["code","V(s)\\leftarrow \\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)[r+\\gamma V(s')]"]],"ex":[["p","V(A) = 0, V(B) = 10, γ = 0,9, từ A sang B với reward 1: backup → V(A) ← 1 + 0,9·10 = 10."]],"tip":[["p","“Backup = update (cập nhật ngược)”, còn “backup diagram” là hình vẽ của nó."]],"fig":false},{"id":"c1-23","part":"c1","n":23,"en":"At least one deterministic optimal policy exists in every Markov decision process.","vi":"Trong mọi MDP đều tồn tại ít nhất một policy tối ưu xác định.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Trong MDP hữu hạn luôn có ít nhất một policy tối ưu, và có thể chọn nó là xác định: tại mỗi trạng thái chọn hành động làm cực đại Q*(s,a) (greedy theo Q*). Việc ngẫu nhiên hóa không bao giờ làm tốt hơn."]],"rl":[["code","\\pi_*(s)=\\arg\\max_a q_*(s,a)"],["p","Có thể có nhiều policy tối ưu (nếu hòa), nhưng v* và q* là duy nhất."]],"ex":[["p","Q*(s, trái) = 3, Q*(s, phải) = 5 → π*(s) = phải."]],"tip":[["p","“Tối ưu thì luôn có bản xác định (argmax Q*)”."]],"fig":false},{"id":"c1-24","part":"c1","n":24,"en":"The optimal state-value function:","vi":"Hàm giá trị trạng thái tối ưu:","opts":[{"l":"A","en":"Is not guaranteed to be unique, even in finite Markov decision processes","vi":"Không được đảm bảo duy nhất, kể cả trong MDP hữu hạn.","note":""},{"l":"B","en":"Is unique in every finite Markov decision process","vi":"Là duy nhất trong mọi MDP hữu hạn.","note":""}],"ans":"B","ansnote":"","exp":[["p","v*(s) = max_π v_π(s) là một hàm duy nhất (nghiệm duy nhất của phương trình tối ưu Bellman với γ < 1). Chỉ policy tối ưu mới có thể không duy nhất (nhiều policy cùng cho v*). A nhầm lẫn giữa “hai policy tối ưu” và “hai v* khác nhau”."]],"rl":[["code","v_*(s)=\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_*(s')]"]],"ex":[["p","Hai hành động cùng cho Q* = 5 → có 2 policy tối ưu nhưng v*(s) = 5 duy nhất."]],"tip":[["p","“Policy tối ưu có thể nhiều, giá trị tối ưu chỉ một”."]],"fig":false},{"id":"c1-25","part":"c1","n":25,"en":"Does adding a constant to all rewards change the set of optimal policies in episodic tasks?","vi":"Việc cộng một hằng số vào mọi reward có làm thay đổi tập policy tối ưu trong các bài toán episodic không?","opts":[{"l":"A","en":"Yes, adding a constant to all rewards changes the set of optimal policies","vi":"Có, việc cộng hằng số làm thay đổi tập policy tối ưu.","note":""},{"l":"B","en":"No, as long as the relative differences between rewards remain the same, the set of optimal policies is the same","vi":"Không, miễn các chênh lệch tương đối giữa reward giữ nguyên thì tập policy tối ưu không đổi.","note":""}],"ans":"A","ansnote":"","exp":[["p","Trong episodic, cộng c vào mọi reward làm return thêm c·T (T là độ dài episode, phụ thuộc policy), nên policy cho episode dài hơn/ngắn hơn được lợi/hại khác nhau → policy tối ưu có thể đổi. B chỉ đúng với continuing với γ < 1 khi mọi policy bị cộng cùng một hằng số c/(1 − γ) vào giá trị."]],"rl":[["code","G_t' = G_t + c\\sum_{k=0}^{T-t-1}\\gamma^k\\quad(\\text{episodic: phụ thuộc } T)"],["p","Continuing γ < 1: mọi v_π cùng dịch một lượng c/(1 − γ) → tập policy tối ưu không đổi."]],"ex":[["p","Mê cung: đường ngắn 3 bước, đường dài 10 bước, reward −1/bước → ngắn tốt hơn (−3 so với −10). Cộng +2 mỗi bước: đường ngắn +3, đường dài +10 → đường dài tốt hơn, policy tối ưu đảo chiều."]],"tip":[["p","Episodic: “con số cộng vào nhân với độ dài” → đổi policy. Continuing γ < 1: mọi thứ dịch cùng một lượng → không đổi."]],"fig":false},{"id":"c1-26","part":"c1","n":26,"en":"Does adding a constant to all rewards change the set of optimal policies in continuing tasks?","vi":"Việc cộng một hằng số vào mọi reward có làm thay đổi tập policy tối ưu trong các bài toán continuing không?","opts":[{"l":"A","en":"No, as long as the relative differences between rewards remain the same, the set of optimal policies is the same","vi":"Không, miễn chênh lệch tương đối giữa reward giữ nguyên thì tập policy tối ưu không đổi.","note":""},{"l":"B","en":"Yes, adding a constant to all rewards changes the set of optimal policies","vi":"Có, làm thay đổi.","note":""}],"ans":"A","ansnote":"","exp":[["p","Ở continuing với γ < 1, cộng hằng số c vào mọi reward làm mọi giá trị cộng cùng một lượng c/(1 − γ), không phụ thuộc policy. Thứ tự xếp hạng các policy không đổi. Khác với episodic (Câu 25), nơi tổng số bước T phụ thuộc policy."]],"rl":[["code","v'_\\pi(s)=v_\\pi(s)+\\frac{c}{1-\\gamma}"]],"ex":[["p","γ = 0,9, c = 2: mọi v_π tăng 2/0,1 = 20 → thứ tự giữa các policy giữ nguyên."]],"tip":[["p","Ghi cặp “Continuing: không đổi / Episodic: đổi” (Câu 26 và Câu 25)."]],"fig":false},{"id":"c1-27","part":"c1","n":27,"en":"Select the equation that correctly relates v∗ to q∗. Assume π is the uniform random policy.","vi":"Chọn phương trình liên hệ đúng giữa v∗ và q∗. Giả sử π là policy ngẫu nhiên đều.","opts":[{"l":"A","en":"v∗(s) = Σ_{a,r,s'} π(a|s) p(s',r|s,a) [r + q∗(s')]","vi":"","note":"q∗ cần cả trạng thái lẫn hành động, không thể viết q∗(s'); thiếu γ"},{"l":"B","en":"v∗(s) = Σ_{a,r,s'} π(a|s) p(s',r|s,a) q∗(s')","vi":"","note":"cũng viết q∗(s') sai dạng"},{"l":"C","en":"v∗(s) = max_a q∗(s, a)","vi":"","note":""},{"l":"D","en":"v∗(s) = Σ_{a,r,s'} π(a|s) p(s',r|s,a) [r + γ q∗(s')]","vi":"","note":"cũng viết q∗(s') sai dạng, và dùng π ngẫu nhiên thay vì max"}],"ans":"C","ansnote":"","exp":[["p","Giá trị trạng thái tối ưu bằng giá trị của hành động tốt nhất tại trạng thái đó. Câu “policy ngẫu nhiên đều” là yếu tố gây nhiễu: vì đây là giá trị tối ưu (v∗) nên phải lấy max, không phải trung bình theo π ngẫu nhiên."]],"rl":[["code","v_*(s)=\\max_a q_*(s,a),\\qquad v_\\pi(s)=\\sum_a\\pi(a|s)q_\\pi(s,a)"]],"ex":[["p","q*(s,trái) = 3, q*(s,phải) = 5 → v*(s) = 5."]],"tip":[["p","“Tối ưu → max; policy bất kỳ → Σ π”."]],"fig":false},{"id":"c1-28","part":"c1","n":28,"en":"Select the equation that correctly relates q∗ to v∗ using the four-argument function p.","vi":"Chọn phương trình liên hệ đúng giữa q∗ và v∗, dùng hàm p bốn đối số.","opts":[{"l":"A","en":"q∗(s,a) = Σ_{s',r} p(s',r|a,s) [r + v∗(s')]","vi":"thiếu γ.","note":""},{"l":"B","en":"q∗(s,a) = Σ_{s',r} p(s',r|a,s) γ [r + v∗(s')]","vi":"γ nhân sai chỗ (cả reward).","note":""},{"l":"C","en":"q∗(s,a) = Σ_{s',r} p(s',r|a,s) [r + γ v∗(s')]","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Giá trị thực hiện a tại s rồi đi theo tối ưu = kỳ vọng của (reward tức thời + γ × giá trị tối ưu của trạng thái kế). Reward không bị chiết khấu, chỉ vế sau bị nhân γ."]],"rl":[["code","q_*(s,a)=\\sum_{s',r}p(s',r\\mid s,a)\\,[\\,r+\\gamma v_*(s')\\,]"]],"ex":[["p","p = 1 (xác định), r = 2, v*(s') = 10, γ = 0,9 → q* = 2 + 9 = 11."]],"tip":[["p","“γ đứng trước v”: trong ngoặc [r + γ v∗(s')], chỉ vế sau (giá trị tương lai) mới nhân γ."]],"fig":false},{"id":"c1-29","part":"c1","n":29,"en":"Write a policy π∗ in terms of q∗.","vi":"Viết policy π∗ theo q∗.","opts":[{"l":"A","en":"π∗(a|s) = q∗(s,a)","vi":"","note":"q∗ không phải xác suất"},{"l":"B","en":"π∗(a|s) = max_{a'} q∗(s,a')","vi":"","note":"max cho ra số (giá trị), không phải xác suất"},{"l":"C","en":"π∗(a|s) = 1 nếu a = argmax_{a'} q∗(s,a'), còn lại 0","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Policy tối ưu chọn hành động có q∗ lớn nhất (argmax), xác suất 1; các hành động khác 0. Cần phân biệt max (trả giá trị) và argmax (trả hành động)."]],"rl":[["code","\\pi_*(a|s)=\\begin{cases}1 & a=\\arg\\max_{a'}q_*(s,a')\\\\ 0 & \\text{otherwise}\\end{cases}"],["p","Nếu hòa, có thể chia xác suất tùy ý giữa các hành động hòa."]],"ex":[["p","q* = (3, 5, 1) cho 3 hành động → π* = (0, 1, 0). max = 5, argmax = hành động thứ 2."]],"tip":[["p","max → “giá trị”, argmax → “chỉ số/hành động”."]],"fig":false},{"id":"c1-30","part":"c1","n":30,"en":"Give an equation for some π∗ in terms of v∗ and the four-argument p.","vi":"Cho một phương trình biểu diễn một π∗ theo v∗ và hàm p bốn đối số.","opts":[{"l":"A","en":"π∗(a|s) = 1 nếu v∗(s) = max_{a'} Σ_{s',r} p(s',r|s,a') [r + γ v∗(s')], còn lại 0","vi":"","note":"— đáp án của đề"},{"l":"B","en":"π∗(a|s) = 1 nếu v∗(s) = Σ_{s',r} p(s',r|s,a) [r + γ v∗(s')], còn lại 0","vi":"chọn hành động a sao cho kỳ vọng một bước của nó bằng v∗(s).","note":""},{"l":"C","en":"π∗(a|s) = Σ p [r + γ v∗]","vi":"","note":"trả về một con số (giá trị), không phải xác suất"},{"l":"D","en":"π∗(a|s) = max_{a'} Σ p [r + γ v∗]","vi":"","note":"cũng trả về giá trị"}],"ans":"A","ansnote":"","exp":[["p","Các phương án C và D sai chắc chắn vì π∗(a|s) là xác suất, không thể bằng một giá trị kỳ vọng. Giữa A và B: về mặt toán học, B mô tả đúng hơn (hành động a được chọn nếu kỳ vọng một bước của nó chạm v∗(s)), còn A so sánh v∗(s) với max_{a'} nên vế phải không phụ thuộc a. Tuy nhiên đáp án trên trang là A, vì vậy khi thi hãy nhớ đáp án A theo đề nhưng hiểu ý tưởng: policy tối ưu = greedy theo giá trị kỳ vọng một bước từ v∗."]],"rl":[["p","Khi có mô hình p, dùng greedy theo v∗ với một bước nhìn trước (one-step lookahead). Khi không có mô hình, cần q∗ (xem Câu 29)."],["code","\\pi_*(s)=\\arg\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_*(s')]"]],"ex":[["p","v*(s') cho hai trạng thái kế là 10 và 4, reward 0, γ = 0,9, hành động 1 đến s' → 9 so với 3,6 → chọn hành động 1."]],"tip":[["p","Có v* + có mô hình p → nhìn trước 1 bước rồi argmax; có q* → argmax trực tiếp."]],"fig":false},{"id":"c1-31","part":"c1","n":31,"en":"A function which maps ___ to ___ is a value function. [Select all that apply]","vi":"Một hàm ánh xạ ___ sang ___ là hàm giá trị. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"State-action pairs to expected returns","vi":"Cặp trạng thái–hành động sang return kỳ vọng.","note":""},{"l":"B","en":"States to expected returns","vi":"Trạng thái sang return kỳ vọng.","note":""},{"l":"C","en":"Values to actions","vi":"Giá trị sang hành động.","note":""},{"l":"D","en":"Values to states","vi":"Giá trị sang trạng thái.","note":""}],"ans":"AB","ansnote":"","exp":[["p","Có hai loại hàm giá trị: v(s) ánh xạ trạng thái → return kỳ vọng, q(s,a) ánh xạ cặp (trạng thái, hành động) → return kỳ vọng. C, D đảo ngược: input không thể là “giá trị”."]],"rl":[["code","v_\\pi(s)=\\mathbb{E}_\\pi[G_t\\mid S_t=s],\\qquad q_\\pi(s,a)=\\mathbb{E}_\\pi[G_t\\mid S_t=s,A_t=a]"]],"ex":[["p","Trong gridworld, v(ô gần đích) = −1; q(ô đó, đi lên) = −2."]],"tip":[["p","V = “vị trí” (state), Q = “quyết định” (state + action). Policy là một ánh xạ khác (state → xác suất hành động), không trả về giá trị."]],"fig":false},{"id":"c1-32","part":"c1","n":32,"en":"Consider the continuing Markov decision process shown below. The only decision to be made is in the top state, where two actions are available, left and right. The numbers show the rewards that are received deterministically after each action. There are exactly two deterministic policies, π_left and π_right. Indicate the optimal policies if γ = 0? If γ = 0.9? If γ = 0.5? [Select all that apply] (có hình minh họa)","vi":"Xét MDP continuing như hình. Quyết định duy nhất nằm ở trạng thái trên cùng, có hai hành động trái/phải. Các số là reward nhận được xác định sau mỗi hành động. Có đúng hai policy xác định. Hãy chỉ ra policy tối ưu khi γ = 0, γ = 0,9, γ = 0,5. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"γ = 0,5: π_left","vi":"","note":""},{"l":"B","en":"γ = 0,9: π_left","vi":"","note":""},{"l":"C","en":"γ = 0: π_left","vi":"","note":""},{"l":"D","en":"γ = 0: π_right","vi":"","note":""},{"l":"E","en":"γ = 0,5: π_right","vi":"","note":""},{"l":"F","en":"γ = 0,9: π_right","vi":"","note":""}],"ans":"ACEF","ansnote":"","exp":[["p","Hình không hiển thị trên trang văn bản; theo bài gốc (Sutton–Barto, Bài tập 3.22): nhánh trái cho +1 rồi về lại trạng thái trên với reward 0; nhánh phải cho 0 rồi +2. Return: π_left = 1 + γ²0 + γ²·1 + … = 1/(1 − γ²); π_right = 0 + γ·2 + γ²·0 + γ³·2 + … = 2γ/(1 − γ²). So sánh 1 so với 2γ: γ < 0,5 → left tốt hơn; γ = 0,5 → bằng nhau (cả hai tối ưu); γ > 0,5 → right tốt hơn. Do đó γ = 0: left (C); γ = 0,5: cả hai (A, E); γ = 0,9: right (F). B, D sai."]],"rl":[["code","v_{\\text{left}}=\\frac{1}{1-\\gamma^2},\\qquad v_{\\text{right}}=\\frac{2\\gamma}{1-\\gamma^2}"],["p","γ nhỏ = cận thị (chọn phần thưởng sớm), γ lớn = nhìn xa (chọn phần thưởng lớn dù đến muộn)."]],"ex":[["p","γ = 0,9: left = 1/0,19 = 5,26; right = 1,8/0,19 = 9,47 → right tốt hơn. γ = 0,5: left = 1/0,75 = 1,33; right = 1/0,75 = 1,33 → bằng nhau."]],"tip":[["p","“Muốn so sánh → viết return dạng chuỗi hình học”; γ vượt ngưỡng 0,5 thì đổi policy."]],"fig":false},{"id":"c1-33","part":"c1","n":33,"en":"Every finite Markov decision process has __. [Select all that apply]","vi":"Mọi MDP hữu hạn đều có __. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A unique optimal value function","vi":"Một hàm giá trị tối ưu duy nhất.","note":""},{"l":"B","en":"A stochastic optimal policy","vi":"Một policy tối ưu ngẫu nhiên.","note":""},{"l":"C","en":"A deterministic optimal policy","vi":"Một policy tối ưu xác định.","note":""},{"l":"D","en":"A unique optimal policy","vi":"Một policy tối ưu duy nhất.","note":""}],"ans":"AC","ansnote":"","exp":[["p","MDP hữu hạn luôn có v* duy nhất và ít nhất một policy tối ưu xác định. B không được chọn: điều được đảm bảo luôn có là policy xác định; policy ngẫu nhiên chỉ là tùy chọn (khi có hòa) chứ không phải điều bắt buộc. D sai vì policy tối ưu có thể không duy nhất khi có hòa."]],"rl":[["p","Tóm tắt: v*, q* duy nhất; π* tồn tại, có thể xác định, có thể nhiều. Liên hệ Câu 23, 24, 36."]],"ex":[["p","Hai hành động đều cho Q* = 5: có 2 policy xác định tối ưu và vô số policy ngẫu nhiên tối ưu (trộn), nhưng v* = 5 vẫn duy nhất."]],"tip":[["p","“Giá trị tối ưu: duy nhất. Policy tối ưu: tồn tại xác định, không duy nhất”."]],"fig":false},{"id":"c1-34","part":"c1","n":34,"en":"The ___ of the reward for each state-action pair, the dynamics function p, and the policy π is _____ to characterize the value function v_π. (Remember that v_π(s) = Σ_a π(a|s) Σ_{s',r} p(s', r | s, a)[r + γ v_π(s')].)","vi":"___ của reward cho mỗi cặp trạng thái–hành động, hàm động lực p và policy π là _____ để xác định hàm giá trị v_π. (Nhớ: công thức Bellman cho v_π ở trên.)","opts":[{"l":"A","en":"Mean; sufficient","vi":"Giá trị trung bình; đủ.","note":""},{"l":"B","en":"Distribution; necessary","vi":"Phân phối; cần thiết.","note":""}],"ans":"A","ansnote":"","exp":[["p","Phương trình Bellman chỉ dùng giá trị kỳ vọng (trung bình) của reward, nên chỉ cần biết trung bình reward cho mỗi cặp (s,a), cùng p và π là đủ (sufficient). Không cần toàn bộ phân phối (B sai). “Necessary” cũng sai vì có thể có nhiều phân phối cho cùng giá trị trung bình."]],"rl":[["code","r(s,a)=\\mathbb{E}[R_{t+1}\\mid S_t=s,A_t=a]\\quad\\Rightarrow\\quad v_\\pi(s)=\\sum_a\\pi(a|s)\\Big[r(s,a)+\\gamma\\sum_{s'}p(s'|s,a)v_\\pi(s')\\Big]"]],"ex":[["p","Hai phân phối reward: {0, 10} (50/50) và {5} đều có trung bình 5 → cùng cho v_π."]],"tip":[["p","Bellman cho v chỉ cần “trung bình” (kỳ vọng), không cần “phân phối”. (Khác với distributional RL)."]],"fig":false},{"id":"c1-35","part":"c1","n":35,"en":"The Bellman equation for a given a policy π: [Select all that apply]","vi":"Phương trình Bellman cho một policy π cho trước: (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Holds only when the policy is greedy with respect to the value function","vi":"Chỉ đúng khi policy greedy theo hàm giá trị.","note":""},{"l":"B","en":"Expresses state values v(s) in terms of state values of successor states","vi":"Biểu diễn v(s) qua giá trị các trạng thái kế tiếp.","note":""},{"l":"C","en":"Expresses the improved policy in terms of the existing policy","vi":"Biểu diễn policy cải thiện theo policy hiện có.","note":""}],"ans":"B","ansnote":"","exp":[["p","Bellman expectation liên hệ giá trị một trạng thái với giá trị các trạng thái kế tiếp, đúng với mọi policy π, không chỉ greedy (A sai). C là mô tả policy improvement, không phải Bellman."]],"rl":[["code","v_\\pi(s)=\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_\\pi(s')]"],["p","Đây là hệ phương trình tuyến tính (|S| ẩn), có thể giải trực tiếp hoặc lặp (policy evaluation)."]],"ex":[["p","Hai trạng thái, π đơn giản: v(A) = 1 + 0,9 v(B), v(B) = 2 + 0,9 v(A) → giải: v(A) = (1 + 1,8)/(1 − 0,81) = 14,74; v(B) = 15,26."]],"tip":[["p","Bellman expectation = “theo policy π” (Σ π); Bellman optimality = “theo max” (max)."]],"fig":false},{"id":"c1-36","part":"c1","n":36,"en":"An optimal policy:","vi":"Một policy tối ưu:","opts":[{"l":"A","en":"Is not guaranteed to be unique, even in finite Markov decision processes","vi":"Không được đảm bảo duy nhất, kể cả trong MDP hữu hạn.","note":""},{"l":"B","en":"Is unique in every finite Markov decision process","vi":"Duy nhất trong mọi MDP hữu hạn.","note":""},{"l":"C","en":"Is unique in every Markov decision process","vi":"Duy nhất trong mọi MDP.","note":""}],"ans":"A","ansnote":"","exp":[["p","Khi hai hành động cùng cho Q* bằng nhau tại một trạng thái, cả hai đều tối ưu → có nhiều policy tối ưu. B, C khẳng định duy nhất nên sai. (Chỉ giá trị tối ưu v* mới duy nhất — xem Câu 24.)"]],"rl":[["p","Tập policy tối ưu Π* = {π : v_π(s) = v*(s) ∀s}, thường có nhiều phần tử khi có hòa."]],"ex":[["p","Hai ô lới đường đi ngắn ngang nhau đến đích → “rẽ trái” và “rẽ phải” đều tối ưu."]],"tip":[["p","“Policy tối ưu: không duy nhất; value tối ưu: duy nhất”."]],"fig":false},{"id":"c1-37","part":"c1","n":37,"en":"The Bellman optimality equation for v∗: [Select all that apply]","vi":"Phương trình tối ưu Bellman cho v∗: (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Expresses the improved policy in terms of the existing policy","vi":"Biểu diễn policy cải thiện theo policy hiện có.","note":""},{"l":"B","en":"Holds for the optimal state value function","vi":"","note":"với hàm giá trị trạng thái tối ưu. (đúng"},{"l":"C","en":"Holds when the policy is greedy with respect to the value function","vi":"","note":"khi policy greedy theo hàm giá trị. (không chọn"},{"l":"D","en":"Expresses state values v∗(s) in terms of state values of successor states","vi":"Biểu diễn v∗(s) qua v∗ của trạng thái kế tiếp.","note":""},{"l":"E","en":"Holds for v_π, the value function of an arbitrary policy π","vi":"","note":"với v_π của policy bất kỳ. (sai"}],"ans":"BD","ansnote":"","exp":[["p","Phương trình tối ưu Bellman chỉ đúng cho v* (không cho policy bất kỳ: E sai) và viết v*(s) qua v* của các trạng thái kế tiếp (D). A mô tả policy improvement. C không được chọn vì mối quan hệ “greedy” không phải điều kiện để phương trình đúng."]],"rl":[["code","v_*(s)=\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_*(s')]"]],"ex":[["p","So sánh Bellman expectation (Σ π, đúng cho mọi π) và Bellman optimality (max, chỉ cho v*). Khi giải bằng Value Iteration, đặt v ← vế phải của phương trình này."]],"tip":[["p","“Max → chỉ đúng cho tối ưu; Σ π → đúng cho policy bất kỳ”."]],"fig":false},{"id":"c1-38","part":"c1","n":38,"en":"Give an equation for v_π in terms of q_π and π.","vi":"Cho một phương trình biểu diễn v_π theo q_π và π.","opts":[{"l":"A","en":"v_π(s) = max_a γ π(a|s) q_π(s,a)","vi":"","note":"max và γ không đúng"},{"l":"B","en":"v_π(s) = max_a π(a|s) q_π(s,a)","vi":"","note":"max không phải trung bình theo π"},{"l":"C","en":"v_π(s) = Σ_a π(a|s) q_π(s,a)","vi":"","note":""},{"l":"D","en":"v_π(s) = Σ_a γ π(a|s) q_π(s,a)","vi":"","note":"không có γ ở đây"}],"ans":"C","ansnote":"","exp":[["p","v_π(s) là kỳ vọng của q_π(s,a) theo phân phối hành động π(·|s): trung bình có trọng số, không phải max (max chỉ dành cho v*) và không có γ (γ chỉ xuất hiện khi đi từ q sang v của trạng thái kế)."]],"rl":[["code","v_\\pi(s)=\\sum_a\\pi(a|s)\\,q_\\pi(s,a)"]],"ex":[["p","π = (0,5; 0,5), q = (4, 8) → v = 0,5·4 + 0,5·8 = 6."]],"tip":[["p","v từ q: lấy trung bình theo π (“Σ π q”). q từ v: nhìn một bước và có γ (Q39)."]],"fig":false},{"id":"c1-39","part":"c1","n":39,"en":"Give an equation for q_π in terms of v_π and the four-argument p.","vi":"Cho một phương trình biểu diễn q_π theo v_π và hàm p bốn đối số.","opts":[{"l":"A","en":"q_π(s,a) = Σ_{s'} Σ_r p(s',r|s,a)[r + γ v_π(s')]","vi":"","note":""},{"l":"B","en":"q_π(s,a) = max_{s',r} p(s',r|s,a)[r + v_π(s')]","vi":"","note":"dùng max và thiếu γ"},{"l":"C","en":"q_π(s,a) = max_{s',r} p(s',r|s,a)[r + γ v_π(s')]","vi":"","note":"dùng max thay vì tổng kỳ vọng"},{"l":"D","en":"q_π(s,a) = max_{s',r} p(s',r|s,a) γ [r + v_π(s')]","vi":"","note":"max và γ sai chỗ"},{"l":"E","en":"q_π(s,a) = Σ_{s'} Σ_r p(s',r|s,a) γ [r + v_π(s')]","vi":"","note":"γ nhân cả reward"},{"l":"F","en":"q_π(s,a) = Σ_{s'} Σ_r p(s',r|s,a) [r + v_π(s')]","vi":"","note":"thiếu γ"}],"ans":"A","ansnote":"","exp":[["p","Giá trị của (s, a) là kỳ vọng theo động lực p của [reward tức thời + γ × giá trị trạng thái kế theo π]. Do không có sự lựa chọn (do đã cố định a), nên là tổng, không dùng max; γ chỉ nhân với v."]],"rl":[["code","q_\\pi(s,a)=\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_\\pi(s')]"]],"ex":[["p","p(s1, r=1) = 0,6; p(s2, r=0) = 0,4; v(s1) = 10, v(s2) = 5; γ = 0,9 → q = 0,6·(1 + 9) + 0,4·(0 + 4,5) = 6 + 1,8 = 7,8."]],"tip":[["p","“Σ p [r + γ v]”: tổng, có γ trước v, không max."]],"fig":false},{"id":"c1-40","part":"c1","n":40,"en":"Let r(s,a) be the expected reward for taking action a in state s, as defined in equation 3.5 of the textbook. Which of the following are valid ways to re-express the Bellman equations, using this expected reward function? [Select all that apply]","vi":"Gọi r(s,a) là reward kỳ vọng khi thực hiện hành động a ở trạng thái s (công thức 3.5 trong sách). Cách viết lại nào dưới đây cho phương trình Bellman là hợp lệ? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"q∗(s,a) = r(s,a) + γ Σ_{s'} p(s'|s,a) max_{a'} q∗(s',a')","vi":"","note":"(Bellman optimality cho q∗"},{"l":"B","en":"v_π(s) = Σ_a π(a|s) [r(s,a) + γ Σ_{s'} p(s'|s,a) v_π(s')]","vi":"","note":"(Bellman expectation cho v_π"},{"l":"C","en":"q_π(s,a) = r(s,a) + γ Σ_{s'} Σ_{a'} p(s'|s,a) π(a'|s') q_π(s',a')","vi":"","note":"(Bellman expectation cho q_π"},{"l":"D","en":"v∗(s) = max_a [r(s,a) + γ Σ_{s'} p(s'|s,a) v∗(s')]","vi":"","note":"(Bellman optimality cho v∗"}],"ans":"ABCD","ansnote":"","exp":[["p","Cả bốn đều là cách viết hợp lệ khi dùng r(s,a) = E[R_{t+1} | s, a]: vì kỳ vọng được tách thành “reward trung bình tức thời” cộng “γ × giá trị kỳ vọng của trạng thái kế”, và p(s'|s,a) = Σ_r p(s',r|s,a)."]],"rl":[["p","Bốn phương trình Bellman cơ bản:"],["code","\\begin{aligned}\nv_\\pi(s)&=\\sum_a\\pi(a|s)\\Big[r(s,a)+\\gamma\\sum_{s'}p(s'|s,a)v_\\pi(s')\\Big]\\\\\nq_\\pi(s,a)&=r(s,a)+\\gamma\\sum_{s'}p(s'|s,a)\\sum_{a'}\\pi(a'|s')q_\\pi(s',a')\\\\\nv_*(s)&=\\max_a\\Big[r(s,a)+\\gamma\\sum_{s'}p(s'|s,a)v_*(s')\\Big]\\\\\nq_*(s,a)&=r(s,a)+\\gamma\\sum_{s'}p(s'|s,a)\\max_{a'}q_*(s',a')\n\\end{aligned}"]],"ex":[["p","s, a → s' xác định, r(s,a) = 2, v*(s') = 10, γ = 0,9 → q*(s,a) = 2 + 9 = 11."]],"tip":[["p","Bốn công thức = 2 (v, q) × 2 (π bất kỳ / tối ưu). “π bất kỳ dùng Σ, tối ưu dùng max”."]],"fig":false},{"id":"c1-41","part":"c1","n":41,"en":"Consider an episodic MDP with one state and two actions (left and right). The left action has stochastic reward 1 with probability p and 3 with probability 1 − p. The right action has stochastic reward 0 with probability q and 10 with probability 1 − q. What relationship between p and q makes the actions equally optimal?","vi":"Xét MDP episodic có một trạng thái và hai hành động (trái, phải). Hành động trái cho reward ngẫu nhiên 1 với xác suất p và 3 với xác suất 1 − p. Hành động phải cho reward 0 với xác suất q và 10 với xác suất 1 − q. Quan hệ nào giữa p và q làm hai hành động tối ưu như nhau?","opts":[{"l":"A","en":"7 + 3p = −10q","vi":"","note":""},{"l":"B","en":"13 + 3p = −10q","vi":"","note":""},{"l":"C","en":"13 + 2p = 10q","vi":"","note":""},{"l":"D","en":"7 + 2p = −10q","vi":"","note":""},{"l":"E","en":"13 + 3p = 10q","vi":"","note":""},{"l":"F","en":"7 + 3p = 10q","vi":"","note":""},{"l":"G","en":"13 + 2p = −10q","vi":"","note":""},{"l":"H","en":"7 + 2p = 10q","vi":"","note":""}],"ans":"H","ansnote":"","exp":[["p","Hai hành động tối ưu như nhau khi reward kỳ vọng bằng nhau (MDP một trạng thái, episodic nên return = reward). E[left] = 1·p + 3(1 − p) = 3 − 2p. E[right] = 0·q + 10(1 − q) = 10 − 10q. Đặt bằng nhau: 3 − 2p = 10 − 10q ⇒ 10q = 7 + 2p. Các đáp án khác sai dấu hoặc hệ số."]],"rl":[["p","q(s,a) = E[R | s, a] = Σ xác suất × reward. Hai hành động đồng tối ưu ⇔ q bằng nhau."]],"ex":[["p","p = 0,5 → E[left] = 2 ⇒ 10q = 8 ⇒ q = 0,8; E[right] = 10 × 0,2 = 2. ✓."]],"tip":[["p","“Kỳ vọng trái = kỳ vọng phải”, nhớ viết mỗi kỳ vọng theo dạng 1 − xác suất của nhánh còn lại."]],"fig":false},{"id":"c1-42","part":"c1","n":42,"en":"The value of any state under an optimal policy is ___ the value of that state under a non-optimal policy. [Select all that apply]","vi":"Giá trị của bất kỳ trạng thái nào dưới policy tối ưu thì ___ giá trị của trạng thái đó dưới policy không tối ưu. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Strictly greater than","vi":"Lớn hơn hẳn.","note":""},{"l":"B","en":"Greater than or equal to","vi":"Lớn hơn hoặc bằng.","note":""},{"l":"C","en":"Strictly less than","vi":"Nhỏ hơn hẳn.","note":""},{"l":"D","en":"Less than or equal to","vi":"Nhỏ hơn hoặc bằng.","note":""}],"ans":"B","ansnote":"","exp":[["p","Định nghĩa: π* ≥ π ⇔ v_{π*}(s) ≥ v_π(s) với mọi s. Chỉ “larger or equal”, vì policy không tối ưu có thể đạt bằng tại một số trạng thái. A sai vì có thể bằng nhau. C, D ngược chiều."]],"rl":[["code","\\pi\\ge\\pi' \\iff v_\\pi(s)\\ge v_{\\pi'}(s)\\ \\forall s"]],"ex":[["p","Tại trạng thái kế sát đích, mọi policy đều chọn đi thẳng → v bằng nhau; ở ô xa thì policy tối ưu tốt hơn hẳn."]],"tip":[["p","“Tối ưu ≥ mọi policy khác” (có dấu bằng)."]],"fig":false},{"id":"c1-43","part":"c1","n":43,"en":"If a policy π is greedy with respect to its own value function v_π, then it is an optimal policy.","vi":"Nếu policy π greedy theo chính hàm giá trị v_π của nó thì π là policy tối ưu.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Nếu π greedy theo v_π thì v_π thỏa phương trình tối ưu Bellman (v(s) = max_a Σ p [r + γ v(s')]), mà v* là nghiệm duy nhất của phương trình này ⇒ v_π = v* ⇒ π tối ưu. Đây là điểm dừng của policy iteration (policy ổn định)."]],"rl":[["p","Policy iteration dừng khi policy improvement không đổi policy."],["code","\\pi(s)\\in\\arg\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_\\pi(s')]\\ \\Rightarrow\\ v_\\pi=v_*"]],"ex":[["p","Sau khi đánh giá π, cải thiện greedy cho cùng π → π đã tối ưu."]],"tip":[["p","“Greedy với chính giá trị của mình = không thể cải thiện thêm = tối ưu”."]],"fig":false},{"id":"c1-44","part":"c1","n":44,"en":"Let v_π be the state-value function for the policy π. Let π' be greedy with respect to v_π. Then v_{π'} ≥ v_π.","vi":"Gọi v_π là hàm giá trị trạng thái của policy π. Gọi π' là policy greedy theo v_π. Khi đó v_{π'} ≥ v_π.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Đây là định lý cải thiện policy (policy improvement theorem): chọn greedy theo v_π không bao giờ làm giảm giá trị ở bất kỳ trạng thái. Dấu bằng xảy ra khi π đã tối ưu."]],"rl":[["p","Nếu q_π(s, π'(s)) ≥ v_π(s) với mọi s thì v_{π'}(s) ≥ v_π(s). Policy iteration = lặp (evaluation → improvement)."],["code","q_\\pi(s,\\pi'(s))\\ge v_\\pi(s)\\ \\forall s\\ \\Rightarrow\\ v_{\\pi'}\\ge v_\\pi"]],"ex":[["p","π ngẫu nhiên trong gridworld → greedy theo v_π cho policy tốt hơn hẳn (đi về đích)."]],"tip":[["p","“Greedy theo giá trị của policy cũ = không tệ hơn”."]],"fig":false},{"id":"c1-45","part":"c1","n":45,"en":"What is the relationship between value iteration and policy iteration? [Select all that apply]","vi":"Quan hệ giữa value iteration và policy iteration là gì? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Value iteration and policy iteration are both special cases of generalized policy iteration","vi":"Cả hai đều là trường hợp đặc biệt của GPI.","note":""},{"l":"B","en":"Policy iteration is a special case of value iteration","vi":"Policy iteration là trường hợp đặc biệt của value iteration.","note":""},{"l":"C","en":"Value iteration is a special case of policy iteration","vi":"Value iteration là trường hợp đặc biệt của policy iteration.","note":""}],"ans":"A","ansnote":"","exp":[["p","GPI là khung chung: evaluation và improvement tương tác. Policy iteration dùng evaluation đầy đủ rồi improvement; value iteration dùng một sweep evaluation (gộp với improvement). Nên cả hai là trường hợp của GPI. B, C sai vì giữa hai thuật toán không có quan hệ “cái này là con của cái kia” theo cách đề đặt ra."]],"rl":[["code","v_{k+1}(s)=\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_k(s')]\\quad(\\text{value iteration})"]],"ex":[["p","Policy iteration: 1 evaluation (nhiều sweep) → 1 improvement. Value iteration: 1 sweep kết hợp “max”. GPI: xen kẽ tùy ý."]],"tip":[["p","GPI = “cháu” của cả hai; PI = “eval kỹ rồi improve”, VI = “eval 1 bước + improve liền”."]],"fig":false},{"id":"c1-46","part":"c1","n":46,"en":"The word synchronous means \"at the same time\". The word asynchronous means \"not at the same time\". A dynamic programming algorithm is: [Select all that apply]","vi":"Từ synchronous (đồng bộ) nghĩa là “cung một lúc”; asynchronous (bất đồng bộ) nghĩa là “không cùng lúc”. Một thuật toán quy hoạch động là: (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Asynchronous, if it does not update all states at each iteration","vi":"Bất đồng bộ nếu không cập nhật tất cả trạng thái mỗi vòng lặp.","note":""},{"l":"B","en":"Synchronous, if it systematically sweeps the entire state space at each iteration","vi":"Đồng bộ nếu quét hệ thống toàn bộ không gian trạng thái mỗi vòng.","note":""},{"l":"C","en":"Asynchronous, if it updates some states more than others","vi":"Bất đồng bộ nếu cập nhật một số trạng thái nhiều hơn các trạng thái khác.","note":""}],"ans":"ABC","ansnote":"","exp":[["p","Ba mệnh đề đều là định nghĩa đúng: DP đồng bộ quét toàn bộ trạng thái mỗi lần (B); DP bất đồng bộ cập nhật trạng thái theo thứ tự bất kỳ, không nhất thiết quét hết (A), có thể cập nhật một số trạng thái nhiều hơn (C)."]],"rl":[["p","DP đồng bộ: v_{k+1} tính từ toàn bộ v_k. Async DP (in-place, prioritized sweeping, real-time DP): vẫn hội tụ nếu mọi trạng thái được cập nhật vô hạn lần."]],"ex":[["p","1000 trạng thái: sync = cập nhật cả 1000 mỗi vòng; async = chỉ cập nhật các trạng thái “quan trọng” (gần đích) nhiều lần hơn."]],"tip":[["p","Sync = quét hết; Async = chọn lọc / thứ tự bất kỳ."]],"fig":false},{"id":"c1-47","part":"c1","n":47,"en":"All Generalized Policy Iteration algorithms are synchronous.","vi":"Tất cả thuật toán Generalized Policy Iteration đều là đồng bộ.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","GPI chỉ yêu cầu hai quá trình evaluation và improvement tương tác, không áp đặt cách quét. Có thể cập nhật bất đồng bộ, từng trạng thái một, hay chỉ một phần."]],"rl":[["p","GPI = họ thuật toán (PI, VI, async DP, MC control, SARSA, …) trong đó policy và value cùng được cải thiện, hội tụ khi cả hai nhất quán với nhau."]],"ex":[["p","Q-learning cập nhật mỗi lần một cặp (s,a) dọc theo quỹ đạo, đây cũng là GPI nhưng không đồng bộ."]],"tip":[["p","“GPI = linh hoạt: sync hay async đều được”."]],"fig":false},{"id":"c1-48","part":"c1","n":48,"en":"Which of the following is true?","vi":"Phát biểu nào sau đây đúng?","opts":[{"l":"A","en":"Asynchronous methods generally scale to large state spaces better than synchronous methods","vi":"Phương pháp bất đồng bộ thường mở rộng tốt hơn cho không gian trạng thái lớn.","note":""},{"l":"B","en":"Synchronous methods generally scale to large state spaces better than asynchronous methods","vi":"Ngược lại.","note":""}],"ans":"A","ansnote":"","exp":[["p","Khi |S| rất lớn, việc quét toàn bộ mỗi vòng rất tốn kém; async cho phép cập nhật các trạng thái liên quan (ví dụ dọc theo quỹ đạo agent) nên tiết kiệm tính toán."]],"rl":[["p","Curse of dimensionality: số trạng thái tăng theo lũy thừa số biến. Async DP + prioritized sweeping/real-time DP giúp tránh quét hết."]],"ex":[["p","Cờ vua 10^43 trạng thái: không thể quét hết, chỉ cập nhật những trạng thái gặp trong trò chơi."]],"tip":[["p","“State space lớn → đừng quét hết → async”."]],"fig":false},{"id":"c1-49","part":"c1","n":49,"en":"Why are dynamic programming algorithms considered planning methods? [Select all that apply]","vi":"Vì sao các thuật toán quy hoạch động được coi là phương pháp lập kế hoạch (planning)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"They learn from trial and error interaction","vi":"Học từ tương tác thử","note":". (sai"},{"l":"B","en":"They use a model to improve the policy","vi":"Dùng mô hình để cải thiện policy.","note":""},{"l":"C","en":"They compute optimal value functions","vi":"Tính hàm giá trị tối ưu. (không chọn)","note":""}],"ans":"B","ansnote":"","exp":[["p","Planning = dùng mô hình môi trường (p, r) để tính ra policy/giá trị mà không cần tương tác thật. A là đặc điểm của học từ trải nghiệm (MC, TD). C: tính hàm giá trị tối ưu là mục tiêu, không phải lý do “planning” (Q-learning cũng tính hàm tối ưu nhưng không phải planning)."]],"rl":[["p","Planning: có mô hình; Learning: không có mô hình, học từ mẫu kinh nghiệm. Dyna kết hợp cả hai."]],"ex":[["p","Value iteration cần biết p(s',r|s,a); Q-learning chỉ cần mẫu (s,a,r,s')."]],"tip":[["p","“DP = có mô hình = planning”."]],"fig":false},{"id":"c1-50","part":"c1","n":50,"en":"Consider the undiscounted, episodic MDP below. There are four actions possible in each state, A = {up, down, right, left}, which deterministically cause the corresponding state transitions, except that actions that would take the agent off the grid in fact leave the state unchanged. The right half of the figure shows the value of each state under the equiprobable random policy. If π is the equiprobable random policy, what is q(7, down)? (có hình)","vi":"Xét MDP episodic không chiết khấu (γ = 1) như hình. Có bốn hành động mỗi trạng thái A = {lên, xuống, phải, trái}, dẫn đến chuyển trạng thái tương ứng một cách xác định, trừ khi hành động đưa agent ra khỏi lưới thì giữ nguyên trạng thái. Nửa phải của hình cho giá trị mỗi trạng thái dưới policy ngẫu nhiên đều. Nếu π là policy ngẫu nhiên đều thì q(7, down) bằng bao nhiêu?","opts":[{"l":"A","en":"−14","vi":"","note":""},{"l":"B","en":"−20","vi":"","note":""},{"l":"C","en":"−21","vi":"","note":""},{"l":"D","en":"−15","vi":"","note":""}],"ans":"D","ansnote":"","exp":[["p","Hình không hiển thị trên trang văn bản; đây là gridworld 4×4 trong sách Sutton–Barto (Ví dụ 4.1, reward −1 mỗi bước). Hành động “xuống” từ trạng thái 7 đưa đến trạng thái 11 với reward −1. Giá trị v(11) = −14 (theo hình), nên q(7, down) = −1 + v(11) = −15 (γ = 1, chuyển xác định). A (−14) quên reward −1; B, C là giá trị các ô khác."]],"rl":[["code","q_\\pi(s,a)=r+\\gamma v_\\pi(s'),\\quad \\text{(chuyển xác định)}"],["p","Quy ước: q của một hành động = reward bước đó + giá trị ô đến."]],"ex":[["p","q(7, down) = −1 + (−14) = −15."]],"tip":[["p","“q = reward bước đó + v của ô kế”. Đừng quên cộng −1."]],"fig":false},{"id":"c1-51","part":"c1","n":51,"en":"Consider the undiscounted, episodic MDP below (the same 4×4 gridworld; a new state 15 has been added). Four actions are possible in each state, A = {up, down, right, left}, which deterministically cause the corresponding state transitions, except that actions that would take the agent off the grid leave the state unchanged. The right half of the figure shows the value of each state under the equiprobable random policy. If π is the equiprobable random policy, what is v(15)? Hint: Recall the Bellman equation v(s) = Σ_a π(a|s) Σ_{s',r} p(s',r|s,a)[r + γ v(s')]. (có hình)","vi":"Xét MDP episodic không chiết khấu như hình (thêm trạng thái 15). Có bốn hành động mỗi trạng thái, chuyển trạng thái xác định, ra khỏi lưới thì giữ nguyên. Hình cho giá trị các trạng thái dưới policy ngẫu nhiên đều. Tính v(15). Gợi ý: dùng phương trình Bellman.","opts":[{"l":"A","en":"−23","vi":"","note":""},{"l":"B","en":"−21","vi":"","note":""},{"l":"C","en":"−24","vi":"","note":""},{"l":"D","en":"−25","vi":"","note":""},{"l":"E","en":"−22","vi":"","note":""}],"ans":"C","ansnote":"theo đáp án của đề","exp":[["p","Hình không hiển thị trên trang văn bản nên mình không thể tự tính lại số định lượng từ hình; đáp án của đề là C (−24). Cách giải: mỗi bước reward −1, γ = 1, nên v(15) = −1 + (1/4)[v(lên) + v(xuống) + v(trái) + v(phải)], trong đó các ô kế là các ô lân cận của 15 trong hình (nếu một hướng ra ngoài lưới thì quay về chính 15, tức là thêm v(15) vào vế phải). Thay giá trị các ô lân cận từ hình rồi giải phương trình một ẩn v(15). Những đáp án A, B, D, E sai vì không thỏa phương trình này với các giá trị trong hình."]],"rl":[["p","Bellman expectation cho π ngẫu nhiên đều, chuyển xác định:"],["code","v(s)=\\frac14\\sum_{a}\\big[-1+v(s'_a)\\big]=-1+\\frac14\\sum_a v(s'_a)"],["p","Nếu một hướng đi ra ngoài lưới, s'_a = s (ở nguyên chỗ), nên vế phải chứa v(s) → chuyển vế và giải."]],"ex":[["p","(Ví dụ minh họa phương pháp, không phải số của đề) Một ô có 3 ô kế có giá trị −10, −12, −14 và 1 hướng ra ngoài lưới: v = −1 + (1/4)(−36 + v) ⇒ 0,75 v = −10 ⇒ v ≈ −13,33."]],"tip":[["p","“Hướng ra ngoài lưới = quay về chính mình → gom v vào một vế”. Mỗi bước −1."]],"fig":false},{"id":"c2-52","part":"c2","n":52,"en":"Which approach ensures continual (never-ending) exploration? (Select all that apply)","vi":"Cách tiếp cận nào đảm bảo khám phá liên tục (không bao giờ dừng)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Exploring starts","vi":"Bắt đầu khám phá (mỗi episode bắt đầu từ một cặp (s,a) ngẫu nhiên).","note":""},{"l":"B","en":"On-policy learning with a deterministic policy","vi":"Học on-policy với policy xác định.","note":""},{"l":"C","en":"On-policy learning with an ε-soft policy","vi":"Học on-policy với policy ε-soft.","note":""},{"l":"D","en":"Off-policy learning with an ε-soft behavior policy and a deterministic target policy","vi":"Off-policy: behavior ε-soft, target xác định.","note":""},{"l":"E","en":"Off-policy learning with an ε-soft target policy and a deterministic behavior policy","vi":"Off-policy: target ε-soft, behavior xác định.","note":""}],"ans":"ACD","ansnote":"","exp":[["p","Khám phá liên tục cần mọi cặp (s,a) được thăm vô hạn lần. A: exploring starts bảo đảm điều này bằng điểm bắt đầu ngẫu nhiên. C: ε-soft luôn cho mọi hành động xác suất ≥ ε/|A| > 0. D: policy sinh dữ liệu (behavior) là ε-soft nên vẫn khám phá đủ. B sai vì policy xác định chỉ đi một đường, không khám phá. E sai vì behavior xác định thì không khám phá; target ε-soft không giúp gì cho việc sinh dữ liệu."]],"rl":[["p","ε-soft: π(a|s) ≥ ε/|A(s)| với mọi a. Điều kiện quan trọng là policy sinh dữ liệu (behavior) phải khám phá."]],"ex":[["p","ε = 0,1, 4 hành động: mỗi hành động có xác suất tối thiểu 0,025."]],"tip":[["p","Khám phá đến từ người sinh dữ liệu (behavior policy) chứ không phải target: “người lái phải liều, người học không cần”."]],"fig":false},{"id":"c2-53","part":"c2","n":53,"en":"When can Monte Carlo methods, as defined in the course, be applied? (Select all that apply)","vi":"Khi nào có thể áp dụng phương pháp Monte Carlo (theo định nghĩa trong khóa học)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"When the problem is continuing and given a batch of data containing sequences of states, actions, and rewards","vi":"Bài toán continuing và có dữ liệu lô các chuỗi (s, a, r).","note":""},{"l":"B","en":"When the problem is continuing and there is a model that produces samples of the next state and reward","vi":"Continuing và có mô hình sinh mẫu.","note":""},{"l":"C","en":"When the problem is episodic and given a batch of data containing sample episodes","vi":"Episodic và có dữ liệu lô các episode mẫu.","note":""},{"l":"D","en":"When the problem is episodic and there is a model that produces samples of the next state and reward","vi":"Episodic và có mô hình sinh mẫu.","note":""}],"ans":"CD","ansnote":"","exp":[["p","MC cần return hoàn chỉnh G_t, chỉ có khi episode kết thúc. Vậy MC chỉ dùng cho bài toán episodic. Nguồn mẫu có thể là dữ liệu có sẵn (C) hoặc mô phỏng từ model (D). A, B sai vì continuing không có điểm kết thúc để tính return."]],"rl":[["p","MC: model-free, học từ episode hoàn chỉnh, không bootstrapping, cập nhật sau khi episode kết thúc. Chỉ cần mô hình dạng “sinh mẫu” (sample model), không cần phân phối đầy đủ (distribution model)."]],"ex":[["p","Chơi Blackjack: mỗi ván là một episode; dùng MC ước lượng giá trị các tay bài."]],"tip":[["p","“MC = chờ hết episode mới học” → bắt buộc episodic."]],"fig":false},{"id":"c2-54","part":"c2","n":54,"en":"Which of the following learning settings are examples of off-policy learning? (Select all that apply)","vi":"Bối cảnh học nào dưới đây là ví dụ của học off-policy? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Learning the optimal policy while continuing to explore","vi":"Học policy tối ưu trong khi vẫn tiếp tục khám phá.","note":""},{"l":"B","en":"Learning from data generated by a human expert","vi":"Học từ dữ liệu do chuyên gia con người tạo ra.","note":""}],"ans":"AB","ansnote":"","exp":[["p","Off-policy = policy đang học (target) khác policy sinh dữ liệu (behavior). A: học π* (target tối ưu/xác định) trong khi hành động theo policy khám phá (behavior). B: dữ liệu từ chuyên gia là behavior, agent học một policy khác."]],"rl":[["p","On-policy: π = b. Off-policy: π ≠ b, cần importance sampling (MC) hoặc dùng max (Q-learning)."]],"ex":[["p","Q-learning: behavior ε-greedy, target greedy. Học từ log lái xe của tài xế → off-policy."]],"tip":[["p","“Off = khác người”: người hành động ≠ người được học."]],"fig":false},{"id":"c2-55","part":"c2","n":55,"en":"Which of the following is a requirement on the behaviour policy b for using off-policy Monte Carlo policy evaluation? This is called the assumption of coverage.","vi":"Điều nào là yêu cầu đối với behavior policy b khi dùng đánh giá MC off-policy? Đây gọi là giả định bao phủ (coverage).","opts":[{"l":"A","en":"For each state s and action a, if π(a|s) > 0 then b(a|s) > 0","vi":"Với mọi s, a: nếu π chọn a thì b cũng phải có thể chọn a.","note":""},{"l":"B","en":"For each state s and action a, if b(a|s) > 0 then π(a|s) > 0","vi":"Ngược lại.","note":""},{"l":"C","en":"All actions have non-zero probabilities under π","vi":"Mọi hành động đều có xác suất khác 0 dưới π.","note":""}],"ans":"A","ansnote":"","exp":[["p","Để ước lượng giá trị π từ dữ liệu của b, b phải “bao phủ” mọi hành động mà π có thể chọn. Nếu π(a|s) > 0 mà b(a|s) = 0 thì không bao giờ quan sát được a → không ước lượng được. B ngược chiều. C không cần: π có thể xác định."]],"rl":[["p","Importance sampling ratio:"],["code","\\rho_{t:T-1}=\\prod_{k=t}^{T-1}\\frac{\\pi(A_k|S_k)}{b(A_k|S_k)}"],["p","Coverage đảm bảo mẫu số không chia cho 0."]],"ex":[["p","π xác định chọn “phải”, b ε-soft chọn “phải” với xác suất ≥ ε/|A| > 0 → thỏa coverage."]],"tip":[["p","“b phải bao π”: π làm gì thì b phải từng làm được."]],"fig":false},{"id":"c2-56","part":"c2","n":56,"en":"When is it possible to determine a policy that is greedy with respect to the value functions v_π, q_π for the policy π? (Select all that apply)","vi":"Khi nào có thể xác định được một policy greedy theo các hàm giá trị v_π, q_π của policy π? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"When state values v_π and a model are available","vi":"Khi có giá trị trạng thái v_π và mô hình.","note":""},{"l":"B","en":"When state values v_π are available but no model is available","vi":"Có v_π nhưng không có mô hình.","note":""},{"l":"C","en":"When action values q_π and a model are available","vi":"Có q_π và mô hình.","note":""},{"l":"D","en":"When action values q_π are available but no model is available","vi":"Có q_π nhưng không có mô hình.","note":""}],"ans":"ACD","ansnote":"","exp":[["p","Với q_π: chỉ cần argmax_a q_π(s,a), không cần model (C, D đúng). Với v_π: phải nhìn trước một bước để biết hành động nào dẫn tới trạng thái tốt, nên cần mô hình p (A đúng). B sai vì có v_π mà không có model thì không biết hành động đưa đến trạng thái nào."]],"rl":[["code","\\pi'(s)=\\arg\\max_a q_\\pi(s,a)=\\arg\\max_a\\sum_{s',r}p(s',r|s,a)[r+\\gamma v_\\pi(s')]"],["p","Đây là lý do MC control ước lượng q thay vì v khi không có mô hình."]],"ex":[["p","Không biết bản đồ: nếu biết “đi phải” = −3 và “đi trái” = −5 thì chọn phải; nếu chỉ biết giá trị ô thì phải biết “đi phải” dẫn đến ô nào."]],"tip":[["p","“Q = sẵn hành động, argmax là xong; V = cần bản đồ (model)”."]],"fig":false},{"id":"c2-57","part":"c2","n":57,"en":"Monte Carlo methods in Reinforcement Learning work by... Hint: recall we used the term sweep in dynamic programming to discuss updating all the states systematically. This is not the same as visiting a state.","vi":"Phương pháp Monte Carlo trong RL hoạt động bằng cách... Gợi ý: trong DP, “sweep” là cập nhật tất cả trạng thái một cách có hệ thống; điều này khác với việc ghé thăm một trạng thái.","opts":[{"l":"A","en":"Averaging sample returns","vi":"Lấy trung bình các return mẫu.","note":""},{"l":"B","en":"Averaging sample rewards","vi":"Lấy trung bình các reward mẫu.","note":""},{"l":"C","en":"Planning with a model of the environment","vi":"Lập kế hoạch với mô hình môi trường.","note":""},{"l":"D","en":"Performing sweeps through the state set","vi":"Thực hiện các lượt quét qua tập trạng thái.","note":""}],"ans":"A","ansnote":"","exp":[["p","MC ước lượng giá trị bằng trung bình các return (tổng reward chiết khấu từ lúc thăm đến hết episode). B sai vì reward không phải return. C là của DP/planning. D là của DP: MC chỉ cập nhật các trạng thái thực sự được ghé thăm trong episode."]],"rl":[["code","V(s)\\approx\\frac{1}{N(s)}\\sum_{i=1}^{N(s)}G_i(s)"]],"ex":[["p","Xem Câu 58 (return 8, 4, 3 → trung bình 5)."]],"tip":[["p","“MC = Mean of Class returns”: trung bình return, không reward, không quét."]],"fig":false},{"id":"c2-58","part":"c2","n":58,"en":"Suppose the state s has been visited three times, with corresponding returns 8, 4, and 3. What is the current Monte Carlo estimate for the value of s?","vi":"Giả sử trạng thái s đã được ghé thăm 3 lần với các return tương ứng là 8, 4 và 3. Ước lượng Monte Carlo hiện tại cho giá trị của s là bao nhiêu?","opts":[{"l":"A","en":"3","vi":"","note":""},{"l":"B","en":"15","vi":"","note":""},{"l":"C","en":"5","vi":"","note":""},{"l":"D","en":"3,5","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","V(s) = (8 + 4 + 3)/3 = 15/3 = 5. B là tổng (quên chia). A là giá trị nhỏ nhất. D không tương ứng phép tính nào (3,5 là trung bình của 4 và 3)."]],"rl":[["p","Có thể cập nhật tăng dần: V ← V + (1/n)(G − V). Sau lần 1: 8; lần 2: 8 + (4 − 8)/2 = 6; lần 3: 6 + (3 − 6)/3 = 5."]],"ex":[["p","(Chính bài toán trên.)"]],"tip":[["p","MC = trung bình → tổng chia số lần thăm."]],"fig":false},{"id":"c2-59","part":"c2","n":59,"en":"When does Monte Carlo prediction perform its first update?","vi":"Khi nào Monte Carlo prediction thực hiện cập nhật đầu tiên?","opts":[{"l":"A","en":"After the first time step","vi":"Sau bước thời gian đầu tiên.","note":""},{"l":"B","en":"After every state is visited at least once","vi":"Sau khi mọi trạng thái được ghé ít nhất một lần.","note":""},{"l":"C","en":"At the end of the first episode","vi":"Khi kết thúc episode đầu tiên.","note":""}],"ans":"C","ansnote":"","exp":[["p","Cần biết return G_t đầy đủ, mà return chỉ được biết khi episode kết thúc. A là đặc điểm của TD (cập nhật mỗi bước). B không cần: MC cập nhật các trạng thái đã thăm ngay sau episode."]],"rl":[["p","MC là phương pháp “offline” (cập nhật cuối episode); TD là “online” (cập nhật mỗi bước). Xem Câu 72."]],"ex":[["p","Episode 5 bước: MC chờ đến bước 5 rồi mới duyệt ngược tính G cho 5 trạng thái; TD(0) cập nhật ở mỗi bước."]],"tip":[["p","MC = “chờ hết ván mới chấm điểm”."]],"fig":false},{"id":"c2-60","part":"c2","n":60,"en":"For Monte Carlo Prediction of state-values, the number of updates at the end of an episode depends on. Hint: look at the innermost loop of the algorithm.","vi":"Với Monte Carlo Prediction cho giá trị trạng thái, số lần cập nhật khi kết thúc episode phụ thuộc vào. Gợi ý: nhìn vòng lặp trong cùng của thuật toán.","opts":[{"l":"A","en":"The length of the episode","vi":"Độ dài của episode.","note":""},{"l":"B","en":"The number of states","vi":"Số trạng thái.","note":""},{"l":"C","en":"The number of possible actions in each state","vi":"Số hành động có thể trong mỗi trạng thái.","note":""}],"ans":"A","ansnote":"","exp":[["p","Vòng lặp trong cùng duyệt ngược t = T−1, …, 0 qua từng bước của episode, nên số cập nhật tỉ lệ với độ dài episode. B phải là đặc điểm của DP (quét mọi trạng thái). C không liên quan vì cập nhật V không lặp qua hành động."]],"rl":[["code","\\text{for } t=T-1,\\dots,0:\\quad G\\leftarrow\\gamma G+R_{t+1};\\ \\ V(S_t)\\leftarrow \\text{average}(G)"]],"ex":[["p","Episode 5 bước → 5 cập nhật; episode 50 bước → 50 cập nhật (bất kể có 1000 trạng thái)."]],"tip":[["p","MC: chi phí ≈ độ dài episode; DP: chi phí ≈ số trạng thái."]],"fig":false},{"id":"c2-61","part":"c2","n":61,"en":"In an ε-greedy policy over 𝒜 actions, what is the probability of the highest valued action if there are no other actions with the same value?","vi":"Trong policy ε-greedy với |𝒜| hành động, xác suất chọn hành động có giá trị cao nhất là bao nhiêu nếu không có hành động nào khác cùng giá trị?","opts":[{"l":"A","en":"1 − ε","vi":"","note":""},{"l":"B","en":"ε","vi":"","note":""},{"l":"C","en":"1 − ε + ε/|𝒜|","vi":"","note":""},{"l":"D","en":"ε/|𝒜|","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Với xác suất 1 − ε chọn greedy; với xác suất ε chọn ngẫu nhiên trong |𝒜| hành động (kể cả hành động greedy). Vậy P(greedy) = (1 − ε) + ε/|𝒜|. A thiếu phần ngẫu nhiên rơi vào greedy. D là xác suất của một hành động không greedy."]],"rl":[["code","\\pi(a|s)=\\begin{cases}1-\\epsilon+\\frac{\\epsilon}{|\\mathcal A|}& a=a^*\\\\ \\frac{\\epsilon}{|\\mathcal A|}& a\\ne a^*\\end{cases}"]],"ex":[["p","ε = 0,1, |𝒜| = 4: P(greedy) = 0,9 + 0,025 = 0,925; mỗi hành động khác 0,025. Tổng = 0,925 + 3·0,025 = 1."]],"tip":[["p","“Greedy được thêm phần chia đều”: 1 − ε + ε/|𝒜|."]],"fig":false},{"id":"c2-62","part":"c2","n":62,"en":"TD(0) is a solution method for:","vi":"TD(0) là phương pháp giải cho:","opts":[{"l":"A","en":"Control","vi":"Điều khiển","note":""},{"l":"B","en":"Prediction","vi":"Dự đoán (đánh giá policy)","note":""}],"ans":"B","ansnote":"","exp":[["p","TD(0) ước lượng v_π cho một policy cho trước (prediction). Control cần thêm bước cải thiện policy; các biến thể TD dùng cho control là Sarsa, Q-learning, Expected Sarsa."]],"rl":[["p","Prediction = đánh giá v_π / q_π của policy cố định. Control = tìm policy tối ưu π*."],["code","V(S_t)\\leftarrow V(S_t)+\\alpha\\,[R_{t+1}+\\gamma V(S_{t+1})-V(S_t)]"]],"ex":[["p","Đánh giá xem policy “lái cẩn thận” tốt đến mức nào (prediction) so với tìm ra cách lái tốt nhất (control)."]],"tip":[["p","“TD(0) = V = dự đoán; Sarsa/Q = Q = điều khiển”."]],"fig":false},{"id":"c2-63","part":"c2","n":63,"en":"Which of the following methods use bootstrapping? (Select all that apply)","vi":"Phương pháp nào dưới đây sử dụng bootstrapping (tự dẫn dắt)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Dynamic Programming","vi":"Quy hoạch động","note":""},{"l":"B","en":"Monte Carlo","vi":"","note":""},{"l":"C","en":"TD(0)","vi":"","note":""}],"ans":"AC","ansnote":"","exp":[["p","Bootstrapping = cập nhật ước lượng dựa trên ước lượng khác (V(S_{t+1})). DP và TD(0) cập nhật dựa trên V(s') hiện có. MC dùng return thực tế G_t, không dùng ước lượng khác nên không bootstrapping."]],"rl":[["p","Bảng so sánh:"],["list",["DP: có model, bootstrapping, expected update.","MC: model-free, không bootstrapping, sample update, cần đến hết episode.","TD: model-free, bootstrapping, sample update, cập nhật mỗi bước."]]],"ex":[["p","TD target: R + γV(s') = 1 + 0,9·10 = 10 (dùng ước lượng V(s')). MC target: G_t = tổng reward thực tế."]],"tip":[["p","Bootstrap = “keo giày bằng dây giày của chính mình”: dùng ước lượng để cập nhật ước lượng."]],"fig":false},{"id":"c2-64","part":"c2","n":64,"en":"Which of the following is the correct characterization of Dynamic Programming (DP) and Temporal Difference (TD) methods?","vi":"Đặc tính nào đúng về Quy hoạch động (DP) và Học sai khác thời gian (TD)?","opts":[{"l":"A","en":"Both TD and DP methods use expected updates","vi":"Cả hai dùng expected update.","note":""},{"l":"B","en":"Both TD and DP methods use sample updates","vi":"Cả hai dùng sample update.","note":""},{"l":"C","en":"TD methods use expected updates, DP methods use sample updates","vi":"TD dùng expected, DP dùng sample.","note":""},{"l":"D","en":"TD methods use sample updates, DP methods use expected updates","vi":"TD dùng sample, DP dùng expected.","note":""}],"ans":"D","ansnote":"","exp":[["p","DP dùng mô hình đầy đủ p(s',r|s,a) nên tính kỳ vọng trên mọi kết quả (expected update). TD chỉ dùng một mẫu (S, A, R, S') quan sát được (sample update). C ngược lại; A, B sai vì hai phương pháp khác nhau ở điểm này."]],"rl":[["code","\\text{DP: }V(s)\\leftarrow\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)[r+\\gamma V(s')]\\qquad \\text{TD: }V(S_t)\\leftarrow V(S_t)+\\alpha[R_{t+1}+\\gamma V(S_{t+1})-V(S_t)]"]],"ex":[["p","DP: cả 3 kết quả có thể (xác suất 0,5; 0,3; 0,2) cùng được cộng có trọng số. TD: chỉ đi một bước, gặp kết quả nào dùng kết quả đó."]],"tip":[["p","“DP = Distribution (expected); TD = Trajectory sample”."]],"fig":false},{"id":"c2-65","part":"c2","n":65,"en":"Match the algorithm name to its correct update (select all that apply)","vi":"Ghép tên thuật toán với công thức cập nhật đúng (chọn tất cả đáp án đúng).","opts":[{"l":"A","en":"TD(0): V(S_t) ← V(S_t) + α[G_t − V(S_t)]","vi":"","note":"(đây là MC"},{"l":"B","en":"Monte Carlo: V(S_t) ← V(S_t) + α[R_{t+1} + γV(S_{t+1}) − V(S_t)]","vi":"","note":"(đây là TD(0"},{"l":"C","en":"Monte Carlo: V(S_t) ← V(S_t) + α[G_t − V(S_t)]","vi":"","note":""},{"l":"D","en":"TD(0): V(S_t) ← V(S_t) + α[R_{t+1} + γV(S_{t+1}) − V(S_t)]","vi":"","note":""}],"ans":"CD","ansnote":"","exp":[["p","MC dùng target là return thực G_t; TD(0) dùng target là R_{t+1} + γV(S_{t+1}). A và B đảo nhãn."]],"rl":[["p","TD error: δ_t = R_{t+1} + γV(S_{t+1}) − V(S_t). MC error: G_t − V(S_t). MC đập ngay target không có V trong đó."]],"ex":[["p","R = 1, V(s') = 10, γ = 0,9, V(s) = 8: TD error = 1 + 9 − 8 = 2."]],"tip":[["p","MC target = G; TD target = R + γV."]],"fig":false},{"id":"c2-66","part":"c2","n":66,"en":"Which of the following well-describe Temporal Difference (TD) and Monte-Carlo (MC) methods?","vi":"Phát biểu nào mô tả đúng các phương pháp TD và MC?","opts":[{"l":"A","en":"TD methods can be used in continuing tasks","vi":"TD dùng được cho bài toán continuing.","note":""},{"l":"B","en":"MC methods can be used in continuing tasks","vi":"MC dùng được cho continuing.","note":""},{"l":"C","en":"TD methods can be used in episodic tasks","vi":"TD dùng được cho episodic.","note":""},{"l":"D","en":"MC methods can be used in episodic tasks","vi":"MC dùng được cho episodic.","note":""}],"ans":"ACD","ansnote":"","exp":[["p","TD cập nhật mỗi bước nên dùng được cả episodic lẫn continuing. MC cần return hoàn chỉnh nên chỉ cho episodic (B sai)."]],"rl":[["p","Vì thế TD linh hoạt hơn và thành thực tế là nền tảng của nhiều thuật toán (Q-learning, DQN)."]],"ex":[["p","Điều khiển nhiệt độ phòng 24/7 (continuing) → TD dùng được, MC thì không."]],"tip":[["p","MC = chỉ episodic; TD = cả hai."]],"fig":false},{"id":"c2-67","part":"c2","n":67,"en":"In an episodic setting, we might have different updates depending on whether the next state is terminal or non-terminal. Which of the following TD error calculations are correct?","vi":"Trong bài toán episodic, công thức cập nhật có thể khác nhau tùy trạng thái kế tiếp là kết thúc hay không. Cách tính TD error nào đúng?","opts":[{"l":"A","en":"S_{t+1} non-terminal: δ_t = R_{t+1} + γV(S_{t+1}) − V(S_t)","vi":"","note":""},{"l":"B","en":"S_{t+1} non-terminal: δ_t = R_{t+1} − V(S_t)","vi":"","note":"(thiếu phần bootstrap"},{"l":"C","en":"S_{t+1} terminal: δ_t = R_{t+1} + γV(S_{t+1}) − V(S_t) với V(S_{t+1}) = 0","vi":"","note":""},{"l":"D","en":"S_{t+1} terminal: δ_t = R_{t+1} − V(S_t)","vi":"","note":"(tương đương C"}],"ans":"ACD","ansnote":"","exp":[["p","Với trạng thái kế không phải kết thúc, dùng đầy đủ R + γV(S') − V(S) (A). Với trạng thái kết thúc, V(terminal) = 0 nên δ = R − V(S_t); C và D là hai cách viết cùng một ý. B sai vì bỏ mất γV(S')."]],"rl":[["code","\\delta_t=R_{t+1}+\\gamma V(S_{t+1})-V(S_t),\\quad V(\\text{terminal})=0"]],"ex":[["p","R = 5, V(S) = 3, S' terminal → δ = 5 − 3 = 2."]],"tip":[["p","“Kết thúc thì không còn gì để bootstrap, V(terminal) = 0”."]],"fig":false},{"id":"c2-68","part":"c2","n":68,"en":"Suppose we have current estimates for the value of two states: V(A) = 1.0, V(B) = 1.0 in an episodic setting. We observe the following trajectory: A, 0, B, 1, B, 0, T where T is a terminal state. Apply TD(0) with step-size α = 1 and discount factor γ = 0.5. What are the value estimates for state A and state B at the end of the episode?","vi":"Giả sử ước lượng hiện tại V(A) = 1,0, V(B) = 1,0. Quan sát quỹ đạo: A, 0, B, 1, B, 0, T (T là trạng thái kết thúc). Áp dụng TD(0) với α = 1 và γ = 0,5. Ước lượng cuối episode của A và B là?","opts":[{"l":"A","en":"(1,0; 1,0)","vi":"","note":""},{"l":"B","en":"(0,5; 0)","vi":"","note":""},{"l":"C","en":"(0; 1,5)","vi":"","note":""},{"l":"D","en":"(1; 0)","vi":"","note":""},{"l":"E","en":"(0; 0)","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Quỹ đạo gồm 3 chuyển: (A, r=0, B), (B, r=1, B), (B, r=0, T). Với α = 1, cập nhật V(S) ← R + γV(S'):"],["p","Bước 1: V(A) = 0 + 0,5·V(B) = 0,5·1 = 0,5."],["p","Bước 2: V(B) = 1 + 0,5·V(B) = 1 + 0,5·1 = 1,5."],["p","Bước 3: V(B) = 0 + 0,5·V(T) = 0 + 0 = 0."],["p","Cuối cùng V(A) = 0,5 và V(B) = 0 → (0,5; 0)."]],"rl":[["p","Với α = 1, TD(0) thay thế hoàn toàn V(S) bằng target R + γV(S'). Thứ tự cập nhật theo thời gian quan trọng vì V(B) thay đổi giữa các bước."]],"ex":[["p","(Bài này là ví dụ số.) Nhớ: ở bước 1 dùng V(B) cũ = 1, chưa phải 1,5."]],"tip":[["p","“Cập nhật theo thứ tự thời gian, dùng giá trị ngay tại thời điểm đó”; V(terminal) = 0."]],"fig":false},{"id":"c2-69","part":"c2","n":69,"en":"Which of the following pairs is the correct characterization of the targets used in TD(0) and Monte Carlo?","vi":"Cặp nào mô tả đúng target của TD(0) và Monte Carlo?","opts":[{"l":"A","en":"TD(0): High Variance Target, Monte Carlo: High Variance Target","vi":"Cả hai phương sai cao.","note":""},{"l":"B","en":"TD(0): High Variance Target, Monte Carlo: Low Variance Target","vi":"TD cao, MC thấp.","note":""},{"l":"C","en":"TD(0): Low Variance Target, Monte Carlo: High Variance Target","vi":"TD thấp, MC cao.","note":""},{"l":"D","en":"TD(0): Low Variance Target, Monte Carlo: Low Variance Target","vi":"Cả hai thấp.","note":""}],"ans":"C","ansnote":"","exp":[["p","Target của TD chỉ phụ thuộc một reward ngẫu nhiên R_{t+1} và một trạng thái kế tiếp nhỏ → phương sai thấp (nhưng có bias do bootstrap). Target MC là tổng nhiều reward ngẫu nhiên trong cả episode → phương sai cao (nhưng không bias)."]],"rl":[["p","Bias–variance: MC unbiased, high variance; TD biased (lúc đầu), low variance. Nên thường TD học nhanh hơn MC."]],"ex":[["p","Episode 100 bước: G_t cộng 100 reward ngẫu nhiên (dao động mạnh); TD target chỉ có 1 reward ngẫu nhiên."]],"tip":[["p","“MC = nhiều nhiễu (high var); TD = bias nhẹ nhưng ít nhiễu”."]],"fig":false},{"id":"c2-70","part":"c2","n":70,"en":"Suppose you observe the following episodes of the form (State, Reward, ...) from a Markov Decision Process with states A and B. Episodes: (A, 0, B, 0), (B, 1), (B, 1), (B, 1), (B, 0), (B, 0), (B, 1), (B, 0). What would batch Monte Carlo methods give for the estimates V(A) and V(B)? What would batch TD(0) give for the estimates V(A) and V(B)? Use γ = 1. For Batch MC: average returns observed from each state. For Batch TD: start with state B, what is its expected return? Then compute V(A) using the TD equation V(S_t) = E[R_{t+1} + γV(S_{t+1})]. (Hint: Example 6.3 in Sutton and Barto, same question with different numbers.)","vi":"Quan sát các episode dạng (Trạng thái, Reward, …) từ một MDP có hai trạng thái A, B như trên. Batch MC cho ước lượng V(A), V(B) là gì? Batch TD(0) cho ước lượng là gì? (γ = 1)","opts":[{"l":"A","en":"(0; 0,5; 0,5; 0,5)","vi":"","note":""},{"l":"B","en":"(0; 0,5; 0; 0,5)","vi":"","note":""},{"l":"C","en":"(0; 0,5; 0; 0)","vi":"","note":""},{"l":"D","en":"(0; 0,5; 1,5; 0,5)","vi":"","note":""},{"l":"E","en":"(0,5; 0,5; 0,5; 0,5)","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Batch MC: A chỉ xuất hiện trong episode 1, return = 0 + 0 = 0 → V(A) = 0. B xuất hiện 8 lần với return 0, 1, 1, 1, 0, 0, 1, 0 (4 lần =1) → V(B) = 4/8 = 0,5. Batch TD: V(B) = 0,5 (như MC); A luôn chuyển sang B với reward 0 → V(A) = 0 + γ·V(B) = 0,5. Vậy MC cho V(A) = 0 (chỉ thấy 1 mẫu), TD cho V(A) = 0,5 (dùng cấu trúc Markov)."]],"rl":[["p","Batch TD(0) hội tụ đến ước lượng certainty-equivalence (mô hình Markov khớp dữ liệu nhất); batch MC hội tụ đến trung bình return thô (ít sai lệch trên dữ liệu huấn luyện nhưng sai nhiều khi tổng quát)."]],"ex":[["p","(Bài số ở trên.) V(A): MC = 0 nhưng TD = 0,5, vì TD khai thác “A luôn đến B”."]],"tip":[["p","MC = “trung bình thô”; TD = “dựng sơ đồ Markov rồi tính”."]],"fig":false},{"id":"c2-71","part":"c2","n":71,"en":"True or False: \"Both TD(0) and Monte-Carlo (MC) methods converge to the true value function asymptotically, given that the environment is Markovian.\"","vi":"Đúng hay Sai: “Cả TD(0) và Monte Carlo đều hội tụ đến hàm giá trị thật khi số mẫu tới vô hạn, với điều kiện môi trường có tính Markov.”","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Cả hai đều hội tụ về v_π (với điều kiện chuẩn: mọi trạng thái được thăm vô hạn lần và bước học α giảm đúng cách). MC hội tụ vì trung bình return → kỳ vọng (luật số lớn); TD(0) hội tụ nhờ tính Markov (định lý hội tụ của Sutton 1988). Lưu ý: hội tụ tiệm cận ≠ hiệu quả trên dữ liệu hữu hạn (xem Câu 70)."]],"rl":[["p","Điều kiện Robbins–Monro: Σα_n = ∞, Σα_n² < ∞. Tabular TD(0), MC: hội tụ với xác suất 1."]],"ex":[["p","Random walk 5 trạng thái: cả TD và MC dần về vỉ giá trị thật (1/6, …, 5/6); TD thường nhanh hơn."]],"tip":[["p","“Cả hai đều hội tụ đúng; khác nhau ở tốc độ và bias/variance”."]],"fig":false},{"id":"c2-72","part":"c2","n":72,"en":"Which of the following pairs is the correct characterization of the TD(0) and Monte-Carlo (MC) methods?","vi":"Cặp nào mô tả đúng phương pháp TD(0) và Monte Carlo (MC)?","opts":[{"l":"A","en":"Both TD(0) and MC are offline methods","vi":"Cả hai đều là offline.","note":""},{"l":"B","en":"Both TD(0) and MC are online methods","vi":"Cả hai đều là online.","note":""},{"l":"C","en":"TD(0) is an online method while MC is an offline method","vi":"TD(0) online, MC offline.","note":""},{"l":"D","en":"MC is an online method while TD(0) is an offline method","vi":"MC online, TD(0) offline.","note":""}],"ans":"C","ansnote":"","exp":[["p","Online = cập nhật ngay sau mỗi bước tương tác (TD(0) làm được nhờ target R + γV(S')). Offline = phải chờ đến hết episode để có return (MC). Vậy C đúng."]],"rl":[["p","Online/offline liên quan đến thời điểm cập nhật. TD có thể học ngay trong episode, hữu ích khi episode rất dài hoặc bài toán continuing."]],"ex":[["p","Xe tự lái: TD cập nhật mỗi giây; MC phải chờ hết chuyến đi."]],"tip":[["p","“TD = Trực tuyến mỗi bước; MC = Muộn (chờ cuối episode)”."]],"fig":false},{"id":"c2-73","part":"c2","n":73,"en":"What is the target policy in Q-learning?","vi":"Target policy trong Q-learning là gì?","opts":[{"l":"A","en":"ε-greedy with respect to the current action-value estimates","vi":"ε-greedy theo ước lượng giá trị hành động hiện tại.","note":""},{"l":"B","en":"Greedy with respect to the current action-value estimates","vi":"Greedy theo ước lượng giá trị hành động hiện tại.","note":""}],"ans":"B","ansnote":"","exp":[["p","Q-learning là off-policy: policy sinh dữ liệu (behavior) thường là ε-greedy (A), nhưng policy được học (target) là greedy (do phép max trong target). A là behavior policy, không phải target."]],"rl":[["code","Q(S_t,A_t)\\leftarrow Q(S_t,A_t)+\\alpha\\big[R_{t+1}+\\gamma\\max_{a}Q(S_{t+1},a)-Q(S_t,A_t)\\big]"]],"ex":[["p","Đi theo ε-greedy (có lúc đi bậy) nhưng cập nhật như thể luôn đi đường tốt nhất tiếp theo."]],"tip":[["p","Q-learning: “Hành động theo ε-greedy, học theo greedy (max)”."]],"fig":false},{"id":"c2-74","part":"c2","n":74,"en":"Which Bellman equation is the basis for the Q-learning update?","vi":"Phương trình Bellman nào là cơ sở của cập nhật Q-learning?","opts":[{"l":"A","en":"Bellman equation for state values","vi":"Bellman cho giá trạng thái.","note":""},{"l":"B","en":"Bellman equation for action values","vi":"Bellman cho giá trị hành động.","note":""},{"l":"C","en":"Bellman optimality equation for state values","vi":"Bellman tối ưu cho giá trị trạng thái.","note":""},{"l":"D","en":"Bellman optimality equation for action values","vi":"Bellman tối ưu cho giá trị hành động.","note":""}],"ans":"D","ansnote":"","exp":[["p","Target của Q-learning có max_a' Q(S', a') → trùng Bellman optimality cho q*. A, B là Bellman expectation (không có max); C là cho v* không phải q*."]],"rl":[["code","q_*(s,a)=\\sum_{s',r}p(s',r|s,a)\\big[r+\\gamma\\max_{a'}q_*(s',a')\\big]"],["p","Q-learning thay kỳ vọng bằng một mẫu."]],"ex":[["p","R = 1, γ = 0,9, max Q(S',·) = 10, Q(S,A) = 8, α = 0,5: target = 1 + 9 = 10; Q mới = 8 + 0,5·(10 − 8) = 9."]],"tip":[["p","Có “max” + hàm Q = “optimality, action values”."]],"fig":false},{"id":"c2-75","part":"c2","n":75,"en":"Which Bellman equation is the basis for the Sarsa update?","vi":"Phương trình Bellman nào là cơ sở của cập nhật Sarsa?","opts":[{"l":"A","en":"Bellman cho giá trị trạng thái","vi":"","note":""},{"l":"B","en":"Bellman cho giá trị hành động","vi":"","note":""},{"l":"C","en":"Bellman tối ưu cho giá trị trạng thái","vi":"","note":""},{"l":"D","en":"Bellman tối ưu cho giá trị hành động (bốn lựa chọn như Câu 74)","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Sarsa là on-policy, ước lượng q_π của policy đang theo, với target R + γQ(S', A') (A' do chính policy chọn). Đây chính là Bellman expectation cho action values: q_π(s,a) = E[R + γ Σ π(a'|s') q_π(s',a')]. Không có max nên không phải optimality."]],"rl":[["code","Q(S_t,A_t)\\leftarrow Q(S_t,A_t)+\\alpha\\big[R_{t+1}+\\gamma Q(S_{t+1},A_{t+1})-Q(S_t,A_t)\\big]"]],"ex":[["p","Sarsa cần bộ năm (S, A, R, S', A') — tên “SARSA”."]],"tip":[["p","Sarsa = “hiện tại + kế tiếp của chính mình” → Bellman expectation (action values)."]],"fig":false},{"id":"c2-76","part":"c2","n":76,"en":"Which Bellman equation is the basis for the Expected Sarsa update?","vi":"Phương trình Bellman nào là cơ sở của cập nhật Expected Sarsa?","opts":[{"l":"A","en":"Bellman cho giá trị trạng thái","vi":"","note":""},{"l":"B","en":"Bellman cho giá trị hành động","vi":"","note":""},{"l":"C","en":"Bellman tối ưu cho giá trị trạng thái","vi":"","note":""},{"l":"D","en":"Bellman tối ưu cho giá trị hành động","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Expected Sarsa dùng kỳ vọng Σ π(a'|S') Q(S', a') thay vì một mẫu A', đúng là vế phải của Bellman expectation cho action values (tính tổng theo π, không phải max)."]],"rl":[["code","Q(S_t,A_t)\\leftarrow Q(S_t,A_t)+\\alpha\\Big[R_{t+1}+\\gamma\\sum_{a'}\\pi(a'|S_{t+1})Q(S_{t+1},a')-Q(S_t,A_t)\\Big]"],["p","Nếu π là greedy thì Expected Sarsa trở thành Q-learning."]],"ex":[["p","π = (0,9; 0,1), Q(S',·) = (10, 4), γ = 0,9 → giá trị kỳ vọng = 0,9·10 + 0,1·4 = 9,4."]],"tip":[["p","Ba thuật toán: Sarsa = mẫu A'; Expected Sarsa = trung bình theo π; Q-learning = max."]],"fig":false},{"id":"c2-77","part":"c2","n":77,"en":"Which algorithm's update requires more computation per step?","vi":"Cập nhật của thuật toán nào đòi hỏi nhiều tính toán hơn mỗi bước?","opts":[{"l":"A","en":"Expected Sarsa","vi":"","note":""},{"l":"B","en":"Sarsa","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Expected Sarsa phải tính tổng Σ_a' π(a'|S') Q(S',a') trên mọi hành động (O(|A|) mỗi bước). Sarsa chỉ dùng một hành động mẫu A' (O(1))."]],"rl":[["p","Đánh đổi: Expected Sarsa tốn tính toán hơn nhưng ít phương sai hơn (xem Câu 78)."]],"ex":[["p","4 hành động: Expected Sarsa 4 phép nhân + cộng; Sarsa 1 tra bảng. Game 1000 hành động: khác biệt đáng kể."]],"tip":[["p","“Expected = cộng hết các hành động → tốn hơn, nhưng êm hơn”."]],"fig":false},{"id":"c2-78","part":"c2","n":78,"en":"Which algorithm has a higher variance target?","vi":"Thuật toán nào có target phương sai cao hơn?","opts":[{"l":"A","en":"Expected Sarsa","vi":"","note":""},{"l":"B","en":"Sarsa","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Target Sarsa dùng một hành động mẫu A' nên có thêm ngẫu nhiên từ việc chọn A'. Expected Sarsa lấy trung bình theo π nên loại bỏ phần ngẫu nhiên đó → phương sai thấp hơn."]],"rl":[["code","\\text{Sarsa: }R+\\gamma Q(S',A')\\qquad \\text{Expected Sarsa: }R+\\gamma\\sum_{a'}\\pi(a'|S')Q(S',a')"]],"ex":[["p","Q(S',·) = (10, 0), π = (0,5; 0,5): Sarsa target dao động giữa 10 và 0 (R + γ·10 hoặc R); Expected Sarsa luôn R + γ·5."]],"tip":[["p","“Càng nhiều trung bình, càng ít nhiễu”: Expected Sarsa < Sarsa về phương sai."]],"fig":false},{"id":"c2-79","part":"c2","n":79,"en":"Q-learning does not learn about the outcomes of exploratory actions.","vi":"Q-learning không học về kết quả của các hành động khám phá.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"theo đáp án của đề","exp":[["p","Target của Q-learning dùng max_a' Q(S', a') (hành động tốt nhất), không phải hành động khám phá thực sự được chọn ở bước sau. Vì vậy kết quả “xấu” của bước khám phá ở bước kế không được đưa vào target. (Lưu ý: hành động khám phá A_t vẫn được cập nhật Q(S_t, A_t), nhưng giá trị được học là của policy tối ưu, không phải của policy ε-greedy đang thực thi.)"]],"rl":[["p","Cliff Walking: Sarsa học đường an toàn (vì tính đến rủi ro đi bậy khi khám phá), Q-learning học đường sát vực (tối ưu) nhưng khi chạy ε-greedy thì thỉnh thoảng rơi xuống."]],"ex":[["p","Cliff Walking, ε = 0,1: reward online của Q-learning thấp hơn Sarsa dù policy học được là tối ưu."]],"tip":[["p","Sarsa “sợ vực” (tính rủi ro khám phá); Q-learning “liều” (học như thể không bao giờ khám phá)."]],"fig":false},{"id":"c2-80","part":"c2","n":80,"en":"Sarsa, Q-learning, and Expected Sarsa have similar targets on a transition to a terminal state.","vi":"Sarsa, Q-learning và Expected Sarsa có target giống nhau khi chuyển sang trạng thái kết thúc.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Khi S' là terminal, Q(S',·) = 0 nên phần bootstrap bằng 0 → cả ba đều có target = R. Sự khác nhau giữa ba thuật toán chỉ nằm ở cách xử lý Q(S', ·) của bước kế."]],"rl":[["p","Target tổng quát: R + γ·(hạng bootstrap). Terminal → hạng bootstrap = 0."]],"ex":[["p","Bước cuối với R = 10: mọi thuật toán đều nhắm tới target 10."]],"tip":[["p","“Hết đường (terminal) thì không còn gì để phân biệt”."]],"fig":false},{"id":"c2-81","part":"c2","n":81,"en":"Sarsa needs to wait until the end of an episode before performing its update.","vi":"Sarsa phải chờ đến khi kết thúc episode mới thực hiện cập nhật.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Sarsa là phương pháp TD: cập nhật sau mỗi bước khi đã có (S, A, R, S', A'). Việc phải chờ hết episode là đặc điểm của Monte Carlo."]],"rl":[["p","TD/Sarsa/Q-learning: online, cập nhật mỗi bước. MC: offline (cuối episode). Xem Câu 72."]],"ex":[["p","Sau khi biết “bước đi này đưa tới ô này với reward này và hành động kế là thế này”, Sarsa cập nhật ngay."]],"tip":[["p","“SARSA = State-Action-Reward-State-Action: đủ năm thành phần là cập nhật”."]],"fig":false},{"id":"c2-82","part":"c2","n":82,"en":"Which of the following are the most accurate characterizations of sample models and distribution models? (Select all that apply)","vi":"Những mô tả nào dưới đây chính xác nhất về sample model và distribution model? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A sample model can be used to compute the probability of all possible trajectories in an episodic task based on the current state and action","vi":"Sample model có thể tính xác suất của mọi quỹ đạo.","note":""},{"l":"B","en":"A distribution model can be used as a sample model","vi":"Distribution model có thể dùng như sample model.","note":""},{"l":"C","en":"Both sample models and distribution models can be used to obtain a possible next state and reward, given the current state and action","vi":"Cả hai đều có thể cho một (s', r) có thể xảy ra.","note":""},{"l":"D","en":"A sample model can be used to obtain a possible next state and reward given the current state and action, whereas a distribution model can only be used to compute the probability of this next state and reward","vi":"Distribution model chỉ tính được xác suất.","note":""}],"ans":"BC","ansnote":"","exp":[["p","Distribution model cho p(s',r|s,a) đầy đủ nên vừa tính xác suất vừa có thể lấy mẫu từ phân phối đó (B, C đúng). Sample model chỉ sinh một kết quả ngẫu nhiên, không cho xác suất (A sai). D sai vì distribution model có thể lấy mẫu được."]],"rl":[["p","Distribution model mạnh hơn sample model (có thể suy ra sample model), nhưng khó xây hơn. DP cần distribution model; MC, TD, Dyna có thể dùng sample model."]],"ex":[["p","Xe ngựa hai mặt: distribution = {mặt 6: 1/6, …}; sample = tung một lần ra 4. Từ distribution ta tung được, nhưng từ lần tung không suy được xác suất."]],"tip":[["p","“Distribution ⊃ Sample”: có xác suất thì tự tung được, ngược lại thì không."]],"fig":false},{"id":"c2-83","part":"c2","n":83,"en":"Which of the following statements are TRUE for Dyna architecture? (Select all that apply)","vi":"Phát biểu nào đúng với kiến trúc Dyna? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Real experience can be used to improve the value function and policy","vi":"Trải nghiệm thật cải thiện hàm giá trị và policy.","note":""},{"l":"B","en":"Real experience can be used to improve the model","vi":"Trải nghiệm thật cải thiện mô hình.","note":""},{"l":"C","en":"Simulated experience can be used to improve the model","vi":"Trải nghiệm mô phỏng cải thiện mô hình.","note":""},{"l":"D","en":"Simulated experience can be used to improve the value function and policy","vi":"Trải nghiệm mô phỏng cải thiện hàm giá trị và policy.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","Dyna dùng trải nghiệm thật theo hai cách: direct RL (cập nhật Q) và model learning (cập nhật mô hình). Trải nghiệm mô phỏng (do model sinh ra) chỉ dùng cho planning, tức cải thiện Q/policy. Không dùng để cải thiện model (C sai) vì sẽ tự tham chiếu: mô hình học từ chính dữ liệu nó tạo ra."]],"rl":[["p","Ba thành phần của Dyna: (1) direct RL, (2) model learning, (3) planning (indirect RL)."]],"ex":[["p","Sau một bước thật (S, A, R, S'): cập nhật Q(S,A) (direct), lưu Model(S,A) = (R,S') (model learning), rồi lặp N lần lấy (s,a) đã thấy từ model và cập nhật Q (planning)."]],"tip":[["p","“Thật → học cả Q và model; Giả → chỉ học Q”."]],"fig":false},{"id":"c2-84","part":"c2","n":84,"en":"Mark all the statements that are TRUE for the tabular Dyna-Q algorithm. (Select all that apply)","vi":"Đánh dấu tất cả phát biểu đúng cho thuật toán Dyna-Q dạng bảng. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"For a given state-action pair, the model predicts the next state and reward","vi":"Với mỗi cặp (s,a), model dự đoán trạng thái kế và reward.","note":""},{"l":"B","en":"The memory requirements for the model in case of a deterministic environment are quadratic in the number of states","vi":"Bộ nhớ của model trong môi trường xác định là bậc hai theo số trạng thái.","note":""},{"l":"C","en":"The algorithm cannot be extended to stochastic environments","vi":"Không mở rộng được cho môi trường ngẫu nhiên.","note":""},{"l":"D","en":"The environment is assumed to be deterministic","vi":"Môi trường được giả định xác định.","note":""}],"ans":"AD","ansnote":"","exp":[["p","Tabular Dyna-Q lưu Model(s,a) = (r, s') — một kết quả duy nhất, nên giả định xác định (D). Với mỗi (s,a) model trả về (r, s') dự đoán (A). B sai vì cần bộ nhớ tỉ lệ với |S|·|A| (mỗi cặp lưu một kết quả), không phải |S|². C sai: có thể mở rộng đến môi trường ngẫu nhiên bằng cách lưu phân phối hoặc nhiều mẫu."]],"rl":[["p","Dyna-Q: mỗi bước: (d) cập nhật Q trực tiếp, (e) cập nhật model, (f) lặp N lần planning."],["code","Q(s,a)\\leftarrow Q(s,a)+\\alpha[r+\\gamma\\max_{a'}Q(s',a')-Q(s,a)]"]],"ex":[["p","100 trạng thái, 4 hành động → model chứa tối đa 400 bản ghi (không phải 10.000)."]],"tip":[["p","“Dyna-Q bảng: nhớ 1 kết quả/cặp (s,a) → xác định, bộ nhớ |S|×|A|”."]],"fig":false},{"id":"c2-85","part":"c2","n":85,"en":"Which of the following statements are TRUE? (Select all that apply)","vi":"Phát biểu nào sau đây đúng? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Model-based methods often suffer more from bias than model-free methods, because of inaccuracies in the model","vi":"Phương pháp dựa trên mô hình thường chịu bias nhiều hơn do mô hình không chính xác.","note":""},{"l":"B","en":"When compared with model-free methods, model-based methods are relatively more sample efficient. They can achieve a comparable performance with comparatively fewer environmental interactions","vi":"Model-based hiệu quả mẫu hơn, cần ít tương tác môi trường hơn để đạt hiệu năng tương đương.","note":""},{"l":"C","en":"Model-based methods like Dyna typically require more memory than model-free methods like Q-learning","vi":"Dyna cần nhiều bộ nhớ hơn Q-learning.","note":""},{"l":"D","en":"The amount of computation per interaction with the environment is larger in the Dyna-Q algorithm (with non-zero planning steps) as compared to the Q-learning algorithm","vi":"Dyna-Q tốn tính toán mỗi tương tác hơn Q-learning.","note":""}],"ans":"ABCD","ansnote":"","exp":[["p","A: model sai → planning học sai (bias). B: tận dụng model sinh trải nghiệm ảo nên cần ít tương tác thật. C: phải lưu thêm model. D: mỗi tương tác thật, Dyna-Q làm thêm N lần cập nhật planning."]],"rl":[["p","Model-based: hiệu quả mẫu cao, bias tiềm ẩn, tốn bộ nhớ + tính toán. Model-free: đơn giản, chịu được lỗi model nhưng cần nhiều dữ liệu."]],"ex":[["p","Robot thật, tương tác tốn kém: Dyna cho phép “mơ” thêm hàng chục lần sau mỗi bước thật; đổi lại nếu model lệch thì học lệch."]],"tip":[["p","Model-based = “tốn tính, tốn nhớ, tiết kiệm dữ liệu, dễ lệch”."]],"fig":false},{"id":"c2-86","part":"c2","n":86,"en":"Which of the following is generally the most computationally expensive step of the Dyna-Q algorithm? Assume N > 1 planning steps are being performed (e.g., N = 20). (có hình thuật toán)","vi":"Bước nào của Dyna-Q thường tốn tính toán nhất? Giả sử thực hiện N > 1 bước planning (ví dụ N = 20).","opts":[{"l":"A","en":"Model learning (step e)","vi":"Học mô hình.","note":""},{"l":"B","en":"Direct RL (step d)","vi":"Cập nhật RL trực tiếp.","note":""},{"l":"C","en":"Action selection (step b)","vi":"Chọn hành động.","note":""},{"l":"D","en":"Planning (Indirect RL; step f)","vi":"Planning (RL gián tiếp).","note":""}],"ans":"D","ansnote":"","exp":[["p","Planning lặp N lần, mỗi lần gồm lấy (s,a) từ model và cập nhật Q (có max), nên chi phí ≈ N lần so với các bước khác chỉ làm 1 lần. Model learning (ghi 1 ô bảng), direct RL (1 cập nhật Q), action selection (1 lần argmax) đều rẻ hơn."]],"rl":[["p","Chi phí mỗi bước thật của Dyna-Q ≈ (1 + N) cập nhật Q, trong đó N cập nhật thuộc planning."]],"ex":[["p","N = 20 → planning chiếm khoảng 20/21 ~ 95% chi phí cập nhật Q."]],"tip":[["p","“Cái gì lặp N lần thì tốn nhất: planning”."]],"fig":false},{"id":"c2-87","part":"c2","n":87,"en":"What are some possible reasons for a learned model to be inaccurate? (Select all that apply)","vi":"Một số lý do có thể khiến mô hình đã học không chính xác là gì? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The transition dynamics of the environment are stochastic, and only a few transitions have been experienced","vi":"Động lực môi trường ngẫu nhiên và mới trải nghiệm ít chuyển trạng thái.","note":""},{"l":"B","en":"The environment has changed","vi":"Môi trường đã thay đổi.","note":""},{"l":"C","en":"The agent's policy has changed significantly from the beginning of training","vi":"Policy của agent thay đổi nhiều so với lúc đầu.","note":""},{"l":"D","en":"There is too much exploration (e.g., ε = 0.5)","vi":"Khám phá quá nhiều.","note":""}],"ans":"AB","ansnote":"","exp":[["p","Mô hình mô tả động lực của môi trường, không phụ thuộc policy. Ít mẫu (A) → ước lượng xác suất sai. Môi trường đổi (B) → model cũ lỗi thời. C, D sai vì policy và mức khám phá chỉ ảnh hưởng đến dữ liệu thu được, không làm hỏng động lực thật; thậm chí khám phá nhiều còn làm model tốt hơn."]],"rl":[["p","Model tốt ⇔ đủ dữ liệu + môi trường không đổi. Giải pháp cho môi trường đổi: Dyna-Q+ (thưởng khám phá)."]],"ex":[["p","Model ghi “đẩy cửa → mở” từ 1 lần thử, nhưng cửa kẹt 30% thời gian → model sai. Hay cửa bị đổi thành tường → model lỗi thời."]],"tip":[["p","Model sai vì “ít dữ liệu” hoặc “thế giới đổi”, không phải vì policy đổi."]],"fig":false},{"id":"c2-88","part":"c2","n":88,"en":"In search control, which of the following methods is likely to make a Dyna agent perform better in problems with a large number of states (like the rod maneuvering problem in Chapter 8 of the textbook)? Recall that search control is the process that selects the starting states and actions in planning. Also, recall the navigation example in the video lectures in which a large number of wasteful updates were being made because of the basic search control procedure in the Dyna-Q algorithm. (Select the best option)","vi":"Trong search control, phương pháp nào có khả năng giúp agent Dyna hoạt động tốt hơn trong bài toán có số trạng thái lớn (như bài toán điều khiển thanh que ở Chương 8)? Nhớ: search control là quá trình chọn trạng thái và hành động bắt đầu cho planning; ví dụ điều hướng trong bài giảng có rất nhiều cập nhật lãng phí. (Chọn đáp án tốt nhất)","opts":[{"l":"A","en":"Select state-action pairs uniformly at random from all previously experienced pairs","vi":"Chọn ngẫu nhiên đều từ mọi cặp đã gặp.","note":""},{"l":"B","en":"Start backwards from state-action pairs that have had a non-zero update (e.g., from the state right beside a goal state). This avoids the otherwise wasteful computations from state-action pairs which have had no updates","vi":"Bắt đầu ngược từ các cặp (s,a) đã có cập nhật khác 0 (ví dụ ô sát đích), tránh lãng phí.","note":""},{"l":"C","en":"Start with state-action pairs enumerated in a fixed order (e.g., top-left to bottom-right; up, down, left, right)","vi":"Duyệt theo thứ tự cố định.","note":""},{"l":"D","en":"All of these are equally good/bad","vi":"Tất cả tương đương.","note":""}],"ans":"B","ansnote":"","exp":[["p","Planning chỉ có ích khi cập nhật thay đổi giá trị. Nếu chọn cặp (s,a) ngẫu nhiên/cố định trong không gian lớn thì hầu hết cập nhật đều bằng 0 (lãng phí). Làm ngược từ các cặp vừa thay đổi giá trị (prioritized sweeping / backward focusing) tập trung vào chỗ có ích nhất."]],"rl":[["p","Prioritized sweeping: duy trì hàng đợi ưu tiên theo mức thay đổi |ΔQ|, cập nhật cặp thay đổi nhiều nhất và lan ngược về các tiền nhiệm."]],"ex":[["p","Mê cung lớn: chỉ ô kề đích có Q ≠ 0 sau lần đầu → bắt đầu từ đó, lan ngược lần lượt về ô xuất phát."]],"tip":[["p","“Muốn planning không phí: nhằm vào chỗ vừa thay đổi, lan ngược về sau”."]],"fig":false},{"id":"c2-89","part":"c2","n":89,"en":"In the lectures, we saw how the Dyna-Q+ agent found the newly-opened shortcut in the shortcut maze, whereas the Dyna-Q agent didn't. Which of the following implications drawn from the figure are TRUE? (Select all that apply) (có hình)","vi":"Trong bài giảng, agent Dyna-Q+ tìm ra lối tắt mới mở trong mê cung, còn Dyna-Q thì không. Những kết luận nào rút ra từ hình là đúng? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The Dyna-Q+ agent performs better than the Dyna-Q agent even in the first half of the experiment because of the increased exploration","vi":"Dyna-Q+ tốt hơn Dyna-Q ngay cả ở nửa đầu nhờ khám phá nhiều hơn.","note":""},{"l":"B","en":"The Dyna-Q agent can never discover shortcuts (i.e., when the environment changes to become better than it was before)","vi":"Dyna-Q không bao giờ tìm ra lối tắt.","note":""},{"l":"C","en":"The difference between Dyna-Q+ and Dyna-Q narrowed slightly over the first part of the experiment. This is because the Dyna-Q+ agent keeps exploring even when the environment isn't changing","vi":"Khoảng cách giữa hai agent thu hẹp nhẹ trong nửa đầu vì Dyna-Q+ vẫn tiếp tục khám phá khi môi trường không đổi.","note":""},{"l":"D","en":"None of the above are true","vi":"Không câu nào đúng.","note":""}],"ans":"AC","ansnote":"theo đáp án của đề","exp":[["p","Hình không hiển thị trên trang văn bản nên phần đọc đồ thị mình dựa vào đáp án của đề. Hai ý quan trọng: (1) Dyna-Q+ cộng bonus thưởng κ√τ cho cặp (s,a) lâu chưa thử nên khám phá nhiều hơn, có thể đạt kết quả tốt sớm hơn (A). (2) Chi phí của việc khám phá thêm khi môi trường không đổi làm khoảng cách thu hẹp (C). B sai vì Dyna-Q vẫn có thể tìm lối tắt nhờ ε-greedy, chỉ rất chậm."]],"rl":[["p","Dyna-Q+ thêm bonus khám phá vào reward mô phỏng: r + κ√τ, với τ = số bước kể từ lần cuối thử (s,a)."],["code","r_{\\text{plan}}=r+\\kappa\\sqrt{\\tau}"]],"ex":[["p","κ = 0,001, τ = 10.000 → bonus = 0,1: đủ kéo agent thử lại lối tắt cũ đã không dùng lâu."]],"tip":[["p","“Q+ = Tò mò”: càng lâu không đến, càng thưởng để đến."]],"fig":false},{"id":"c2-90","part":"c2","n":90,"en":"Consider the gridworld depicted in the diagram below. There are four actions corresponding to up, down, right, and left movements. Marked is the path taken by an agent in a single episode, ending at a location of high reward, marked by the G. In this example the values were all zero at the start of the episode, and all rewards were zero during the episode except for a positive reward at G. Now which of the following figures best depicts the action values that would've increased by the end of the episode using one-step Sarsa and 500-step-planning Dyna-Q? (Select the best option)","vi":"Xét gridworld như hình. Có 4 hành động lên, xuống, phải, trái. Đường đi của agent trong một episode được đánh dấu, kết thúc ở ô thưởng cao G. Ban đầu mọi giá trị bằng 0, và mọi reward trong episode bằng 0 trừ reward dương tại G. Hình nào mô tả tốt nhất các giá trị hành động đã tăng sau episode khi dùng Sarsa một bước và Dyna-Q 500 bước planning?","opts":[{"l":"A","en":"Sarsa: cả đường đi; Dyna-Q: cả đường đi.","vi":"","note":""},{"l":"B","en":"Sarsa: cả đường đi; Dyna-Q: chỉ ô cạnh G.","vi":"","note":""},{"l":"C","en":"Sarsa: chỉ ô cạnh G; Dyna-Q: cả đường đi.","vi":"","note":""},{"l":"D","en":"Sarsa: chỉ ô cạnh G; Dyna-Q: chỉ ô cạnh G.","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Sarsa một bước chỉ cập nhật Q(S_t, A_t) khi đi qua; vì giá trị ban đầu 0 và reward 0 ngoài G, nên chỉ cặp (s,a) ngay trước G (nhận reward) tăng. Dyna-Q với 500 bước planning tận dụng model: sau khi đến G, planning lan truyền giá trị ngược dọc toàn đường đã đi, nên tất cả các cặp trên đường đều tăng (có thể cả những cặp khác nếu model ghi nhớ)."]],"rl":[["p","Sarsa một bước: giá trị lan ra 1 bước mỗi episode. Dyna: planning nhiều bước → lan toàn tuyến ngay trong một episode."]],"ex":[["p","Đường 10 ô: Sarsa sau 1 episode mới “biết” ô thứ 10; sau 10 episode mới lan về ô đầu. Dyna-Q 500 planning: lan về ô đầu ngay sau episode đầu."]],"tip":[["p","“Sarsa = lan chậm 1 ô/lần; Dyna = lan nhanh nhờ mơ thêm”."]],"fig":false},{"id":"c2-91","part":"c2","n":91,"en":"Which of the following are planning methods? (Select all that apply)","vi":"Phương pháp nào dưới đây là phương pháp lập kế hoạch (planning)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Q-learning","vi":"","note":""},{"l":"B","en":"Expected Sarsa","vi":"","note":""},{"l":"C","en":"Value Iteration","vi":"","note":""},{"l":"D","en":"Dyna-Q","vi":"","note":""}],"ans":"CD","ansnote":"","exp":[["p","Planning = dùng mô hình để cải thiện policy/giá trị. Value Iteration dùng mô hình p (DP). Dyna-Q dùng model đã học để lặp planning. Q-learning và Expected Sarsa chỉ học từ trải nghiệm thật (model-free), không có model nên không phải planning."]],"rl":[["p","Learning (model-free): Q-learning, Sarsa, Expected Sarsa, MC, TD. Planning (model-based): DP, Dyna, MCTS."]],"ex":[["p","Giống học cờ bằng chơi thật (learning) so với nhẩm nước đi trong đầu (planning)."]],"tip":[["p","“Có model = planning (DP, Dyna); không model = learning (Q, Sarsa)”."]],"fig":false},{"id":"c3-92","part":"c3","n":92,"en":"Which of the following statements is true about function approximation in reinforcement learning? (Select all that apply)","vi":"Phát biểu nào đúng về xấp xỉ hàm (function approximation) trong học tăng cường? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"It allows faster training by generalizing between states","vi":"Cho phép huấn luyện nhanh hơn nhờ tổng quát giữa các trạng thái.","note":""},{"l":"B","en":"We only use function approximation because we have to for large or continuous state spaces. We would use tabular methods if we could, and learn an independent value per state","vi":"Ta chỉ dùng xấp xỉ hàm vì bắt buộc (không gian lớn/liên tục); nếu được ta sẽ dùng bảng.","note":""},{"l":"C","en":"It can be more memory efficient","vi":"Có thể tiết kiệm bộ nhớ hơn.","note":""},{"l":"D","en":"It can help the agent achieve good generalization with good discrimination, so that it learns faster and represent the values quite accurately","vi":"Giúp tổng quát tốt mà vẫn phân biệt tốt, học nhanh và biểu diễn giá trị khá chính xác.","note":""}],"ans":"ACD","ansnote":"","exp":[["p","Xấp xỉ hàm không chỉ là “con đường bắt buộc”: nó còn đem lại lợi ích riêng là tổng quát (học ở trạng thái này cải thiện ước lượng ở trạng thái tương tự, nên học nhanh hơn), tiết kiệm bộ nhớ (chỉ lưu vector trọng số w nhỏ thay vì 1 giá trị/trạng thái). B sai vì ngay cả khi không gian nhỏ, tổng quát vẫn có thể hữu ích."]],"rl":[["p","xấp xỉ với tham số w ∈ ℝ^d, d ≪ |S|:"],["code","\\hat v(s,\\mathbf w)\\approx v_\\pi(s)"],["p","Tổng quát (generalization) và phân biệt (discrimination) đánh đổi nhau: quá tổng quát thì lẫn lộn trạng thái, quá phân biệt thì như bảng."]],"ex":[["p","Trò chơi có 10^20 trạng thái: bảng không thể lưu, mạng với 10^6 trọng số thì được; đồng thời thấy 1 thế cờ cũng cải thiện ước lượng cho thế cờ gần giống."]],"tip":[["p","Function approximation = “nhớ ít, đoán giống” (bộ nhớ nhỏ, generalization). Không chỉ là “chữa cháy”."]],"fig":false},{"id":"c3-93","part":"c3","n":93,"en":"We learned how value function estimation can be framed as supervised learning. But not all supervised learning methods are suitable. What are some characteristics of reinforcement learning that can make it harder to apply standard supervised learning methods?","vi":"Ta đã học cách biểu diễn ước lượng hàm giá trị như học có giám sát. Nhưng không phải phương pháp học có giám sát nào cũng phù hợp. Đặc điểm nào của RL khiến việc áp dụng các phương pháp học có giám sát chuẩn khó hơn?","opts":[{"l":"A","en":"Data is available as a fixed batch","vi":"Dữ liệu có sẵn dạng lô cố định.","note":""},{"l":"B","en":"Data is temporally correlated in reinforcement learning","vi":"Dữ liệu trong RL có tương quan theo thời gian.","note":""},{"l":"C","en":"When using bootstrapping methods like TD, the target labels change","vi":"Khi dùng bootstrapping như TD, nhãn mục tiêu (target) thay đổi.","note":""}],"ans":"BC","ansnote":"","exp":[["p","Học có giám sát chuẩn giả định mẫu độc lập, phân phối dữ liệu cố định, nhãn cố định. RL vi phạm: (B) các bước liên tiếp tương quan, không i.i.d; (C) target R + γû(S', w) phụ thuộc chính w đang học nên “nhãn” dịch chuyển. A sai vì dữ liệu cố định dạng lô là điều kiện dễ chứ không khó; trong RL dữ liệu là luồng thay đổi theo policy."]],"rl":[["p","Các khác biệt RL so với SL: dữ liệu tương quan, non-stationary (policy đổi), target phụ thuộc w. DQN xử lý bằng experience replay và target network."]],"ex":[["p","100 bước liên tiếp trong cùng một phòng nhìn gần giống nhau → tương quan; target TD thay đổi mỗi lần w cập nhật."]],"tip":[["p","“RL ≠ SL vì: dữ liệu dính nhau (tương quan) + nhãn trôi (target đổi)”."]],"fig":false},{"id":"c3-94","part":"c3","n":94,"en":"Value Prediction (or Policy Evaluation) with Function Approximation can be viewed as supervised learning mainly because _________. [choose the most appropriate completion]","vi":"Dự đoán giá trị (đánh giá policy) với xấp xỉ hàm có thể xem là học có giám sát chủ yếu vì _________. (chọn cách hoàn thành phù hợp nhất)","opts":[{"l":"A","en":"Each state and its target (used in the Monte Carlo update, TD(0) update, and DP update) forms an input-output training example which we can use to train our approximation to the value function","vi":"Mỗi trạng thái cùng target của nó (trong cập nhật MC, TD(0), DP) tạo thành một mẫu vào–ra để huấn luyện.","note":""},{"l":"B","en":"We use stochastic gradient descent to learn the value function","vi":"Ta dùng SGD để học.","note":""},{"l":"C","en":"We can learn the value function by training with batches of data obtained from the agent's interaction with the world","vi":"Học theo lô dữ liệu từ tương tác.","note":""}],"ans":"A","ansnote":"","exp":[["p","Bản chất của học có giám sát là có cặp (input, nhãn). Ở đây input = trạng thái S_t, nhãn = target U_t (G_t cho MC, R + γû cho TD(0), hoặc kỳ vọng cho DP). B, C nêu công cụ/cách lấy dữ liệu chứ không phải lý do “là supervised”."]],"rl":[["code","S_t\\mapsto U_t,\\qquad \\mathbf w\\leftarrow\\mathbf w+\\alpha[U_t-\\hat v(S_t,\\mathbf w)]\\nabla\\hat v(S_t,\\mathbf w)"]],"ex":[["p","MC: (S_t, G_t); TD(0): (S_t, R_{t+1} + γû(S_{t+1})); DP: (s, Σ p [r + γû(s')])."]],"tip":[["p","“Supervised = cặp (x, y); ở đây x = state, y = target”."]],"fig":false},{"id":"c3-95","part":"c3","n":95,"en":"Which of the following is true about using Mean Squared Value Error (VE = Σ μ(s)[v_π(s) − û(s,w)]²) as the prediction objective? μ(s) represents the weighted distribution of visited states. (Select all that apply)","vi":"Phát biểu nào đúng khi dùng sai số bình phương trung bình của giá trị (MSVE) làm mục tiêu dự đoán? μ(s) là phân phối có trọng số của các trạng thái được ghé thăm. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Even if the agent uses a linear representation that cannot represent the true values, the agent can still get zero MSVE","vi":"Dù biểu diễn tuyến tính không biểu diễn được giá trị thật, vẫn có thể đạt MSVE = 0.","note":""},{"l":"B","en":"Gradient Monte Carlo with linear function approximation converges to the global optimum of this objective, if the step size is reduced over time","vi":"Gradient MC với xấp xỉ tuyến tính hội tụ đến tối ưu toàn cục nếu α giảm dần.","note":""},{"l":"C","en":"The agent can get zero MSVE when using a tabular representation that can represent the true values","vi":"Dùng bảng (biểu diễn được giá trị thật) thì MSVE = 0 đạt được.","note":""},{"l":"D","en":"This objective makes it explicit how we should trade-off accuracy of the value estimates across states, using the weighting μ","vi":"Mục tiêu này nêu rõ cách đánh đổi độ chính xác giữa các trạng thái qua trọng số μ.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","A sai vì nếu biểu diễn không đủ mạnh để biểu diễn v_π thì sai số dư khác 0. B: hàm mục tiêu lồi (tuyến tính) nên SGD với α giảm đúng cách hội tụ đến tối ưu toàn cục. C: bảng có đủ tham số cho từng trạng thái. D: μ quy định trạng thái nào quan trọng hơn."]],"rl":[["code","\\overline{VE}(\\mathbf w)=\\sum_{s}\\mu(s)\\big[v_\\pi(s)-\\hat v(s,\\mathbf w)\\big]^2"]],"ex":[["p","Hai trạng thái với μ = (0,9; 0,1): sai số ở trạng thái 1 được phạt nặng gấp 9 lần."]],"tip":[["p","“μ = nhiều lần ghé → quan trọng”; tabular đủ tham số → VE = 0 được; tuyến tính thì chỉ đạt tối ưu trong lớp hàm."]],"fig":false},{"id":"c3-96","part":"c3","n":96,"en":"Which of the following is true about μ(S) in Mean Squared Value Error? (Select all that apply)","vi":"Phát biểu nào đúng về μ(S) trong MSVE? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"It serves as a weighting to minimize the error more in states that we care about","vi":"Là trọng số để giảm sai số nhiều hơn ở các trạng thái ta quan tâm.","note":""},{"l":"B","en":"It is a probability distribution","vi":"Là một phân phối xác suất.","note":""},{"l":"C","en":"If the policy is uniformly random, μ(S) would have the same value for all states","vi":"Nếu policy ngẫu nhiên đều thì μ(S) bằng nhau ở mọi trạng thái.","note":""},{"l":"D","en":"It has higher values for states that are visited more often","vi":"Giá trị cao hơn cho các trạng thái được ghé thăm thường xuyên hơn.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","μ(s) ≥ 0, Σμ = 1 (A, B), và μ(s) lớn ở trạng thái hay ghé (D). C sai: policy ngẫu nhiên đều vẫn tạo phân phối ghé thăm không đều vì cấu trúc môi trường (ví dụ ô góc ít được ghé, trạng thái khởi đầu phân bố khác nhau)."]],"rl":[["p","μ(s) là phân phối ổn định (on-policy distribution) dưới π: phần thời gian trạng thái s được ghé."]],"ex":[["p","Phòng ở giữa mê cung được ghé nhiều → μ cao; góc khó đến → μ thấp, dù π ngẫu nhiên."]],"tip":[["p","“μ = thống kê số lần ghé, không phải độ ngu nhiên của policy”."]],"fig":false},{"id":"c3-97","part":"c3","n":97,"en":"The stochastic gradient descent update for the MSVE would be as follows. Fill in the blanks (A), (B), (C) and (D) with correct terms. (Select all correct answers)","vi":"Cập nhật gradient descent ngẫu nhiên cho MSVE như sau. Điền vào các chỗ trống (A), (B), (C), (D) bằng các số hạng đúng. (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"+, −, v_π(S_t), û(S_t, w_t)","vi":"","note":""},{"l":"B","en":"−, −, û(S_t, w_t), v_π(S_t)","vi":"","note":""},{"l":"C","en":"−, +, v_π(S_t), û(S_t, w_t)","vi":"","note":""},{"l":"D","en":"+, +, û(S_t, w_t), v_π(S_t)","vi":"","note":""}],"ans":"BC","ansnote":"","exp":[["p","Gradient descent: trừ gradient: w_{t+1} = w_t − ½α∇[·]², nên (A) là dấu −. Áp dụng ∇[v_π − û]² = 2[v_π − û]·(−∇û) ⇒ w_{t+1} = w_t + α[v_π − û]∇û. Nếu đảo thứ tự trong ngoặc: [û − v_π]² thì ∇ = 2[û − v_π]∇û nên còn lại dấu − (phương án B). Vậy hai cách ghi (B và C) đều cho cùng một quy tắc. A, D sai vì có dấu + ở (A) là gradient ascent."]],"rl":[["code","\\mathbf w_{t+1}=\\mathbf w_t-\\tfrac12\\alpha\\nabla[v_\\pi(S_t)-\\hat v(S_t,\\mathbf w_t)]^2=\\mathbf w_t+\\alpha[v_\\pi(S_t)-\\hat v(S_t,\\mathbf w_t)]\\nabla\\hat v(S_t,\\mathbf w_t)"]],"ex":[["p","v_π = 10, û = 8, ∇û = x = 2, α = 0,1 → Δw = 0,1·(10−8)·2 = 0,4 → û tăng lên."]],"tip":[["p","“Descent = dấu trừ; (về đích − hiện tại) × ∇û = cộng”: sai số dương thì đẩy û lên."]],"fig":false},{"id":"c3-98","part":"c3","n":98,"en":"In a Monte Carlo Update with function approximation, we do stochastic gradient descent using the gradient ∇[G_t − û(s,w)]² = 2[G_t − û]∇(−û) = (−1)·2[G_t − û]∇û. But the actual Monte Carlo Update rule is w_{t+1} = w_t + α[G_t − û(S_t,w_t)]∇û(S_t,w_t), α > 0. Where did the constants −1 and 2 go when α is positive? (Choose all that apply)","vi":"Trong cập nhật Monte Carlo với xấp xỉ hàm, ta dùng SGD với gradient như trên, nhưng quy tắc cập nhật thực tế không có hằng số −1 và 2. Chúng đi đâu mất khi α dương? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"We assume that the 2 is included in ∇û(S_t, w_t)","vi":"Giả sự số 2 nằm trong ∇û.","note":""},{"l":"B","en":"We are performing gradient descent, so we subtract the gradient from the weights, negating −1","vi":"Ta đang gradient descent nên trừ gradient, làm triệt tiêu −1.","note":""},{"l":"C","en":"We are performing gradient ascent, so we subtract the gradient","vi":"Ta đang gradient ascent.","note":""},{"l":"D","en":"We assume that the 2 is included in the step-size","vi":"Giả sự số 2 nằm trong hệ số bước α.","note":""}],"ans":"BD","ansnote":"","exp":[["p","Đang gradient descent: w ← w − α'∇L; ∇L có hệ số −1 nên “trừ × (−1) = cộng” (B). Hằng số 2 được gộp vào bước học α (D) vì α là hằng số tự chọn. A sai vì ∇û là gradient của û, không chứa hằng số 2. C sai vì ta đang tối thiểu hóa sai số (descent), không phải ascent."]],"rl":[["p","SGD: w ← w − α∇L. Với L = ½[G − û]², ∇L = −[G − û]∇û."]],"ex":[["p","α' = 0,05 và hằng số 2 ⇒ α = 0,1 nếu ta “gộp 2 vào α”."]],"tip":[["p","“Descent: trừ gradient; −1 triệt tiêu −1 → +; hằng số 2 → chui vào α”."]],"fig":false},{"id":"c3-99","part":"c3","n":99,"en":"When using stochastic gradient descent for learning the value function, why do we only make a small update towards minimizing the error instead of fully minimizing the error at each encountered state?","vi":"Khi học hàm giá trị bằng SGD, vì sao ta chỉ cập nhật nhỏ về phía giảm sai số thay vì giảm đến tối thiểu tại mỗi trạng thái gặp?","opts":[{"l":"A","en":"Because we want to minimize approximation error for all states, proportionally to μ","vi":"Vì ta muốn giảm sai số xấp xỉ cho tất cả trạng thái, theo tỷ lệ μ.","note":""},{"l":"B","en":"Because small updates guarantee we can slowly reduce approximation error to zero for all states","vi":"Vì cập nhật nhỏ đảm bảo giảm dần sai số về 0 cho mọi trạng thái.","note":""},{"l":"C","en":"Because the target value may not be accurate initially for both TD(0) and Monte Carlo method","vi":"Vì target ban đầu có thể không chính xác cho cả TD(0) và MC.","note":""}],"ans":"A","ansnote":"","exp":[["p","Vì các trạng thái dùng chung tham số w, sửa mạnh cho trạng thái này sẽ làm hỏng các trạng thái khác. Mục tiêu là giảm sai số tổng thể, trọng số theo μ, nên mỗi lần chỉ đi một bước nhỏ (SGD) rồi trung bình dần qua nhiều mẫu. B sai vì không đảm bảo sai số về 0 (xấp xỉ có giới hạn năng lực). C chỉ đúng với TD, không đúng với MC (target MC không bias)."]],"rl":[["p","Khác với tabular (các ô độc lập, có thể đặt û = target), xấp xỉ hàm có can thiệp lẫn nhau giữa các trạng thái."]],"ex":[["p","Ûp(s1) = 5 đúng, nhưng û(s2) = 8 và hai trạng thái dùng chung w. Chỉnh s1 về đúng hoàn toàn có thể đẩy s2 lệch."]],"tip":[["p","“Chia chung tham số → sửa nhẹ tay, tránh đẩy hỏng ô khác”."]],"fig":false},{"id":"c3-100","part":"c3","n":100,"en":"The general stochastic gradient descent update rule for state-value prediction is w_{t+1} = w_t + α[U_t − û(S_t,w_t)]∇û(S_t,w_t). For what values of U_t would this be a semi-gradient method?","vi":"Quy tắc SGD tổng quát cho dự đoán giá trị trạng thái như trên. Với U_t nào thì đây là phương pháp semi-gradient?","opts":[{"l":"A","en":"v_π(S_t)","vi":"giá trị thật (không phụ thuộc w) → gradient đầy đủ.","note":""},{"l":"B","en":"R_{t+1} + û(S_{t+1}, w_t)","vi":"target phụ thuộc w → semi-gradient.","note":""},{"l":"C","en":"R_{t+1} + R_{t+2} + … + R_T","vi":"return thực → gradient đầy đủ.","note":""},{"l":"D","en":"G_t","vi":"return → gradient đầy đủ.","note":""}],"ans":"B","ansnote":"","exp":[["p","Semi-gradient: khi target U_t phụ thuộc w (bootstrapping) nhưng ta coi target như hằng số, chỉ lấy gradient theo û(S_t, w) mà bỏ qua gradient của target. Chỉ û(S_{t+1}, w) trong B phụ thuộc w. A, C, D không phụ thuộc w nên là gradient thực."]],"rl":[["p","Semi-gradient TD(0):"],["code","\\mathbf w\\leftarrow\\mathbf w+\\alpha[R_{t+1}+\\gamma\\hat v(S_{t+1},\\mathbf w)-\\hat v(S_t,\\mathbf w)]\\nabla\\hat v(S_t,\\mathbf w)"],["p","True gradient sẽ thêm thành phần γ∇û(S_{t+1}); semi-gradient bỏ nó."]],"ex":[["p","MC: U = G_t = 7 (hằng) → gradient thật. TD(0): U = 1 + 0,9·û(S') phụ thuộc w → bỏ qua → semi-gradient."]],"tip":[["p","“Có bootstrapping (û trong target) → semi”."]],"fig":false},{"id":"c3-101","part":"c3","n":101,"en":"Which of the following statements is true about state-value prediction using stochastic gradient descent w_{t+1} = w_t + α[U_t − û(S_t,w_t)]∇û(S_t,w_t)? (Select all that apply)","vi":"Phát biểu nào đúng về dự đoán giá trạng thái bằng SGD với quy tắc trên? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Using the Monte Carlo return as target, and under appropriate stochastic approximation conditions, the value function will converge to a local optimum of the MSVE","vi":"Với target MC và điều kiện xấp xỉ ngẫu nhiên thích hợp, hội tụ đến tối ưu cục bộ của MSVE.","note":""},{"l":"B","en":"Using the Monte Carlo return or true value function as target results in an unbiased update","vi":"Target là return MC hoặc giá trị thật đều cho cập nhật không chệch.","note":""},{"l":"C","en":"When using U_t = R_{t+1} + û(S_{t+1}, w_t), the weight update is not using the true gradient of the TD error","vi":"Với U_t dạng bootstrapping, cập nhật không dùng gradient thật của TD error.","note":""},{"l":"D","en":"SGD updates with Monte Carlo targets always reduce the MSVE at each step","vi":"Cập nhật SGD với target MC luôn giảm MSVE ở mỗi bước.","note":""},{"l":"E","en":"Semi-gradient TD(0) methods typically learn faster than gradient Monte Carlo methods","vi":"Semi-gradient TD(0) thường học nhanh hơn gradient MC.","note":""}],"ans":"ABCE","ansnote":"","exp":[["p","A: MC target không bias, SGD hội tụ đến điểm cực tiểu cục bộ. B: E[G_t | S_t] = v_π(S_t) nên không bias. C: bootstrapping làm cập nhật là semi-gradient. E: phương sai thấp hơn nên học nhanh hơn (xem Câu 69). D sai vì mỗi bước SGD là ngẫu nhiên nên có thể tăng MSVE; chỉ giảm kỳ vọng."]],"rl":[["p","SGD chỉ giảm MSVE trung bình; semi-gradient TD tuyến tính hội tụ đến TD fixed point (Câu 102)."]],"ex":[["p","Trong chuỗi 1 bước cập nhật với mẫu nhiễu, MSVE vẫn có thể tăng nhẹ rồi giảm về sau."]],"tip":[["p","MC = không bias, nhiễu cao; TD = chút bias, học nhanh; SGD = giảm “trung bình” chứ không “mỗi bước”."]],"fig":false},{"id":"c3-102","part":"c3","n":102,"en":"Which of the following is true about the TD fixed point? (Select all correct answers)","vi":"Phát biểu nào đúng về điểm cố định TD (TD fixed point)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Semi-gradient TD(0) with linear function approximation converges to the TD fixed point","vi":"Semi-gradient TD(0) tuyến tính hội tụ đến TD fixed point.","note":""},{"l":"B","en":"The weight vector corresponding to the TD fixed point is a local minimum of the MSVE","vi":"Vector trọng số tại TD fixed point là cực tiểu cục bộ của MSVE.","note":""},{"l":"C","en":"... is the global minimum of the MSVE","vi":"Là cực tiểu toàn cục của MSVE.","note":""},{"l":"D","en":"At the TD fixed point, the MSVE is not larger than 1/(1 − γ) times the minimal MSVE, assuming the same linear function approximation","vi":"Tại TD fixed point, MSVE không lớn hơn 1/(1 − γ) lần MSVE nhỏ nhất.","note":""}],"ans":"AD","ansnote":"","exp":[["p","Semi-gradient TD tuyến tính hội tụ đến w_TD (A), nhưng w_TD không tối thiểu MSVE (B, C sai) mà chỉ là nghiệm của phương trình projected Bellman. Sai số của nó bị chặn: VE(w_TD) ≤ (1/(1 − γ)) min_w VE(w) (D). γ càng gần 1 thì cận càng lỏng."]],"rl":[["code","\\overline{VE}(\\mathbf w_{TD})\\le\\frac{1}{1-\\gamma}\\min_{\\mathbf w}\\overline{VE}(\\mathbf w),\\qquad \\mathbf w_{TD}=\\mathbf A^{-1}\\mathbf b"]],"ex":[["p","γ = 0,9: TD fixed point có thể có sai số gấp tối đa 10 lần sai số tối thiểu (thường tốt hơn nhiều)."]],"tip":[["p","“TD fixed point ≠ optimum của MSVE; nhưng có cận 1/(1 − γ)”."]],"fig":false},{"id":"c3-103","part":"c3","n":103,"en":"Which of the following is true about Linear Function Approximation, for estimating state-values? (Select all that apply)","vi":"Phát biểu nào đúng về xấp xỉ hàm tuyến tính để ước lượng giá trị trạng thái? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The size of the feature vector is not necessarily equal to the size of the weight vector","vi":"Kích thước vector đặc trưng không nhất thiết bằng kích thước vector trọng số.","note":""},{"l":"B","en":"The gradient of û(s, w) with respect to w is just the feature vector","vi":"Gradient của û theo w chính là vector đặc trưng.","note":""},{"l":"C","en":"State aggregation is one way to generate features for linear function approximation","vi":"Gom trạng thái là một cách tạo đặc trưng.","note":""}],"ans":"BC","ansnote":"","exp":[["p","û(s,w) = wᵀx(s) = Σ w_i x_i(s) nên ∇_w û = x(s) (B). State aggregation là trường hợp đặc biệt với x(s) là one-hot theo nhóm (C). A sai: mỗi trọng số ứng với một đặc trưng nên hai vector cùng chiều."]],"rl":[["code","\\hat v(s,\\mathbf w)=\\mathbf w^\\top\\mathbf x(s),\\qquad\\nabla_{\\mathbf w}\\hat v=\\mathbf x(s)"],["p","Cập nhật tuyến tính: w ← w + α[U − wᵀx]x."]],"ex":[["p","x(s) = (1, 0, 1), w = (2, 5, 3) → û = 2 + 3 = 5; ∇û = (1, 0, 1)."]],"tip":[["p","“Tuyến tính → gradient = feature”."]],"fig":false},{"id":"c3-104","part":"c3","n":104,"en":"Which of the following is TRUE about coarse coding? (Select all that apply)","vi":"Phát biểu nào đúng về mã hóa thô (coarse coding)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"In coarse coding, generalization occurs between states that have features with overlapping receptive fields","vi":"Tổng quát xảy ra giữa các trạng thái có đặc trưng với trường tiếp nhận chồng lấn.","note":""},{"l":"B","en":"... depends on the size and shape of the receptive fields","vi":"Tổng quát phụ thuộc kích thước và hình dạng trường tiếp nhận.","note":""},{"l":"C","en":"When using features with large receptive fields, the function approximator cannot make discriminations that are finer than the width of the receptive fields","vi":"Trường lớn thì không phân biệt được mịn hơn độ rộng trường.","note":""},{"l":"D","en":"When training at one state, the learned value function will be updated over all states within the intersection of the receptive fields","vi":"Cập nhật trên mọi trạng thái trong phần giao của các trường.","note":""}],"ans":"AB","ansnote":"","exp":[["p","Mỗi đặc trưng hoạt động khi trạng thái nằm trong vùng (receptive field) của nó; hai trạng thái cùng thuộc một số vùng chung thì cập nhật làm chúng ảnh hưởng lẫn nhau (A). Kích thước/hình dạng vùng quyết định độ rộng và hướng tổng quát (B). C sai vì với nhiều vùng chồng lấn khéo, phân biệt vẫn có thể mịn hơn độ rộng một vùng. D sai vì cập nhật tác động lên tất cả trạng thái chia sẻ ít nhất một đặc trưng với trạng thái đang học (hợp), không chỉ giao."]],"rl":[["p","Coarse coding: mỗi đặc trưng nhị phân (1 nếu trạng thái nằm trong vùng). Vùng rộng → tổng quát rộng, học nhanh lúc đầu, nhưng độ phân giải cuối cùng do số vùng quyết định."]],"ex":[["p","3 vòng tròn chồng lấn: điểm x trong 2 vòng sẽ cập nhật cả hai vòng; mọi điểm trong 2 vòng đó bị ảnh hưởng."]],"tip":[["p","“Chồng lấn → tổng quát; to/nhỏ/hình dạng → quyết định kiểu tổng quát”."]],"fig":false},{"id":"c3-105","part":"c3","n":105,"en":"Consider a continuous two-dimensional state space. Assuming linear function approximation with the coarse-codings in either A, B or C, which of the following is TRUE? (Select all that apply) (có hình)","vi":"Xét không gian trạng thái hai chiều liên tục. Giả sử xấp xỉ tuyến tính với các mã hóa thô ở hình A, B hoặc C, phát biểu nào đúng? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Generalization is broader in case A as compared to case B","vi":"Tổng quát ở A rộng hơn B.","note":""},{"l":"B","en":"In case B, when updating the state marked by an ‘x’, the value function will be affected for a larger number of states as compared to case A","vi":"Ở B, cập nhật trạng thái ‘x’ ảnh hưởng tới nhiều trạng thái hơn A.","note":""},{"l":"C","en":"In case C, each update results in more generalization along the vertical dimension, as compared to horizontal","vi":"Ở C, mỗi cập nhật tổng quát nhiều hơn theo chiều dọc so với chiều ngang.","note":""},{"l":"D","en":"In case C, ... more generalization along the horizontal dimension","vi":"Ngược lại.","note":""}],"ans":"BC","ansnote":"theo đáp án của đề","exp":[["p","Hình không hiển thị trên trang văn bản nên phần nhìn hình dựa vào đáp án của đề: trường tiếp nhận ở B lớn hơn A nên tổng quát ở B rộng hơn (B đúng, A sai); ở C các vùng dạng elip kéo dài theo chiều dọc nên tổng quát mạnh theo chiều dọc (C đúng, D sai). Nguyên tắc: hình dạng vùng quy định hướng tổng quát."]],"rl":[["p","Vùng kéo dài theo trục nào → tổng quát mạnh theo trục đó. Vùng tròn → tổng quát đẳng hướng."]],"ex":[["p","Vùng elip cao hẹp: cập nhật tại x lan nhiều lên/xuống, ít sang trái/phải."]],"tip":[["p","“Vùng dài theo hướng nào, tri thức lan theo hướng đó”."]],"fig":false},{"id":"c3-106","part":"c3","n":106,"en":"Which of the following affects generalization in tile coding? (Select all that apply)","vi":"Yếu tố nào ảnh hưởng đến tổng quát trong tile coding? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The number of tiles","vi":"Số ô (tiles).","note":""},{"l":"B","en":"The number of tilings","vi":"Số lớp lát (tilings).","note":""},{"l":"C","en":"How the tilings are offset from each other","vi":"Cách các lớp lệch nhau.","note":""},{"l":"D","en":"The shape of the tiles","vi":"Hình dạng ô.","note":""}],"ans":"ABCD","ansnote":"","exp":[["p","Số/kích thước ô quyết định độ thô của mỗi lớp; số lớp quyết định độ mịn/độ phân giải; độ lệch giữa các lớp quyết định pattern chồng lấn; hình dạng ô (vuông, chữ nhật, lục giác) quy định hướng tổng quát. Tất cả cùng quyết định những trạng thái nào chia sẻ đặc trưng."]],"rl":[["p","Tile coding: n tilings, mỗi lớp chia không gian thành các ô; đặc trưng nhị phân; số đặc trưng hoạt động mỗi lần = n (Q107)."]],"ex":[["p","8 tilings, mỗi lớp 10×10 ô: 800 đặc trưng, mỗi lần 8 hoạt động; ô lớn → tổng quát rộng, ô nhỏ → phân biệt mịn."]],"tip":[["p","“Tile coding: số ô, số lớp, độ lệch, hình ô: bốn núm vặn tổng quát”."]],"fig":false},{"id":"c3-107","part":"c3","n":107,"en":"When tile coding is used for feature construction, the number of active or non-zero features","vi":"Khi dùng tile coding để tạo đặc trưng, số đặc trưng đang hoạt động (khác 0) là","opts":[{"l":"A","en":"is the number of tiles","vi":"bằng số ô (tiles).","note":""},{"l":"B","en":"is the number of tilings","vi":"bằng số lớp lát (tilings).","note":""},{"l":"C","en":"is the number of tilings multiplied by the number of tiles","vi":"bằng số lớp nhân số ô.","note":""},{"l":"D","en":"depends on the state","vi":"phụ thuộc trạng thái.","note":""}],"ans":"B","ansnote":"","exp":[["p","Mỗi lớp lát (tiling) chia không gian thành các ô không chồng nhau, nên mỗi trạng thái rơi vào đúng một ô trong mỗi lớp. Vậy có đúng một đặc trưng hoạt động cho mỗi lớp, tức bằng số lớp, luôn như nhau với mọi trạng thái."]],"rl":[["p","Tổng số đặc trưng = (số lớp) × (số ô mỗi lớp), nhưng số đặc trưng hoạt động = số lớp. Hệ quả: có thể chọn α = α_0/n_tilings để đổi bước ổn định; gradient û chỉ có n phần tử khác 0."]],"ex":[["p","8 tilings, mỗi lớp 100 ô → 800 đặc trưng, nhưng mỗi trạng thái chỉ bật 8; û tính bằng tổng 8 trọng số."]],"tip":[["p","“Mỗi lớp bật đúng 1 ô → active = số lớp”. Tính toán rất rẻ."]],"fig":false},{"id":"c3-108","part":"c3","n":108,"en":"Which of the following is TRUE about neural networks (NNs)? (Select all that apply)","vi":"Phát biểu nào đúng về mạng nơ-ron (NN)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A NN is feedforward if there are no paths within the network by which a unit's output can influence its input","vi":"NN là feedforward nếu không có đường nào để đầu ra của một đơn vị ảnh hưởng ngược lại đầu vào của nó.","note":""},{"l":"B","en":"Hidden layers are layers that are neither input nor output layers","vi":"Lớp ẩn là lớp không phải vào cũng không phải ra.","note":""},{"l":"C","en":"The output of the units in NNs are typically a linear function of their input signals","vi":"Đầu ra của các đơn vị thường là hàm tuyến tính của đầu vào.","note":""},{"l":"D","en":"NNs are parameterized functions that enable the agent to learn a nonlinear value function of state","vi":"NN là hàm có tham số cho phép học giá trị phi tuyến.","note":""},{"l":"E","en":"The nonlinear functions applied to the weighted sum of the input signals are called the activation function","vi":"Hàm phi tuyến áp lên tổng có trọng số gọi là hàm kích hoạt.","note":""}],"ans":"ABDE","ansnote":"","exp":[["p","C sai: nếu các đơn vị đều tuyến tính thì mạng nhiều lớp cũng chỉ tương đương một phép biến đổi tuyến tính, mất sức mạnh; vì thế mỗi đơn vị áp dụng hàm kích hoạt phi tuyến (E)."]],"rl":[["p","Đơn vị: y = f(w·x + b). Feedforward: không có vòng lặp; lớp ẩn: giữa input và output. NN cho û phi tuyến, học đặc trưng tự động."]],"ex":[["p","DQN: ảnh Atari → CNN (feedforward) → Q cho từng hành động."]],"tip":[["p","“NN = tuyến tính + kích hoạt phi tuyến”. “Feedforward = không quay vòng”."]],"fig":false},{"id":"c3-109","part":"c3","n":109,"en":"Which of the following is the rectified linear activation function?","vi":"Hàm nào là hàm kích hoạt tuyến tính chỉnh lưu (ReLU)?","opts":[{"l":"A","en":"f(x) = 1/(1 + e^{−x})","vi":"hàm sigmoid.","note":""},{"l":"B","en":"f(x) = 1 nếu x > 0, ngược lại 0","vi":"hàm bước (step).","note":""},{"l":"C","en":"f(x) = max(0, x)","vi":"ReLU.","note":""},{"l":"D","en":"f(x) = (e^x − e^{−x})/(e^x + e^{−x})","vi":"hàm tanh.","note":""}],"ans":"C","ansnote":"","exp":[["p","ReLU(x) = max(0, x): bằng x khi x > 0 và bằng 0 khi x ≤ 0. A là sigmoid, B là hàm bước, D là tanh."]],"rl":[["p","ReLU đạo hàm = 1 nếu x > 0, 0 nếu x < 0; ít làm gradient biến mất hơn sigmoid/tanh."],["code","\\mathrm{ReLU}(x)=\\max(0,x),\\quad \\sigma(x)=\\frac1{1+e^{-x}},\\quad \\tanh(x)=\\frac{e^x-e^{-x}}{e^x+e^{-x}}"]],"ex":[["p","ReLU(−3) = 0; ReLU(2,5) = 2,5."]],"tip":[["p","“ReLU = Re-Luồng mặt âm = cắt phần âm” (max(0, x))."]],"fig":false},{"id":"c3-110","part":"c3","n":110,"en":"Which of the following are TRUE statements? (Select all that apply)","vi":"Những phát biểu nào sau đây đúng? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A disadvantage of linear function approximation methods like tile coding is that they are linear in the input state","vi":"Nhược điểm của phương pháp tuyến tính như tile coding là tuyến tính theo trạng thái đầu vào.","note":""},{"l":"B","en":"NNs are powerful function approximators and can learn accurate value functions, but typically require many samples to train","vi":"NN mạnh nhưng cần nhiều mẫu.","note":""},{"l":"C","en":"An advantage of linear methods is that they can be more data efficient than NNs, but they rely on an expert to design the features appropriately","vi":"Phương pháp tuyến tính hiệu quả dữ liệu hơn NN nhưng phụ thuộc chuyên gia thiết kế đặc trưng.","note":""},{"l":"D","en":"An advantage of NNs is that learning can adapt the features, as compared to methods like tile coding","vi":"NN có ưu điểm là học thích nghi đặc trưng.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","A sai vì tile coding tuyến tính theo đặc trưng, không theo trạng thái: nó vẫn biểu diễn được hàm phi tuyến của trạng thái. B, C, D là đánh đổi chuẩn: tuyến tính = ít dữ liệu nhưng cần đặc trưng tốt; NN = mạnh, tự học đặc trưng nhưng cần nhiều mẫu."]],"rl":[["p","Tuyến tính (tile coding, coarse coding): dễ phân tích, hội tụ tốt, cần feature thủ công. NN: biểu diễn phi tuyến, học feature, khó huấn luyện hơn."]],"ex":[["p","Bài toán nhỏ 2D: tile coding hiệu quả. Atari pixel: NN (DQN) thắng."]],"tip":[["p","“Tuyến tính = rẻ, cần thủ công; NN = đắt, tự học”."]],"fig":false},{"id":"c3-111","part":"c3","n":111,"en":"Which of the following is TRUE about backpropagation? (Select all that apply)","vi":"Phát biểu nào đúng về lan truyền ngược (backpropagation)? (Chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Backpropagation corresponds to updating the parameters of a neural network using gradient descent","vi":"Backprop tương ứng với việc cập nhật tham số bằng gradient descent.","note":""},{"l":"B","en":"Backpropagation involves computing the partial derivatives of an objective function with respect to the weights of the network","vi":"Backprop tính đạo hàm riêng của hàm mục tiêu theo các trọng số.","note":""},{"l":"C","en":"The forward pass in backpropagation updates the weights of the network using the partial derivatives computed by the backward passes","vi":"Lượt xuôi cập nhật trọng số dùng đạo hàm tính ở lượt ngược.","note":""},{"l":"D","en":"Backpropagation computes partial derivatives starting from the last layer in the network, to save computation","vi":"Backprop tính đạo hàm từ lớp cuối để tiết kiệm tính toán.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","Forward pass chỉ tính đầu ra (C sai). Backward pass tính đạo hàm từ lớp cuối về đầu bằng quy tắc chuỗi, tái sử dụng kết quả ở lớp sau cho lớp trước nên tiết kiệm (D). Sau đó gradient descent cập nhật w (A, B)."]],"rl":[["code","\\frac{\\partial L}{\\partial W^{[0]}}=\\frac{\\partial L}{\\partial v}\\cdot\\frac{\\partial v}{\\partial x}\\cdot\\frac{\\partial x}{\\partial\\psi}\\cdot\\frac{\\partial\\psi}{\\partial W^{[0]}}"]],"ex":[["p","Mạng 3 lớp: lấy ∂L/∂(lớp 3) trước, nhân dần lui về lớp 2, lớp 1 dùng lại kết quả đã tính."]],"tip":[["p","“Forward = tính v; Backward = tính ∇; Gradient descent = cập nhật w”."]],"fig":false},{"id":"c3-112","part":"c3","n":112,"en":"Training neural networks (NNs) with backpropagation can be challenging because (Select all that apply)","vi":"Huấn luyện mạng nơ-ron bằng backpropagation có thể khó khăn vì (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"the loss surface might have flat regions, or poor local minima, meaning gradient descent gets stuck at poor solutions","vi":"bề mặt hàm mất mát có thể có vùng phẳng hoặc cực tiểu cục bộ xấu khiến gradient descent kẹt ở nghiệm kém.","note":""},{"l":"B","en":"the initialization can have a big impact on how much progress the gradient updates can make and on the quality of the final solution","vi":"khởi tạo ảnh hưởng lớn đến tiến độ cập nhật và chất lượng nghiệm cuối.","note":""},{"l":"C","en":"neural networks cannot accurately represent most functions, so the loss stays large","vi":"NN không biểu diễn chính xác đa số hàm nên loss luôn lớn.","note":""},{"l":"D","en":"learning can be slow due to the vanishing gradient problem, where if the partial derivatives for later nodes in the network are zero or near zero then this causes earlier nodes in the network to have small or near zero gradient updates","vi":"học chậm do gradient biến mất: đạo hàm của các nút sau gần 0 làm gradient của các nút trước cũng gần 0.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","A, B, D là ba khó khăn kinh điển (cảnh quan loss không lồi, nhạy với khởi tạo, vanishing gradient). C sai vì NN là xấp xỉ vạn năng (universal approximator): vấn đề nằm ở việc tối ưu, không phải khả năng biểu diễn."]],"rl":[["p","Gradient của lớp đầu là tích của nhiều đạo hàm theo quy tắc chuỗi; nếu các thừa số nhỏ (<1) thì tích tiến về 0."],["code","\\frac{\\partial L}{\\partial W^{[0]}}=\\frac{\\partial L}{\\partial v}\\prod_{l}\\frac{\\partial h_{l+1}}{\\partial h_l}\\cdots"]],"ex":[["p","Sigmoid có đạo hàm tối đa 0,25; qua 10 lớp: 0,25^10 ≈ 10^-6 → lớp đầu gần như không học."]],"tip":[["p","“Khó train vì: Kẹt (flat/local min), Khởi tạo, Biến mất gradient” — NN không phải “không đủ sức biểu diễn”."]],"fig":false},{"id":"c3-113","part":"c3","n":113,"en":"Consider the following network: [hình] where for a given input s, the value of v is computed by ψ = sW^[0] + b^[0], x = max(0, ψ), v = xW^[1] + b^[1]. What is the partial derivative of v(s) with respect to W^[0]_ij?","vi":"Xét mạng sau (có hình): với đầu vào s, ψ = sW^[0] + b^[0], x = max(0, ψ), v = xW^[1] + b^[1]. Đạo hàm riêng của v(s) theo W^[0]_ij là gì?","opts":[{"l":"A","en":"s_i","vi":"thiếu thừa số W^[1]_j và ReLU.","note":""},{"l":"B","en":"W^[1]_j · s_i nếu x_j > 0, và 0 nếu ngược lại.","vi":"","note":""},{"l":"C","en":"x_j","vi":"đây là đạo hàm theo W^[1]_j, không phải W^[0].","note":""},{"l":"D","en":"W^[1]_j · x_j nếu x_j > 0, ngược lại 0","vi":"","note":"vì ∂ψ_j/∂W^[0]_ij = s_i chứ không phải x_j. (sai"}],"ans":"B","ansnote":"","exp":[["p","W^[0]_ij nối đầu vào s_i với nút ẩn j nên chỉ ψ_j phụ thuộc vào nó: ∂ψ_j/∂W^[0]_ij = s_i. ReLU cho ∂x_j/∂ψ_j = 1 nếu ψ_j > 0 (tức x_j > 0), ngược lại 0. Cuối cùng ∂v/∂x_j = W^[1]_j. Nhân chuỗi: W^[1]_j · 1[x_j>0] · s_i."]],"rl":[["code","\\frac{\\partial v}{\\partial W^{[0]}_{ij}}=\\frac{\\partial v}{\\partial x_j}\\cdot\\frac{\\partial x_j}{\\partial \\psi_j}\\cdot\\frac{\\partial \\psi_j}{\\partial W^{[0]}_{ij}}=W^{[1]}_j\\cdot\\mathbf 1[x_j>0]\\cdot s_i"]],"ex":[["p","s_i = 2, W^[1]_j = 3, x_j > 0 → gradient = 6; nếu x_j = 0 (ReLU tắt) → gradient = 0."]],"tip":[["p","“Đạo hàm theo trọng số lớp nào = đầu vào của trọng số đó × (ReLU bật/tắt) × trọng số lớp sau”. Nhớ ReLU là cổng 0/1."]],"fig":true},{"id":"c3-114","part":"c3","n":114,"en":"Which of the following is TRUE? (Select all that apply)","vi":"Phát biểu nào sau đây đúng? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"When using stochastic gradient descent, we often completely eliminate the error for each example","vi":"khi dùng SGD ta thường triệt tiêu hoàn toàn sai số của từng mẫu.","note":""},{"l":"B","en":"The difference between stochastic gradient descent methods and batch gradient descent methods is that in the former the weights get updated using one random example whereas in the latter they get updated based on batches of data","vi":"SGD cập nhật bằng một mẫu ngẫu nhiên, batch GD cập nhật bằng cả lô dữ liệu.","note":"theo đáp án của đề"},{"l":"C","en":"Adagrad, Adam, and AMSGrad are stochastic gradient descent algorithms with adaptive step-sizes","vi":"Adagrad, Adam, AMSGrad là các biến thể SGD có bước học thích nghi.","note":""},{"l":"D","en":"Setting the step-size parameter for stochastic gradient descent can be challenging because a small step-size makes learning slow and a large step-size can result in divergence","vi":"chọn bước học khó: nhỏ thì chậm, lớn thì phân kỳ.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","A sai vì mỗi bước SGD chỉ giảm một phần sai số (bước nhỏ α), không triệt tiêu hẳn; làm vậy còn làm hỏng các mẫu khác. B mô tả sự khác biệt cốt lõi (một mẫu vs cả lô). C, D là sự thật về thuật toán tối ưu."]],"rl":[["p","SGD: w ← w − α∇L(w; mẫu). Batch GD: gradient trung bình trên cả lô. Mini-batch nằm giữa. Adam kết hợp động lượng và chuẩn hóa theo bình phương gradient."],["code","w\\leftarrow w-\\alpha\\,\\nabla_w L(w;x_i)"]],"ex":[["p","α quá lớn → loss tăng vọt (phân kỳ); α quá nhỏ → hàng triệu bước vẫn chưa hội tụ."]],"tip":[["p","“SGD = 1 mẫu, Batch = cả lô; Adam/Adagrad = bước học tự chỉnh”."]],"fig":false},{"id":"c3-115","part":"c3","n":115,"en":"Which of the following is TRUE about artificial neural networks (ANNs)? (Select all that apply)","vi":"Phát biểu nào đúng về mạng nơ-ron nhân tạo (ANN)? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"It is best to initialize the weights of a NN to large numbers so that the input signal does not get too small as it passes through the network","vi":"nên khởi tạo trọng số lớn để tín hiệu không bị nhỏ dần.","note":""},{"l":"B","en":"It is best to initialize the weights of a NN to small numbers so that the input signal does not grow rapidly as it passes through the network","vi":"nên khởi tạo trọng số nhỏ để tín hiệu không phình to.","note":""},{"l":"C","en":"If possible, it would be best to initialize the weights of an NN near the global optimum","vi":"nếu có thể, khởi tạo gần cực tiểu toàn cục là tốt nhất.","note":""},{"l":"D","en":"A reasonable way to initialize the NN is with random weights, with each weight sampled from a normal distribution with the variance scaled by the number of inputs to the layer for that weight","vi":"khởi tạo ngẫu nhiên từ phân phối chuẩn với phương sai scale theo số đầu vào của lớp.","note":""}],"ans":"CD","ansnote":"","exp":[["p","A và B đều sai vì quá tuyệt đối: trọng số quá lớn làm tín hiệu/gradient bùng nổ, quá nhỏ làm biến mất; phải scale đúng. D chính là ý tưởng của khởi tạo Xavier/He. C hiển nhiên: càng gần nghiệm tốt thì càng ít phải học."]],"rl":[["p","Xavier: Var(w) = 1/n_in (hoặc 2/(n_in+n_out)); He (cho ReLU): Var(w) = 2/n_in. Khởi tạo tất cả bằng 0 (hoặc bằng nhau) làm các nút đối xứng và học như nhau."],["code","w\\sim\\mathcal N\\!\\left(0,\\frac{2}{n_{\\text{in}}}\\right)\\quad(\\text{He})"]],"ex":[["p","Lớp có 100 đầu vào, He: độ lệch chuẩn √(2/100) ≈ 0,141."]],"tip":[["p","“Không quá lớn, không quá nhỏ — scale theo 1/√(số đầu vào)”. Hai đáp án tuyệt đối “lớn/nhỏ” thường là bẫy."]],"fig":false},{"id":"c3-116","part":"c3","n":116,"en":"Which of the following are true? (Select all that apply)","vi":"Những phát biểu nào sau đây đúng? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"In the tabular case, updating the value of one state does not affect the values of other states","vi":"trường hợp bảng: cập nhật giá trị một trạng thái không ảnh hưởng trạng thái khác.","note":""},{"l":"B","en":"When using state aggregation or coarse coding, updating the value of one state does not affect the values of other states","vi":"khi dùng state aggregation/coarse coding, cập nhật một trạng thái không ảnh hưởng trạng thái khác.","note":""},{"l":"C","en":"When using state aggregation or coarse coding, there is generalization across states","vi":"có tổng quát hóa giữa các trạng thái.","note":""},{"l":"D","en":"In the tabular case, there is generalization across states, i.e., updates to the value function of one state influences the value function of other states","vi":"trường hợp bảng có tổng quát hóa.","note":""}],"ans":"AC","ansnote":"","exp":[["p","Tabular là trường hợp đặc biệt của xấp xỉ hàm với one-hot features: mỗi trạng thái có tham số riêng nên không có tổng quát hóa. State aggregation/coarse coding dùng chung tham số giữa các trạng thái lân cận nên cập nhật một trạng thái lan sang các trạng thái khác."]],"rl":[["p","v̂(s,w) = wᵀx(s). Tabular: x(s) là one-hot. Tổng quát hóa là ưu điểm (học nhanh với nhiều trạng thái) nhưng cũng gây nhiễu (làm hỏng giá trị trạng thái khác)."]],"ex":[["p","Gộp 10 trạng thái vào 1 nhóm: cập nhật một trạng thái đổi giá trị cả 10. Tabular: chỉ đổi đúng một ô."]],"tip":[["p","“Bảng = mỗi ô riêng, không lan; gộp/mã hóa thô = dùng chung, có lan (generalization)”."]],"fig":false},{"id":"c3-117","part":"c3","n":117,"en":"To turn the update of Expected Sarsa algorithm to the update of Q-learning, one must:","vi":"Để biến công thức cập nhật của Expected Sarsa thành của Q-learning, ta phải:","opts":[{"l":"A","en":"Use a neural network to approximate the action-value function","vi":"dùng mạng nơ-ron để xấp xỉ hàm giá trị hành động.","note":""},{"l":"B","en":"Expected Sarsa cannot be adapted to represent Q-learning","vi":"Expected Sarsa không thể chuyển thành Q-learning.","note":""},{"l":"C","en":"Use the maximum over all the actions instead of the expectation in the update function","vi":"dùng max trên mọi hành động thay cho kỳ vọng.","note":""},{"l":"D","en":"Behave greedily with respect to the action-value function","vi":"hành xử tham lam theo hàm giá trị.","note":""}],"ans":"C","ansnote":"","exp":[["p","Expected Sarsa dùng Σ π(a'|S')Q(S',a'). Nếu thay chính sách π bằng chính sách tham lam (phân phối tập trung vào argmax) thì kỳ vọng đó chính là max_a' Q(S',a'), tức Q-learning. A không liên quan; B sai vì Q-learning là trường hợp đặc biệt của Expected Sarsa; D nói về chính sách hành xử, không phải công thức cập nhật."]],"rl":[["code","\\text{Exp. Sarsa: } R+\\gamma\\sum_{a'}\\pi(a'|S')Q(S',a')\\;\\;\\to\\;\\;\\text{Q-learning: } R+\\gamma\\max_{a'}Q(S',a')"]],"ex":[["p","Q(S',·) = [1, 3, 2], π ngẫu nhiên đều → kỳ vọng = 2; max = 3 → target Q-learning lớn hơn."]],"tip":[["p","“Kỳ vọng → max = Q-learning”; Expected Sarsa tổng quát, Q-learning là trường hợp π tham lam."]],"fig":false},{"id":"c3-118","part":"c3","n":118,"en":"Which of the following are true:","vi":"Những phát biểu nào sau đây đúng:","opts":[{"l":"A","en":"Exploration is not a problem when using function approximation because learning generalizes across states and actions","vi":"khám phá không còn là vấn đề khi dùng xấp xỉ hàm vì học tổng quát hóa.","note":""},{"l":"B","en":"When using function approximation, Q-learning will always result in better performance than Sarsa and Expected Sarsa","vi":"với xấp xỉ hàm, Q-learning luôn tốt hơn Sarsa và Expected Sarsa.","note":""},{"l":"C","en":"When using function approximation and with discrete actions, there is no straightforward way to turn Sarsa into Expected Sarsa","vi":"với hành động rời rạc không có cách đơn giản chuyển Sarsa thành Expected Sarsa.","note":""},{"l":"D","en":"When learning value functions in the mountain car domain and using tile coding, where all the rewards are −1 except when the terminal state is reached, initializing the weights of a linear function approximation to zero is an example of optimistic initialization","vi":"trong Mountain Car (mọi phần thưởng −1), khởi tạo trọng số bằng 0 là khởi tạo lạc quan.","note":""}],"ans":"D","ansnote":"","exp":[["p","Phần thưởng luôn −1 nên giá trị thật đều âm; khởi tạo Q = 0 cao hơn giá trị thật ⇒ lạc quan: hành động chưa thử có vẻ tốt hơn, thúc đẩy khám phá. A sai: khám phá vẫn là vấn đề. B sai: không có thuật toán nào “luôn” tốt hơn. C sai: với hành động rời rạc, chỉ cần tính Σ π(a|s)q̂(s,a) — rất đơn giản."]],"rl":[["p","Optimistic initialization: đặt ước lượng ban đầu cao hơn giá trị thật để buộc agent thử nhiều hành động. Với xấp xỉ hàm tuyến tính, phải chọn trọng số sao cho q̂ cao ở mọi nơi — không phải lúc nào cũng dễ."]],"ex":[["p","Mountain Car: q* ≈ −100 đến −150; q̂ = 0 → hành động nào thử xong bị giảm xuống (vì −1), hành động chưa thử vẫn 0 nên được chọn."]],"tip":[["p","“Toàn phần thưởng âm → 0 là lạc quan”. Câu chứa “always / not a problem” thường sai."]],"fig":false},{"id":"c3-119","part":"c3","n":119,"en":"Which of the following statements about discounted return and differential return algorithms are true:","vi":"Phát biểu nào về các thuật toán dùng discounted return và differential return là đúng:","opts":[{"l":"A","en":"There is a set of Bellman equations for the value function corresponding to the discounted return. However, there is no set of Bellman equations for differential value functions","vi":"có Bellman cho discounted return nhưng không có cho differential value.","note":""},{"l":"B","en":"The performance of discounted return algorithms can suffer because the optimal value of gamma is problem dependent","vi":"hiệu năng thuật toán discounted có thể kém vì γ tối ưu phụ thuộc bài toán.","note":""},{"l":"C","en":"Algorithms that maximize the discounted return can suffer from an exponentially large variance when using a large discount factor","vi":"thuật toán tối đa hóa discounted return có thể có phương sai rất lớn khi γ lớn.","note":""}],"ans":"BC","ansnote":"","exp":[["p","A sai: differential value cũng có phương trình Bellman, trong đó thay γ bằng việc trừ phần thưởng trung bình r̄. B, C là lý do phát triển cách tiếp cận average reward: không phải chỉnh γ và tránh phương sai bùng nổ khi γ → 1."]],"rl":[["code","v_\\pi(s)=\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)\\big[r-\\bar r+v_\\pi(s')\\big]"]],"ex":[["p","γ = 0,99 → “tầm nhìn” ~100 bước, tổng nhiều nhiễu; γ = 0,5 → nhìn gần, có thể bỏ lỡ phần thưởng xa."]],"tip":[["p","“Differential = trừ r̄ thay vì chiết khấu; vẫn có Bellman”. Nhóm B, C mô tả nhược điểm của γ."]],"fig":false},{"id":"c3-120","part":"c3","n":120,"en":"Imagine we have 7 state features and 6 actions and we want to use linear function approximation to compute the action-value function. If we use feature stacking (as explained in Week 3), how many features would we need in total to approximate the action-value function of all the different actions?","vi":"Giả sử có 7 đặc trưng trạng thái và 6 hành động, dùng xấp xỉ hàm tuyến tính cho hàm giá trị hành động. Nếu dùng feature stacking (như ở Tuần 3), tổng cộng cần bao nhiêu đặc trưng để xấp xỉ giá trị của mọi hành động?","opts":[{"l":"A","en":"67","vi":"","note":""},{"l":"B","en":"13","vi":"","note":""},{"l":"C","en":"42","vi":"","note":""},{"l":"D","en":"76","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Feature stacking tạo vector đặc trưng gồm |A| khối, mỗi khối có d đặc trưng; khối của hành động a mới khác 0. Tổng = d × |A| = 7 × 6 = 42. B (7 + 6 = 13) là cộng thay vì nhân; A (67) và D (76) là các số gây nhiễu (ghép chữ số 7 và 6)."]],"rl":[["code","x(s,a)=\\big[\\mathbf 0,\\dots,\\;x(s),\\;\\dots,\\mathbf 0\\big]\\in\\mathbb R^{d|\\mathcal A|},\\qquad \\hat q(s,a,w)=w^\\top x(s,a)"]],"ex":[["p","Hành động thứ 3: x(s) đặt ở khối 3, các khối còn lại bằng 0 → q̂ = w_3ᵀx(s)."]],"tip":[["p","“Stacking = Nhân (d × |A|), không phải Cộng”."]],"fig":false},{"id":"c3-121","part":"c3","n":121,"en":"Imagine we are approximating the action-value function of three different actions (red, green, and blue) using three state features, resulting in the following weights and features: [hình]. Which of these statements is true about our function approximation scheme?","vi":"Giả sử ta xấp xỉ hàm giá trị hành động của ba hành động (đỏ, xanh lá, xanh dương) bằng ba đặc trưng trạng thái, với trọng số và đặc trưng như trong hình. Phát biểu nào đúng về lược đồ xấp xỉ này?","opts":[{"l":"A","en":"The green action will never be selected","vi":"hành động xanh lá sẽ không bao giờ được chọn.","note":""},{"l":"B","en":"The action-value of the green action will be exactly the same as the action-value of the red action for any state","vi":"giá trị hành động xanh lá luôn bằng giá trị hành động đỏ với mọi trạng thái.","note":""},{"l":"C","en":"There will not be any generalization across states","vi":"không có tổng quát hóa giữa các trạng thái.","note":""},{"l":"D","en":"The action-value of the red action will be exactly the same as the action-value of the blue action","vi":"giá trị hành động đỏ luôn bằng hành động xanh dương.","note":""}],"ans":"B","ansnote":"theo đáp án của đề, vì hình không hiển thị","exp":[["p","Với feature stacking, mỗi hành động có một khối trọng số riêng nên q̂(s,a) = w_aᵀx(s). Hai hành động có cùng giá trị với mọi trạng thái khi hai khối trọng số trong hình giống hệt nhau — theo key, đó là xanh lá và đỏ. Vì vậy chúng không bao giờ khác nhau, còn xanh dương có khối trọng số khác. A sai vì xanh lá có thể được chọn (hòa với đỏ). C sai vì các trọng số được chia sẻ qua đặc trưng nên vẫn có tổng quát hóa."]],"rl":[["p","Với hành động rời rạc, mỗi hành động có một khối tham số w_a; hai khối giống nhau ⇒ q̂ giống nhau."]],"ex":[["p","w_red = w_green = [1, 2, 3] → q̂(s, red) = q̂(s, green) mọi s."]],"tip":[["p","“Cùng khối trọng số ⇒ cùng giá trị; còn tổng quát hóa đến từ chia sẻ đặc trưng”."]],"fig":true},{"id":"c3-122","part":"c3","n":122,"en":"Consider the following feature and weight vectors corresponding to three state features and three actions (red, green, and blue): [hình]. What is the approximate action-value for the blue action?","vi":"Xét các vector đặc trưng và trọng số ứng với ba đặc trưng trạng thái và ba hành động (đỏ, xanh lá, xanh dương) trong hình. Giá trị hành động xấp xỉ của hành động xanh dương là bao nhiêu?","opts":[{"l":"A","en":"12","vi":"","note":""},{"l":"B","en":"42","vi":"","note":""},{"l":"C","en":"16","vi":"","note":""},{"l":"D","en":"53","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Trong feature stacking, chỉ khối trọng số của hành động được chọn đóng góp vào giá trị: q̂(s, xanh dương) = w_blue · x(s) (tích vô hướng của vector trọng số xanh dương với vector đặc trưng). Hãy lấy ba trọng số của khối xanh dương nhân từng đặc trưng rồi cộng lại. Các đáp án khác thường là kết quả khi dùng nhầm khối trọng số (đỏ/xanh lá) hoặc cộng cả ba khối."]],"rl":[["code","\\hat q(s,a_{\\text{blue}},w)=\\sum_{i=1}^{3} w^{\\text{blue}}_i\\,x_i(s)"]],"ex":[["p","x = [2, 1, 3], w_blue = [4, 2, 2] → q̂ = 8 + 2 + 6 = 16 (ví dụ minh họa, không phải số trong hình)."]],"tip":[["p","“Chọn hành động nào → chỉ dùng khối trọng số của hành động đó (các khối khác nhân với 0)”."]],"fig":true},{"id":"c3-123","part":"c3","n":123,"en":"Which of the following statements about epsilon-greedy policies and optimistic initialization are true:","vi":"Phát biểu nào về chính sách epsilon-greedy và khởi tạo lạc quan là đúng:","opts":[{"l":"A","en":"Implementing optimistic initialization is always straightforward and simple to implement regardless of the function approximation technique","vi":"cài đặt khởi tạo lạc quan luôn đơn giản dù dùng kỹ thuật xấp xỉ nào.","note":""},{"l":"B","en":"Optimistic initialization results in a more systematic exploration in the tabular case because the agent takes actions it has not taken as often in a state","vi":"khởi tạo lạc quan cho khám phá có hệ thống hơn trong trường hợp bảng vì agent chọn hành động ít được thử.","note":""},{"l":"C","en":"Optimistic initialization is always preferred over using an epsilon-greedy policy","vi":"khởi tạo lạc quan luôn được ưu tiên hơn epsilon-greedy.","note":""},{"l":"D","en":"Epsilon-greedy can be easily combined with any function approximation technique because it only needs to be able to query for the approximate action-values, without needing to know how they are initialized or computed","vi":"epsilon-greedy kết hợp dễ với mọi xấp xỉ hàm vì chỉ cần truy vấn giá trị xấp xỉ.","note":""}],"ans":"BD","ansnote":"","exp":[["p","A và C dùng từ “luôn” nên sai: với NN hay tile coding, khó đặt trọng số để q̂ cao ở mọi trạng thái (đặc biệt khi có tổng quát hóa, cập nhật một điểm làm giảm điểm khác). B đúng trong trường hợp bảng: hành động ít được thử vẫn giữ giá trị cao nên được chọn. D đúng vì ε-greedy chỉ cần giá trị xấp xỉ."]],"rl":[["p","ε-greedy: với xác suất 1−ε chọn argmax q̂, với ε chọn ngẫu nhiên — không phụ thuộc cách biểu diễn q̂. Optimistic init: phụ thuộc cách biểu diễn và khó kiểm soát khi xấp xỉ."]],"ex":[["p","Bảng 10 trạng thái × 4 hành động: gán Q = 10 cho mọi ô rất dễ; NN: không có cách đảm bảo đầu ra ≥ 10 ở mọi trạng thái."]],"tip":[["p","“ε-greedy = đúng với mọi thứ (tổng quát); optimistic = chỉ đẹp khi dùng bảng”. Tránh “always”."]],"fig":false},{"id":"c3-124","part":"c3","n":124,"en":"Consider the mountain car environment where all the rewards are −1 after every action until reaching the flag on top of the right hill: [hình]. Which of the following are examples of optimistic initialization when using linear function approximation?","vi":"Xét môi trường Mountain Car, mọi phần thưởng là −1 sau mỗi hành động cho tới khi tới lá cờ trên đỉnh đồi phải. Đâu là ví dụ của khởi tạo lạc quan khi dùng xấp xỉ tuyến tính?","opts":[{"l":"A","en":"Initialize all the weights at random using a uniform distribution between −5 and 5","vi":"khởi tạo tất cả trọng số ngẫu nhiên đều trong [−5, 5].","note":"ngẫu nhiên, giá trị có cả âm lẫn dương, không đảm bảo cao hơn giá trị thật"},{"l":"B","en":"Initialize all the weights so that the action-value function is −1 everywhere","vi":"khởi tạo sao cho q̂ = −1 ở mọi nơi.","note":"theo đáp án của đề"},{"l":"C","en":"Initialize all the weights so that the action-value function is zero everywhere","vi":"khởi tạo sao cho q̂ = 0 ở mọi nơi.","note":""},{"l":"D","en":"Initialize all the weights so that the action-value function is 10 everywhere","vi":"khởi tạo sao cho q̂ = 10 ở mọi nơi.","note":""}],"ans":"CD","ansnote":"","exp":[["p","Do mọi phần thưởng đều âm, giá trị thật luôn ≤ −1 và thường rất âm (ví dụ ≈ −100). Khởi tạo q̂ = 0 hoặc 10 chắc chắn cao hơn giá trị thật ở mọi nơi → lạc quan. A không đảm bảo vì có trọng số âm. Với B: −1 chỉ đúng bằng phần thưởng một bước, vì thế đề không tính là lạc quan rõ rệt (về lý thuyết nó cũng cao hơn hầu hết giá trị thật, nên đây là điểm cần nhớ theo key của đề)."]],"rl":[["p","Optimistic init: q̂_0(s,a) > q*(s,a) cho mọi (s,a). Với tuyến tính + tile coding (mỗi đặc trưng nhị phân), đặt mỗi trọng số = c/(số tilings) để q̂ = c."]],"ex":[["p","8 tilings: mỗi trọng số = 10/8 = 1,25 → q̂ = 8 × 1,25 = 10 cho mọi trạng thái."]],"tip":[["p","“Phần thưởng toàn âm → khởi tạo 0 (hoặc dương) = lạc quan”."]],"fig":true},{"id":"c3-125","part":"c3","n":125,"en":"Consider the following MDP where the red action (L) at state S results in an immediate reward of +1 and 0 afterwards, and the blue action (R) results in 0 immediate reward, but a final reward of +2 when returning to state S: [hình]. In this MDP, what is the optimal policy at state S when using discounted return with γ = 0.5? When using discounted return with γ = 0.9? When using average reward? (Hint: You can modify the equations used for the task from lesson 3 of this module to get the solution.)","vi":"Xét MDP sau: hành động đỏ (L) tại trạng thái S cho phần thưởng tức thì +1 rồi 0 sau đó; hành động xanh dương (R) cho phần thưởng tức thì 0, nhưng có phần thưởng cuối +2 khi quay lại S. Chính sách tối ưu tại S là gì khi dùng discounted return với γ = 0,5? với γ = 0,9? và khi dùng average reward? (Gợi ý: sửa các phương trình của bài từ bài học 3 của module).","opts":[{"l":"A","en":"γ = 0,5: xanh dương; γ = 0,9: đỏ; average reward: xanh dương.","vi":"","note":""},{"l":"B","en":"γ = 0,5: xanh dương; γ = 0,9: đỏ; average reward: đỏ.","vi":"","note":""},{"l":"C","en":"γ = 0,5: đỏ; γ = 0,9: xanh dương; average reward: xanh dương.","vi":"","note":""},{"l":"D","en":"γ = 0,5: xanh dương; γ = 0,9: xanh dương; average reward: đỏ.","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Đây là MDP “cận thị” (nearsighted) của Tuần 3: mỗi vòng đều có độ dài n bước. Giả sử n = 5 (như bài giảng): vòng đỏ được +1 ngay (giá trị 1, không chiết khấu), vòng xanh được +2 sau 5 bước, tức giá trị 2γ⁴. Với γ = 0,5: 2·0,0625 = 0,125 < 1 → chọn đỏ. Với γ = 0,9: 2·0,6561 ≈ 1,31 > 1 → chọn xanh dương. Average reward: đỏ = 1 mỗi 5 bước, xanh = 2 mỗi 5 bước → xanh thắng, không phụ thuộc γ. Đáp án C khớp với tính toán này (độ dài vòng 5 là giả định dựa trên bài giảng, hình không hiển thị)."]],"rl":[["code","G_{\\text{red}}=1,\\qquad G_{\\text{blue}}=\\gamma^{\\,n-1}\\cdot 2,\\qquad \\bar r_{\\text{red}}=\\tfrac{1}{n},\\ \\ \\bar r_{\\text{blue}}=\\tfrac{2}{n}"]],"ex":[["p","Ngưỡng chuyển đổi: 2γ⁴ = 1 → γ = (1/2)^{1/4} ≈ 0,84. γ < 0,84 → đỏ; γ > 0,84 → xanh."]],"tip":[["p","“γ nhỏ = cận thị (chọn thưởng gần); γ lớn = nhìn xa. Average reward không có γ nên không cận thị.”"]],"fig":true},{"id":"c3-126","part":"c3","n":126,"en":"Consider the following MDP with two states. State 1 has two actions: staying in the same state (blue) and switching to the other state (red). State 2 has a single (red) action leading to State 1. The rewards are listed next to each arrow/transition: [hình]. If the agent is following a policy that takes the blue and red actions with equal probability, what is the average reward? (Hint: the state visitation probability is 2/3 for state 1 and 1/3 for state 2, the target policy π is the random policy, and all the transitions p are deterministic.) Recall the formula is: [hình].","vi":"Xét MDP hai trạng thái: trạng thái 1 có hai hành động, ở lại trạng thái 1 (xanh dương) và chuyển sang trạng thái kia (đỏ); trạng thái 2 chỉ có một hành động (đỏ) đưa về trạng thái 1. Phần thưởng ghi cạnh mỗi mũi tên (xem hình). Nếu agent theo chính sách chọn xanh và đỏ với xác suất bằng nhau, phần thưởng trung bình là bao nhiêu? (Gợi ý: xác suất ghé thăm là 2/3 cho trạng thái 1 và 1/3 cho trạng thái 2, π là chính sách ngẫu nhiên, mọi chuyển đổi là xác định.)","opts":[{"l":"A","en":"3/4","vi":"","note":""},{"l":"B","en":"2","vi":"","note":""},{"l":"C","en":"1","vi":"","note":""},{"l":"D","en":"4/3","vi":"","note":""}],"ans":"D","ansnote":"","exp":[["p","Dùng công thức phần thưởng trung bình: nhân xác suất ở trạng thái μ(s), xác suất chọn hành động π(a|s) và phần thưởng r của từng chuyển đổi rồi cộng lại. Trạng thái 1: (2/3) × [0,5·r_xanh + 0,5·r_đỏ]; trạng thái 2: (1/3) × r_(2→1). Thay các phần thưởng trong hình vào sẽ ra 4/3."]],"rl":[["code","r(\\pi)=\\sum_s\\mu(s)\\sum_a\\pi(a|s)\\sum_{s',r}p(s',r|s,a)\\,r"]],"ex":[["p","Một bộ số minh họa: r_xanh = 2, r_đỏ(1→2) = 2, r_(2→1) = 0 → (2/3)(0,5·2 + 0,5·2) + (1/3)·0 = 4/3 (bộ số minh họa khớp key, không chắc là số trong hình)."]],"tip":[["p","“μ × π × p × r, cộng tất cả”. Thứ tự: trạng thái → hành động → chuyển đổi → thưởng."]],"fig":true},{"id":"c3-127","part":"c3","n":127,"en":"For which of the following tasks is the average reward setting preferable than the discounted return setting if we are interested in maximizing the total amount of reward?","vi":"Với những nhiệm vụ nào sau đây, thiết lập phần thưởng trung bình (average reward) được ưu tiên hơn thiết lập discounted return, nếu ta quan tâm tới việc tối đa hóa tổng lượng phần thưởng?","opts":[{"l":"A","en":"The nearsighted MDP from Week 3: the agent starts at an initial state S that splits into two paths, each leading to a ring that leads back to S after some time. Choosing the left ring gives an immediate reward of +1 followed by 0 rewards, whereas choosing the right ring gives 0 immediately but a final reward of +2 when returning to S","vi":"MDP “cận thị” của Tuần 3: hai vòng quay về S, vòng trái +1 rồi 0, vòng phải 0 rồi +2 khi về S.","note":""},{"l":"B","en":"An Atari 2600 game where the agent can keep playing until it loses all its lives, which are a finite amount","vi":"trò Atari 2600, chơi đến khi hết một số mạng hữu hạn.","note":""},{"l":"C","en":"The job scheduling task from Section 10.3 of Sutton and Barto: the agent decides whether to accept or reject jobs into three servers according to their priority; accepting gives a positive reward equal to the priority, rejecting gives a negative reward proportional to the priority; jobs are continually added to the queue","vi":"bài toán xếp lịch công việc (Sutton & Barto, mục 10.3): nhận việc thì thưởng bằng độ ưu tiên, từ chối thì phạt; công việc liên tục đến.","note":""},{"l":"D","en":"The episodic mountain car environment","vi":"môi trường Mountain Car dạng tập (episodic).","note":""}],"ans":"AC","ansnote":"","exp":[["p","Average reward phù hợp với bài toán liên tục (continuing), không có điểm kết thúc, khi ta muốn tối đa hóa tổng thưởng dài hạn mà không muốn “cận thị” vì chiết khấu. A là ví dụ kinh điển: với γ nhỏ agent chọn vòng đỏ (thưởng gần) dù vòng xanh tốt hơn về lâu dài. C là bài toán liên tục: công việc đến mãi mãi, mục tiêu tự nhiên là thưởng trung bình mỗi bước. B và D là bài toán episodic: có điểm kết thúc nên dùng return không chiết khấu (γ = 1) là đủ, không cần average reward."]],"rl":[["p","Average reward cho tác vụ liên tục, chỉ có ý nghĩa khi quá trình có phân phối dừng μ. Differential return dùng thay cho discounted return."],["code","r(\\pi)=\\lim_{h\\to\\infty}\\frac1h\\sum_{t=1}^{h}\\mathbb E[R_t],\\qquad G_t=R_{t+1}-r(\\pi)+R_{t+2}-r(\\pi)+\\cdots"]],"ex":[["p","Bộ định tuyến mạng chạy 24/7: nên tối đa hóa gói tin xử lý trung bình mỗi giây, không cần γ. Game Atari: có Game Over nên dùng return theo tập."]],"tip":[["p","“Liên tục (không kết thúc) → average reward; có kết thúc (episodic) → return/discount”."]],"fig":false},{"id":"c3-128","part":"c3","n":128,"en":"Which of the following is true about policy gradient methods? (Select all that apply)","vi":"Phát biểu nào đúng về các phương pháp policy gradient? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Policy gradient methods use generalized policy iteration to learn policies directly","vi":"policy gradient dùng GPI để học chính sách trực tiếp.","note":""},{"l":"B","en":"Policy gradient methods do gradient ascent on the policy objective","vi":"policy gradient thực hiện gradient ascent trên hàm mục tiêu chính sách.","note":""},{"l":"C","en":"If we have access to the true value function, we can perform unbiased stochastic gradient updates using the result from the Policy Gradient Theorem","vi":"nếu có hàm giá trị thật, ta cập nhật gradient ngẫu nhiên không chệch nhờ định lý policy gradient.","note":""},{"l":"D","en":"The policy gradient theorem provides a form for the policy gradient that does not contain the gradient of the state distribution μ, which is hard to estimate","vi":"định lý cho dạng gradient không chứa gradient của phân phối trạng thái μ (khó ước lượng).","note":""}],"ans":"BCD","ansnote":"","exp":[["p","A sai: GPI (đánh giá + cải thiện chính sách) là của phương pháp dựa trên giá trị; policy gradient tối ưu trực tiếp tham số θ bằng gradient ascent. B đúng. D là điểm mấu chốt của định lý: ∇r(π) không chứa ∇μ nên không cần biết động lực học môi trường để tính. C đúng: dùng giá trị thật (q_π) thì ước lượng gradient là không chệch."]],"rl":[["code","\\nabla J(\\theta)\\propto\\sum_s\\mu(s)\\sum_a q_\\pi(s,a)\\nabla\\pi(a|s,\\theta),\\qquad \\theta\\leftarrow\\theta+\\alpha\\,\\nabla J(\\theta)"]],"ex":[["p","Robot đi bộ: tăng nhẹ xác suất các động tác dẫn tới q cao; không cần biết μ (xác suất ở mỗi tư thế)."]],"tip":[["p","“PG = Ascent trên J(θ), không GPI; Theorem = bỏ được ∇μ”."]],"fig":false},{"id":"c3-129","part":"c3","n":129,"en":"Which of the following statements about parameterized policies are true? (Select all that apply)","vi":"Phát biểu nào về chính sách được tham số hóa là đúng? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The policy must be approximated using linear function approximation","vi":"chính sách phải được xấp xỉ bằng hàm tuyến tính.","note":""},{"l":"B","en":"The function used for representing the policy must be a softmax function","vi":"hàm biểu diễn chính sách phải là softmax.","note":""},{"l":"C","en":"The probability of selecting any action must be greater than or equal to zero","vi":"xác suất chọn mọi hành động phải ≥ 0.","note":""},{"l":"D","en":"For each state, the sum of all the action probabilities must equal to one","vi":"với mỗi trạng thái, tổng xác suất các hành động bằng 1.","note":""}],"ans":"CD","ansnote":"","exp":[["p","Chính sách là phân phối xác suất nên phải thỏa tiên đề xác suất: không âm và tổng bằng 1 (C, D). Hình thức tham số hóa thì tự do: có thể tuyến tính, mạng nơ-ron, softmax cho hành động rời rạc hoặc Gaussian cho hành động liên tục, nên A và B sai."]],"rl":[["p","Ràng buộc: π(a|s,θ) ≥ 0 và Σ_a π(a|s,θ) = 1. Softmax là một lựa chọn phổ biến, không phải bắt buộc; hành động liên tục dùng Gaussian."]],"ex":[["p","π(·|s) = [0,2; 0,5; 0,3]: hợp lệ. [0,6; 0,6; −0,2]: không hợp lệ."]],"tip":[["p","“Chính sách = phân phối: ≥ 0 và tổng = 1; còn dạng hàm thì tự do”."]],"fig":false},{"id":"c3-130","part":"c3","n":130,"en":"Assume you're given the following preferences h₁ = 44, h₂ = 42, and h₃ = 38, corresponding to three different actions (a₁, a₂, a₃), respectively. Under a softmax policy, what is the probability of choosing a₂, rounded to three decimal numbers?","vi":"Giả sử có các độ ưu tiên h₁ = 44, h₂ = 42, h₃ = 38 tương ứng ba hành động a₁, a₂, a₃. Theo chính sách softmax, xác suất chọn a₂ là bao nhiêu (làm tròn ba chữ số thập phân)?","opts":[{"l":"A","en":"0,119","vi":"","note":""},{"l":"B","en":"0,42","vi":"","note":""},{"l":"C","en":"0,002","vi":"","note":""},{"l":"D","en":"0,879","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","π(a₂) = e^42 / (e^44 + e^42 + e^38). Chia cả tử và mẫu cho e^44: = e^(−2) / (1 + e^(−2) + e^(−6)) = 0,1353 / (1 + 0,1353 + 0,0025) = 0,1353 / 1,1378 ≈ 0,119. B (0,42) là số gây nhiễu (ghép từ h₂ = 42); C (0,002) chính là π(a₃); D (0,879) chính là π(a₁)."]],"rl":[["code","\\pi(a|s,\\theta)=\\frac{e^{h(s,a,\\theta)}}{\\sum_b e^{h(s,b,\\theta)}}"],["p","Softmax chỉ phụ thuộc vào hiệu của các h, nên có thể trừ cùng một hằng số cho mọi h để tránh tràn số."]],"ex":[["p","Tính cả ba: π(a₁) = 1/1,1378 ≈ 0,879; π(a₂) ≈ 0,119; π(a₃) = 0,0025/1,1378 ≈ 0,002. Tổng = 1. Vậy 0,879 chính là xác suất của a₁."]],"tip":[["p","“Trừ max trước khi lũy thừa: h − 44 = [0, −2, −6]”. Xác suất a₁ ≈ 0,879, a₂ ≈ 0,119, a₃ ≈ 0,002."]],"fig":false},{"id":"c3-131","part":"c3","n":131,"en":"Which of the following is true about softmax policy? (Select all that apply)","vi":"Phát biểu nào đúng về chính sách softmax? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Similar to epsilon-greedy policy, softmax policy cannot approach a deterministic policy","vi":"giống ε-greedy, softmax không thể tiến tới chính sách xác định.","note":""},{"l":"B","en":"It cannot represent an optimal policy that is stochastic, because it reaches a deterministic policy as one action preference dominates others","vi":"không biểu diễn được chính sách tối ưu ngẫu nhiên vì sẽ thành xác định khi một độ ưu tiên áp đảo.","note":""},{"l":"C","en":"It is used to represent a policy in discrete action spaces","vi":"dùng để biểu diễn chính sách trong không gian hành động rời rạc.","note":""},{"l":"D","en":"It can be parameterized by any function approximator as long as it can output scalar values for each available action, to form a softmax policy","vi":"có thể tham số hóa bằng bất kỳ bộ xấp xỉ hàm nào miễn là xuất ra một số vô hướng cho mỗi hành động.","note":""}],"ans":"CD","ansnote":"","exp":[["p","A sai: với softmax trên độ ưu tiên (preferences), nếu h của một hành động tăng vô hạn thì xác suất tiến tới 1, tức là có thể tiệm cận chính sách xác định; ε-greedy thì luôn giữ ít nhất ε/|A| cho mỗi hành động. B sai: softmax biểu diễn được cả chính sách ngẫu nhiên (khi các h gần nhau) lẫn xác định. C đúng: mỗi hành động rời rạc có một h. D đúng: h có thể do bảng, tuyến tính hoặc mạng nơ-ron tạo ra."]],"rl":[["p","Softmax trên action-preferences h(s,a,θ) khác softmax trên action-values: preferences không bị ràng buộc bởi độ lớn của q nên có thể tiến tới tất định hoặc giữ ngẫu nhiên tùy bài toán. Gaussian dùng cho hành động liên tục."]],"ex":[["p","h = [10, 0, 0] → π ≈ [0,9999; 0,00005; 0,00005] (gần xác định). h = [1, 1, 1] → π = [1/3, 1/3, 1/3] (ngẫu nhiên đều)."]],"tip":[["p","“Softmax: rời rạc + mọi bộ xấp xỉ + tiến được tới tất định (nếu dùng preferences), ε-greedy thì không”."]],"fig":false},{"id":"c3-132","part":"c3","n":132,"en":"What are the differences between using softmax policy over action-values and using softmax policy over action-preferences? (Select all that apply)","vi":"Sự khác nhau giữa dùng chính sách softmax trên giá trị hành động (action-values) và softmax trên độ ưu tiên hành động (action-preferences) là gì? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"When using softmax policy over action-values, assuming a tabular representation, the policy will converge to the optimal policy regardless of whether the optimal policy is stochastic or deterministic","vi":"softmax trên giá trị hành động (bảng) hội tụ về chính sách tối ưu dù tối ưu là ngẫu nhiên hay xác định.","note":""},{"l":"B","en":"When using softmax policy over action-preferences, assuming a tabular representation, the policy will converge to the optimal policy regardless of whether the optimal policy is stochastic or deterministic","vi":"softmax trên độ ưu tiên (bảng) hội tụ về chính sách tối ưu dù tối ưu là ngẫu nhiên hay xác định.","note":""},{"l":"C","en":"When using softmax policy over action-values, even if the optimal policy is deterministic, the policy may never approach a deterministic policy","vi":"softmax trên giá trị, dù chính sách tối ưu là xác định, có thể không bao giờ tiến tới chính sách xác định.","note":""}],"ans":"BC","ansnote":"","exp":[["p","Softmax trên action-values: π(a|s) ∝ e^{q(s,a)/τ}. Khi q → q*, xác suất bị “dính” vào khoảng cách giữa các q (chỉ gần 1 khi khoảng cách rất lớn), nên nhìn chung không tiến được tới tất định (C đúng) và cũng không tự khớp được xác suất ngẫu nhiên tối ưu (A sai). Với action-preferences, h là tham số học được trực tiếp, không bị gắn với độ lớn của q, nên có thể tiến tới tất định hoặc giữ ngẫu nhiên tùy bài toán (B đúng)."]],"rl":[["code","\\text{values: }\\pi(a|s)=\\frac{e^{q(s,a)/\\tau}}{\\sum_b e^{q(s,b)/\\tau}}\\qquad \\text{preferences: }\\pi(a|s,\\theta)=\\frac{e^{h(s,a,\\theta)}}{\\sum_b e^{h(s,b,\\theta)}}"]],"ex":[["p","q = [1, 0], τ = 1 → π(a₁) = e/(e + 1) ≈ 0,73 (không bao giờ 1). Preferences h = [1, 0] có thể học tăng lên h = [20, 0] → π ≈ 1."]],"tip":[["p","“Preferences = tự do (học đến tất định); Values = bị xích bởi giá trị”."]],"fig":false},{"id":"c3-133","part":"c3","n":133,"en":"What is the following objective, and in which task formulation? r(π) = Σ_s μ(s) Σ_a π(a|s,θ) Σ_{s',r} p(s',r|s,a) r","vi":"Hàm mục tiêu sau là gì, và trong dạng bài toán nào?","opts":[{"l":"A","en":"Average reward objective, episodic task","vi":"mục tiêu phần thưởng trung bình, bài toán episodic.","note":""},{"l":"B","en":"Average reward objective, continuing task","vi":"mục tiêu phần thưởng trung bình, bài toán liên tục.","note":""},{"l":"C","en":"Discounted return objective, continuing task","vi":"mục tiêu discounted return, bài toán liên tục.","note":""},{"l":"D","en":"Undiscounted return objective, episodic task","vi":"mục tiêu return không chiết khấu, bài toán episodic.","note":""}],"ans":"B","ansnote":"","exp":[["p","Biểu thức là kỳ vọng phần thưởng tức thì trung bình theo phân phối dừng μ của chính sách — đúng là định nghĩa average reward r(π), và chỉ có nghĩa với bài toán liên tục (có μ). Không có γ nên không phải discounted; không có tổng theo tập nên không phải episodic."]],"rl":[["p","r(π) = Σ_s μ(s) Σ_a π(a|s) Σ p(s',r|s,a) r. μ(s) là phân phối dừng (stationary) dưới π."]],"ex":[["p","Như Câu 126: μ = (2/3, 1/3), π ngẫu nhiên, phần thưởng từng chuyển đổi → cộng lại cho r(π)."]],"tip":[["p","“μ + không γ = average reward = continuing”."]],"fig":false},{"id":"c3-134","part":"c3","n":134,"en":"The following equation is the outcome of the policy gradient theorem: ∇r(π) = Σ_s μ(s) Σ_a ∇π(a|s,θ) q_π(s,a). Which of the following is true about the policy gradient theorem? (Select all that apply)","vi":"Phương trình sau là kết quả của định lý policy gradient. Phát biểu nào đúng về định lý này? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"We do not need to compute the gradient of the state distribution μ","vi":"không cần tính gradient của phân phối trạng thái μ.","note":""},{"l":"B","en":"This expression can be converted into E_π[Σ_a ∇π(a|S,θ) q_π(S,a)]. In discrete action space, by approximating q_π we could also use this gradient to update the policy","vi":"biểu thức có thể viết thành kỳ vọng E_π[Σ_a ∇π q_π]; với hành động rời rạc, xấp xỉ q_π để cập nhật chính sách.","note":""},{"l":"C","en":"The true action value q_π can be approximated in many ways, for example using TD algorithms","vi":"q_π thật có thể xấp xỉ nhiều cách, ví dụ bằng TD.","note":""},{"l":"D","en":"This expression can be converted into E_π[∇ ln π(A|S,θ) q_π(S,A)]","vi":"biểu thức có thể chuyển thành kỳ vọng E_π[∇ ln π(A|S) q_π(S,A)] (dạng REINFORCE/log-derivative).","note":""}],"ans":"ABCD","ansnote":"","exp":[["p","A là ý chính của định lý (bỏ ∇μ). B: Σ_s μ(s)(·) chính là kỳ vọng theo trạng thái S ~ μ. C: q_π không biết trước nên phải ước lượng (Monte Carlo, TD...). D: dùng mẹo log-derivative ∇π = π ∇ ln π để biến tổng thành kỳ vọng theo cả hành động A ~ π (để lấy mẫu)."]],"rl":[["code","\\nabla\\pi=\\pi\\,\\nabla\\ln\\pi\\;\\Rightarrow\\;\\nabla r(\\pi)=\\mathbb E_\\pi\\big[\\nabla\\ln\\pi(A|S,\\theta)\\,q_\\pi(S,A)\\big]"]],"ex":[["p","Mỗi bước, lấy mẫu (S, A) từ π, ước lượng q bằng TD, cập nhật θ += α q ∇ ln π (đây chính là REINFORCE/Actor-Critic)."]],"tip":[["p","“∇π = π∇lnπ → biến tổng thành kỳ vọng → lấy mẫu được”."]],"fig":false},{"id":"c3-135","part":"c3","n":135,"en":"Which of the following statements is true? (Select all that apply)","vi":"Phát biểu nào sau đây đúng? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The Actor-Critic algorithm consists of two parts: a parameterized policy","vi":"the actor — and a value function — the critic — Actor-Critic gồm hai phần: chính sách tham số hóa (actor) và hàm giá trị (critic).","note":""},{"l":"B","en":"Subtracting a baseline in the policy gradient update tends to reduce the variance of the update, which results in faster learning","vi":"trừ baseline giúp giảm phương sai, học nhanh hơn.","note":""},{"l":"C","en":"TD methods do not have a role when estimating the policy directly","vi":"TD không có vai trò khi ước lượng chính sách trực tiếp.","note":""},{"l":"D","en":"To update the actor in Actor-Critic, we can use TD error in place of q_π in the Policy Gradient Theorem","vi":"để cập nhật actor có thể dùng TD error thay cho q_π.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","C sai vì TD dùng cho critic, và TD error δ là tín hiệu dẫn dắt actor. D: δ = R + γ v̂(S') − v̂(S) là ước lượng không chệch của hàm advantage (q − v), vừa thay q_π vừa đóng vai baseline. B: baseline giảm phương sai mà không làm chệch gradient."]],"rl":[["code","\\delta_t=R_{t+1}+\\gamma\\hat v(S_{t+1},w)-\\hat v(S_t,w),\\quad w\\leftarrow w+\\alpha_w\\delta\\nabla\\hat v,\\quad \\theta\\leftarrow\\theta+\\alpha_\\theta\\delta\\nabla\\ln\\pi(A|S,\\theta)"]],"ex":[["p","δ > 0: hành động tốt hơn dự đoán → tăng xác suất; δ < 0 → giảm."]],"tip":[["p","“Actor = hành động, Critic = chấm điểm bằng TD error”."]],"fig":false},{"id":"c3-136","part":"c3","n":136,"en":"To train the critic, we must use the average reward version of semi-gradient TD(0).","vi":"Để huấn luyện critic, bắt buộc phải dùng phiên bản average reward của semi-gradient TD(0).","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Critic có thể dùng bất kỳ phương pháp ước lượng giá trị nào phù hợp: TD(0) có chiết khấu (bài toán episodic hay liên tục đều được), TD(λ), hoặc TD average reward cho tác vụ liên tục. Không “bắt buộc” phiên bản average reward. Chỉ khi mục tiêu chính sách là average reward thì critic mới được thiết kế theo differential value (ngay cả khi đó, đây là lựa chọn thiết kế, không phải bắt buộc)."]],"rl":[["p","Discounted TD: δ = R + γ v̂(S') − v̂(S). Average reward TD: δ = R − r̄ + v̂(S') − v̂(S), cập nhật cả r̄."]],"ex":[["p","Actor-Critic trên bài toán episodic (CartPole) dùng TD(0) chiết khấu là hoàn toàn hợp lệ."]],"tip":[["p","“Câu có ‘must’ (bắt buộc) thường là sai”. Critic linh hoạt, actor mới giữ phần chính sách."]],"fig":false},{"id":"c3-137","part":"c3","n":137,"en":"Consider the following state features and parameters θ for three different actions (red, green, and blue): [hình]. Compute the action preferences for each of the three different actions using linear function approximation and stacked features for the action preferences. What is the action preference of a₁ (green)?","vi":"Xét các đặc trưng trạng thái và tham số θ cho ba hành động (đỏ, xanh lá, xanh dương) trong hình. Hãy tính độ ưu tiên của từng hành động bằng xấp xỉ tuyến tính và đặc trưng xếp chồng (stacked) cho độ ưu tiên. Độ ưu tiên của hành động a₁ (xanh lá) là bao nhiêu?","opts":[{"l":"A","en":"42","vi":"","note":""},{"l":"B","en":"40","vi":"","note":""},{"l":"C","en":"35","vi":"","note":""},{"l":"D","en":"32","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Với stacked features, độ ưu tiên của mỗi hành động là tích vô hướng của đặc trưng trạng thái với khối tham số θ của riêng hành động đó: h(s, a) = θ_aᵀ x(s). Với xanh lá (a₁), lấy khối θ xanh lá nhân đặc trưng rồi cộng. Đáp án 42 cũng khớp với các con số dùng ở Câu 130 (44, 42, 38 là bộ độ ưu tiên của đỏ/xanh lá/xanh dương), nhưng đó chỉ là gợi ý, không phải bằng chứng."]],"rl":[["code","h(s,a,\\theta)=\\theta^\\top x(s,a),\\qquad \\pi(a|s,\\theta)=\\frac{e^{h(s,a,\\theta)}}{\\sum_b e^{h(s,b,\\theta)}}"]],"ex":[["p","x = [2, 3, 1], θ_green = [10, 5, 7] → h = 20 + 15 + 7 = 42 (chỉ là ví dụ minh họa)."]],"tip":[["p","“Muốn độ ưu tiên hành động nào → lấy đúng khối θ của hành động đó, nhân với đặc trưng”."]],"fig":true},{"id":"c3-138","part":"c3","n":138,"en":"Which of the following statements are true about the Actor-Critic algorithm with softmax policies? (Choose all that apply)","vi":"Phát biểu nào đúng về thuật toán Actor-Critic với chính sách softmax? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The preferences must be approximated using linear function approximation","vi":"độ ưu tiên bắt buộc xấp xỉ bằng hàm tuyến tính.","note":""},{"l":"B","en":"Since the policy is written as a function of the current state, it is like having a different softmax distribution for each state","vi":"vì chính sách là hàm của trạng thái hiện tại nên giống như có một phân phối softmax riêng cho mỗi trạng thái.","note":""},{"l":"C","en":"The actor and the critic share the same set of parameters","vi":"actor và critic dùng chung một tập tham số.","note":""},{"l":"D","en":"The learning rate parameter of the actor and the critic can be different","vi":"bước học của actor và critic có thể khác nhau.","note":""}],"ans":"BD","ansnote":"","exp":[["p","A sai: độ ưu tiên có thể đến từ bất kỳ bộ xấp xỉ nào (tuyến tính, NN...). C sai: actor có tham số θ, critic có tham số w, là hai tập riêng (dù có thể chia sẻ một phần mạng trong một số cài đặt nâng cao, đây không phải mặc định). B đúng vì π(·|s) là một phân phối riêng cho từng s. D đúng vì α_θ và α_w là hai siêu tham số độc lập."]],"rl":[["code","w\\leftarrow w+\\alpha_w\\,\\delta\\,\\nabla\\hat v(S,w),\\qquad \\theta\\leftarrow\\theta+\\alpha_\\theta\\,\\delta\\,\\nabla\\ln\\pi(A|S,\\theta)"]],"ex":[["p","α_w = 0,1 cho critic (học nhanh), α_θ = 0,01 cho actor (ổn định) là lựa chọn thường gặp."]],"tip":[["p","“Hai tập tham số (θ, w), hai bước học (α_θ, α_w), mỗi trạng thái một softmax”."]],"fig":false},{"id":"c3-139","part":"c3","n":139,"en":"Which of the following is an advantage of Gaussian policy parameterization over discretizing the action space? (Select all that apply)","vi":"Đâu là ưu điểm của tham số hóa chính sách Gaussian so với rời rạc hóa không gian hành động? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"Gaussian policies are differentiable, whereas policies over discretized actions are not","vi":"chính sách Gaussian khả vi, còn chính sách trên hành động rời rạc thì không.","note":"softmax trên hành động rời rạc cũng khả vi"},{"l":"B","en":"Continuous actions also allow learning to generalize over actions","vi":"hành động liên tục cho phép tổng quát hóa giữa các hành động.","note":""},{"l":"C","en":"Even if the true action set is discrete, but very large, it might be better to treat them as a continuous range","vi":"ngay cả khi tập hành động thực sự rời rạc nhưng rất lớn, coi nó là khoảng liên tục có thể tốt hơn.","note":""},{"l":"D","en":"There might not be a straightforward way to choose a discrete set of actions","vi":"có thể không có cách đơn giản để chọn tập hành động rời rạc.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","A sai vì softmax trên hành động rời rạc cũng khả vi theo θ; khác biệt không nằm ở khả vi. Gaussian tận dụng cấu trúc liên tục: hành động gần nhau thì tương tự nhau nên học được tổng quát (B); giảm số tham số khi có quá nhiều hành động rời rạc (C); và tránh phải tự chia lưới (D)."]],"rl":[["code","\\pi(a|s,\\theta)=\\frac{1}{\\sigma(s,\\theta)\\sqrt{2\\pi}}\\exp\\!\\Big(-\\frac{(a-\\mu(s,\\theta))^2}{2\\sigma(s,\\theta)^2}\\Big),\\quad \\nabla\\ln\\pi=\\frac{a-\\mu}{\\sigma^2}\\nabla\\mu+\\Big(\\frac{(a-\\mu)^2}{\\sigma^3}-\\frac1\\sigma\\Big)\\nabla\\sigma"]],"ex":[["p","Tay robot có góc khớp trong [0°, 180°]: Gaussian cho μ = 90°, σ = 10°; rời rạc hóa 1° → 180 hành động, không chia sẻ thông tin."]],"tip":[["p","“Gaussian = hành động liên tục, 2 tham số (μ, σ), tổng quát giữa các hành động”."]],"fig":false},{"id":"c4-140","part":"c4","n":140,"en":"Which of the following algorithms are appropriate in a control setting in which updates will be made at every time step? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán điều khiển (control) mà việc cập nhật diễn ra ở mỗi bước thời gian? [Chọn tất cả đáp án đúng]","opts":[{"l":"A","en":"Expected SARSA","vi":"","note":""},{"l":"B","en":"SARSA","vi":"","note":""},{"l":"C","en":"Q-learning","vi":"","note":""}],"ans":"ABC","ansnote":"","exp":[["p","Cả ba là thuật toán TD control: sau mỗi chuyển đổi (S, A, R, S') đều cập nhật Q ngay (bootstrapping), không cần đợi hết tập. Khác nhau ở target: SARSA dùng Q(S',A'), Expected SARSA dùng kỳ vọng ΣπQ(S',·), Q-learning dùng max."]],"rl":[["code","\\text{SARSA: } Q(S,A)\\!\\leftarrow\\! Q+\\alpha[R+\\gamma Q(S',A')-Q]\\\\\n\\text{Exp.SARSA: } \\ldots+\\gamma\\sum_a\\pi(a|S')Q(S',a)\\\\\n\\text{Q-learning: } \\ldots+\\gamma\\max_a Q(S',a)"]],"ex":[["p","Robot đi mê cung: đi một bước → cập nhật Q ngay lập tức, không chờ tới đích."]],"tip":[["p","“TD control = mỗi bước cập nhật; MC = cuối tập mới cập nhật”."]],"fig":false},{"id":"c4-141","part":"c4","n":141,"en":"Which of the following algorithms are appropriate in a prediction setting in which updates will be made at the end of each episode? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán dự đoán (prediction) mà việc cập nhật diễn ra khi kết thúc mỗi tập?","opts":[{"l":"A","en":"Monte-Carlo Prediction","vi":"dự đoán Monte Carlo.","note":""},{"l":"B","en":"Exploring Starts Monte-Carlo","vi":"Monte Carlo với bắt đầu khám phá.","note":"đây là thuật toán control"},{"l":"C","en":"Off-Policy Monte-Carlo","vi":"Monte Carlo off-policy.","note":""}],"ans":"AC","ansnote":"","exp":[["p","Monte Carlo chỉ cập nhật khi đã có return của cả tập. A là MC prediction thuần túy. C: off-policy MC ước lượng giá trị của chính sách đích bằng importance sampling (bài toán prediction). B là control (vừa đánh giá vừa cải thiện chính sách), không phải prediction."]],"rl":[["code","V(S_t)\\leftarrow V(S_t)+\\alpha\\,[G_t-V(S_t)],\\qquad \\text{off-policy: } G_t\\to\\rho_{t:T-1}G_t"]],"ex":[["p","Trò blackjack: chơi hết ván mới biết thắng/thua → cập nhật V cho các bài đã gặp trong ván."]],"tip":[["p","“Prediction = đánh giá v; Control = tìm π*”. ES-MC có chữ “Control” ở bản chất."]],"fig":false},{"id":"c4-142","part":"c4","n":142,"en":"Which of the following algorithms are appropriate in a tabular setting in which we will be learning a model and using it for planning? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán dạng bảng (tabular) mà ta sẽ học một mô hình rồi dùng nó để lập kế hoạch (planning)?","opts":[{"l":"A","en":"Expected SARSA —","vi":"","note":"model-free, không học mô hình"},{"l":"B","en":"Dyna-Q —","vi":"","note":""},{"l":"C","en":"Dyna-Q+ —","vi":"","note":""}],"ans":"BC","ansnote":"","exp":[["p","Dyna-Q vừa học từ kinh nghiệm thật (Q-learning), vừa học mô hình môi trường và dùng mô hình đó sinh kinh nghiệm giả để lập kế hoạch. Dyna-Q+ thêm thưởng khám phá κ√τ cho cặp (s, a) lâu chưa thử, để thích nghi khi môi trường thay đổi. Expected SARSA chỉ dùng mẫu thật, không có mô hình."]],"rl":[["code","\\text{Dyna-Q+ planning reward: } r+\\kappa\\sqrt{\\tau(s,a)}"]],"ex":[["p","Mê cung đổi lối đi: Dyna-Q+ khám phá lại và tìm lối mới nhanh hơn Dyna-Q."]],"tip":[["p","“Dyna = Direct RL + Model learning + Planning”."]],"fig":false},{"id":"c4-143","part":"c4","n":143,"en":"Which of the following algorithms are appropriate in a control setting in which we are given access to a model? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán điều khiển khi ta đã được cung cấp mô hình môi trường?","opts":[{"l":"A","en":"Iterative Policy Evaluation","vi":"đánh giá chính sách lặp.","note":"chỉ là prediction"},{"l":"B","en":"Policy Iteration","vi":"lặp chính sách.","note":""},{"l":"C","en":"Value Iteration","vi":"lặp giá trị.","note":""},{"l":"D","en":"Dyna-Q —","vi":"","note":"theo đáp án của đề: có mô hình thì có thể dùng planning"}],"ans":"BCD","ansnote":"","exp":[["p","Khi mô hình p(s',r|s,a) đã biết, Policy Iteration và Value Iteration (quy hoạch động) tìm chính sách tối ưu. Iterative Policy Evaluation chỉ đánh giá một chính sách cố định (prediction) nên không phải control. Dyna-Q vẫn là thuật toán control có thành phần planning: nếu được cho sẵn mô hình thì chỉ cần dùng mô hình đó cho planning, nên đề coi là phù hợp."]],"rl":[["code","v_{k+1}(s)=\\max_a\\sum_{s',r}p(s',r|s,a)\\big[r+\\gamma v_k(s')\\big]\\quad(\\text{Value Iteration})"]],"ex":[["p","Gridworld biết đầy đủ xác suất chuyển đổi → Value Iteration ra π* không cần tương tác."]],"tip":[["p","“Có mô hình + control = DP (PI, VI) hoặc Dyna; Policy Evaluation = chỉ prediction”."]],"fig":false},{"id":"c4-144","part":"c4","n":144,"en":"Which of the following algorithms are appropriate in a continuing control setting with a discrete action space and function approximation? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán control liên tục, không gian hành động rời rạc và có xấp xỉ hàm?","opts":[{"l":"A","en":"Gaussian Actor-Critic —","vi":"","note":"Gaussian dành cho hành động liên tục"},{"l":"B","en":"Differential Softmax Actor-Critic —","vi":"","note":""},{"l":"C","en":"Differential Semi-Gradient SARSA —","vi":"","note":""}],"ans":"BC","ansnote":"","exp":[["p","“Liên tục” → dùng phiên bản differential (average reward). “Hành động rời rạc” → softmax (B) hoặc phương pháp giá trị như SARSA (C). Gaussian actor-critic dùng cho hành động liên tục."]],"rl":[["code","\\delta=R-\\bar R+\\hat q(S',A',w)-\\hat q(S,A,w),\\qquad \\bar R\\leftarrow\\bar R+\\beta\\delta"]],"ex":[["p","Hệ thống xếp lịch công việc chạy mãi mãi với vài lựa chọn rời rạc → differential semi-gradient SARSA."]],"tip":[["p","“Liên tục → Differential; rời rạc → softmax; liên tục (hành động) → Gaussian”."]],"fig":false},{"id":"c4-145","part":"c4","n":145,"en":"Which of the following algorithms are appropriate in an online prediction setting with linear function approximation? [Select all that apply]","vi":"Thuật toán nào phù hợp trong bài toán dự đoán trực tuyến (online) với xấp xỉ hàm tuyến tính?","opts":[{"l":"A","en":"Semi-Gradient TD","vi":"TD bán gradient.","note":""},{"l":"B","en":"Gradient Monte Carlo —","vi":"","note":"phải chờ hết tập mới có return, không online từng bước"},{"l":"C","en":"SARSA —","vi":"","note":"là control, không phải prediction"}],"ans":"A","ansnote":"","exp":[["p","Semi-gradient TD(0) cập nhật mỗi bước, ước lượng và dùng bootstrapping. Gradient MC cần return đầy đủ nên chỉ cập nhật cuối tập. SARSA là control."]],"rl":[["code","w\\leftarrow w+\\alpha\\,[R+\\gamma\\hat v(S',w)-\\hat v(S,w)]\\,\\nabla\\hat v(S,w)"]],"ex":[["p","Sau mỗi bước, dùng đặc trưng tuyến tính → ∇v̂ = x(S), cập nhật w ngay."]],"tip":[["p","“Online + prediction = TD; control = SARSA/Q”."]],"fig":false},{"id":"c4-146","part":"c4","n":146,"en":"In the continuing acrobot system (shown below), a double pendulum is fixed to the red square. The goal is to swing the double pendulum such that the height of the mass on the end of the lower pendulum exceeds the height of the black line. When the goal is reached, a reward of one is given and the double pendulum transitions to a vertical position. Otherwise, the reward is zero. Which of the following algorithms are appropriate for control in this context? [Select all that apply]","vi":"Trong hệ acrobot liên tục (xem hình), một con lắc kép gắn vào ô vuông đỏ. Mục tiêu là đu đưa con lắc sao cho khối lượng ở đầu con lắc dưới vượt quá đường đen. Khi đạt mục tiêu, nhận phần thưởng 1 và con lắc quay về vị trí thẳng đứng; ngược lại thưởng 0. Thuật toán nào phù hợp cho control trong bối cảnh này?","opts":[{"l":"A","en":"Expected SARSA —","vi":"","note":"theo đáp án của đề"},{"l":"B","en":"Q-learning —","vi":"","note":"theo đáp án của đề"},{"l":"C","en":"Average Reward Actor-Critic —","vi":"","note":""}],"ans":"C","ansnote":"","exp":[["p","Đây là bài toán liên tục (không có trạng thái kết thúc; sau khi đạt mục tiêu con lắc “reset” nhưng vẫn chạy tiếp). Đáp án của đề chọn thuật toán được thiết kế cho mục tiêu average reward. Lưu ý: Expected SARSA/Q-learning (có chiết khấu) về kỹ thuật vẫn có thể chạy, nhưng không được đề coi là phù hợp với mục tiêu trung bình dài hạn — nên đây là câu “theo đáp án của đề”."]],"rl":[["p","Continuing task + average reward → differential/average-reward actor-critic (δ = R − R̄ + v̂(S') − v̂(S))."]],"ex":[["p","Acrobot chạy 24/7, thưởng 1 mỗi lần đạt đích → tối đa hóa số lần đạt đích trung bình mỗi bước."]],"tip":[["p","“Liên tục + thưởng thưa thớt → average reward”."]],"fig":false},{"id":"c4-147","part":"c4","n":147,"en":"Which of the following algorithms are appropriate for control in the lunar lander MDP, as it is described in the lecture “Initial Project Meeting with Martha: Formalizing the Problem”? [Select all that apply]","vi":"Thuật toán nào phù hợp cho control trong MDP lunar lander như mô tả trong bài giảng “Initial Project Meeting with Martha”?","opts":[{"l":"A","en":"Expected SARSA —","vi":"","note":""},{"l":"B","en":"Q-learning —","vi":"","note":""},{"l":"C","en":"Average Reward Actor-Critic —","vi":"","note":""}],"ans":"AB","ansnote":"","exp":[["p","Lunar lander là bài toán episodic (kết thúc khi đáp hoặc rơi) với hành động rời rạc (bật/tắt các động cơ), nên phù hợp với TD control có chiết khấu như Expected SARSA và Q-learning. Average-reward actor-critic dành cho bài toán liên tục."]],"rl":[["p","Episodic + discrete actions → (Expected) SARSA / Q-learning, kèm NN (DQN) nếu trạng thái liên tục."]],"ex":[["p","Mỗi lần hạ cánh là một tập → “episode” rõ ràng."]],"tip":[["p","“Có điểm kết thúc (đáp/rơi) = episodic”; so với acrobot câu 146 (liên tục)."]],"fig":false},{"id":"c4-148","part":"c4","n":148,"en":"Which of the following meta-parameters can be tuned to improve performance of the agent? Performance refers to the cumulative reward the agent would receive in expectation across different runs. (Select all that apply)","vi":"Siêu tham số nào có thể được tinh chỉnh để cải thiện hiệu năng của agent? (Hiệu năng là tổng phần thưởng tích lũy kỳ vọng qua các lần chạy khác nhau.)","opts":[{"l":"A","en":"Random seed (for the random number generator)","vi":"hạt giống ngẫu nhiên.","note":""},{"l":"B","en":"Exploration parameter (e.g., epsilon in e-greedy or the temperature tau in the softmax policy)","vi":"tham số khám phá (ε hoặc nhiệt độ τ).","note":""},{"l":"C","en":"The step size in the update rule of the learning algorithm (e.g., alpha in Q-learning)","vi":"bước học α.","note":""},{"l":"D","en":"Number of hidden-layer units in a neural network approximating the value function","vi":"số đơn vị ẩn của mạng xấp xỉ giá trị.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","Hiệu năng được đo kỳ vọng trên nhiều lần chạy, nên random seed chỉ đổi kết quả từng lần chạy, không đổi hiệu năng kỳ vọng (không phải siêu tham số để tối ưu). B, C, D đều ảnh hưởng tốc độ học và chất lượng nghiệm."]],"rl":[["p","Siêu tham số (meta-parameters): α, ε/τ, γ, λ, kiến trúc mạng, số tilings… Thường chạy nhiều seed để đánh giá trung bình, không “tối ưu seed”."]],"ex":[["p","Thử α ∈ {2^-8,…,2^-1}, 30 seed mỗi giá trị, lấy α có trung bình thưởng cao nhất."]],"tip":[["p","“Seed = may rủi, không phải tham số để tinh chỉnh”."]],"fig":false},{"id":"c4-149","part":"c4","n":149,"en":"Suppose a problem that you have formulated as an MDP has k continuous input dimensions. You are considering using tile coding as a function approximator. With T tilings and t tiles per dimension in each tiling, which of the following represent the resultant number of features? (Assume each tiling covers all k dimensions.)","vi":"Giả sử MDP có k chiều đầu vào liên tục, dùng tile coding. Với T lớp lát, mỗi lớp có t ô trên mỗi chiều, tổng số đặc trưng là bao nhiêu? (Giả định mỗi lớp phủ cả k chiều.)","opts":[{"l":"A","en":"T·t^k","vi":"","note":""},{"l":"B","en":"k·T^t","vi":"","note":""},{"l":"C","en":"T·t/k","vi":"","note":""},{"l":"D","en":"T·t·k","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Mỗi lớp chia lưới k chiều, mỗi chiều t ô, nên mỗi lớp có t^k ô (tích của k số t). Có T lớp nên tổng là T·t^k. Chính vì thế bộ nhớ tăng theo cấp số mũ theo số chiều (“lời nguyền của chiều cao”). B, C, D sai dạng mũ/nhân."]],"rl":[["p","Tổng số đặc trưng = T × t^k; số đặc trưng hoạt động = T."],["code","d=T\\cdot t^{k}"]],"ex":[["p","k = 4, t = 10, T = 8 → 8 × 10^4 = 80 000 đặc trưng (nhưng chỉ 8 bật)."]],"tip":[["p","“Mỗi lớp = t^k ô; nhân với số lớp T”."]],"fig":false},{"id":"c4-150","part":"c4","n":150,"en":"Which of the following statements regarding feature-construction methods are TRUE? (Select all that apply)","vi":"Phát biểu nào về các phương pháp xây dựng đặc trưng là ĐÚNG? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A simple implementation of tile coding leads to memory requirements that might be exponential in the number of features","vi":"cài đặt đơn giản của tile coding có thể đòi bộ nhớ tăng theo cấp số mũ.","note":""},{"l":"B","en":"The feature representation obtained using neural networks changes with time","vi":"biểu diễn đặc trưng của NN thay đổi theo thời gian (khi học).","note":""},{"l":"C","en":"The feature representation obtained using tile coding changes with time","vi":"biểu diễn đặc trưng của tile coding thay đổi theo thời gian.","note":""},{"l":"D","en":"In low-dimensional problems, tile coding is computationally efficient and provides good generalization and discrimination","vi":"với bài toán ít chiều, tile coding hiệu quả về tính toán, có tổng quát hóa và phân biệt tốt.","note":""}],"ans":"ABD","ansnote":"","exp":[["p","A: số ô t^k tăng theo cấp số mũ khi số chiều k tăng. B: NN học ra đặc trưng, trọng số đổi nên đặc trưng đổi. C sai: tile coding là đặc trưng cố định do người thiết kế; chỉ trọng số được học. D đúng cho ít chiều."]],"rl":[["p","Tile coding: đặc trưng nhị phân, cố định, kích thước T·t^k. NN: đặc trưng học được, thích nghi."]],"ex":[["p","Mountain Car (2 chiều) → tile coding đẹp; ảnh Atari → NN."]],"tip":[["p","“Tile coding = đặc trưng đóng bang, chỉ ít chiều; NN = đặc trưng sống”."]],"fig":false},{"id":"c4-151","part":"c4","n":151,"en":"True or False: Adding more hidden layers (of a fixed finite width) increases the representation capacity of neural network. For example, if you have a single-hidden layer neural network with 16 units and nonlinear activations, then adding another layer of 16 units to get a neural network with two hidden layers can represent more functions.","vi":"Đúng hay Sai: Thêm nhiều lớp ẩn (độ rộng hữu hạn cố định) làm tăng năng lực biểu diễn của mạng. Ví dụ, mạng một lớp ẩn 16 đơn vị với kích hoạt phi tuyến, thêm một lớp 16 đơn vị để thành hai lớp ẩn thì biểu diễn được nhiều hàm hơn.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Thêm lớp (với kích hoạt phi tuyến) mở rộng tập hàm có thể biểu diễn; mạng sâu có thể biểu diễn một số hàm với ít đơn vị hơn rất nhiều so với mạng nông cùng độ rộng, và mạng 1 lớp ẩn 16 đơn vị có thể xem như trường hợp riêng của mạng 2 lớp ẩn, nên mạng 2 lớp ẩn biểu diễn được ít nhất như vậy và thêm nhiều hàm khác (đáp án của đề: True)."]],"rl":[["p","NN tăng độ sâu → tổ hợp phi tuyến nhiều lần → các đặc trưng phân cấp (cạnh → hình → vật)."]],"ex":[["p","Nhận dạng ảnh: lớp 1 nhận cạnh, lớp 2 nhận góc, lớp 3 nhận vật thể."]],"tip":[["p","“Sâu hơn = biểu diễn phong phú hơn, nhưng khó huấn luyện hơn” (xem Câu 112)."]],"fig":false},{"id":"c4-152","part":"c4","n":152,"en":"True or False: Adding more hidden layers to a neural network increases the number of parameters needed to be learned.","vi":"Đúng hay Sai: Thêm nhiều lớp ẩn vào mạng nơ-ron làm tăng số tham số cần học.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Mỗi lớp ẩn mới thêm ma trận trọng số và bias mới, nên số tham số tăng."]],"rl":[["p","Số tham số của một lớp kết nối đầy đủ = n_in × n_out + n_out."]],"ex":[["p","Input 10, hidden 16, output 1: 10×16+16 + 16×1+1 = 193. Thêm lớp 16→16: thêm 16×16+16 = 272 tham số."]],"tip":[["p","“Thêm lớp = thêm W và b”."]],"fig":false},{"id":"c4-153","part":"c4","n":153,"en":"Which of the following statements regarding the exploration approach are TRUE? (Select all that apply)","vi":"Phát biểu nào về cách khám phá là ĐÚNG? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"A softmax policy is a limited strategy for exploration because it can only be used with action preferences and policy-gradient methods","vi":"softmax là chiến lược khám phá hạn chế vì chỉ dùng với preferences và policy gradient.","note":""},{"l":"B","en":"Optimistic initial values are difficult to maintain when using neural networks as a function approximator","vi":"giá trị khởi tạo lạc quan khó duy trì khi dùng NN.","note":""},{"l":"C","en":"Epsilon-greedy exploration is difficult to combine with neural networks","vi":"ε-greedy khó kết hợp với NN.","note":""},{"l":"D","en":"Both optimistic initial values and epsilon-greedy exploration can be easily used with neural networks, because they are simple exploration strategies","vi":"cả hai dễ dùng với NN.","note":""}],"ans":"B","ansnote":"","exp":[["p","A sai: softmax có thể đặt trên action-values (Boltzmann) cho Q-learning. B đúng: khó đặt trọng số NN để đầu ra cao ở mọi trạng thái, và huấn luyện sẽ nhanh chóng “làm mất” sự lạc quan (xem Câu 123). C sai vì ε-greedy chỉ cần truy vấn giá trị đầu ra nên dùng được với mọi NN. D sai vì chỉ ε-greedy là dễ dùng, còn optimistic init thì không."]],"rl":[["p","ε-greedy: chỉ cần q̂; softmax: cần h/q; optimistic: phụ thuộc khởi tạo. DQN dùng ε-greedy."]],"ex":[["p","DQN Atari: ε giảm từ 1 xuống 0,1 — đơn giản, không cần biết cấu trúc mạng."]],"tip":[["p","“NN: ε-greedy OK, optimistic init khó”."]],"fig":false},{"id":"c4-154","part":"c4","n":154,"en":"Which of the following are TRUE about the softmax temperature parameter tau?","vi":"Phát biểu nào đúng về tham số nhiệt độ τ của softmax?","opts":[{"l":"A","en":"Tau does not affect the exploration at all","vi":"τ không ảnh hưởng tới khám phá.","note":""},{"l":"B","en":"For very small tau, the agent mostly selects the greedy action","vi":"τ rất nhỏ thì agent hầu như chọn hành động tham lam.","note":""},{"l":"C","en":"For very large tau, the agent's policy is nearly a uniformly-random policy","vi":"τ rất lớn thì chính sách gần như ngẫu nhiên đều.","note":""},{"l":"D","en":"If tau is large, the agent's policy is more stochastic","vi":"τ lớn thì chính sách càng ngẫu nhiên.","note":""}],"ans":"BCD","ansnote":"","exp":[["p","π(a) ∝ e^{q(a)/τ}. τ → 0: khoảng cách giữa các q/τ bùng nổ → chọn max (tham lam). τ → ∞: q/τ → 0 → mọi hành động cùng xác suất. τ đóng vai trò “núm xoay” khám phá."]],"rl":[["code","\\pi(a)=\\frac{e^{q(a)/\\tau}}{\\sum_b e^{q(b)/\\tau}}\\qquad \\tau\\to0:\\ \\text{greedy},\\quad \\tau\\to\\infty:\\ \\text{uniform}"]],"ex":[["p","q = [2, 1], τ = 1 → π = [0,73; 0,27]. τ = 0,1 → π ≈ [1; 0,00005]. τ = 100 → π ≈ [0,5025; 0,4975]."]],"tip":[["p","“τ = nhiệt độ: nóng → loạn (ngẫu nhiên), lạnh → chắc chắn (tham lam)”."]],"fig":false},{"id":"c4-155","part":"c4","n":155,"en":"Which of the following statements are true about activation functions? (Select all that apply)","vi":"Phát biểu nào về hàm kích hoạt là đúng? (chọn tất cả đáp án đúng)","opts":[{"l":"A","en":"The gradient of flat regions in the range of an activation function w.r.t. the input is zero","vi":"đạo hàm ở vùng phẳng của hàm kích hoạt theo đầu vào bằng 0.","note":""},{"l":"B","en":"Linear activation functions (such as f(x) = x) have derivatives close to zero for inputs of large magnitude","vi":"hàm kích hoạt tuyến tính có đạo hàm gần 0 với đầu vào lớn.","note":"đạo hàm luôn bằng 1"},{"l":"C","en":"Rectified Linear Units (ReLUs) are linear activation functions","vi":"ReLU là hàm kích hoạt tuyến tính.","note":"ReLU là tuyến tính từng khúc nhưng phi tuyến tổng thể"},{"l":"D","en":"For inputs of large magnitude, the derivative of the sigmoid and tanh functions are close to zero","vi":"với đầu vào có độ lớn lớn, đạo hàm sigmoid và tanh gần 0.","note":""}],"ans":"AD","ansnote":"","exp":[["p","Vùng phẳng ⇒ đạo hàm 0 (A). Sigmoid và tanh bão hòa ở hai đầu nên đạo hàm ≈ 0 — nguyên nhân vanishing gradient (D). B sai: f(x) = x có f'(x) = 1. C sai: ReLU = max(0, x) là phi tuyến."]],"rl":[["code","\\sigma'(x)=\\sigma(x)(1-\\sigma(x))\\le 0.25,\\qquad \\tanh'(x)=1-\\tanh^2(x),\\qquad \\mathrm{ReLU}'(x)=\\mathbf 1[x>0]"]],"ex":[["p","x = 10: σ'(10) ≈ 4,5×10⁻⁵ (gần 0); ReLU'(10) = 1."]],"tip":[["p","“Sigmoid/tanh bão hòa → gradient biến mất; ReLU cổng 0/1”."]],"fig":false},{"id":"c4-156","part":"c4","n":156,"en":"Consider you are using a neural network to approximate the action-value function of a reinforcement learning agent. You decide to use a neural network with two hidden layers. Now you want to choose the activation function for the hidden layers and the output layer. One option is to use a neural network with tanh activation functions in both hidden layers, and a linear activation in the output layer. Another option is to use a neural network with linear activations in both the hidden layers and the output layer. True or False: In both cases (option one and option two), the neural network can represent the same class of action-value functions.","vi":"Giả sử dùng NN hai lớp ẩn để xấp xỉ hàm giá trị hành động. Lựa chọn 1: tanh ở cả hai lớp ẩn và kích hoạt tuyến tính ở lớp ra. Lựa chọn 2: kích hoạt tuyến tính ở cả hai lớp ẩn và lớp ra. Đúng hay Sai: cả hai trường hợp NN biểu diễn cùng một lớp hàm giá trị hành động.","opts":[{"l":"A","en":"True","vi":"","note":""},{"l":"B","en":"False","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Mạng toàn kích hoạt tuyến tính chỉ là một phép biến đổi tuyến tính (tích các ma trận là một ma trận) → chỉ biểu diễn hàm tuyến tính theo đầu vào. Mạng có tanh biểu diễn được hàm phi tuyến (xấp xỉ vạn năng). Vậy hai lựa chọn không tương đương."]],"rl":[["code","W_3(W_2(W_1x))=(W_3W_2W_1)x\\;\\Rightarrow\\;\\text{chỉ là một phép tuyến tính}"]],"ex":[["p","Cần học q(s) = |s|: mạng tuyến tính không làm được, mạng tanh thì xấp xỉ được."]],"tip":[["p","“Nhiều lớp tuyến tính = 1 lớp tuyến tính; muốn sâu thật sự phải có phi tuyến” (xem Câu 108)."]],"fig":false},{"id":"c4-157","part":"c4","n":157,"en":"Which of the following statements are TRUE regarding methods for selecting a stepsize for the learning update?","vi":"Phát biểu nào về các phương pháp chọn bước học cho cập nhật học là ĐÚNG?","opts":[{"l":"A","en":"A stepsize that reduces over time (such as 1/N, where N is the number of agent-environment interactions) is necessary when the environment changes over time","vi":"bước học giảm dần theo thời gian (như 1/N) là cần thiết khi môi trường thay đổi theo thời gian.","note":""},{"l":"B","en":"An adaptive stepsize selection method like RMSProp uses a heuristic to change the stepsize during learning","vi":"phương pháp thích nghi như RMSProp dùng heuristic để đổi bước học.","note":""},{"l":"C","en":"The heuristic to change the stepsize can be learned from the data collected from the agent-environment interactions","vi":"heuristic đổi bước học có thể học từ dữ liệu tương tác.","note":""}],"ans":"BC","ansnote":"","exp":[["p","A sai: khi môi trường thay đổi (non-stationary) cần bước học không giảm về 0 để vẫn theo kịp thay đổi; bước giảm dần 1/N phù hợp bài toán ổn định. RMSProp, Adam, Adagrad tự điều chỉnh bước theo lịch sử gradient từ dữ liệu (B, C)."]],"rl":[["code","v\\leftarrow\\beta v+(1-\\beta)g^2,\\qquad \\theta\\leftarrow\\theta-\\frac{\\alpha}{\\sqrt{v}+\\epsilon}\\,g\\quad(\\text{RMSProp})"]],"ex":[["p","Tham số có gradient lớn → bước tự nhỏ lại; gradient nhỏ → bước tự lớn lên."]],"tip":[["p","“Đổi thay đổi → bước học không được về 0; adaptive = học bước từ gradient”."]],"fig":false},{"id":"c4-158","part":"c4","n":158,"en":"Suppose we want to find the optimal policy that obtains the maximum undiscounted return per episode in some task. We are using Expected Sarsa. With the rest of the meta-parameters fixed, we want to find the best setting of the stepsize that results in the best performance in this setting. In the following graph, the blue line represents how the performance measure varies with stepsize. Obviously, we do not have this information beforehand, and we are selecting a range of stepsizes to try out with our agent. Which of the following graphs best represent the range of stepsizes that should be tried out for a given experiment? (the orange points represent the selected stepsizes)","vi":"Giả sử ta muốn tìm chính sách tối ưu có return không chiết khấu tối đa mỗi tập, dùng Expected Sarsa. Cố định các siêu tham số khác, ta tìm bước học tốt nhất. Đường xanh dương là hiệu năng theo bước học (ta không biết trước). Đồ thị nào biểu diễn tốt nhất khoảng bước học nên thử? (các điểm cam là bước học đã chọn)","opts":[{"l":"A","en":"[hình]","vi":"","note":""},{"l":"B","en":"[hình]","vi":"","note":""},{"l":"C","en":"[hình]","vi":"","note":""}],"ans":"B","ansnote":"","exp":[["p","Nguyên tắc chọn dải bước học: thử nhiều giá trị cách đều trên thang log (ví dụ các lũy thừa của 2: 2^-10, …, 2^0) sạch bao phủ nhiều bậc độ lớn, sao cho đỉnh hiệu năng nằm giữa dải (không sát biên) và có cả hai bên đỉnh để thấy hiệu năng giảm. Không thử theo thang tuyến tính hẹp quanh một giá trị, vì đỉnh thường không biết trước."]],"rl":[["p","Quy trình chọn α: quét thang log α = 2^{-k}, chạy nhiều seed, vẽ hiệu năng theo α, chọn đỉnh và kiểm tra rằng đỉnh không ở rìa dải."]],"ex":[["p","Thử α ∈ {1/1024,…,1/2, 1}: nếu đỉnh ở 1/32 → thu hẹp quanh đó."]],"tip":[["p","“α quét theo thang log, đỉnh phải nằm trong dải, không được chạm biên”."]],"fig":true},{"id":"c4-159","part":"c4","n":159,"en":"True or False: Epsilon-greedy exploration uses information from all the action values of a particular state when choosing a non-greedy action in that state.","vi":"Đúng hay Sai: khám phá ε-greedy dùng thông tin từ tất cả giá trị hành động của một trạng thái khi chọn hành động không tham lam tại trạng thái đó.","opts":[{"l":"A","en":"False","vi":"","note":""},{"l":"B","en":"True","vi":"","note":""}],"ans":"A","ansnote":"","exp":[["p","Khi đã khám phá (xác suất ε), ε-greedy chọn một hành động ngẫu nhiên đều, không quan tâm giá trị của các hành động khác; chỉ bước chọn hành động tham lam mới dùng giá trị (argmax). Ngược lại, softmax dùng mọi giá trị để án xạ xác suất."]],"rl":[["code","\\pi(a|s)=\\begin{cases}1-\\epsilon+\\epsilon/|\\mathcal A| & a=\\arg\\max_b q(s,b)\\\\ \\epsilon/|\\mathcal A| & \\text{otherwise}\\end{cases}"]],"ex":[["p","q = [5, 4,9, −1000], ε = 0,1: ε-greedy chọn hành động 3 (rất tệ) với cùng xác suất như hành động 2 (gần tốt). Softmax sẽ tránh hành động 3."]],"tip":[["p","“ε-greedy: khám phá ‘mù’, softmax: khám phá ‘có hiểu biết’”."]],"fig":false}];
